#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ZcnblkOperationMode {
    Write,
    Read,
    Mixed,
}

impl ZcnblkOperationMode {
    fn from_env() -> io::Result<Self> {
        match env::var("URING_PLAY_ZCNBLK_OP")
            .unwrap_or_else(|_| "write".to_string())
            .to_ascii_lowercase()
            .as_str()
        {
            "" | "write" | "writes" => Ok(Self::Write),
            "read" | "reads" => Ok(Self::Read),
            "mixed" | "rw" | "read-write" | "write-read" => Ok(Self::Mixed),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown URING_PLAY_ZCNBLK_OP={other:?}; use write, read, or mixed"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Write => "write",
            Self::Read => "read",
            Self::Mixed => "mixed",
        }
    }

    fn op_for_frame(self, frame_index: usize) -> u16 {
        match self {
            Self::Write => ZCNBLK_OP_WRITE,
            Self::Read => ZCNBLK_OP_READ,
            Self::Mixed => {
                if frame_index % 2 == 0 {
                    ZCNBLK_OP_WRITE
                } else {
                    ZCNBLK_OP_READ
                }
            }
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum ZcnblkAccessPattern {
    Linear,
    Random { range_bytes: usize, seed: u64 },
}

impl ZcnblkAccessPattern {
    fn from_env(bytes_per_connection: usize, chunk_bytes: usize) -> io::Result<Self> {
        let mode = env::var("URING_PLAY_ZCNBLK_ACCESS")
            .or_else(|_| env::var("URING_PLAY_ZCNBLK_OFFSET_MODE"))
            .unwrap_or_else(|_| "linear".to_string())
            .to_ascii_lowercase();
        match mode.as_str() {
            "" | "linear" | "sequential" | "seq" => Ok(Self::Linear),
            "random" | "rand" | "rand4k" | "random-4k" => {
                let range_bytes = env_size_opt("URING_PLAY_ZCNBLK_RANDOM_RANGE_BYTES")?
                    .unwrap_or(bytes_per_connection);
                if range_bytes < chunk_bytes || range_bytes % chunk_bytes != 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!(
                            "URING_PLAY_ZCNBLK_RANDOM_RANGE_BYTES={range_bytes} must be >= chunk_bytes={chunk_bytes} and a multiple of chunk_bytes"
                        ),
                    ));
                }
                if range_bytes > bytes_per_connection {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!(
                            "URING_PLAY_ZCNBLK_RANDOM_RANGE_BYTES={range_bytes} exceeds bytes_per_connection={bytes_per_connection}; response validation expects requests inside the stream range"
                        ),
                    ));
                }
                let seed =
                    env_u64_parse_or("URING_PLAY_ZCNBLK_RANDOM_SEED", 0x7a63_6e62_6c6b_0001)?;
                Ok(Self::Random { range_bytes, seed })
            }
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown URING_PLAY_ZCNBLK_ACCESS={other:?}; use linear or random"),
            )),
        }
    }

    fn label(self) -> String {
        match self {
            Self::Linear => "linear".to_string(),
            Self::Random { range_bytes, seed } => {
                format!("random:range_bytes={range_bytes}:seed=0x{seed:016x}")
            }
        }
    }

    fn offset(
        self,
        spec: &ZcnblkConnectSpec,
        issued_bytes: usize,
        frame_index: usize,
        bytes_per_connection: usize,
        chunk_bytes: usize,
    ) -> io::Result<u64> {
        let relative = match self {
            Self::Linear => issued_bytes,
            Self::Random { range_bytes, seed } => {
                let chunks = range_bytes / chunk_bytes;
                let lane = spec.spec.lane as u64;
                let conn = spec.spec.conn_index as u64;
                let shard = spec.shard as u64;
                let stream = lane.rotate_left(17) ^ conn.rotate_left(33) ^ shard.rotate_left(49);
                let hash = splitmix64(
                    seed ^ stream ^ (frame_index as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15),
                );
                (hash as usize % chunks) * chunk_bytes
            }
        };
        if relative >= bytes_per_connection {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "zcnblk access pattern produced relative offset {relative} outside bytes_per_connection={bytes_per_connection}"
                ),
            ));
        }
        spec.base_offset
            .checked_add(relative as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcnblk offset overflow"))
    }
}

fn env_u64_parse_or(name: &str, default: u64) -> io::Result<u64> {
    let Ok(value) = env::var(name) else {
        return Ok(default);
    };
    let value = value.trim();
    if value.is_empty() {
        return Ok(default);
    }
    if let Some(hex) = value
        .strip_prefix("0x")
        .or_else(|| value.strip_prefix("0X"))
    {
        return u64::from_str_radix(hex, 16).map_err(|err| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid {name}={value:?}: {err}"),
            )
        });
    }
    value.parse::<u64>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid {name}={value:?}: {err}"),
        )
    })
}

fn zcnblk_parse_io_mode(value: &str, env_name: &str) -> io::Result<TcpWalWriteMode> {
    match value {
        "" | "write" | "plain" | "normal" => Ok(TcpWalWriteMode::Write),
        "fixed" | "write-fixed" | "fixedbuf" | "fixedbufs" => Ok(TcpWalWriteMode::WriteFixed),
        "fixed-file" | "fixedfile" | "fixedbufs-registerfiles" | "fast" => {
            Ok(TcpWalWriteMode::WriteFixedFile)
        }
        "null" | "sink" | "discard" | "none" => Ok(TcpWalWriteMode::Null),
        "slot" | "slots" | "io-slot" | "io-slots" => Ok(TcpWalWriteMode::Slot),
        other => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("unknown {env_name}={other:?}; use write, fixed, fixed-file, slot, or null"),
        )),
    }
}

fn zcnblk_read_mode_from_env(write_mode: TcpWalWriteMode) -> io::Result<TcpWalWriteMode> {
    match env::var("URING_PLAY_ZCNBLK_READ_MODE") {
        Ok(value) => {
            let value = value.to_ascii_lowercase();
            if matches!(value.as_str(), "same" | "write-mode" | "write_mode") {
                Ok(write_mode)
            } else {
                zcnblk_parse_io_mode(&value, "URING_PLAY_ZCNBLK_READ_MODE")
            }
        }
        Err(env::VarError::NotPresent) => Ok(TcpWalWriteMode::Write),
        Err(err) => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid URING_PLAY_ZCNBLK_READ_MODE: {err}"),
        )),
    }
}

fn zcnblk_expand_target_token(token: &str) -> io::Result<Vec<String>> {
    let token = token.trim();
    let Some((left, right)) = token.split_once("..") else {
        return Ok(vec![token.to_string()]);
    };
    let split = left
        .rfind(|ch: char| !ch.is_ascii_digit())
        .map(|idx| idx + 1)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("zcnblk target range {token:?} lacks a numeric start"),
            )
        })?;
    let (prefix, start_text) = left.split_at(split);
    if prefix.is_empty() || start_text.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid zcnblk target range {token:?}"),
        ));
    }
    let start = start_text.parse::<usize>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid zcnblk target range start {start_text:?}: {err}"),
        )
    })?;
    let end = right.trim().parse::<usize>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid zcnblk target range end {right:?}: {err}"),
        )
    })?;
    if end < start {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("zcnblk target range end {end} is before start {start}"),
        ));
    }
    Ok((start..=end)
        .map(|idx| format!("{prefix}{idx}"))
        .collect::<Vec<_>>())
}

fn zcnblk_is_devnull_target(token: &str) -> bool {
    let token = token.trim();
    let token = token.strip_prefix("/dev/").unwrap_or(token);
    token == "zcdevnull"
        || token.strip_prefix("zcdevnull").is_some_and(|suffix| {
            !suffix.is_empty() && suffix.bytes().all(|byte| byte.is_ascii_digit())
        })
}

fn zcnblk_parse_wal_target(token: &str) -> io::Result<Option<ZcnblkTargetPlan>> {
    let Some(spec) = token
        .strip_prefix("zcwal:")
        .or_else(|| token.strip_prefix("zcwal="))
    else {
        return Ok(None);
    };
    let parts = spec.split(':').collect::<Vec<_>>();
    if parts.len() > 6 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk zcwal target requires zcwal:ADDR[:BASE_PORT[:EXTENT_BYTES[:ACK[:BYTES[:ALIGN]]]]]",
        ));
    }
    let addr = parts.first().copied().unwrap_or_default();
    if addr.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk zcwal target requires a WAL receiver address",
        ));
    }
    let base_port = match parts.get(1).filter(|value| !value.is_empty()) {
        Some(value) => value.parse::<u16>().map_err(|err| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("zcwal base port {value:?} is invalid: {err}"),
            )
        })?,
        None => optional_u16_env("URING_PLAY_ZCNBLK_WAL_BASE_PORT")?.unwrap_or(26400),
    };
    let extent_bytes = match parts.get(2).filter(|value| !value.is_empty()) {
        Some(value) => parse_size_arg(value, "zcwal extent bytes")?,
        None => env_size_opt("URING_PLAY_ZCNBLK_WAL_EXTENT_BYTES")?.unwrap_or(4usize * 1024 * 1024),
    };
    let ack_enabled = match parts.get(3).filter(|value| !value.is_empty()) {
        Some(value) => parse_bool_arg(value, "zcwal ack")?,
        None => env_enabled_or("URING_PLAY_ZCNBLK_WAL_ACKS", true),
    };
    let device_bytes = match parts.get(4).filter(|value| !value.is_empty()) {
        Some(value) => parse_size_arg(value, "zcwal bytes")? as u64,
        None => env_size_opt("URING_PLAY_ZCNBLK_WAL_BYTES")?
            .unwrap_or(1024usize * 1024 * 1024 * 1024) as u64,
    };
    let required_alignment = match parts.get(5).filter(|value| !value.is_empty()) {
        Some(value) => parse_size_arg(value, "zcwal alignment")?,
        None => env_size_opt("URING_PLAY_ZCNBLK_WAL_ALIGNMENT")?.unwrap_or(ZC_WAL_RECORD_SIZE),
    };
    if device_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcwal bytes must be non-zero",
        ));
    }
    if required_alignment == 0 || required_alignment % ZC_WAL_RECORD_SIZE != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcwal alignment must be a non-zero multiple of 4096",
        ));
    }
    zcwal_validate_extent_shape(extent_bytes, extent_bytes)?;
    Ok(Some(ZcnblkTargetPlan {
        backend: ZcnblkTargetBackend::Wal(ZcnblkWalTarget {
            addr: addr.to_string(),
            base_port,
            extent_bytes,
            ack_enabled,
        }),
        device_bytes,
        required_alignment,
    }))
}

fn zcnblk_parse_raid0_target(
    token: &str,
    chunk_bytes: usize,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<Option<ZcnblkTargetPlan>> {
    let Some(spec) = token
        .strip_prefix("zcraid0:")
        .or_else(|| token.strip_prefix("zcraid0="))
    else {
        return Ok(None);
    };
    let (members_spec, stripe_spec) =
        spec.rsplit_once(':').map_or((spec, None), |(left, right)| {
            if right.bytes().any(|byte| byte.is_ascii_digit()) {
                (left, Some(right))
            } else {
                (spec, None)
            }
        });
    if members_spec.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcraid0 target requires zcraid0:/dev/zcbrdSTART..END[:STRIPE_BYTES]",
        ));
    }
    let stripe_bytes = match stripe_spec {
        Some(value) => parse_size_arg(value, "zcraid0 stripe bytes")?,
        None => env_size_opt("URING_PLAY_ZCNBLK_RAID0_STRIPE_BYTES")?.unwrap_or(chunk_bytes),
    };
    if stripe_bytes == 0 || stripe_bytes % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcraid0 stripe bytes must be non-zero and a multiple of chunk_bytes",
        ));
    }

    let segment_bytes = buffer_mode.segment_bytes()?;
    let mut members = Vec::new();
    for expanded in zcnblk_expand_target_token(members_spec)? {
        let target = parse_slot_wal_target(&expanded)?;
        if !matches!(
            target.kind,
            SlotWalTargetKind::NullBlock
                | SlotWalTargetKind::RamBlockDisk
                | SlotWalTargetKind::ZcBlockRamDisk
                | SlotWalTargetKind::PartUuid(_)
        ) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "zcraid0 members must be terminal leaf block devices, not RAID block devices",
            ));
        }
        let metadata = fs::metadata(target.open_path())?;
        if !metadata.file_type().is_block_device() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("{} is not a block device", target.label()),
            ));
        }
        validate_slot_wal_write_target_safety(&target, &metadata)?;
        let required_alignment =
            validate_slot_wal_geometry_alignment(&metadata, chunk_bytes, chunk_bytes)?;
        validate_slot_wal_queue_limits(&metadata, chunk_bytes, segment_bytes, buffer_mode)?;
        let file = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_CLOEXEC)
            .open(target.open_path())?;
        let device_bytes = block_device_size(file.as_raw_fd())?;
        if device_bytes < stripe_bytes as u64 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "{} is smaller than zcraid0 stripe bytes {stripe_bytes}",
                    target.label()
                ),
            ));
        }
        members.push(ZcnblkRaid0Member {
            target,
            device_bytes,
            required_alignment,
        });
    }
    if members.len() < 2 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcraid0 requires at least two leaf members",
        ));
    }
    let min_member_bytes = members
        .iter()
        .map(|member| member.device_bytes)
        .min()
        .expect("members checked non-empty");
    let usable_member_bytes = min_member_bytes - (min_member_bytes % stripe_bytes as u64);
    if usable_member_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcraid0 members have no stripe-aligned usable bytes",
        ));
    }
    let device_bytes = usable_member_bytes
        .checked_mul(members.len() as u64)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcraid0 size overflow"))?;
    let required_alignment = members
        .iter()
        .map(|member| member.required_alignment)
        .max()
        .unwrap_or(chunk_bytes);
    Ok(Some(ZcnblkTargetPlan {
        backend: ZcnblkTargetBackend::Raid0(ZcnblkRaid0Target {
            members,
            stripe_bytes,
        }),
        device_bytes,
        required_alignment,
    }))
}

fn zcnblk_parse_tier_target(token: &str) -> io::Result<Option<ZcnblkTargetPlan>> {
    let Some(spec) = token
        .strip_prefix("zctier:")
        .or_else(|| token.strip_prefix("zctier="))
    else {
        return Ok(None);
    };
    let parts = spec.split(':').collect::<Vec<_>>();
    let hot = parts.first().copied().unwrap_or_default();
    if hot.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk zctier target requires zctier:HOT[:SPILL[:BYTES[:ALIGN[:MEMORY]]]]",
        ));
    }
    if parts.len() > 5 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk zctier target accepts at most HOT:SPILL:BYTES:ALIGN:MEMORY",
        ));
    }
    let spill_path = parts
        .get(1)
        .filter(|value| !value.is_empty())
        .map(|value| PathBuf::from(*value));
    let device_bytes = match parts.get(2).filter(|value| !value.is_empty()) {
        Some(value) => parse_size_arg(value, "zctier bytes")? as u64,
        None => env_size_opt("URING_PLAY_ZCNBLK_TIER_BYTES")?
            .unwrap_or(64usize * 1024 * 1024 * 1024) as u64,
    };
    let required_alignment = match parts.get(3).filter(|value| !value.is_empty()) {
        Some(value) => parse_size_arg(value, "zctier alignment")?,
        None => env_size_opt("URING_PLAY_ZCNBLK_TIER_ALIGNMENT")?.unwrap_or(SECTOR_SIZE),
    };
    let memory_bytes = match parts.get(4).filter(|value| !value.is_empty()) {
        Some(value) => parse_size_arg(value, "zctier memory")?,
        None => {
            env_size_opt("URING_PLAY_ZCNBLK_TIER_MEMORY_BYTES")?.unwrap_or(256usize * 1024 * 1024)
        }
    };
    if device_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zctier bytes must be non-zero",
        ));
    }
    if required_alignment == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zctier alignment must be non-zero",
        ));
    }
    if memory_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zctier memory must be non-zero",
        ));
    }
    let hot_path = PathBuf::from(hot);
    let read_from_spill_on_open =
        !hot_path.exists() && spill_path.as_ref().is_some_and(|path| path.exists());
    Ok(Some(ZcnblkTargetPlan {
        backend: ZcnblkTargetBackend::Tier(ZcnblkTierTarget {
            hot_path,
            spill_path,
            device_bytes,
            read_from_spill_on_open,
            backpressure: Arc::new(ZcTierBackpressure::new(memory_bytes)),
        }),
        device_bytes,
        required_alignment,
    }))
}

fn zcnblk_ensure_parent_dir(path: &Path, context: &str) -> io::Result<()> {
    let Some(parent) = path.parent() else {
        return Ok(());
    };
    if parent.as_os_str().is_empty() || parent.exists() {
        return Ok(());
    }
    fs::create_dir_all(parent).map_err(|err| {
        io::Error::new(
            err.kind(),
            format!("create {context} directory {}: {err}", parent.display()),
        )
    })
}

fn zcnblk_maybe_set_file_len(path: &Path, file: &fs::File, bytes: u64) -> io::Result<()> {
    if fs::metadata(path)
        .map(|metadata| metadata.file_type().is_block_device())
        .unwrap_or(false)
    {
        return Ok(());
    }
    file.set_len(bytes).map_err(|err| {
        io::Error::new(
            err.kind(),
            format!(
                "size zcnblk tier file {} to {bytes} bytes: {err}",
                path.display()
            ),
        )
    })
}

fn zcnblk_tier_read_at_zero_fill(
    file: &fs::File,
    mut buf: &mut [u8],
    mut offset: u64,
) -> io::Result<()> {
    while !buf.is_empty() {
        match file.read_at(buf, offset) {
            Ok(0) => {
                buf.fill(0);
                return Ok(());
            }
            Ok(n) => {
                let (_, rest) = buf.split_at_mut(n);
                buf = rest;
                offset = offset.checked_add(n as u64).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "zcnblk tier read offset overflow",
                    )
                })?;
            }
            Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        }
    }
    Ok(())
}

fn zcnblk_tier_spill_loop(
    file: fs::File,
    rx: mpsc::Receiver<ZcnblkTierSpillItem>,
    backpressure: Arc<ZcTierBackpressure>,
) -> io::Result<ZcTierSpillStats> {
    let mut stats = ZcTierSpillStats::default();
    for item in rx {
        let len = item.data.len();
        let write_result = zc_write_all_at(&file, &item.data, item.offset);
        backpressure.release(len)?;
        write_result?;
        stats.bytes = stats.bytes.checked_add(len as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk tier spill byte count overflow",
            )
        })?;
        stats.chunks = stats.chunks.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk tier spill chunk count overflow",
            )
        })?;
    }
    Ok(stats)
}

fn zcnblk_tier_write_extent_bytes() -> io::Result<usize> {
    Ok(env_size_opt("URING_PLAY_ZCNBLK_TIER_WRITE_EXTENT_BYTES")?
        .unwrap_or(DEFAULT_ZCNBLK_TIER_WRITE_EXTENT_BYTES))
}

fn zcnblk_spawn_tier_spill(
    path: PathBuf,
    device_bytes: u64,
    queue_depth: usize,
    backpressure: Arc<ZcTierBackpressure>,
) -> ZcnblkTierBlockSpill {
    let label = format!("file:{}", path.display());
    let label_for_thread = label.clone();
    let bp_for_thread = Arc::clone(&backpressure);
    let (tx, rx) = mpsc::sync_channel::<ZcnblkTierSpillItem>(queue_depth);
    let handle = thread::spawn(move || {
        zcnblk_ensure_parent_dir(&path, "zcnblk tier spill")?;
        let file = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .custom_flags(libc::O_CLOEXEC)
            .open(&path)
            .map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!("open zcnblk tier spill {}: {err}", path.display()),
                )
            })?;
        zcnblk_maybe_set_file_len(&path, &file, device_bytes)?;
        zcnblk_tier_spill_loop(file, rx, bp_for_thread)
    });
    ZcnblkTierBlockSpill {
        label: label_for_thread,
        tx,
        handle,
        backpressure,
    }
}

impl ZcnblkTierRuntime {
    fn open(target: &ZcnblkTierTarget, queue_depth: usize) -> io::Result<Self> {
        let write_extent_bytes = zcnblk_tier_write_extent_bytes()?;
        zcnblk_ensure_parent_dir(&target.hot_path, "zcnblk tier hot")?;
        let hot = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .custom_flags(libc::O_CLOEXEC)
            .open(&target.hot_path)
            .map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!("open zcnblk tier hot {}: {err}", target.hot_path.display()),
                )
            })?;
        zcnblk_maybe_set_file_len(&target.hot_path, &hot, target.device_bytes)?;
        let read_fallback = if let Some(path) = target.spill_path.as_ref()
            && target.read_from_spill_on_open
        {
            Some(
                OpenOptions::new()
                    .read(true)
                    .custom_flags(libc::O_CLOEXEC)
                    .open(path)
                    .map_err(|err| {
                        io::Error::new(
                            err.kind(),
                            format!("open zcnblk tier read fallback {}: {err}", path.display()),
                        )
                    })?,
            )
        } else {
            None
        };
        let spill = target.spill_path.as_ref().map(|path| {
            zcnblk_spawn_tier_spill(
                path.clone(),
                target.device_bytes,
                queue_depth,
                Arc::clone(&target.backpressure),
            )
        });
        Ok(Self {
            hot,
            read_fallback,
            read_from_spill: target.read_from_spill_on_open,
            spill,
            write_extent_bytes,
            pending_offset: 0,
            pending_write: Vec::with_capacity(write_extent_bytes.min(1024 * 1024)),
        })
    }

    fn write_hot_and_spill_now(&mut self, offset: u64, data: &[u8]) -> io::Result<()> {
        zc_write_all_at(&self.hot, data, offset)?;
        let Some(spill) = self.spill.as_ref() else {
            return Ok(());
        };
        spill.backpressure.acquire(data.len())?;
        let item = ZcnblkTierSpillItem {
            offset,
            data: Arc::new(data.to_vec()),
        };
        let len = item.data.len();
        spill.tx.send(item).map_err(|err| {
            let _ = spill.backpressure.release(len);
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                format!("zcnblk tier spill {} exited: {err}", spill.label),
            )
        })
    }

    fn write_hot_and_spill_owned(&mut self, offset: u64, data: Vec<u8>) -> io::Result<()> {
        zc_write_all_at(&self.hot, &data, offset)?;
        let Some(spill) = self.spill.as_ref() else {
            return Ok(());
        };
        spill.backpressure.acquire(data.len())?;
        let len = data.len();
        let item = ZcnblkTierSpillItem {
            offset,
            data: Arc::new(data),
        };
        spill.tx.send(item).map_err(|err| {
            let _ = spill.backpressure.release(len);
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                format!("zcnblk tier spill {} exited: {err}", spill.label),
            )
        })
    }

    fn flush_pending_write(&mut self) -> io::Result<()> {
        if self.pending_write.is_empty() {
            return Ok(());
        }
        let offset = self.pending_offset;
        if self.spill.is_some() {
            let data = std::mem::replace(
                &mut self.pending_write,
                Vec::with_capacity(self.write_extent_bytes.min(1024 * 1024)),
            );
            self.write_hot_and_spill_owned(offset, data)
        } else {
            zc_write_all_at(&self.hot, &self.pending_write, offset)?;
            self.pending_write.clear();
            Ok(())
        }
    }

    fn write_hot_and_spill(
        &mut self,
        offset: u64,
        data: &[u8],
        flush_for_ack: bool,
    ) -> io::Result<()> {
        if self.write_extent_bytes == 0 || data.len() >= self.write_extent_bytes || flush_for_ack {
            self.flush_pending_write()?;
            self.write_hot_and_spill_now(offset, data)?;
            return Ok(());
        }

        if self.pending_write.is_empty() {
            self.pending_offset = offset;
        } else {
            let pending_end = self
                .pending_offset
                .checked_add(self.pending_write.len() as u64)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk tier offset overflow")
                })?;
            if pending_end != offset
                || self
                    .pending_write
                    .len()
                    .checked_add(data.len())
                    .is_none_or(|len| len > self.write_extent_bytes)
            {
                self.flush_pending_write()?;
                self.pending_offset = offset;
            }
        }
        self.pending_write.extend_from_slice(data);
        if self.pending_write.len() >= self.write_extent_bytes {
            self.flush_pending_write()?;
        }
        Ok(())
    }

    fn read_hot(&mut self, offset: u64, out: &mut [u8]) -> io::Result<()> {
        self.flush_pending_write()?;
        if self.read_from_spill
            && let Some(spill) = self.read_fallback.as_ref()
        {
            zcnblk_tier_read_at_zero_fill(spill, out, offset)?;
            zc_write_all_at(&self.hot, out, offset)?;
            return Ok(());
        }
        zcnblk_tier_read_at_zero_fill(&self.hot, out, offset)
    }

    fn finish(mut self) -> io::Result<Option<(String, ZcTierSpillStats, usize, usize)>> {
        self.flush_pending_write()?;
        let Some(spill) = self.spill else {
            return Ok(None);
        };
        let label = spill.label.clone();
        drop(spill.tx);
        let stats = spill
            .handle
            .join()
            .map_err(|_| io::Error::other(format!("zcnblk tier spill {label} panicked")))??;
        let (final_queued, max_queued) = spill.backpressure.snapshot()?;
        Ok(Some((label, stats, final_queued, max_queued)))
    }
}

fn parse_zcnblk_target_plans(
    target_spec: &str,
    chunk_bytes: usize,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<Vec<ZcnblkTargetPlan>> {
    let mut targets = Vec::new();
    let devnull_bytes =
        env_size_opt("URING_PLAY_ZCNBLK_DEVNULL_BYTES")?.unwrap_or(1024usize * 1024 * 1024 * 1024);
    let devnull_alignment = env_size_opt("URING_PLAY_ZCNBLK_DEVNULL_ALIGNMENT")?.unwrap_or(1);
    if devnull_alignment == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "URING_PLAY_ZCNBLK_DEVNULL_ALIGNMENT must be non-zero",
        ));
    }
    for token in target_spec.split(',') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }
        if let Some(plan) = zcnblk_parse_wal_target(token)? {
            targets.push(plan);
            continue;
        }
        if let Some(plan) = zcnblk_parse_raid0_target(token, chunk_bytes, buffer_mode)? {
            targets.push(plan);
            continue;
        }
        for expanded in zcnblk_expand_target_token(token)? {
            if let Some(plan) = zcnblk_parse_tier_target(&expanded)? {
                targets.push(plan);
                continue;
            }
            if zcnblk_is_devnull_target(&expanded) {
                targets.push(ZcnblkTargetPlan {
                    backend: ZcnblkTargetBackend::DevNull,
                    device_bytes: devnull_bytes as u64,
                    required_alignment: devnull_alignment,
                });
                continue;
            }
            let target = parse_slot_wal_target(&expanded)?;
            if !matches!(
                target.kind,
                SlotWalTargetKind::NullBlock
                    | SlotWalTargetKind::RamBlockDisk
                    | SlotWalTargetKind::ZcBlockRamDisk
                    | SlotWalTargetKind::PartUuid(_)
            ) {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "zcnblk-target accepts zcdevnullN, zctier:..., /dev/zcbrdN backing, Linux test block devices, or an allowlisted PARTUUID real device",
                ));
            }
            let metadata = fs::metadata(target.open_path())?;
            if !metadata.file_type().is_block_device() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("{} is not a block device", target.label()),
                ));
            }
            validate_slot_wal_write_target_safety(&target, &metadata)?;
            let required_alignment =
                validate_slot_wal_geometry_alignment(&metadata, chunk_bytes, chunk_bytes)?;
            let segment_bytes = buffer_mode.segment_bytes()?;
            validate_slot_wal_queue_limits(&metadata, chunk_bytes, segment_bytes, buffer_mode)?;
            let file = OpenOptions::new()
                .read(true)
                .custom_flags(libc::O_CLOEXEC)
                .open(target.open_path())?;
            let device_bytes = block_device_size(file.as_raw_fd())?;
            targets.push(ZcnblkTargetPlan {
                backend: ZcnblkTargetBackend::Block(target),
                device_bytes,
                required_alignment,
            });
        }
    }
    if targets.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target requires at least one target device",
        ));
    }
    Ok(targets)
}

fn zcnblk_wal_backend(targets: &[ZcnblkTargetPlan]) -> io::Result<Option<ZcnblkWalTarget>> {
    let mut wal_target: Option<ZcnblkWalTarget> = None;
    let mut saw_non_wal = false;
    for target in targets {
        match &target.backend {
            ZcnblkTargetBackend::Wal(wal) => {
                if let Some(existing) = wal_target.as_ref() {
                    if existing != wal {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "zcnblk-target zcwal mode requires all zcwal target shards to use the same WAL receiver",
                        ));
                    }
                } else {
                    wal_target = Some(wal.clone());
                }
            }
            _ => saw_non_wal = true,
        }
    }
    if wal_target.is_some() && saw_non_wal {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target cannot mix zcwal with block, tier, RAID, or devnull targets",
        ));
    }
    Ok(wal_target)
}

fn zcnblk_validate_wal_target_shape(
    wal: &ZcnblkWalTarget,
    bytes_per_connection: usize,
    chunk_bytes: usize,
) -> io::Result<()> {
    zcwal_validate_extent_shape(bytes_per_connection, wal.extent_bytes)?;
    if chunk_bytes % ZC_WAL_RECORD_SIZE != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target zcwal chunk-bytes must be a multiple of 4096",
        ));
    }
    if wal.extent_bytes % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target zcwal extent-bytes must be a multiple of chunk-bytes",
        ));
    }
    Ok(())
}

fn zcnblk_partition_accepted_streams(
    streams: Vec<TcpBenchAcceptedStream>,
    workers: usize,
    policy: TcpMuxShardPolicy,
    label: &str,
    pin_requested: bool,
) -> Vec<Vec<TcpBenchAcceptedStream>> {
    let mut shards = (0..workers).map(|_| Vec::new()).collect::<Vec<_>>();
    let mut counts = vec![0usize; workers];
    for (idx, accepted) in streams.into_iter().enumerate() {
        let worker = policy.choose_worker_with_pin(&accepted, idx, workers, pin_requested);
        println!(
            "{label}-mux-assignment: worker={worker} policy={} peer={} listener_lane={} \
             listener_port={} conn={} {}",
            policy.label(),
            accepted.peer_addr,
            accepted.lane,
            accepted.port,
            accepted.conn_index,
            socket_locality_label(accepted.locality)
        );
        counts[worker] += 1;
        shards[worker].push(accepted);
    }
    println!(
        "{label}-mux-assignment-summary: policy={} workers={workers} streams_by_worker={}",
        policy.label(),
        tcp_mux_counts_label(&counts)
    );
    shards
}

fn zcnblk_validate_frame_topology(
    frame: ZcnblkFrameHeader,
    stream_lane: usize,
    lane_base: usize,
    topology_lane_count: usize,
) -> io::Result<()> {
    if !frame.topology_valid() {
        return Ok(());
    }
    let expected_lane = lane_base.checked_add(stream_lane).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk target lane base overflow",
        )
    })?;
    if frame.topology.lane_id as usize != expected_lane {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk frame lane_id={} arrived on stream lane {stream_lane} expected_global_lane={expected_lane}",
                frame.topology.lane_id
            ),
        ));
    }
    if frame.topology.lane_count != 0 && frame.topology.lane_count as usize != topology_lane_count {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk frame lane_count={} does not match target topology_lane_count={topology_lane_count}",
                frame.topology.lane_count
            ),
        ));
    }
    if frame.topology.tier_id != frame.shard {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk frame tier_id={} does not match shard={}",
                frame.topology.tier_id, frame.shard
            ),
        ));
    }
    Ok(())
}

fn zcnblk_queue_block_io(
    ring: &mut RawRing,
    fds_by_shard: &[Option<i32>],
    fixed_file_by_shard: &[Option<u32>],
    buffers: &FixedSendBuffers,
    slot: usize,
    frame: ZcnblkFrameHeader,
    write_mode: TcpWalWriteMode,
) -> io::Result<()> {
    let shard = frame.shard as usize;
    if shard >= fds_by_shard.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk frame shard {shard} out of range {}",
                fds_by_shard.len()
            ),
        ));
    }
    let fd = fds_by_shard[shard].ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk shard {shard} has no block fd"),
        )
    })?;
    let fixed_file = fixed_file_by_shard[shard].ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk shard {shard} has no registered file index"),
        )
    });
    match write_mode {
        TcpWalWriteMode::Null => Ok(()),
        TcpWalWriteMode::Slot => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target does not support io-slot write mode yet; use fixed-file, fixed, write, or null",
        )),
        TcpWalWriteMode::Write => match frame.op {
            ZCNBLK_OP_WRITE => ring.queue_write(
                fd,
                buffers.ptr(slot).cast_const(),
                frame.len,
                frame.offset,
                slot as u64,
            ),
            ZCNBLK_OP_READ => {
                ring.queue_read(fd, buffers.ptr(slot), frame.len, frame.offset, slot as u64)
            }
            other => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zcnblk block queue got unsupported op {other}"),
            )),
        },
        TcpWalWriteMode::WriteFixed => match frame.op {
            ZCNBLK_OP_WRITE => ring.queue_write_fixed(
                fd,
                buffers.ptr(slot).cast_const(),
                frame.len,
                frame.offset,
                slot as u16,
                slot as u64,
            ),
            ZCNBLK_OP_READ => ring.queue_read_fixed(
                fd,
                buffers.ptr(slot),
                frame.len,
                frame.offset,
                slot as u16,
                slot as u64,
            ),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zcnblk block queue got unsupported op {other}"),
            )),
        },
        TcpWalWriteMode::WriteFixedFile => {
            let fixed_file = fixed_file?;
            match frame.op {
                ZCNBLK_OP_WRITE => ring.queue_write_fixed_file(
                    fixed_file,
                    buffers.ptr(slot).cast_const(),
                    frame.len,
                    frame.offset,
                    slot as u16,
                    slot as u64,
                ),
                ZCNBLK_OP_READ => ring.queue_read_fixed_file(
                    fixed_file,
                    buffers.ptr(slot),
                    frame.len,
                    frame.offset,
                    slot as u16,
                    slot as u64,
                ),
                other => Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("zcnblk block queue got unsupported op {other}"),
                )),
            }
        }
    }
}

fn zcnblk_raid0_map(
    runtime: &ZcnblkRaid0Runtime,
    offset: u64,
    len: usize,
) -> io::Result<(usize, u64, ZcnblkRaid0MemberRuntime)> {
    if runtime.members.is_empty() || runtime.stripe_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "zcraid0 runtime has no members or zero stripe bytes",
        ));
    }
    let stripe_bytes = runtime.stripe_bytes as u64;
    let stripe_off = offset % stripe_bytes;
    if stripe_off
        .checked_add(len as u64)
        .is_none_or(|end| end > stripe_bytes)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcraid0 request crosses a stripe boundary; use smaller frames or larger stripe bytes",
        ));
    }
    let stripe_no = offset / stripe_bytes;
    let member_idx = (stripe_no % runtime.members.len() as u64) as usize;
    let row = stripe_no / runtime.members.len() as u64;
    let member_offset = row
        .checked_mul(stripe_bytes)
        .and_then(|base| base.checked_add(stripe_off))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcraid0 offset overflow"))?;
    let member = runtime.members[member_idx];
    if len % member.required_alignment != 0 || member_offset % member.required_alignment as u64 != 0
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcraid0 member={member_idx} offset={member_offset} len={len} not aligned to {}",
                member.required_alignment
            ),
        ));
    }
    let member_end = member_offset.checked_add(len as u64).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "zcraid0 member range overflow")
    })?;
    if member_end > member.device_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcraid0 member={member_idx} range [{member_offset}..{member_end}) exceeds device bytes {}",
                member.device_bytes
            ),
        ));
    }
    Ok((member_idx, member_offset, member))
}

fn zcnblk_queue_raid0_io(
    ring: &mut RawRing,
    runtime: &ZcnblkRaid0Runtime,
    buffers: &FixedSendBuffers,
    slot: usize,
    frame: ZcnblkFrameHeader,
    io_mode: TcpWalWriteMode,
) -> io::Result<()> {
    let (_member_idx, member_offset, member) =
        zcnblk_raid0_map(runtime, frame.offset, frame.len as usize)?;
    match io_mode {
        TcpWalWriteMode::Null => Ok(()),
        TcpWalWriteMode::Slot => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target does not support io-slot write mode yet; use fixed-file, fixed, write, or null",
        )),
        TcpWalWriteMode::Write => match frame.op {
            ZCNBLK_OP_WRITE => ring.queue_write(
                member.fd,
                buffers.ptr(slot).cast_const(),
                frame.len,
                member_offset,
                slot as u64,
            ),
            ZCNBLK_OP_READ => ring.queue_read(
                member.fd,
                buffers.ptr(slot),
                frame.len,
                member_offset,
                slot as u64,
            ),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zcnblk raid0 queue got unsupported op {other}"),
            )),
        },
        TcpWalWriteMode::WriteFixed => match frame.op {
            ZCNBLK_OP_WRITE => ring.queue_write_fixed(
                member.fd,
                buffers.ptr(slot).cast_const(),
                frame.len,
                member_offset,
                slot as u16,
                slot as u64,
            ),
            ZCNBLK_OP_READ => ring.queue_read_fixed(
                member.fd,
                buffers.ptr(slot),
                frame.len,
                member_offset,
                slot as u16,
                slot as u64,
            ),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zcnblk raid0 queue got unsupported op {other}"),
            )),
        },
        TcpWalWriteMode::WriteFixedFile => {
            let fixed_file = member.fixed_file.ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk raid0 member has no registered file index",
                )
            })?;
            match frame.op {
                ZCNBLK_OP_WRITE => ring.queue_write_fixed_file(
                    fixed_file,
                    buffers.ptr(slot).cast_const(),
                    frame.len,
                    member_offset,
                    slot as u16,
                    slot as u64,
                ),
                ZCNBLK_OP_READ => ring.queue_read_fixed_file(
                    fixed_file,
                    buffers.ptr(slot),
                    frame.len,
                    member_offset,
                    slot as u16,
                    slot as u64,
                ),
                other => Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("zcnblk raid0 queue got unsupported op {other}"),
                )),
            }
        }
    }
}

fn zcnblk_send_read_response(
    streams: &mut [ZcnblkTransport],
    stream_idx: usize,
    flags: u16,
    shard: usize,
    len: usize,
    offset: u64,
    topology: ZcnblkFrameTopology,
    buffers: &FixedSendBuffers,
    slot: usize,
) -> io::Result<usize> {
    let header =
        ZcnblkFrameHeader::with_topology(ZCNBLK_OP_READ_RESP, flags, shard, len, offset, topology)?
            .encode();
    let payload = unsafe { slice::from_raw_parts(buffers.ptr(slot).cast_const(), len) };
    streams[stream_idx].write_frame_payload(&header, payload, true)
}

fn zcnblk_send_write_ack(
    streams: &mut [ZcnblkTransport],
    stream_idx: usize,
    flags: u16,
    shard: usize,
    len: usize,
    offset: u64,
    topology: ZcnblkFrameTopology,
) -> io::Result<usize> {
    let header =
        ZcnblkFrameHeader::with_topology(ZCNBLK_OP_WRITE_ACK, flags, shard, len, offset, topology)?
            .encode();
    streams[stream_idx].write_frame_payload(&header, &[], true)
}

fn write_all_iovecs(fd: i32, iovecs: &mut [libc::iovec], mut remaining: usize) -> io::Result<()> {
    let mut idx = 0usize;
    while remaining > 0 {
        while idx < iovecs.len() && iovecs[idx].iov_len == 0 {
            idx += 1;
        }
        if idx >= iovecs.len() {
            return Err(io::Error::new(
                io::ErrorKind::WriteZero,
                "writev exhausted iovecs before writing all bytes",
            ));
        }
        let iov_count = (iovecs.len() - idx).min(1024);
        let ret = unsafe { libc::writev(fd, iovecs[idx..].as_ptr(), iov_count as libc::c_int) };
        if ret < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        if ret == 0 {
            return Err(io::Error::new(
                io::ErrorKind::WriteZero,
                "writev wrote zero bytes",
            ));
        }
        let mut consumed = ret as usize;
        remaining = remaining.saturating_sub(consumed);
        while consumed > 0 {
            if consumed >= iovecs[idx].iov_len {
                consumed -= iovecs[idx].iov_len;
                iovecs[idx].iov_len = 0;
                idx += 1;
            } else {
                iovecs[idx].iov_base =
                    unsafe { (iovecs[idx].iov_base as *mut u8).add(consumed) }.cast();
                iovecs[idx].iov_len -= consumed;
                consumed = 0;
            }
        }
    }
    Ok(())
}

fn zcnblk_write_all_iovecs(
    stream: &mut ZcnblkTransport,
    iovecs: &mut [libc::iovec],
    total: usize,
) -> io::Result<()> {
    if !stream.is_encrypted() {
        return write_all_iovecs(stream.as_raw_fd(), iovecs, total);
    }
    let mut written = 0usize;
    for iov in iovecs {
        if iov.iov_len == 0 {
            continue;
        }
        let bytes = unsafe { slice::from_raw_parts(iov.iov_base.cast::<u8>(), iov.iov_len) };
        stream.write_all(bytes)?;
        written = written.checked_add(iov.iov_len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk encrypted iovec overflow",
            )
        })?;
    }
    if written != total {
        return Err(io::Error::new(
            io::ErrorKind::WriteZero,
            format!("zcnblk encrypted iovec wrote {written}/{total} bytes"),
        ));
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct ZcnblkReadyReadResponse {
    flags: u16,
    stream_idx: usize,
    shard: usize,
    len: usize,
    offset: u64,
    topology: ZcnblkFrameTopology,
    slot: usize,
}

fn zcnblk_send_read_response_batch(
    streams: &mut [ZcnblkTransport],
    stream_idx: usize,
    buffers: &FixedSendBuffers,
    reads: &[ZcnblkReadyReadResponse],
) -> io::Result<usize> {
    if reads.is_empty() {
        return Ok(0);
    }
    if streams[stream_idx].uses_payload_crypto() {
        let mut total = 0usize;
        for read in reads {
            total = total
                .checked_add(zcnblk_send_read_response(
                    streams,
                    stream_idx,
                    read.flags,
                    read.shard,
                    read.len,
                    read.offset,
                    read.topology,
                    buffers,
                    read.slot,
                )?)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                })?;
        }
        return Ok(total);
    }
    if reads.len() == 1 {
        let read = reads[0];
        return zcnblk_send_read_response(
            streams,
            stream_idx,
            read.flags,
            read.shard,
            read.len,
            read.offset,
            read.topology,
            buffers,
            read.slot,
        );
    }

    let payload_bytes = reads
        .iter()
        .try_fold(0usize, |acc, read| acc.checked_add(read.len))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcnblk response overflow"))?;
    let outer = ZcnblkFrameHeader::with_flags(
        ZCNBLK_OP_BATCH_RESP,
        0,
        0,
        reads.len(),
        payload_bytes as u64,
    )?
    .encode();
    let mut headers = Vec::with_capacity(reads.len());
    for read in reads {
        headers.push(
            ZcnblkFrameHeader::with_topology(
                ZCNBLK_OP_READ_RESP,
                read.flags,
                read.shard,
                read.len,
                read.offset,
                read.topology,
            )?
            .encode(),
        );
    }

    let mut iovecs = Vec::with_capacity(2 + reads.len());
    iovecs.push(libc::iovec {
        iov_base: outer.as_ptr().cast::<libc::c_void>().cast_mut(),
        iov_len: outer.len(),
    });
    iovecs.push(libc::iovec {
        iov_base: headers.as_ptr().cast::<libc::c_void>().cast_mut(),
        iov_len: headers.len() * ZCNBLK_FRAME_HEADER_LEN,
    });
    for read in reads {
        iovecs.push(libc::iovec {
            iov_base: buffers.ptr(read.slot).cast::<libc::c_void>(),
            iov_len: read.len,
        });
    }
    let total = ZCNBLK_FRAME_HEADER_LEN
        .checked_add(headers.len() * ZCNBLK_FRAME_HEADER_LEN)
        .and_then(|value| value.checked_add(payload_bytes))
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcnblk response overflow"))?;
    zcnblk_write_all_iovecs(&mut streams[stream_idx], &mut iovecs, total)?;
    Ok(total)
}

fn zcnblk_target_flush_ready_reads(
    streams: &mut [ZcnblkTransport],
    buffers: &FixedSendBuffers,
    slots: &mut [ZcnblkWriteSlot],
    free_slots: &mut Vec<usize>,
    ready_reads: &mut Vec<ZcnblkReadyReadResponse>,
    total_read: &mut usize,
    total_response: &mut usize,
    total_completed: &mut usize,
) -> io::Result<()> {
    if ready_reads.is_empty() {
        return Ok(());
    }
    let mut pending = Vec::new();
    std::mem::swap(ready_reads, &mut pending);
    let mut start = 0usize;
    while start < pending.len() {
        let stream_idx = pending[start].stream_idx;
        let mut end = start + 1;
        while end < pending.len() && pending[end].stream_idx == stream_idx {
            end += 1;
        }
        let group = &pending[start..end];
        *total_response = (*total_response)
            .checked_add(zcnblk_send_read_response_batch(
                streams, stream_idx, buffers, group,
            )?)
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
            })?;
        for read in group {
            *total_read = (*total_read).checked_add(read.len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total read overflow")
            })?;
            *total_completed = (*total_completed).checked_add(read.len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total complete overflow")
            })?;
            slots[read.slot] = ZcnblkWriteSlot::default();
            free_slots.push(read.slot);
        }
        start = end;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target_process_request_frame(
    targets: &[ZcnblkTargetPlan],
    streams: &mut [ZcnblkTransport],
    stream_idx: usize,
    frame: ZcnblkFrameHeader,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    write_acks: bool,
    write_mode: TcpWalWriteMode,
    read_mode: TcpWalWriteMode,
    ring: &mut RawRing,
    fds_by_shard: &[Option<i32>],
    fixed_file_by_shard: &[Option<u32>],
    raid0_by_shard: &[Option<ZcnblkRaid0Runtime>],
    tier_by_shard: &mut [Option<ZcnblkTierRuntime>],
    tier_queue_depth: usize,
    buffers: &FixedSendBuffers,
    slots: &mut [ZcnblkWriteSlot],
    slot: usize,
    free_slots: &mut Vec<usize>,
    logical_started: &mut [usize],
    issue_complete_streams: &mut usize,
    total_received: &mut usize,
    total_written: &mut usize,
    total_read: &mut usize,
    total_response: &mut usize,
    total_completed: &mut usize,
    frames: &mut usize,
    read_frames: &mut usize,
    write_frames: &mut usize,
) -> io::Result<bool> {
    if !matches!(frame.op, ZCNBLK_OP_WRITE | ZCNBLK_OP_READ) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk target request op {} is invalid", frame.op),
        ));
    }
    let len = frame.len as usize;
    if len == 0 || len > chunk_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk frame length {len} invalid for chunk_bytes={chunk_bytes}"),
        ));
    }
    let shard = frame.shard as usize;
    let Some(target) = targets.get(shard) else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk frame shard {shard} out of range {}", targets.len()),
        ));
    };
    if len % target.required_alignment != 0 || frame.offset % target.required_alignment as u64 != 0
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk frame shard={shard} offset={} len={len} not aligned to {}",
                frame.offset, target.required_alignment
            ),
        ));
    }
    let frame_end = frame.offset.checked_add(len as u64).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidData, "zcnblk frame offset overflow")
    })?;
    if frame_end > target.device_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk frame shard={shard} range [{}..{}) exceeds device bytes {}",
                frame.offset, frame_end, target.device_bytes
            ),
        ));
    }
    let next_started = logical_started[stream_idx]
        .checked_add(len)
        .ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk logical byte overflow")
        })?;
    if next_started > bytes_per_connection {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk stream {stream_idx} requested {next_started}/{bytes_per_connection} logical bytes"
            ),
        ));
    }

    if frame.op == ZCNBLK_OP_WRITE {
        let payload = unsafe { slice::from_raw_parts_mut(buffers.ptr(slot), len) };
        let header = frame.encode();
        streams[stream_idx].read_frame_payload(&header, payload, false)?;
        *total_received = (*total_received).checked_add(len).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk total receive overflow")
        })?;
        *write_frames += 1;
    } else {
        if streams[stream_idx].uses_payload_crypto() {
            let mut empty = [];
            let header = frame.encode();
            streams[stream_idx].read_frame_payload(&header, &mut empty, false)?;
        }
        *read_frames += 1;
    }
    logical_started[stream_idx] = next_started;
    if next_started == bytes_per_connection {
        *issue_complete_streams += 1;
    }
    *frames += 1;

    let io_mode = if frame.op == ZCNBLK_OP_READ {
        read_mode
    } else {
        write_mode
    };
    if io_mode.is_null() || target.backend.is_devnull() {
        if frame.op == ZCNBLK_OP_WRITE {
            *total_written = (*total_written).checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total write overflow")
            })?;
            if write_acks {
                *total_response = (*total_response)
                    .checked_add(zcnblk_send_write_ack(
                        streams,
                        stream_idx,
                        frame.flags,
                        shard,
                        len,
                        frame.offset,
                        frame.topology,
                    )?)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                    })?;
            }
        } else {
            let payload = unsafe { slice::from_raw_parts_mut(buffers.ptr(slot), len) };
            payload.fill(0);
            *total_response = (*total_response)
                .checked_add(zcnblk_send_read_response(
                    streams,
                    stream_idx,
                    frame.flags,
                    shard,
                    len,
                    frame.offset,
                    frame.topology,
                    buffers,
                    slot,
                )?)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                })?;
            *total_read = (*total_read).checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total read overflow")
            })?;
        }
        *total_completed = (*total_completed).checked_add(len).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk total complete overflow")
        })?;
        free_slots.push(slot);
        return Ok(false);
    }

    if let ZcnblkTargetBackend::Tier(tier_target) = &target.backend {
        let tier_count = tier_by_shard.len();
        let tier_slot = tier_by_shard.get_mut(shard).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("zcnblk tier shard {shard} out of runtime range {tier_count}"),
            )
        })?;
        if tier_slot.is_none() {
            *tier_slot = Some(ZcnblkTierRuntime::open(tier_target, tier_queue_depth)?);
        }
        let tier = tier_slot
            .as_mut()
            .expect("zcnblk tier runtime was opened above");
        if frame.op == ZCNBLK_OP_WRITE {
            let payload = unsafe { slice::from_raw_parts(buffers.ptr(slot).cast_const(), len) };
            tier.write_hot_and_spill(frame.offset, payload, write_acks)?;
            *total_written = (*total_written).checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total write overflow")
            })?;
            if write_acks {
                *total_response = (*total_response)
                    .checked_add(zcnblk_send_write_ack(
                        streams,
                        stream_idx,
                        frame.flags,
                        shard,
                        len,
                        frame.offset,
                        frame.topology,
                    )?)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                    })?;
            }
        } else {
            let payload = unsafe { slice::from_raw_parts_mut(buffers.ptr(slot), len) };
            tier.read_hot(frame.offset, payload)?;
            *total_response = (*total_response)
                .checked_add(zcnblk_send_read_response(
                    streams,
                    stream_idx,
                    frame.flags,
                    shard,
                    len,
                    frame.offset,
                    frame.topology,
                    buffers,
                    slot,
                )?)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                })?;
            *total_read = (*total_read).checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total read overflow")
            })?;
        }
        *total_completed = (*total_completed).checked_add(len).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk total complete overflow")
        })?;
        free_slots.push(slot);
        return Ok(false);
    }

    if matches!(target.backend, ZcnblkTargetBackend::Raid0(_)) {
        let runtime = raid0_by_shard
            .get(shard)
            .and_then(|runtime| runtime.as_ref())
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("zcnblk raid0 shard {shard} has no runtime"),
                )
            })?;
        slots[slot] = ZcnblkWriteSlot {
            op: frame.op,
            flags: frame.flags,
            stream_idx,
            shard,
            len: frame.len,
            offset: frame.offset,
            topology: frame.topology,
        };
        zcnblk_queue_raid0_io(ring, runtime, buffers, slot, frame, io_mode)?;
        return Ok(true);
    }

    slots[slot] = ZcnblkWriteSlot {
        op: frame.op,
        flags: frame.flags,
        stream_idx,
        shard,
        len: frame.len,
        offset: frame.offset,
        topology: frame.topology,
    };
    zcnblk_queue_block_io(
        ring,
        fds_by_shard,
        fixed_file_by_shard,
        buffers,
        slot,
        frame,
        io_mode,
    )?;
    Ok(true)
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target_complete_cqe(
    streams: &mut [ZcnblkTransport],
    slots: &mut [ZcnblkWriteSlot],
    free_slots: &mut Vec<usize>,
    ready_reads: &mut Vec<ZcnblkReadyReadResponse>,
    cqe: IoUringCqe32,
    write_acks: bool,
    outstanding: &mut usize,
    total_written: &mut usize,
    total_response: &mut usize,
    total_completed: &mut usize,
) -> io::Result<()> {
    *outstanding = (*outstanding).saturating_sub(1);
    let slot = cqe.user_data as usize;
    if slot >= slots.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk CQE invalid slot {slot}"),
        ));
    }
    if cqe.res < 0 {
        return Err(io::Error::from_raw_os_error(-cqe.res));
    }
    if cqe.res != slots[slot].len as i32 {
        return Err(io::Error::new(
            io::ErrorKind::WriteZero,
            format!(
                "short zcnblk completion op={} shard={} offset={} res={} expected={}",
                slots[slot].op, slots[slot].shard, slots[slot].offset, cqe.res, slots[slot].len
            ),
        ));
    }
    let completed_len = slots[slot].len as usize;
    if slots[slot].op == ZCNBLK_OP_WRITE {
        *total_written = (*total_written).checked_add(completed_len).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk total write overflow")
        })?;
        if write_acks {
            *total_response = (*total_response)
                .checked_add(zcnblk_send_write_ack(
                    streams,
                    slots[slot].stream_idx,
                    slots[slot].flags,
                    slots[slot].shard,
                    completed_len,
                    slots[slot].offset,
                    slots[slot].topology,
                )?)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                })?;
        }
    } else if slots[slot].op == ZCNBLK_OP_READ {
        ready_reads.push(ZcnblkReadyReadResponse {
            flags: slots[slot].flags,
            stream_idx: slots[slot].stream_idx,
            shard: slots[slot].shard,
            len: completed_len,
            offset: slots[slot].offset,
            topology: slots[slot].topology,
            slot,
        });
        return Ok(());
    }
    *total_completed = (*total_completed)
        .checked_add(completed_len)
        .ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk total complete overflow")
        })?;
    slots[slot] = ZcnblkWriteSlot::default();
    free_slots.push(slot);
    Ok(())
}

#[derive(Clone, Copy)]
struct ZcnblkWalPendingAck {
    flags: u16,
    shard: usize,
    len: usize,
    offset: u64,
    topology: ZcnblkFrameTopology,
}

struct ZcnblkWalSplicePipe {
    read_fd: i32,
    write_fd: i32,
}

impl ZcnblkWalSplicePipe {
    fn new() -> io::Result<Self> {
        let mut fds = [0i32; 2];
        let ret = unsafe { libc::pipe2(fds.as_mut_ptr(), libc::O_CLOEXEC) };
        if ret != 0 {
            return Err(io::Error::last_os_error());
        }
        let pipe = Self {
            read_fd: fds[0],
            write_fd: fds[1],
        };
        let pipe_bytes =
            env_size_opt("URING_PLAY_ZCNBLK_WAL_SPLICE_PIPE_BYTES")?.unwrap_or(1024 * 1024);
        if pipe_bytes != 0 {
            let _ = unsafe { libc::fcntl(pipe.read_fd, libc::F_SETPIPE_SZ, pipe_bytes) };
        }
        Ok(pipe)
    }
}

impl Drop for ZcnblkWalSplicePipe {
    fn drop(&mut self) {
        unsafe {
            libc::close(self.read_fd);
            libc::close(self.write_fd);
        }
    }
}

fn zcnblk_wal_splice_enabled() -> bool {
    env_enabled_or("URING_PLAY_ZCNBLK_WAL_SPLICE", true)
}

fn zcnblk_wal_splice_exact(
    pipe: &ZcnblkWalSplicePipe,
    src_fd: i32,
    dst_fd: i32,
    mut len: usize,
) -> io::Result<()> {
    while len != 0 {
        let request = len.min(1024 * 1024);
        let moved = loop {
            let ret = unsafe {
                libc::splice(
                    src_fd,
                    std::ptr::null_mut(),
                    pipe.write_fd,
                    std::ptr::null_mut(),
                    request,
                    libc::SPLICE_F_MOVE | libc::SPLICE_F_MORE,
                )
            };
            if ret < 0 {
                let err = io::Error::last_os_error();
                if err.kind() == io::ErrorKind::Interrupted {
                    continue;
                }
                return Err(err);
            }
            if ret == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::UnexpectedEof,
                    "zcnblk-target zcwal splice read EOF",
                ));
            }
            break ret as usize;
        };
        let mut drained = 0usize;
        while drained < moved {
            let ret = unsafe {
                libc::splice(
                    pipe.read_fd,
                    std::ptr::null_mut(),
                    dst_fd,
                    std::ptr::null_mut(),
                    moved - drained,
                    libc::SPLICE_F_MOVE | libc::SPLICE_F_MORE,
                )
            };
            if ret < 0 {
                let err = io::Error::last_os_error();
                if err.kind() == io::ErrorKind::Interrupted {
                    continue;
                }
                return Err(err);
            }
            if ret == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    "zcnblk-target zcwal splice wrote zero bytes",
                ));
            }
            drained += ret as usize;
        }
        len -= moved;
    }
    Ok(())
}

struct ZcnblkWalStreamState {
    meta: TcpBenchStreamMeta,
    wal_stream: TcpStream,
    payload: Vec<u8>,
    splice_pipe: Option<ZcnblkWalSplicePipe>,
    filled: usize,
    pending_acks: Vec<ZcnblkWalPendingAck>,
    extent_sequence: u64,
    next_logical_index: u64,
    wal_payload_bytes: usize,
    wal_wire_bytes: usize,
    wal_extents: usize,
    wal_acks: usize,
}

impl ZcnblkWalStreamState {
    fn connect(meta: TcpBenchStreamMeta, wal: &ZcnblkWalTarget) -> io::Result<Self> {
        let port = tcp_bench_port(wal.base_port, meta.lane)?;
        let stream = tcp_bench_connect(&wal.addr, port, None).map_err(|err| {
            io::Error::new(
                err.kind(),
                format!(
                    "zcnblk-target zcwal connect {}:{} lane={} conn={}: {err}",
                    wal.addr, port, meta.lane, meta.conn_index
                ),
            )
        })?;
        set_tcp_nodelay_from_env(&stream)?;
        set_tcp_bench_buffers(&stream);
        let splice_pipe = if zcnblk_wal_splice_enabled() {
            Some(ZcnblkWalSplicePipe::new()?)
        } else {
            None
        };
        println!(
            "zcnblk-target-zcwal-stream: listener_lane={} listener_port={} conn={} \
             wal_addr={} wal_port={} wal_extent_bytes={} splice_payload={}",
            meta.lane,
            meta.port,
            meta.conn_index,
            wal.addr,
            port,
            wal.extent_bytes,
            yes(splice_pipe.is_some())
        );
        Ok(Self {
            meta,
            wal_stream: stream,
            payload: vec![0u8; wal.extent_bytes],
            splice_pipe,
            filled: 0,
            pending_acks: Vec::with_capacity(wal.extent_bytes / ZC_WAL_RECORD_SIZE),
            extent_sequence: 0,
            next_logical_index: 0,
            wal_payload_bytes: 0,
            wal_wire_bytes: 0,
            wal_extents: 0,
            wal_acks: 0,
        })
    }

    fn extent_record_count(&self) -> io::Result<u32> {
        u32::try_from(self.payload.len() / ZC_WAL_RECORD_SIZE).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcnblk-target zcwal record count overflow",
            )
        })
    }

    fn extent_header(&self, lane_count: usize) -> io::Result<[u8; ZC_WAL_EXTENT_HEADER_LEN]> {
        let record_count = self.extent_record_count()?;
        let base_wal_offset = self
            .extent_sequence
            .checked_mul(self.payload.len() as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal offset overflow"))?;
        let descriptor_id = ((self.meta.lane as u64) << 48)
            | ((self.meta.conn_index as u64) << 32)
            | (self.extent_sequence & 0xffff_ffff);
        Ok(ZcWalExtentHeader {
            flags: 0,
            lane_id: self.meta.lane as u32,
            lane_count: lane_count as u32,
            shard_id: self.meta.lane as u32,
            record_size: ZC_WAL_RECORD_SIZE as u32,
            record_count,
            payload_len: self.payload.len() as u32,
            table_len: 0,
            base_logical_index: self.next_logical_index,
            extent_sequence: self.extent_sequence,
            base_wal_offset,
            wal_epoch: 0,
            descriptor_id,
            payload_crc32c: 0,
        }
        .encode())
    }

    fn begin_splice_extent(&mut self, lane_count: usize) -> io::Result<()> {
        if self.filled != 0 {
            return Ok(());
        }
        let header = self.extent_header(lane_count)?;
        self.wal_stream.write_all(&header)?;
        self.wal_wire_bytes = self
            .wal_wire_bytes
            .checked_add(ZC_WAL_EXTENT_HEADER_LEN)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal wire overflow"))?;
        Ok(())
    }

    fn flush_full_extent(
        &mut self,
        zcnblk_streams: &mut [ZcnblkTransport],
        stream_idx: usize,
        lane_count: usize,
        ack_wal: bool,
        ack_zcnblk: bool,
        payload_already_sent: bool,
    ) -> io::Result<usize> {
        if self.filled == 0 {
            return Ok(0);
        }
        if self.filled != self.payload.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "zcnblk-target zcwal stream lane={} conn={} has partial extent {} of {} bytes",
                    self.meta.lane,
                    self.meta.conn_index,
                    self.filled,
                    self.payload.len()
                ),
            ));
        }
        let record_count = self.extent_record_count()?;
        if !payload_already_sent {
            let header = self.extent_header(lane_count)?;
            self.wal_stream.write_all(&header)?;
            self.wal_stream.write_all(&self.payload)?;
            self.wal_payload_bytes =
                self.wal_payload_bytes
                    .checked_add(self.filled)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zcwal payload overflow")
                    })?;
            self.wal_wire_bytes = self
                .wal_wire_bytes
                .checked_add(ZC_WAL_EXTENT_HEADER_LEN + self.filled)
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal wire overflow"))?;
        }
        self.wal_extents = self
            .wal_extents
            .checked_add(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal extent overflow"))?;
        if ack_wal {
            let mut ack_buf = [0u8; ZC_WAL_ACK_HEADER_LEN];
            self.wal_stream.read_exact(&mut ack_buf)?;
            let ack = ZcWalAckHeader::decode(&ack_buf)?;
            if ack.status != 0
                || ack.lane_id as usize != self.meta.lane
                || ack.shard_id != ack.lane_id
                || ack.extent_sequence != self.extent_sequence
                || ack.record_size != ZC_WAL_RECORD_SIZE as u32
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-target zcwal ack mismatch lane={} conn={} seq={} got lane={} shard={} seq={} status={}",
                        self.meta.lane,
                        self.meta.conn_index,
                        self.extent_sequence,
                        ack.lane_id,
                        ack.shard_id,
                        ack.extent_sequence,
                        ack.status
                    ),
                ));
            }
            self.wal_acks = self
                .wal_acks
                .checked_add(1)
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal ack overflow"))?;
        }
        let mut response_bytes = 0usize;
        if ack_zcnblk {
            for pending in self.pending_acks.drain(..) {
                response_bytes = response_bytes
                    .checked_add(zcnblk_send_write_ack(
                        zcnblk_streams,
                        stream_idx,
                        pending.flags,
                        pending.shard,
                        pending.len,
                        pending.offset,
                        pending.topology,
                    )?)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zcnblk response overflow")
                    })?;
            }
        } else {
            self.pending_acks.clear();
        }
        self.filled = 0;
        self.extent_sequence = self
            .extent_sequence
            .checked_add(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal sequence overflow"))?;
        self.next_logical_index = self
            .next_logical_index
            .checked_add(record_count as u64)
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcwal logical index overflow")
            })?;
        Ok(response_bytes)
    }
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target_process_wal_frame(
    targets: &[ZcnblkTargetPlan],
    wal: &ZcnblkWalTarget,
    zcnblk_streams: &mut [ZcnblkTransport],
    stream_idx: usize,
    wal_state: &mut ZcnblkWalStreamState,
    frame: ZcnblkFrameHeader,
    lane_count: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    write_acks: bool,
    logical_started: &mut [usize],
    issue_complete_streams: &mut usize,
    total_received: &mut usize,
    total_response: &mut usize,
    frames: &mut usize,
    write_frames: &mut usize,
) -> io::Result<()> {
    if frame.op != ZCNBLK_OP_WRITE {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-target zcwal is a write onramp; op {} is not supported",
                frame.op
            ),
        ));
    }
    let len = frame.len as usize;
    if len == 0 || len > chunk_bytes || len % ZC_WAL_RECORD_SIZE != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-target zcwal frame length {len} invalid for chunk_bytes={chunk_bytes} record_size={ZC_WAL_RECORD_SIZE}",
            ),
        ));
    }
    let shard = frame.shard as usize;
    let Some(target) = targets.get(shard) else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk frame shard {shard} out of range {}", targets.len()),
        ));
    };
    if !matches!(target.backend, ZcnblkTargetBackend::Wal(_)) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk-target zcwal received non-wal shard {shard}"),
        ));
    }
    if len % target.required_alignment != 0 || frame.offset % target.required_alignment as u64 != 0
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-target zcwal shard={shard} offset={} len={len} not aligned to {}",
                frame.offset, target.required_alignment
            ),
        ));
    }
    let frame_end = frame.offset.checked_add(len as u64).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidData, "zcnblk frame offset overflow")
    })?;
    if frame_end > target.device_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-target zcwal shard={shard} range [{}..{}) exceeds device bytes {}",
                frame.offset, frame_end, target.device_bytes
            ),
        ));
    }
    let next_started = logical_started[stream_idx]
        .checked_add(len)
        .ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcnblk logical byte overflow")
        })?;
    if next_started > bytes_per_connection {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-target zcwal stream {stream_idx} requested {next_started}/{bytes_per_connection} logical bytes"
            ),
        ));
    }
    if len > wal.extent_bytes - wal_state.filled {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "zcnblk-target zcwal frame would cross an extent boundary; use extent-bytes as a multiple of chunk-bytes",
        ));
    }

    let header = frame.encode();
    let payload_spliced =
        wal_state.splice_pipe.is_some() && !zcnblk_streams[stream_idx].is_encrypted();
    if payload_spliced {
        wal_state.begin_splice_extent(lane_count)?;
        zcnblk_wal_splice_exact(
            wal_state.splice_pipe.as_ref().expect("checked splice pipe"),
            zcnblk_streams[stream_idx].as_raw_fd(),
            wal_state.wal_stream.as_raw_fd(),
            len,
        )?;
        wal_state.wal_payload_bytes = wal_state
            .wal_payload_bytes
            .checked_add(len)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal payload overflow"))?;
        wal_state.wal_wire_bytes = wal_state
            .wal_wire_bytes
            .checked_add(len)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal wire overflow"))?;
    } else {
        let start = wal_state.filled;
        let end = start + len;
        zcnblk_streams[stream_idx].read_frame_payload(
            &header,
            &mut wal_state.payload[start..end],
            false,
        )?;
    }
    wal_state.pending_acks.push(ZcnblkWalPendingAck {
        flags: frame.flags,
        shard,
        len,
        offset: frame.offset,
        topology: frame.topology,
    });
    wal_state.filled = wal_state
        .filled
        .checked_add(len)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal extent fill overflow"))?;
    *total_received = (*total_received).checked_add(len).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidData, "zcnblk total receive overflow")
    })?;
    logical_started[stream_idx] = next_started;
    if next_started == bytes_per_connection {
        *issue_complete_streams += 1;
    }
    *frames += 1;
    *write_frames += 1;

    if wal_state.filled == wal.extent_bytes {
        *total_response = (*total_response)
            .checked_add(wal_state.flush_full_extent(
                zcnblk_streams,
                stream_idx,
                lane_count,
                wal.ack_enabled,
                write_acks,
                payload_spliced,
            )?)
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
            })?;
    }
    Ok(())
}

fn zcnblk_read_batch_headers(
    stream: &mut ZcnblkTransport,
    count: usize,
    label: &str,
) -> io::Result<Vec<ZcnblkFrameHeader>> {
    let header_bytes_len = count.checked_mul(ZCNBLK_FRAME_HEADER_LEN).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} batch header byte count overflow"),
        )
    })?;
    let mut header_bytes = vec![0u8; header_bytes_len];
    stream.read_exact(&mut header_bytes)?;
    let mut batch_frames = Vec::with_capacity(count);
    for batch_buf in header_bytes.chunks_exact(ZCNBLK_FRAME_HEADER_LEN) {
        let batch_buf: &[u8; ZCNBLK_FRAME_HEADER_LEN] = batch_buf.try_into().map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("{label} batch header chunk length mismatch"),
            )
        })?;
        batch_frames.push(ZcnblkFrameHeader::decode(batch_buf)?);
    }
    Ok(batch_frames)
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target_process_wal_batch(
    targets: &[ZcnblkTargetPlan],
    wal: &ZcnblkWalTarget,
    zcnblk_streams: &mut [ZcnblkTransport],
    stream_idx: usize,
    wal_state: &mut ZcnblkWalStreamState,
    batch_frames: &[ZcnblkFrameHeader],
    lane_count: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    write_acks: bool,
    logical_started: &mut [usize],
    issue_complete_streams: &mut usize,
    total_received: &mut usize,
    total_response: &mut usize,
    frames: &mut usize,
    write_frames: &mut usize,
) -> io::Result<()> {
    let payload_spliced =
        wal_state.splice_pipe.is_some() && !zcnblk_streams[stream_idx].is_encrypted();
    let mut idx = 0usize;
    while idx < batch_frames.len() {
        let group_start = wal_state.filled;
        let mut group_bytes = 0usize;
        if payload_spliced {
            wal_state.begin_splice_extent(lane_count)?;
        }

        while idx < batch_frames.len() {
            let frame = batch_frames[idx];
            if frame.op != ZCNBLK_OP_WRITE {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-target zcwal batch is a write onramp; op {} is not supported",
                        frame.op
                    ),
                ));
            }
            let len = frame.len as usize;
            if len == 0 || len > chunk_bytes || len % ZC_WAL_RECORD_SIZE != 0 {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-target zcwal batch frame length {len} invalid for chunk_bytes={chunk_bytes} record_size={ZC_WAL_RECORD_SIZE}",
                    ),
                ));
            }
            let shard = frame.shard as usize;
            let Some(target) = targets.get(shard) else {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk batch frame shard {shard} out of range {}",
                        targets.len()
                    ),
                ));
            };
            if !matches!(target.backend, ZcnblkTargetBackend::Wal(_)) {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("zcnblk-target zcwal batch received non-wal shard {shard}"),
                ));
            }
            if len % target.required_alignment != 0
                || frame.offset % target.required_alignment as u64 != 0
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-target zcwal batch shard={shard} offset={} len={len} not aligned to {}",
                        frame.offset, target.required_alignment
                    ),
                ));
            }
            let frame_end = frame.offset.checked_add(len as u64).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk frame offset overflow")
            })?;
            if frame_end > target.device_bytes {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-target zcwal batch shard={shard} range [{}..{}) exceeds device bytes {}",
                        frame.offset, frame_end, target.device_bytes
                    ),
                ));
            }
            let next_started = logical_started[stream_idx]
                .checked_add(len)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk logical byte overflow")
                })?;
            if next_started > bytes_per_connection {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-target zcwal batch stream {stream_idx} requested {next_started}/{bytes_per_connection} logical bytes"
                    ),
                ));
            }
            if len > wal.extent_bytes - wal_state.filled {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-target zcwal batch frame would cross an extent boundary; use extent-bytes as a multiple of chunk-bytes",
                ));
            }

            wal_state.pending_acks.push(ZcnblkWalPendingAck {
                flags: frame.flags,
                shard,
                len,
                offset: frame.offset,
                topology: frame.topology,
            });
            wal_state.filled = wal_state.filled.checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcwal extent fill overflow")
            })?;
            logical_started[stream_idx] = next_started;
            if next_started == bytes_per_connection {
                *issue_complete_streams += 1;
            }
            *total_received = (*total_received).checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk total receive overflow")
            })?;
            *frames += 1;
            *write_frames += 1;
            group_bytes = group_bytes.checked_add(len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk batch payload overflow")
            })?;
            idx += 1;

            if wal_state.filled == wal.extent_bytes {
                break;
            }
        }

        if group_bytes == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-target zcwal batch made no payload progress",
            ));
        }
        if payload_spliced {
            zcnblk_wal_splice_exact(
                wal_state.splice_pipe.as_ref().expect("checked splice pipe"),
                zcnblk_streams[stream_idx].as_raw_fd(),
                wal_state.wal_stream.as_raw_fd(),
                group_bytes,
            )?;
            wal_state.wal_payload_bytes = wal_state
                .wal_payload_bytes
                .checked_add(group_bytes)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcwal payload overflow")
                })?;
            wal_state.wal_wire_bytes = wal_state
                .wal_wire_bytes
                .checked_add(group_bytes)
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal wire overflow"))?;
        } else {
            zcnblk_streams[stream_idx]
                .read_exact(&mut wal_state.payload[group_start..group_start + group_bytes])?;
        }

        if wal_state.filled == wal.extent_bytes {
            *total_response = (*total_response)
                .checked_add(wal_state.flush_full_extent(
                    zcnblk_streams,
                    stream_idx,
                    lane_count,
                    wal.ack_enabled,
                    write_acks,
                    payload_spliced,
                )?)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk total response overflow")
                })?;
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target_wal_worker(
    targets: Arc<Vec<ZcnblkTargetPlan>>,
    wal: ZcnblkWalTarget,
    worker: usize,
    mut streams: Vec<ZcnblkTransport>,
    stream_meta: Vec<TcpBenchStreamMeta>,
    lane_count: usize,
    topology_lane_base: usize,
    topology_lane_count: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    pipeline: usize,
    write_acks: bool,
    affinity: ThreadAffinity,
) -> io::Result<ZcnblkWorkerStats> {
    zcnblk_validate_wal_target_shape(&wal, bytes_per_connection, chunk_bytes)?;
    let stream_count = streams.len();
    let mut wal_states = stream_meta
        .into_iter()
        .map(|meta| ZcnblkWalStreamState::connect(meta, &wal))
        .collect::<io::Result<Vec<_>>>()?;
    let mut logical_started = vec![0usize; stream_count];
    let mut next_stream = 0usize;
    let mut issue_complete_streams = 0usize;
    let mut total_received = 0usize;
    let mut total_response = 0usize;
    let mut frames = 0usize;
    let mut batches = 0usize;
    let mut write_frames = 0usize;
    let mut completed_streams = vec![false; stream_count];
    let mut complete = 0usize;
    let batch_limit = pipeline.max(1);
    let started = Instant::now();

    while complete < stream_count {
        let mut progressed = false;
        for _ in 0..stream_count {
            let stream_idx = next_stream;
            next_stream = (next_stream + 1) % stream_count;
            if completed_streams[stream_idx] {
                continue;
            }
            if logical_started[stream_idx] == bytes_per_connection {
                if wal_states[stream_idx].filled != 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "zcnblk-target zcwal finished stream with a partial WAL extent",
                    ));
                }
                wal_states[stream_idx]
                    .wal_stream
                    .shutdown(Shutdown::Write)?;
                let _ = streams[stream_idx].shutdown(Shutdown::Both);
                completed_streams[stream_idx] = true;
                complete += 1;
                progressed = true;
                continue;
            }

            let mut header_buf = [0u8; ZCNBLK_FRAME_HEADER_LEN];
            streams[stream_idx].read_exact(&mut header_buf)?;
            let frame = ZcnblkFrameHeader::decode(&header_buf)?;

            if frame.op == ZCNBLK_OP_BATCH {
                batches = batches.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk batch count overflow")
                })?;
                if streams[stream_idx].uses_payload_crypto() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "zcnblk-target zcwal payload AES mode does not support request batches",
                    ));
                }
                let count = frame.len as usize;
                if count == 0 || count > batch_limit {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!(
                            "zcnblk-target zcwal batch count {count} invalid for pipeline={batch_limit}"
                        ),
                    ));
                }
                let batch_frames = zcnblk_read_batch_headers(
                    &mut streams[stream_idx],
                    count,
                    "zcnblk-target zcwal",
                )?;
                for batch_frame in &batch_frames {
                    zcnblk_validate_frame_topology(
                        *batch_frame,
                        wal_states[stream_idx].meta.lane,
                        topology_lane_base,
                        topology_lane_count,
                    )?;
                }
                zcnblk_target_process_wal_batch(
                    targets.as_ref(),
                    &wal,
                    &mut streams,
                    stream_idx,
                    &mut wal_states[stream_idx],
                    &batch_frames,
                    lane_count,
                    bytes_per_connection,
                    chunk_bytes,
                    write_acks,
                    &mut logical_started,
                    &mut issue_complete_streams,
                    &mut total_received,
                    &mut total_response,
                    &mut frames,
                    &mut write_frames,
                )?;
            } else {
                zcnblk_validate_frame_topology(
                    frame,
                    wal_states[stream_idx].meta.lane,
                    topology_lane_base,
                    topology_lane_count,
                )?;
                zcnblk_target_process_wal_frame(
                    targets.as_ref(),
                    &wal,
                    &mut streams,
                    stream_idx,
                    &mut wal_states[stream_idx],
                    frame,
                    lane_count,
                    bytes_per_connection,
                    chunk_bytes,
                    write_acks,
                    &mut logical_started,
                    &mut issue_complete_streams,
                    &mut total_received,
                    &mut total_response,
                    &mut frames,
                    &mut write_frames,
                )?;
            }
            progressed = true;
            break;
        }
        if !progressed {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "zcnblk-target zcwal made no progress",
            ));
        }
        if issue_complete_streams == stream_count {
            for idx in 0..stream_count {
                if completed_streams[idx] {
                    continue;
                }
                if wal_states[idx].filled != 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "zcnblk-target zcwal final stream has a partial WAL extent",
                    ));
                }
                wal_states[idx].wal_stream.shutdown(Shutdown::Write)?;
                let _ = streams[idx].shutdown(Shutdown::Both);
                completed_streams[idx] = true;
                complete += 1;
            }
        }
    }

    let mut wal_payload_bytes = 0usize;
    let mut wal_wire_bytes = 0usize;
    let mut wal_extents = 0usize;
    let mut wal_acks = 0usize;
    for state in &wal_states {
        wal_payload_bytes = wal_payload_bytes
            .checked_add(state.wal_payload_bytes)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal payload overflow"))?;
        wal_wire_bytes = wal_wire_bytes
            .checked_add(state.wal_wire_bytes)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal wire overflow"))?;
        wal_extents = wal_extents
            .checked_add(state.wal_extents)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal extent overflow"))?;
        wal_acks = wal_acks
            .checked_add(state.wal_acks)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "zcwal ack overflow"))?;
    }

    Ok(ZcnblkWorkerStats {
        worker,
        streams: stream_count,
        received_bytes: total_received,
        written_bytes: wal_payload_bytes,
        read_bytes: 0,
        response_bytes: total_response,
        wal_wire_bytes,
        wal_extents,
        wal_acks,
        frames,
        batches,
        read_frames: 0,
        write_frames,
        elapsed: started.elapsed(),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
    })
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target_worker(
    targets: Arc<Vec<ZcnblkTargetPlan>>,
    worker: usize,
    streams: Vec<TcpBenchAcceptedStream>,
    _lane_count: usize,
    topology_lane_base: usize,
    topology_lane_count: usize,
    connections_per_port: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    write_mode: TcpWalWriteMode,
    read_mode: TcpWalWriteMode,
    crypto_config: ZcnblkCryptoConfig,
    pin: bool,
) -> io::Result<ZcnblkWorkerStats> {
    let affinity = pin_current_thread_if_requested("zcnblk-target-worker", worker, pin);
    let stream_count = streams.len();
    if stream_count == 0 {
        return Ok(ZcnblkWorkerStats {
            worker,
            streams: 0,
            target_cpu: affinity.target_cpu,
            affinity_applied: affinity.applied,
            ..ZcnblkWorkerStats::default()
        });
    }

    let pipeline = pipeline.max(1);
    let ring_entries = ring_entries.max((pipeline as u32).saturating_mul(2).max(64));
    if pipeline > u16::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target pipeline must fit in u16 for fixed buffer indexes",
        ));
    }
    let wal_backend = zcnblk_wal_backend(targets.as_ref())?;
    if wal_backend.is_none()
        && (write_mode == TcpWalWriteMode::Slot || read_mode == TcpWalWriteMode::Slot)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target does not support io-slot mode yet; use fixed-file, fixed, write, or null",
        ));
    }
    let write_acks = env_enabled_or("URING_PLAY_ZCNBLK_WRITE_ACKS", false);

    let mut stream_lanes = Vec::with_capacity(stream_count);
    let mut stream_meta = Vec::with_capacity(stream_count);
    let mut streams = streams
        .into_iter()
        .map(|accepted| {
            let meta = accepted.meta();
            let lane = accepted.lane;
            let conn_index = accepted.conn_index;
            println!(
                "zcnblk-target-worker-stream: worker={worker} peer={} lane={} port={} conn={} {}",
                accepted.peer_addr,
                lane,
                accepted.port,
                conn_index,
                socket_locality_label(accepted.locality)
            );
            stream_lanes.push(lane);
            stream_meta.push(meta);
            let conn_id = zcnblk_transport_conn_id(lane, conn_index, connections_per_port)?;
            ZcnblkTransport::accept_target(accepted, conn_id, &crypto_config)
        })
        .collect::<io::Result<Vec<_>>>()?;

    if let Some(wal) = wal_backend {
        return zcnblk_target_wal_worker(
            targets,
            wal,
            worker,
            streams,
            stream_meta,
            _lane_count,
            topology_lane_base,
            topology_lane_count,
            bytes_per_connection,
            chunk_bytes,
            pipeline,
            write_acks,
            affinity,
        );
    }

    let mut open_shards = vec![true; targets.len()];
    if targets.len() == topology_lane_count && topology_lane_count != 0 {
        open_shards.fill(false);
        for lane in &stream_lanes {
            let shard = topology_lane_base.checked_add(*lane).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "zcnblk target lane base overflow",
                )
            })?;
            if shard >= targets.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!(
                        "zcnblk target worker lane {lane} maps to shard {shard}, but target count is {}",
                        targets.len()
                    ),
                ));
            }
            open_shards[shard] = true;
        }
    }

    let mut files = Vec::new();
    let mut fds_by_shard = vec![None; targets.len()];
    let mut fixed_file_by_shard = vec![None; targets.len()];
    let mut raid0_by_shard = (0..targets.len()).map(|_| None).collect::<Vec<_>>();
    let mut tier_by_shard = (0..targets.len()).map(|_| None).collect::<Vec<_>>();
    for (shard, target) in targets.iter().enumerate() {
        if !open_shards[shard] {
            continue;
        }
        if let ZcnblkTargetBackend::Raid0(raid0) = &target.backend {
            let mut members = Vec::with_capacity(raid0.members.len());
            for member in &raid0.members {
                let file = OpenOptions::new()
                    .read(true)
                    .write(true)
                    .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
                    .open(member.target.open_path())?;
                let fixed_file = u32::try_from(files.len()).map_err(|_| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "zcnblk fixed file index does not fit in u32",
                    )
                })?;
                members.push(ZcnblkRaid0MemberRuntime {
                    fd: file.as_raw_fd(),
                    fixed_file: Some(fixed_file),
                    device_bytes: member.device_bytes,
                    required_alignment: member.required_alignment,
                });
                files.push(file);
            }
            raid0_by_shard[shard] = Some(ZcnblkRaid0Runtime {
                members,
                stripe_bytes: raid0.stripe_bytes,
            });
            continue;
        }
        if matches!(target.backend, ZcnblkTargetBackend::Tier(_)) {
            continue;
        }
        let Some(path) = target.backend.open_path() else {
            continue;
        };
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
            .open(path)?;
        fds_by_shard[shard] = Some(file.as_raw_fd());
        fixed_file_by_shard[shard] = Some(u32::try_from(files.len()).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcnblk fixed file index does not fit in u32",
            )
        })?);
        files.push(file);
    }
    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    ring.register_napi_from_env(&format!("zcnblk-target-worker-{worker}"))?;
    let registered_files = (write_mode.needs_registered_files()
        || read_mode.needs_registered_files())
        && !files.is_empty();
    if registered_files {
        let mut registered_fds = files
            .iter()
            .map(|file| file.as_raw_fd())
            .collect::<Vec<_>>();
        ring.register_files(&mut registered_fds)?;
    }
    let opened_shards = fds_by_shard
        .iter()
        .enumerate()
        .filter_map(|(shard, fd)| fd.map(|_| shard.to_string()))
        .collect::<Vec<_>>()
        .join(",");
    let raid0_shards = raid0_by_shard
        .iter()
        .enumerate()
        .filter_map(|(shard, runtime)| {
            runtime.as_ref().map(|runtime| {
                format!("{shard}:{}x{}", runtime.members.len(), runtime.stripe_bytes)
            })
        })
        .collect::<Vec<_>>()
        .join(",");
    println!(
        "zcnblk-target-worker-files: worker={worker} opened_shards={} raid0_shards={} registered_files={registered_files}",
        if opened_shards.is_empty() {
            "-"
        } else {
            opened_shards.as_str()
        },
        if raid0_shards.is_empty() {
            "-"
        } else {
            raid0_shards.as_str()
        }
    );
    let buffers = buffer_mode.allocate(pipeline, chunk_bytes)?;
    let mut iovecs = buffers.iovecs(chunk_bytes);
    if write_mode.needs_registered_buffers() || read_mode.needs_registered_buffers() {
        ring.register_buffers(&mut iovecs)?;
    }

    let mut logical_started = vec![0usize; streams.len()];
    let mut slots = vec![ZcnblkWriteSlot::default(); pipeline];
    let mut free_slots = (0..pipeline).rev().collect::<Vec<_>>();
    let mut next_stream = 0usize;
    let mut issue_complete_streams = 0usize;
    let submit_batch = env_usize_or("URING_PLAY_ZCNBLK_SUBMIT_BATCH", pipeline.min(64)).max(1);
    let total_target = stream_count
        .checked_mul(bytes_per_connection)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcnblk total overflow"))?;
    let mut total_completed = 0usize;
    let mut total_received = 0usize;
    let mut total_written = 0usize;
    let mut total_read = 0usize;
    let mut total_response = 0usize;
    let mut frames = 0usize;
    let mut batches = 0usize;
    let mut read_frames = 0usize;
    let mut write_frames = 0usize;
    let mut outstanding = 0usize;
    let mut drain_outstanding = false;
    let mut ready_reads = Vec::with_capacity(pipeline);
    let started = Instant::now();

    while total_completed < total_target {
        if drain_outstanding && outstanding == 0 {
            drain_outstanding = false;
        }
        let mut queued_since_submit = 0usize;
        while !drain_outstanding && outstanding < pipeline && issue_complete_streams < streams.len()
        {
            if free_slots.is_empty() {
                break;
            }
            let mut stream_idx = None;
            for _ in 0..streams.len() {
                let candidate = next_stream;
                next_stream = (next_stream + 1) % streams.len();
                if logical_started[candidate] < bytes_per_connection {
                    stream_idx = Some(candidate);
                    break;
                }
            }
            let Some(stream_idx) = stream_idx else {
                break;
            };

            let mut header_buf = [0u8; ZCNBLK_FRAME_HEADER_LEN];
            streams[stream_idx].read_exact(&mut header_buf)?;
            let frame = ZcnblkFrameHeader::decode(&header_buf)?;

            if frame.op == ZCNBLK_OP_BATCH {
                batches = batches.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk batch count overflow")
                })?;
                if streams[stream_idx].uses_payload_crypto() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "zcnblk payload AES mode does not support request batches",
                    ));
                }
                let count = frame.len as usize;
                if count == 0 || count > pipeline {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!("zcnblk batch count {count} invalid for pipeline={pipeline}"),
                    ));
                }
                if count > free_slots.len() || count > pipeline.saturating_sub(outstanding) {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        format!(
                            "zcnblk batch count {count} exceeds free slots={} outstanding={outstanding} pipeline={pipeline}",
                            free_slots.len()
                        ),
                    ));
                }
                let batch_frames =
                    zcnblk_read_batch_headers(&mut streams[stream_idx], count, "zcnblk-target")?;
                let mut batch_queued = 0usize;
                for batch_frame in &batch_frames {
                    zcnblk_validate_frame_topology(
                        *batch_frame,
                        stream_lanes[stream_idx],
                        topology_lane_base,
                        topology_lane_count,
                    )?;
                }
                for batch_frame in batch_frames {
                    let slot = free_slots.pop().expect("batch free slot");
                    if zcnblk_target_process_request_frame(
                        targets.as_ref(),
                        &mut streams,
                        stream_idx,
                        batch_frame,
                        bytes_per_connection,
                        chunk_bytes,
                        write_acks,
                        write_mode,
                        read_mode,
                        &mut ring,
                        &fds_by_shard,
                        &fixed_file_by_shard,
                        &raid0_by_shard,
                        &mut tier_by_shard,
                        pipeline,
                        &buffers,
                        &mut slots,
                        slot,
                        &mut free_slots,
                        &mut logical_started,
                        &mut issue_complete_streams,
                        &mut total_received,
                        &mut total_written,
                        &mut total_read,
                        &mut total_response,
                        &mut total_completed,
                        &mut frames,
                        &mut read_frames,
                        &mut write_frames,
                    )? {
                        outstanding += 1;
                        queued_since_submit += 1;
                        batch_queued += 1;
                    }
                }
                if batch_queued > 1 {
                    drain_outstanding = true;
                }
            } else {
                let slot = free_slots.pop().expect("normal free slot");
                zcnblk_validate_frame_topology(
                    frame,
                    stream_lanes[stream_idx],
                    topology_lane_base,
                    topology_lane_count,
                )?;
                if zcnblk_target_process_request_frame(
                    targets.as_ref(),
                    &mut streams,
                    stream_idx,
                    frame,
                    bytes_per_connection,
                    chunk_bytes,
                    write_acks,
                    write_mode,
                    read_mode,
                    &mut ring,
                    &fds_by_shard,
                    &fixed_file_by_shard,
                    &raid0_by_shard,
                    &mut tier_by_shard,
                    pipeline,
                    &buffers,
                    &mut slots,
                    slot,
                    &mut free_slots,
                    &mut logical_started,
                    &mut issue_complete_streams,
                    &mut total_received,
                    &mut total_written,
                    &mut total_read,
                    &mut total_response,
                    &mut total_completed,
                    &mut frames,
                    &mut read_frames,
                    &mut write_frames,
                )? {
                    outstanding += 1;
                    queued_since_submit += 1;
                }
            }
            if queued_since_submit >= submit_batch {
                break;
            }
            // Submit queued IO before doing another blocking header read.
            if queued_since_submit > 0 {
                break;
            }
        }

        if outstanding == 0 {
            if total_completed == total_target {
                break;
            }
            if !ready_reads.is_empty() {
                zcnblk_target_flush_ready_reads(
                    &mut streams,
                    &buffers,
                    &mut slots,
                    &mut free_slots,
                    &mut ready_reads,
                    &mut total_read,
                    &mut total_response,
                    &mut total_completed,
                )?;
                continue;
            }
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "zcnblk-target made no progress and has no outstanding IO",
            ));
        }

        ring.submit_pending()?;
        let cqe = ring.wait_cqe()?;
        zcnblk_target_complete_cqe(
            &mut streams,
            &mut slots,
            &mut free_slots,
            &mut ready_reads,
            cqe,
            write_acks,
            &mut outstanding,
            &mut total_written,
            &mut total_response,
            &mut total_completed,
        )?;
        while outstanding > 0 {
            let Some(cqe) = ring.try_pop_cqe() else {
                break;
            };
            zcnblk_target_complete_cqe(
                &mut streams,
                &mut slots,
                &mut free_slots,
                &mut ready_reads,
                cqe,
                write_acks,
                &mut outstanding,
                &mut total_written,
                &mut total_response,
                &mut total_completed,
            )?;
        }
        if !drain_outstanding || outstanding == 0 {
            zcnblk_target_flush_ready_reads(
                &mut streams,
                &buffers,
                &mut slots,
                &mut free_slots,
                &mut ready_reads,
                &mut total_read,
                &mut total_response,
                &mut total_completed,
            )?;
        }
        if outstanding == 0 {
            drain_outstanding = false;
        }
    }

    if write_mode.needs_registered_buffers() || read_mode.needs_registered_buffers() {
        ring.unregister_buffers()?;
    }
    if registered_files {
        ring.unregister_files()?;
    }
    for stream in &streams {
        let _ = stream.shutdown(Shutdown::Both);
    }
    for (shard, tier) in tier_by_shard.into_iter().enumerate() {
        let Some(runtime) = tier else {
            continue;
        };
        if let Some((label, stats, final_queued, max_queued)) = runtime.finish()? {
            println!(
                "zcnblk-target-tier-spill: worker={worker} shard={shard} spill={} bytes={} chunks={} final_queued_bytes={} max_queued_bytes={}",
                label, stats.bytes, stats.chunks, final_queued, max_queued
            );
        }
    }

    Ok(ZcnblkWorkerStats {
        worker,
        streams: stream_count,
        received_bytes: total_received,
        written_bytes: total_written,
        read_bytes: total_read,
        response_bytes: total_response,
        wal_wire_bytes: 0,
        wal_extents: 0,
        wal_acks: 0,
        frames,
        batches,
        read_frames,
        write_frames,
        elapsed: started.elapsed(),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
    })
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_target(
    target_spec: &str,
    bind: &str,
    base_port: u16,
    ports: usize,
    connections_per_port: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    pipeline: usize,
    workers: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    pin_workers: bool,
) -> io::Result<()> {
    if bytes_per_connection == 0 || chunk_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target bytes-per-connection and chunk-bytes must be non-zero",
        ));
    }
    if bytes_per_connection % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target bytes-per-connection must be a multiple of chunk-bytes",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    let targets = Arc::new(parse_zcnblk_target_plans(
        target_spec,
        chunk_bytes,
        buffer_mode,
    )?);
    let wal_target = zcnblk_wal_backend(targets.as_ref())?;
    if let Some(wal) = wal_target.as_ref() {
        zcnblk_validate_wal_target_shape(wal, bytes_per_connection, chunk_bytes)?;
    }
    let crypto_config = ZcnblkCryptoConfig::from_env()?;
    let total_connections = tcp_bench_total_connections(ports, connections_per_port)?;
    let write_mode = TcpWalWriteMode::from_env()?;
    let read_mode = zcnblk_read_mode_from_env(write_mode)?;
    let write_acks = env_enabled_or("URING_PLAY_ZCNBLK_WRITE_ACKS", false);
    let tier_write_extent_bytes = zcnblk_tier_write_extent_bytes()?;
    if wal_target.is_none()
        && (write_mode == TcpWalWriteMode::Slot || read_mode == TcpWalWriteMode::Slot)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-target does not support io-slot mode yet; set URING_PLAY_TCP_WAL_WRITE_MODE and URING_PLAY_ZCNBLK_READ_MODE to fixed-file, fixed, write, or null",
        ));
    }
    let shard_policy =
        TcpMuxShardPolicy::from_env_or("URING_PLAY_ZCNBLK_SHARD", TcpMuxShardPolicy::PortLane)?;
    let topology_lane_base = env_usize_or("URING_PLAY_ZCNBLK_LANE_BASE", 0);
    let topology_lane_count = env_usize_or("URING_PLAY_ZCNBLK_TOTAL_LANES", ports);
    let workers = tcp_bench_auto_workers(workers, total_connections);
    let submit_batch = env_usize_or("URING_PLAY_ZCNBLK_SUBMIT_BATCH", pipeline.min(64)).max(1);
    zcnblk_warn_target_perf_contract(
        &targets,
        bind,
        ports,
        connections_per_port,
        total_connections,
        chunk_bytes,
        pipeline,
        ring_entries,
        buffer_mode,
        write_mode,
        read_mode,
        write_acks,
        shard_policy,
        workers,
        submit_batch,
        pin_workers,
    )?;
    let target_labels = targets
        .iter()
        .enumerate()
        .map(|(idx, target)| {
            format!(
                "{}:{}:{}B:align{}",
                idx,
                target.backend.label(),
                target.device_bytes,
                target.required_alignment
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let wal_label = wal_target
        .as_ref()
        .map(|wal| {
            format!(
                "{}:{}:extent{}:ack{}",
                wal.addr, wal.base_port, wal.extent_bytes, wal.ack_enabled
            )
        })
        .unwrap_or_else(|| "-".to_string());

    println!(
        "zcnblk-target: targets={} bind={bind} base_port={base_port} ports={ports} \
         connections_per_port={connections_per_port} total_connections={total_connections} \
         bytes_per_connection={bytes_per_connection} chunk_bytes={chunk_bytes} \
         pipeline={pipeline} workers={workers} ring_entries={ring_entries} \
         submit_batch={submit_batch} buffer_mode={} write_mode={} read_mode={} \
         write_acks={write_acks} tier_write_extent_bytes={tier_write_extent_bytes} \
         shard_policy={} topology_lane_base={topology_lane_base} \
         topology_lane_count={topology_lane_count} encryption={} aes_frame_bytes={} \
         pin_workers={pin_workers} wal_target={}",
        target_labels,
        buffer_mode.as_str(),
        write_mode.label(),
        read_mode.label(),
        shard_policy.label(),
        crypto_config.label(),
        crypto_config.max_frame_bytes,
        wal_label,
    );

    let listeners = tcp_bench_mux_bind_listeners(bind, base_port, ports)?;
    let accepted = tcp_bench_mux_accept_tagged_listeners(listeners, ports, connections_per_port)?;
    let shards = zcnblk_partition_accepted_streams(
        accepted,
        workers,
        shard_policy,
        "zcnblk-target",
        pin_workers,
    );
    let started = Instant::now();
    let mut handles = Vec::with_capacity(workers);
    for (worker_idx, shard) in shards.into_iter().enumerate() {
        if shard.is_empty() {
            continue;
        }
        let targets = Arc::clone(&targets);
        let crypto_config = crypto_config.clone();
        handles.push(thread::spawn(move || {
            let result = zcnblk_target_worker(
                targets,
                worker_idx,
                shard,
                ports,
                topology_lane_base,
                topology_lane_count,
                connections_per_port,
                bytes_per_connection,
                chunk_bytes,
                pipeline,
                ring_entries,
                buffer_mode,
                write_mode,
                read_mode,
                crypto_config,
                pin_workers,
            );
            if let Err(err) = &result {
                eprintln!("zcnblk-target-worker-error: worker={worker_idx} error={err}");
            }
            result
        }));
    }

    let mut total_received = 0usize;
    let mut total_written = 0usize;
    let mut total_read = 0usize;
    let mut total_response = 0usize;
    let mut total_wal_wire = 0usize;
    let mut total_wal_extents = 0usize;
    let mut total_wal_acks = 0usize;
    let mut total_frames = 0usize;
    let mut total_batches = 0usize;
    let mut total_read_frames = 0usize;
    let mut total_write_frames = 0usize;
    for handle in handles {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other("zcnblk target worker panicked"))??;
        let secs = stats.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        println!(
            "zcnblk-target-worker: worker={} streams={} received_bytes={} written_bytes={} \
             read_bytes={} response_bytes={} wal_wire_bytes={} wal_extents={} wal_acks={} \
             frames={} batches={} read_frames={} write_frames={} frames_per_sec={:.0} \
             seconds={secs:.6} logical_MiBps={:.2} \
             target_cpu={} affinity_applied={}",
            stats.worker,
            stats.streams,
            stats.received_bytes,
            stats.written_bytes,
            stats.read_bytes,
            stats.response_bytes,
            stats.wal_wire_bytes,
            stats.wal_extents,
            stats.wal_acks,
            stats.frames,
            stats.batches,
            stats.read_frames,
            stats.write_frames,
            stats.frames as f64 / secs,
            (stats.written_bytes + stats.read_bytes) as f64 / (1024.0 * 1024.0) / secs,
            stats.target_cpu,
            stats.affinity_applied
        );
        total_received += stats.received_bytes;
        total_written += stats.written_bytes;
        total_read += stats.read_bytes;
        total_response += stats.response_bytes;
        total_wal_wire += stats.wal_wire_bytes;
        total_wal_extents += stats.wal_extents;
        total_wal_acks += stats.wal_acks;
        total_frames += stats.frames;
        total_batches += stats.batches;
        total_read_frames += stats.read_frames;
        total_write_frames += stats.write_frames;
    }
    println!(
        "zcnblk-target-summary: received_bytes={total_received} written_bytes={total_written} \
         read_bytes={total_read} response_bytes={total_response} wal_wire_bytes={total_wal_wire} \
         wal_extents={total_wal_extents} wal_acks={total_wal_acks} frames={total_frames} \
         batches={total_batches} read_frames={total_read_frames} write_frames={total_write_frames} \
         frames_per_sec={:.0}",
        total_frames as f64 / started.elapsed().as_secs_f64().max(f64::MIN_POSITIVE)
    );
    print_tcp_bench_result(
        "zcnblk-target",
        total_written + total_read,
        started.elapsed(),
    );
    Ok(())
}

fn zcnblk_connect_specs(
    base_port: u16,
    ports: usize,
    connections_per_port: usize,
    source_ports: TcpSourcePortPlan,
    shard_count: usize,
    bytes_per_connection: usize,
) -> io::Result<Vec<ZcnblkConnectSpec>> {
    let mut specs = Vec::with_capacity(tcp_bench_total_connections(ports, connections_per_port)?);
    let mut shard_ordinals = vec![0usize; shard_count];
    let base_offset = env_size_opt("URING_PLAY_ZCNBLK_BASE_OFFSET_BYTES")?.unwrap_or(0) as u64;
    let map = env::var("URING_PLAY_ZCNBLK_SEND_SHARD")
        .unwrap_or_else(|_| "port-lane".to_string())
        .to_ascii_lowercase();
    let source_specs =
        tcp_bench_mux_connect_specs(base_port, ports, connections_per_port, source_ports)?;
    for (global_index, spec) in source_specs.into_iter().enumerate() {
        let shard = match map.as_str() {
            "" | "port-lane" | "lane" | "port" => spec.lane % shard_count,
            "round-robin" | "rr" => global_index % shard_count,
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!(
                        "unknown URING_PLAY_ZCNBLK_SEND_SHARD={other:?}; use port-lane or round-robin"
                    ),
                ));
            }
        };
        let ordinal = shard_ordinals[shard];
        shard_ordinals[shard] = shard_ordinals[shard].checked_add(1).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "zcnblk shard ordinal overflow")
        })?;
        let offset = base_offset
            .checked_add(
                (ordinal as u64)
                    .checked_mul(bytes_per_connection as u64)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidInput, "zcnblk offset overflow")
                    })?,
            )
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcnblk offset overflow"))?;
        specs.push(ZcnblkConnectSpec {
            spec,
            shard,
            base_offset: offset,
        });
    }
    Ok(specs)
}

fn zcnblk_partition_connect_specs(
    specs: Vec<ZcnblkConnectSpec>,
    workers: usize,
) -> Vec<Vec<ZcnblkConnectSpec>> {
    let mut shards = (0..workers).map(|_| Vec::new()).collect::<Vec<_>>();
    for (idx, spec) in specs.into_iter().enumerate() {
        shards[idx % workers].push(spec);
    }
    shards
}

fn zcnblk_latency_fields(prefix: &str, latency: &LatencyHistogram) -> String {
    format!(
        "{prefix}_count={} {prefix}_avg_ns={} {prefix}_min_ns={} \
         {prefix}_p50_ns={} {prefix}_p95_ns={} {prefix}_p99_ns={} \
         {prefix}_p999_ns={} {prefix}_max_ns={}",
        latency.count,
        latency.avg_ns(),
        latency.min_ns(),
        latency.percentile_ns(50, 100),
        latency.percentile_ns(95, 100),
        latency.percentile_ns(99, 100),
        latency.percentile_ns(999, 1000),
        latency.max_ns(),
    )
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_send_worker(
    worker: usize,
    addr: Arc<String>,
    specs: Vec<ZcnblkConnectSpec>,
    connections_per_port: usize,
    lane_count: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    payload_pattern: SendPayloadPattern,
    op_mode: ZcnblkOperationMode,
    access_pattern: ZcnblkAccessPattern,
    crypto_config: ZcnblkCryptoConfig,
    ready_barrier: Arc<Barrier>,
    start_barrier: Arc<Barrier>,
) -> io::Result<ZcnblkSendStats> {
    let affinity = maybe_pin_current_thread("zcnblk-send-worker", worker);
    let stream_count = specs.len();
    let mut streams = Vec::with_capacity(specs.len());
    for spec in &specs {
        let stream = tcp_bench_connect(addr.as_str(), spec.spec.port, spec.spec.source_port)
            .map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!(
                        "zcnblk connect {}:{} lane={} conn={}: {err}",
                        addr.as_str(),
                        spec.spec.port,
                        spec.spec.lane,
                        spec.spec.conn_index
                    ),
                )
            })?;
        set_tcp_nodelay_from_env(&stream)?;
        set_tcp_bench_buffers(&stream);
        println!(
            "zcnblk-send-stream: worker={worker} lane={} port={} conn={} shard={} base_offset={}",
            spec.spec.lane, spec.spec.port, spec.spec.conn_index, spec.shard, spec.base_offset
        );
        let conn_id =
            zcnblk_transport_conn_id(spec.spec.lane, spec.spec.conn_index, connections_per_port)?;
        streams.push(ZcnblkTransport::connect_client(
            stream,
            spec.spec.lane,
            conn_id,
            &crypto_config,
        )?);
    }

    let mut payload = vec![0u8; chunk_bytes];
    payload_pattern.fill(&mut payload);
    let mut read_buf = vec![0u8; chunk_bytes];
    let verify_reads = env_enabled_or("URING_PLAY_ZCNBLK_VERIFY_READS", false);
    let mut expected_buf = if verify_reads {
        vec![0u8; chunk_bytes]
    } else {
        Vec::new()
    };
    let read_window = env_usize_or("URING_PLAY_ZCNBLK_READ_WINDOW", 64).max(1);
    let wait_write_acks = env_enabled_or("URING_PLAY_ZCNBLK_WAIT_WRITE_ACKS", false);
    let batch_depth = env_usize_or("URING_PLAY_ZCNBLK_BATCH_DEPTH", 1).max(1);
    let latency_enabled = env_enabled_or("URING_PLAY_ZCNBLK_LATENCY", false);
    let drain_ready_responses = env_enabled_or("URING_PLAY_ZCNBLK_DRAIN_READY_RESPONSES", true);
    let write_window_default = batch_depth.saturating_mul(16).max(read_window);
    let write_window = env_usize_or("URING_PLAY_ZCNBLK_WRITE_WINDOW", write_window_default).max(1);
    let fan_batch_window = env_usize_or("URING_PLAY_ZCNBLK_WAL_BATCH_WINDOW", 16).max(1);
    let min_pipelined_write_window = batch_depth.saturating_mul(fan_batch_window);
    if worker == 0
        && zcnblk_perf_warnings_enabled()
        && wait_write_acks
        && batch_depth > 1
        && write_window < min_pipelined_write_window
    {
        eprintln!(
            "PERF WARNING: zcnblk-send write_window={write_window} is below \
             batch_depth({batch_depth}) * fan_batch_window({fan_batch_window}); \
             this forces upstream-idle drains in fan WAL and keeps effective leaf batches \
             smaller than the configured topology window"
        );
    }
    if worker == 0 && latency_enabled && op_mode != ZcnblkOperationMode::Read && !wait_write_acks {
        eprintln!(
            "PERF WARNING: URING_PLAY_ZCNBLK_LATENCY=1 cannot report write latency unless \
             URING_PLAY_ZCNBLK_WAIT_WRITE_ACKS=1; writes complete at issue time in this run"
        );
    }
    let mut issued = vec![0usize; streams.len()];
    let mut completed = vec![0usize; streams.len()];
    let mut in_flight_reads = vec![0usize; streams.len()];
    let mut in_flight_writes = vec![0usize; streams.len()];
    let mut done = vec![false; streams.len()];
    let mut complete = 0usize;
    let mut write_bytes = 0usize;
    let mut read_bytes = 0usize;
    let mut verified_read_bytes = 0usize;
    let mut read_checksum = 0u64;
    let mut expected_checksum = 0u64;
    let mut wire_bytes = 0usize;
    let mut frames = 0usize;
    let mut read_frames = 0usize;
    let mut write_frames = 0usize;
    let mut request_batches = 0usize;
    let mut request_batch_frames = 0usize;
    let mut max_request_batch_frames = 0usize;
    let mut write_batches = 0usize;
    let mut write_batch_frames = 0usize;
    let mut max_write_batch_frames = 0usize;
    let mut pending_write_latency = if latency_enabled {
        (0..streams.len())
            .map(|_| BTreeMap::<(u16, u64), ZcnblkPendingIo>::new())
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let mut pending_read_latency = if latency_enabled {
        (0..streams.len())
            .map(|_| BTreeMap::<(u16, u64), ZcnblkPendingIo>::new())
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let mut write_ack_latency = LatencyHistogram::new();
    let mut read_latency = LatencyHistogram::new();

    ready_barrier.wait();
    start_barrier.wait();
    let started = Instant::now();
    while complete < streams.len() {
        let mut progressed = false;
        for idx in 0..streams.len() {
            while issued[idx] < bytes_per_connection {
                let frame_index = issued[idx] / chunk_bytes;
                let op = op_mode.op_for_frame(frame_index);
                if op == ZCNBLK_OP_READ && in_flight_reads[idx] >= read_window {
                    break;
                }
                if op == ZCNBLK_OP_WRITE && wait_write_acks && in_flight_writes[idx] >= write_window
                {
                    break;
                }
                if op == ZCNBLK_OP_READ && op_mode == ZcnblkOperationMode::Read && batch_depth > 1 {
                    if streams[idx].uses_payload_crypto() {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "zcnblk-send payload AES mode does not support request batches",
                        ));
                    }
                    let remaining_frames =
                        (bytes_per_connection - issued[idx]).div_ceil(chunk_bytes);
                    let target_batch = batch_depth.min(read_window).min(remaining_frames);
                    let available_window = read_window.saturating_sub(in_flight_reads[idx]);
                    if available_window == 0 {
                        break;
                    }
                    if in_flight_reads[idx] > 0 && available_window < target_batch {
                        break;
                    }
                    let batch_limit = target_batch.min(available_window);
                    if batch_limit <= 1 {
                        // Let the ordinary single-frame path handle the tail.
                    } else {
                        let mut header_bytes =
                            Vec::with_capacity(batch_limit.saturating_mul(ZCNBLK_FRAME_HEADER_LEN));
                        let mut batch_pending = if latency_enabled {
                            Vec::with_capacity(batch_limit)
                        } else {
                            Vec::new()
                        };
                        let mut batch_count = 0usize;
                        while issued[idx] < bytes_per_connection && batch_count < batch_limit {
                            let frame_index = issued[idx] / chunk_bytes;
                            let len = (bytes_per_connection - issued[idx]).min(chunk_bytes);
                            let offset = access_pattern.offset(
                                &specs[idx],
                                issued[idx],
                                frame_index,
                                bytes_per_connection,
                                chunk_bytes,
                            )?;
                            let request_id = ((idx as u64) << 32) | frame_index as u64;
                            let topology = ZcnblkFrameTopology {
                                lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk lane exceeds u32",
                                    )
                                })?,
                                lane_count: u32::try_from(lane_count).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk lane count exceeds u32",
                                    )
                                })?,
                                preferred_worker: u32::try_from(worker).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk worker exceeds u32",
                                    )
                                })?,
                                queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk queue exceeds u32",
                                    )
                                })?,
                                request_id,
                                tier_id: u32::try_from(specs[idx].shard).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk tier exceeds u32",
                                    )
                                })?,
                                topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                            };
                            let frame = ZcnblkFrameHeader::with_topology(
                                ZCNBLK_OP_READ,
                                0,
                                specs[idx].shard,
                                len,
                                offset,
                                topology,
                            )?;
                            header_bytes.extend_from_slice(&frame.encode());
                            issued[idx] += len;
                            frames += 1;
                            read_frames += 1;
                            batch_count += 1;
                            if latency_enabled {
                                batch_pending.push((request_id, len, offset));
                            }
                            in_flight_reads[idx] += 1;
                        }
                        let outer = ZcnblkFrameHeader::with_topology(
                            ZCNBLK_OP_BATCH,
                            0,
                            0,
                            batch_count,
                            0,
                            ZcnblkFrameTopology {
                                lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk lane exceeds u32",
                                    )
                                })?,
                                lane_count: u32::try_from(lane_count).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk lane count exceeds u32",
                                    )
                                })?,
                                preferred_worker: u32::try_from(worker).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk worker exceeds u32",
                                    )
                                })?,
                                queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk queue exceeds u32",
                                    )
                                })?,
                                request_id: 0,
                                tier_id: 0,
                                topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                            },
                        )?
                        .encode();
                        let issued_at = if latency_enabled {
                            Some(Instant::now())
                        } else {
                            None
                        };
                        streams[idx].write_all(&outer)?;
                        streams[idx].write_all(&header_bytes)?;
                        if let Some(issued_at) = issued_at {
                            for (request_id, len, offset) in batch_pending {
                                zcnblk_track_pending_io(
                                    &mut pending_read_latency[idx],
                                    ZCNBLK_OP_READ,
                                    request_id,
                                    len,
                                    offset,
                                    issued_at,
                                )?;
                            }
                        }
                        wire_bytes = wire_bytes
                            .checked_add(ZCNBLK_FRAME_HEADER_LEN + header_bytes.len())
                            .ok_or_else(|| {
                                io::Error::new(io::ErrorKind::InvalidData, "zcnblk wire overflow")
                            })?;
                        request_batches = request_batches.checked_add(1).ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "zcnblk request batch overflow",
                            )
                        })?;
                        request_batch_frames = request_batch_frames
                            .checked_add(batch_count)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk request batch frame overflow",
                                )
                            })?;
                        max_request_batch_frames = max_request_batch_frames.max(batch_count);
                        progressed = true;
                        continue;
                    }
                }
                if op_mode == ZcnblkOperationMode::Mixed && batch_depth > 1 {
                    if streams[idx].uses_payload_crypto() {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "zcnblk-send payload AES mode does not support request batches",
                        ));
                    }
                    let remaining_frames =
                        (bytes_per_connection - issued[idx]).div_ceil(chunk_bytes);
                    let mut probe_issued = issued[idx];
                    let mut batch_count = 0usize;
                    let mut batch_payload_len = 0usize;
                    let mut batch_read_count = 0usize;
                    let mut batch_write_count = 0usize;
                    let mut header_bytes =
                        Vec::with_capacity(batch_depth.saturating_mul(ZCNBLK_FRAME_HEADER_LEN));
                    let mut payload_bytes =
                        Vec::with_capacity(batch_depth.saturating_mul(chunk_bytes / 2));
                    let mut batch_pending_reads = if latency_enabled {
                        Vec::with_capacity(batch_depth)
                    } else {
                        Vec::new()
                    };
                    let mut batch_pending_writes = if latency_enabled && wait_write_acks {
                        Vec::with_capacity(batch_depth)
                    } else {
                        Vec::new()
                    };
                    while probe_issued < bytes_per_connection && batch_count < batch_depth {
                        let batch_frame_index = probe_issued / chunk_bytes;
                        let batch_op = op_mode.op_for_frame(batch_frame_index);
                        if batch_op == ZCNBLK_OP_READ
                            && in_flight_reads[idx] + batch_read_count >= read_window
                        {
                            break;
                        }
                        if batch_op == ZCNBLK_OP_WRITE
                            && wait_write_acks
                            && in_flight_writes[idx] + batch_write_count >= write_window
                        {
                            break;
                        }
                        let len = (bytes_per_connection - probe_issued).min(chunk_bytes);
                        let offset = access_pattern.offset(
                            &specs[idx],
                            probe_issued,
                            batch_frame_index,
                            bytes_per_connection,
                            chunk_bytes,
                        )?;
                        let request_id = ((idx as u64) << 32) | batch_frame_index as u64;
                        let topology = ZcnblkFrameTopology {
                            lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk lane exceeds u32",
                                )
                            })?,
                            lane_count: u32::try_from(lane_count).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk lane count exceeds u32",
                                )
                            })?,
                            preferred_worker: u32::try_from(worker).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk worker exceeds u32",
                                )
                            })?,
                            queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk queue exceeds u32",
                                )
                            })?,
                            request_id,
                            tier_id: u32::try_from(specs[idx].shard).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk tier exceeds u32",
                                )
                            })?,
                            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                        };
                        let frame = ZcnblkFrameHeader::with_topology(
                            batch_op,
                            0,
                            specs[idx].shard,
                            len,
                            offset,
                            topology,
                        )?;
                        header_bytes.extend_from_slice(&frame.encode());
                        if batch_op == ZCNBLK_OP_WRITE {
                            if payload_pattern.is_offset_dependent() {
                                payload_pattern.fill_for_zcnblk(
                                    &mut payload[..len],
                                    specs[idx].shard,
                                    offset,
                                );
                            }
                            payload_bytes.extend_from_slice(&payload[..len]);
                            batch_payload_len =
                                batch_payload_len.checked_add(len).ok_or_else(|| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zcnblk mixed batch payload overflow",
                                    )
                                })?;
                            batch_write_count += 1;
                            if latency_enabled && wait_write_acks {
                                batch_pending_writes.push((request_id, len, offset));
                            }
                        } else {
                            batch_read_count += 1;
                            if latency_enabled {
                                batch_pending_reads.push((request_id, len, offset));
                            }
                        }
                        probe_issued += len;
                        batch_count += 1;
                    }
                    if batch_count == 0 {
                        break;
                    }
                    if batch_count == 1
                        && remaining_frames > 1
                        && (in_flight_reads[idx] != 0 || in_flight_writes[idx] != 0)
                    {
                        break;
                    }
                    if batch_count > 1 {
                        let outer = ZcnblkFrameHeader::with_topology(
                            ZCNBLK_OP_BATCH,
                            0,
                            0,
                            batch_count,
                            batch_payload_len as u64,
                            ZcnblkFrameTopology {
                                lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk lane exceeds u32",
                                    )
                                })?,
                                lane_count: u32::try_from(lane_count).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk lane count exceeds u32",
                                    )
                                })?,
                                preferred_worker: u32::try_from(worker).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk worker exceeds u32",
                                    )
                                })?,
                                queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidInput,
                                        "zcnblk queue exceeds u32",
                                    )
                                })?,
                                request_id: 0,
                                tier_id: 0,
                                topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                            },
                        )?
                        .encode();
                        let issued_at = if latency_enabled {
                            Some(Instant::now())
                        } else {
                            None
                        };
                        streams[idx].write_all(&outer)?;
                        streams[idx].write_all(&header_bytes)?;
                        streams[idx].write_all(&payload_bytes)?;
                        if let Some(issued_at) = issued_at {
                            for (request_id, len, offset) in batch_pending_reads {
                                zcnblk_track_pending_io(
                                    &mut pending_read_latency[idx],
                                    ZCNBLK_OP_READ,
                                    request_id,
                                    len,
                                    offset,
                                    issued_at,
                                )?;
                            }
                            if wait_write_acks {
                                for (request_id, len, offset) in batch_pending_writes {
                                    zcnblk_track_pending_io(
                                        &mut pending_write_latency[idx],
                                        ZCNBLK_OP_WRITE,
                                        request_id,
                                        len,
                                        offset,
                                        issued_at,
                                    )?;
                                }
                            }
                        }
                        issued[idx] = probe_issued;
                        frames += batch_count;
                        read_frames += batch_read_count;
                        write_frames += batch_write_count;
                        write_bytes =
                            write_bytes.checked_add(batch_payload_len).ok_or_else(|| {
                                io::Error::new(io::ErrorKind::InvalidData, "zcnblk write overflow")
                            })?;
                        in_flight_reads[idx] += batch_read_count;
                        if wait_write_acks {
                            in_flight_writes[idx] += batch_write_count;
                        } else {
                            completed[idx] = completed[idx]
                                .checked_add(batch_payload_len)
                                .ok_or_else(|| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zcnblk completion overflow",
                                    )
                                })?;
                        }
                        wire_bytes = wire_bytes
                            .checked_add(
                                ZCNBLK_FRAME_HEADER_LEN + header_bytes.len() + payload_bytes.len(),
                            )
                            .ok_or_else(|| {
                                io::Error::new(io::ErrorKind::InvalidData, "zcnblk wire overflow")
                            })?;
                        request_batches = request_batches.checked_add(1).ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "zcnblk request batch overflow",
                            )
                        })?;
                        request_batch_frames = request_batch_frames
                            .checked_add(batch_count)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk request batch frame overflow",
                                )
                            })?;
                        max_request_batch_frames = max_request_batch_frames.max(batch_count);
                        progressed = true;
                        continue;
                    }
                }
                if op == ZCNBLK_OP_WRITE && op_mode == ZcnblkOperationMode::Write && batch_depth > 1
                {
                    if streams[idx].uses_payload_crypto() {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "zcnblk-send payload AES mode does not support request batches",
                        ));
                    }
                    let batch_limit = if wait_write_acks {
                        batch_depth.min(write_window.saturating_sub(in_flight_writes[idx]))
                    } else {
                        batch_depth
                    };
                    if batch_limit == 0 {
                        break;
                    }
                    let mut header_bytes =
                        Vec::with_capacity(batch_limit.saturating_mul(ZCNBLK_FRAME_HEADER_LEN));
                    let mut payload_bytes =
                        Vec::with_capacity(batch_limit.saturating_mul(chunk_bytes));
                    let mut batch_pending = if latency_enabled && wait_write_acks {
                        Vec::with_capacity(batch_limit)
                    } else {
                        Vec::new()
                    };
                    let mut batch_count = 0usize;
                    let mut batch_payload_len = 0usize;
                    while issued[idx] < bytes_per_connection && batch_count < batch_limit {
                        let frame_index = issued[idx] / chunk_bytes;
                        let len = (bytes_per_connection - issued[idx]).min(chunk_bytes);
                        let offset = access_pattern.offset(
                            &specs[idx],
                            issued[idx],
                            frame_index,
                            bytes_per_connection,
                            chunk_bytes,
                        )?;
                        let request_id = ((idx as u64) << 32) | frame_index as u64;
                        let topology = ZcnblkFrameTopology {
                            lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk lane exceeds u32",
                                )
                            })?,
                            lane_count: u32::try_from(lane_count).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk lane count exceeds u32",
                                )
                            })?,
                            preferred_worker: u32::try_from(worker).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk worker exceeds u32",
                                )
                            })?,
                            queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk queue exceeds u32",
                                )
                            })?,
                            request_id,
                            tier_id: u32::try_from(specs[idx].shard).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk tier exceeds u32",
                                )
                            })?,
                            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                        };
                        let frame = ZcnblkFrameHeader::with_topology(
                            ZCNBLK_OP_WRITE,
                            0,
                            specs[idx].shard,
                            len,
                            offset,
                            topology,
                        )?;
                        header_bytes.extend_from_slice(&frame.encode());
                        if payload_pattern.is_offset_dependent() {
                            payload_pattern.fill_for_zcnblk(
                                &mut payload[..len],
                                specs[idx].shard,
                                offset,
                            );
                        }
                        payload_bytes.extend_from_slice(&payload[..len]);
                        issued[idx] += len;
                        frames += 1;
                        write_frames += 1;
                        write_bytes += len;
                        batch_count += 1;
                        batch_payload_len =
                            batch_payload_len.checked_add(len).ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk batch payload overflow",
                                )
                            })?;
                        if wait_write_acks {
                            if latency_enabled {
                                batch_pending.push((request_id, len, offset));
                            }
                            in_flight_writes[idx] += 1;
                        } else {
                            completed[idx] = completed[idx].checked_add(len).ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk completion overflow",
                                )
                            })?;
                        }
                    }
                    let outer = ZcnblkFrameHeader::with_topology(
                        ZCNBLK_OP_BATCH,
                        0,
                        0,
                        batch_count,
                        batch_payload_len as u64,
                        ZcnblkFrameTopology {
                            lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk lane exceeds u32",
                                )
                            })?,
                            lane_count: u32::try_from(lane_count).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk lane count exceeds u32",
                                )
                            })?,
                            preferred_worker: u32::try_from(worker).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk worker exceeds u32",
                                )
                            })?,
                            queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                                io::Error::new(
                                    io::ErrorKind::InvalidInput,
                                    "zcnblk queue exceeds u32",
                                )
                            })?,
                            request_id: 0,
                            tier_id: 0,
                            topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                        },
                    )?
                    .encode();
                    let issued_at = if latency_enabled && wait_write_acks {
                        Some(Instant::now())
                    } else {
                        None
                    };
                    streams[idx].write_all(&outer)?;
                    streams[idx].write_all(&header_bytes)?;
                    streams[idx].write_all(&payload_bytes)?;
                    if let Some(issued_at) = issued_at {
                        for (request_id, len, offset) in batch_pending {
                            zcnblk_track_pending_io(
                                &mut pending_write_latency[idx],
                                ZCNBLK_OP_WRITE,
                                request_id,
                                len,
                                offset,
                                issued_at,
                            )?;
                        }
                    }
                    wire_bytes = wire_bytes
                        .checked_add(
                            ZCNBLK_FRAME_HEADER_LEN + header_bytes.len() + payload_bytes.len(),
                        )
                        .ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidData, "zcnblk wire overflow")
                        })?;
                    write_batches = write_batches.checked_add(1).ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zcnblk write batch overflow")
                    })?;
                    write_batch_frames =
                        write_batch_frames.checked_add(batch_count).ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "zcnblk write batch frame overflow",
                            )
                        })?;
                    max_write_batch_frames = max_write_batch_frames.max(batch_count);
                    progressed = true;
                    continue;
                }
                let len = (bytes_per_connection - issued[idx]).min(chunk_bytes);
                let offset = access_pattern.offset(
                    &specs[idx],
                    issued[idx],
                    frame_index,
                    bytes_per_connection,
                    chunk_bytes,
                )?;
                let request_id = ((idx as u64) << 32) | frame_index as u64;
                let topology = ZcnblkFrameTopology {
                    lane_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidInput, "zcnblk lane exceeds u32")
                    })?,
                    lane_count: u32::try_from(lane_count).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidInput, "zcnblk lane count exceeds u32")
                    })?,
                    preferred_worker: u32::try_from(worker).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidInput, "zcnblk worker exceeds u32")
                    })?,
                    queue_id: u32::try_from(specs[idx].spec.lane).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidInput, "zcnblk queue exceeds u32")
                    })?,
                    request_id,
                    tier_id: u32::try_from(specs[idx].shard).map_err(|_| {
                        io::Error::new(io::ErrorKind::InvalidInput, "zcnblk tier exceeds u32")
                    })?,
                    topology_flags: ZCNBLK_TOPOLOGY_VALID | ZCNBLK_TOPOLOGY_PORT_LANE,
                };
                let frame = ZcnblkFrameHeader::with_topology(
                    op,
                    0,
                    specs[idx].shard,
                    len,
                    offset,
                    topology,
                )?;
                let header = frame.encode();
                issued[idx] += len;
                frames += 1;
                progressed = true;
                if op == ZCNBLK_OP_WRITE {
                    if payload_pattern.is_offset_dependent() {
                        payload_pattern.fill_for_zcnblk(
                            &mut payload[..len],
                            specs[idx].shard,
                            offset,
                        );
                    }
                    let issued_at = if latency_enabled && wait_write_acks {
                        Some(Instant::now())
                    } else {
                        None
                    };
                    wire_bytes +=
                        streams[idx].write_frame_payload(&header, &payload[..len], false)?;
                    write_bytes += len;
                    write_frames += 1;
                    if wait_write_acks {
                        if let Some(issued_at) = issued_at {
                            zcnblk_track_pending_io(
                                &mut pending_write_latency[idx],
                                ZCNBLK_OP_WRITE,
                                request_id,
                                len,
                                offset,
                                issued_at,
                            )?;
                        }
                        in_flight_writes[idx] += 1;
                    } else {
                        completed[idx] = completed[idx].checked_add(len).ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidData, "zcnblk completion overflow")
                        })?;
                    }
                } else {
                    let issued_at = if latency_enabled {
                        Some(Instant::now())
                    } else {
                        None
                    };
                    wire_bytes += streams[idx].write_frame_payload(&header, &[], false)?;
                    if let Some(issued_at) = issued_at {
                        zcnblk_track_pending_io(
                            &mut pending_read_latency[idx],
                            ZCNBLK_OP_READ,
                            request_id,
                            len,
                            offset,
                            issued_at,
                        )?;
                    }
                    in_flight_reads[idx] += 1;
                    read_frames += 1;
                }
            }
        }

        for idx in 0..streams.len() {
            let mut drained_for_stream = false;
            loop {
                if in_flight_reads[idx] == 0 && in_flight_writes[idx] == 0 {
                    break;
                }
                if drained_for_stream
                    && (!drain_ready_responses
                        || !zcnblk_fan_wal_upstream_next_request_ready(&streams[idx])?)
                {
                    break;
                }
                let mut response_header = [0u8; ZCNBLK_FRAME_HEADER_LEN];
                streams[idx].read_exact(&mut response_header)?;
                let response = ZcnblkFrameHeader::decode(&response_header)?;
                let expected_start = specs[idx].base_offset;
                let expected_end = specs[idx]
                    .base_offset
                    .checked_add(bytes_per_connection as u64)
                    .ok_or_else(|| {
                        io::Error::new(io::ErrorKind::InvalidData, "zcnblk expected range overflow")
                    })?;
                if response.op == ZCNBLK_OP_BATCH_RESP {
                    let count = response.len as usize;
                    let payload_bytes = usize::try_from(response.offset).map_err(|_| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "zcnblk batch response payload byte count overflow",
                        )
                    })?;
                    if count == 0 {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "zcnblk got an empty batch response",
                        ));
                    }
                    let batch_frames = zcnblk_read_batch_headers(
                        &mut streams[idx],
                        count,
                        "zcnblk-send-response",
                    )?;
                    wire_bytes = wire_bytes
                        .checked_add(
                            ZCNBLK_FRAME_HEADER_LEN
                                + count * ZCNBLK_FRAME_HEADER_LEN
                                + payload_bytes,
                        )
                        .ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidData, "zcnblk wire overflow")
                        })?;
                    let mut batch_payload_read = 0usize;
                    for member in batch_frames {
                        let len = member.len as usize;
                        let member_end =
                            member
                                .offset
                                .checked_add(member.len as u64)
                                .ok_or_else(|| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zcnblk batch response offset overflow",
                                    )
                                })?;
                        if member.shard as usize != specs[idx].shard
                            || len == 0
                            || len > chunk_bytes
                            || member.offset < expected_start
                            || member_end > expected_end
                        {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "zcnblk batch response member mismatch op={} shard={} len={} offset={}",
                                    member.op, member.shard, member.len, member.offset
                                ),
                            ));
                        }
                        if member.op == ZCNBLK_OP_WRITE_ACK {
                            if !wait_write_acks {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk got batched write ack while write acks are disabled",
                                ));
                            }
                            if in_flight_writes[idx] == 0 {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk write ack batch exceeded inflight writes",
                                ));
                            }
                            in_flight_writes[idx] -= 1;
                            if latency_enabled {
                                zcnblk_complete_pending_io(
                                    &mut pending_write_latency[idx],
                                    ZCNBLK_OP_WRITE,
                                    member.topology.request_id,
                                    len,
                                    member.offset,
                                    &mut write_ack_latency,
                                    "zcnblk batch write ack",
                                )?;
                            }
                        } else if member.op == ZCNBLK_OP_READ_RESP {
                            let next_payload_read =
                                batch_payload_read.checked_add(len).ok_or_else(|| {
                                    io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        "zcnblk batch response payload overflow",
                                    )
                                })?;
                            if next_payload_read > payload_bytes {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk batch response read payload exceeded outer byte count",
                                ));
                            }
                            streams[idx].read_exact(&mut read_buf[..len])?;
                            batch_payload_read = next_payload_read;
                            if latency_enabled {
                                zcnblk_complete_pending_io(
                                    &mut pending_read_latency[idx],
                                    ZCNBLK_OP_READ,
                                    member.topology.request_id,
                                    len,
                                    member.offset,
                                    &mut read_latency,
                                    "zcnblk batch read response",
                                )?;
                            }
                            if verify_reads {
                                payload_pattern.fill_for_zcnblk(
                                    &mut expected_buf[..len],
                                    specs[idx].shard,
                                    member.offset,
                                );
                                let got_checksum = checksum_bytes_scalar(&read_buf[..len]);
                                let want_checksum = checksum_bytes_scalar(&expected_buf[..len]);
                                read_checksum = read_checksum.wrapping_add(got_checksum);
                                expected_checksum = expected_checksum.wrapping_add(want_checksum);
                                if read_buf[..len] != expected_buf[..len] {
                                    let mismatch = read_buf[..len]
                                        .iter()
                                        .zip(&expected_buf[..len])
                                        .position(|(got, want)| got != want)
                                        .unwrap_or(0);
                                    return Err(io::Error::new(
                                        io::ErrorKind::InvalidData,
                                        format!(
                                            "zcnblk batch read verify mismatch stream={idx} shard={} offset={} len={len} mismatch_at={} got=0x{:02x} expected=0x{:02x} got_checksum=0x{got_checksum:016x} expected_checksum=0x{want_checksum:016x}",
                                            member.shard,
                                            member.offset,
                                            mismatch,
                                            read_buf[mismatch],
                                            expected_buf[mismatch],
                                        ),
                                    ));
                                }
                                verified_read_bytes =
                                    verified_read_bytes.checked_add(len).ok_or_else(|| {
                                        io::Error::new(
                                            io::ErrorKind::InvalidData,
                                            "zcnblk verified bytes overflow",
                                        )
                                    })?;
                            }
                            if in_flight_reads[idx] == 0 {
                                return Err(io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk read response batch exceeded inflight reads",
                                ));
                            }
                            in_flight_reads[idx] -= 1;
                            read_bytes += len;
                        } else {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!("zcnblk batch response got unsupported op={}", member.op),
                            ));
                        }
                        completed[idx] = completed[idx].checked_add(len).ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidData, "zcnblk completion overflow")
                        })?;
                    }
                    if batch_payload_read != payload_bytes {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "zcnblk batch response payload mismatch read={batch_payload_read} expected={payload_bytes}"
                            ),
                        ));
                    }
                    progressed = true;
                    drained_for_stream = true;
                    continue;
                }
                let len = response.len as usize;
                let response_end = response
                    .offset
                    .checked_add(response.len as u64)
                    .ok_or_else(|| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            "zcnblk response offset overflow",
                        )
                    })?;
                let response_header = response.encode();
                if response.op == ZCNBLK_OP_WRITE_ACK {
                    if !wait_write_acks
                        || response.shard as usize != specs[idx].shard
                        || len == 0
                        || len > chunk_bytes
                        || response.offset < expected_start
                        || response_end > expected_end
                    {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "zcnblk write ack mismatch op={} shard={} len={} offset={}",
                                response.op, response.shard, response.len, response.offset
                            ),
                        ));
                    }
                    let mut empty = [];
                    wire_bytes +=
                        streams[idx].read_frame_payload(&response_header, &mut empty, true)?
                            + ZCNBLK_FRAME_HEADER_LEN;
                    if in_flight_writes[idx] == 0 {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "zcnblk write ack exceeded inflight writes",
                        ));
                    }
                    in_flight_writes[idx] -= 1;
                    if latency_enabled {
                        zcnblk_complete_pending_io(
                            &mut pending_write_latency[idx],
                            ZCNBLK_OP_WRITE,
                            response.topology.request_id,
                            len,
                            response.offset,
                            &mut write_ack_latency,
                            "zcnblk write ack",
                        )?;
                    }
                } else {
                    if response.op != ZCNBLK_OP_READ_RESP
                        || response.shard as usize != specs[idx].shard
                        || len == 0
                        || len > chunk_bytes
                        || response.offset < expected_start
                        || response_end > expected_end
                    {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "zcnblk read response mismatch op={} shard={} len={} offset={}",
                                response.op, response.shard, response.len, response.offset
                            ),
                        ));
                    }
                    wire_bytes += streams[idx].read_frame_payload(
                        &response_header,
                        &mut read_buf[..len],
                        true,
                    )? + ZCNBLK_FRAME_HEADER_LEN;
                    if latency_enabled {
                        zcnblk_complete_pending_io(
                            &mut pending_read_latency[idx],
                            ZCNBLK_OP_READ,
                            response.topology.request_id,
                            len,
                            response.offset,
                            &mut read_latency,
                            "zcnblk read response",
                        )?;
                    }
                    if verify_reads {
                        payload_pattern.fill_for_zcnblk(
                            &mut expected_buf[..len],
                            specs[idx].shard,
                            response.offset,
                        );
                        let got_checksum = checksum_bytes_scalar(&read_buf[..len]);
                        let want_checksum = checksum_bytes_scalar(&expected_buf[..len]);
                        read_checksum = read_checksum.wrapping_add(got_checksum);
                        expected_checksum = expected_checksum.wrapping_add(want_checksum);
                        if read_buf[..len] != expected_buf[..len] {
                            let mismatch = read_buf[..len]
                                .iter()
                                .zip(&expected_buf[..len])
                                .position(|(got, want)| got != want)
                                .unwrap_or(0);
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "zcnblk read verify mismatch stream={idx} shard={} offset={} len={len} mismatch_at={} got=0x{:02x} expected=0x{:02x} got_checksum=0x{got_checksum:016x} expected_checksum=0x{want_checksum:016x}",
                                    response.shard,
                                    response.offset,
                                    mismatch,
                                    read_buf[mismatch],
                                    expected_buf[mismatch],
                                ),
                            ));
                        }
                        verified_read_bytes =
                            verified_read_bytes.checked_add(len).ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "zcnblk verified bytes overflow",
                                )
                            })?;
                    }
                    if in_flight_reads[idx] == 0 {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "zcnblk read response exceeded inflight reads",
                        ));
                    }
                    in_flight_reads[idx] -= 1;
                    read_bytes += len;
                }
                completed[idx] = completed[idx].checked_add(len).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk completion overflow")
                })?;
                progressed = true;
                drained_for_stream = true;
            }
        }

        for idx in 0..streams.len() {
            if !done[idx]
                && issued[idx] == bytes_per_connection
                && completed[idx] == bytes_per_connection
                && in_flight_reads[idx] == 0
                && in_flight_writes[idx] == 0
            {
                done[idx] = true;
                complete += 1;
                streams[idx].shutdown(Shutdown::Write).ok();
            }
        }

        if !progressed {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "zcnblk-send made no progress",
            ));
        }
    }

    if latency_enabled {
        for idx in 0..streams.len() {
            if !pending_write_latency[idx].is_empty() || !pending_read_latency[idx].is_empty() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-send finished with pending latency entries stream={idx} writes={} reads={}",
                        pending_write_latency[idx].len(),
                        pending_read_latency[idx].len()
                    ),
                ));
            }
        }
    }

    Ok(ZcnblkSendStats {
        worker,
        streams: stream_count,
        write_bytes,
        read_bytes,
        verified_read_bytes,
        read_checksum,
        expected_checksum,
        wire_bytes,
        frames,
        read_frames,
        write_frames,
        request_batches,
        request_batch_frames,
        max_request_batch_frames,
        write_batches,
        write_batch_frames,
        max_write_batch_frames,
        elapsed: started.elapsed(),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        write_ack_latency,
        read_latency,
    })
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_send(
    addr: &str,
    shard_count: usize,
    base_port: u16,
    ports: usize,
    connections_per_port: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    workers: usize,
) -> io::Result<()> {
    if shard_count == 0 || bytes_per_connection == 0 || chunk_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-send shard-count, bytes-per-connection, and chunk-bytes must be non-zero",
        ));
    }
    if bytes_per_connection % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-send bytes-per-connection must be a multiple of chunk-bytes",
        ));
    }
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    let payload_pattern = SendPayloadPattern::from_env(chunk_bytes)?;
    payload_pattern.validate(bytes_per_connection, chunk_bytes)?;
    let op_mode = ZcnblkOperationMode::from_env()?;
    let access_pattern = ZcnblkAccessPattern::from_env(bytes_per_connection, chunk_bytes)?;
    let verify_reads = env_enabled_or("URING_PLAY_ZCNBLK_VERIFY_READS", false);
    let read_window = env_usize_or("URING_PLAY_ZCNBLK_READ_WINDOW", 64).max(1);
    let wait_write_acks = env_enabled_or("URING_PLAY_ZCNBLK_WAIT_WRITE_ACKS", false);
    let batch_depth = env_usize_or("URING_PLAY_ZCNBLK_BATCH_DEPTH", 1).max(1);
    let latency_enabled = env_enabled_or("URING_PLAY_ZCNBLK_LATENCY", false);
    let drain_ready_responses = env_enabled_or("URING_PLAY_ZCNBLK_DRAIN_READY_RESPONSES", true);
    let write_window_default = batch_depth.saturating_mul(16).max(read_window);
    let write_window = env_usize_or("URING_PLAY_ZCNBLK_WRITE_WINDOW", write_window_default).max(1);
    let source_ports = TcpSourcePortPlan::from_env()?;
    let source_ip = tcp_bench_source_ip_from_env()?;
    let crypto_config = ZcnblkCryptoConfig::from_env()?;
    let total_connections = tcp_bench_total_connections(ports, connections_per_port)?;
    let workers = tcp_bench_auto_workers(workers, total_connections);
    let specs = zcnblk_connect_specs(
        base_port,
        ports,
        connections_per_port,
        source_ports,
        shard_count,
        bytes_per_connection,
    )?;
    let shards = zcnblk_partition_connect_specs(specs, workers);
    let active_workers = shards.iter().filter(|shard| !shard.is_empty()).count();
    let ready_barrier = Arc::new(Barrier::new(active_workers + 1));
    let start_barrier = Arc::new(Barrier::new(active_workers + 1));
    let addr = Arc::new(addr.to_string());

    println!(
        "zcnblk-send: addr={} shard_count={shard_count} base_port={base_port} ports={ports} \
         connections_per_port={connections_per_port} total_connections={total_connections} \
         bytes_per_connection={bytes_per_connection} chunk_bytes={chunk_bytes} \
         workers={workers} op_mode={} read_window={read_window} write_window={write_window} \
         access={} verify_reads={} wait_write_acks={} batch_depth={batch_depth} \
         drain_ready_responses={} payload_pattern={} source_ip={} \
         source_ports={} latency={} encryption={} aes_frame_bytes={}",
        addr,
        op_mode.label(),
        access_pattern.label(),
        yes(verify_reads),
        yes(wait_write_acks),
        yes(drain_ready_responses),
        payload_pattern.label(),
        source_ip
            .map(|ip| ip.to_string())
            .unwrap_or_else(|| "kernel-route".to_string()),
        source_ports.label(),
        yes(latency_enabled),
        crypto_config.label(),
        crypto_config.max_frame_bytes,
    );

    let mut handles = Vec::with_capacity(workers);
    for (worker_idx, shard) in shards.into_iter().enumerate() {
        if shard.is_empty() {
            continue;
        }
        let addr = Arc::clone(&addr);
        let ready_barrier = Arc::clone(&ready_barrier);
        let start_barrier = Arc::clone(&start_barrier);
        let crypto_config = crypto_config.clone();
        handles.push(thread::spawn(move || {
            zcnblk_send_worker(
                worker_idx,
                addr,
                shard,
                connections_per_port,
                ports,
                bytes_per_connection,
                chunk_bytes,
                payload_pattern,
                op_mode,
                access_pattern,
                crypto_config,
                ready_barrier,
                start_barrier,
            )
        }));
    }
    ready_barrier.wait();
    let started = Instant::now();
    start_barrier.wait();

    let mut total_write = 0usize;
    let mut total_read = 0usize;
    let mut total_verified_read = 0usize;
    let mut total_read_checksum = 0u64;
    let mut total_expected_checksum = 0u64;
    let mut total_wire = 0usize;
    let mut total_frames = 0usize;
    let mut total_read_frames = 0usize;
    let mut total_write_frames = 0usize;
    let mut total_request_batches = 0usize;
    let mut total_request_batch_frames = 0usize;
    let mut total_max_request_batch_frames = 0usize;
    let mut total_write_batches = 0usize;
    let mut total_write_batch_frames = 0usize;
    let mut total_max_write_batch_frames = 0usize;
    let mut total_write_ack_latency = LatencyHistogram::new();
    let mut total_read_latency = LatencyHistogram::new();
    let mut elapsed = started.elapsed();
    for handle in handles {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other("zcnblk send worker panicked"))??;
        let secs = stats.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        println!(
            "zcnblk-send-worker: worker={} streams={} write_bytes={} read_bytes={} \
             verified_read_bytes={} read_checksum=0x{:016x} expected_checksum=0x{:016x} \
             wire_bytes={} frames={} read_frames={} write_frames={} frames_per_sec={:.0} \
             request_batches={} request_batch_frames={} max_request_batch_frames={} \
             write_batches={} write_batch_frames={} max_write_batch_frames={} \
             seconds={secs:.6} logical_MiBps={:.2} \
             target_cpu={} affinity_applied={}",
            stats.worker,
            stats.streams,
            stats.write_bytes,
            stats.read_bytes,
            stats.verified_read_bytes,
            stats.read_checksum,
            stats.expected_checksum,
            stats.wire_bytes,
            stats.frames,
            stats.read_frames,
            stats.write_frames,
            stats.frames as f64 / secs,
            stats.request_batches,
            stats.request_batch_frames,
            stats.max_request_batch_frames,
            stats.write_batches,
            stats.write_batch_frames,
            stats.max_write_batch_frames,
            (stats.write_bytes + stats.read_bytes) as f64 / (1024.0 * 1024.0) / secs,
            stats.target_cpu,
            stats.affinity_applied
        );
        if latency_enabled {
            println!(
                "zcnblk-send-worker-latency: worker={} {} {}",
                stats.worker,
                zcnblk_latency_fields("write_ack", &stats.write_ack_latency),
                zcnblk_latency_fields("read", &stats.read_latency)
            );
        }
        total_write += stats.write_bytes;
        total_read += stats.read_bytes;
        total_verified_read += stats.verified_read_bytes;
        total_read_checksum = total_read_checksum.wrapping_add(stats.read_checksum);
        total_expected_checksum = total_expected_checksum.wrapping_add(stats.expected_checksum);
        total_wire += stats.wire_bytes;
        total_frames += stats.frames;
        total_read_frames += stats.read_frames;
        total_write_frames += stats.write_frames;
        total_request_batches += stats.request_batches;
        total_request_batch_frames += stats.request_batch_frames;
        total_max_request_batch_frames =
            total_max_request_batch_frames.max(stats.max_request_batch_frames);
        total_write_batches += stats.write_batches;
        total_write_batch_frames += stats.write_batch_frames;
        total_max_write_batch_frames =
            total_max_write_batch_frames.max(stats.max_write_batch_frames);
        if latency_enabled {
            total_write_ack_latency.merge(&stats.write_ack_latency);
            total_read_latency.merge(&stats.read_latency);
        }
        elapsed = elapsed.max(stats.elapsed);
    }
    println!(
        "zcnblk-send-summary: write_bytes={total_write} read_bytes={total_read} \
         verified_read_bytes={total_verified_read} read_checksum=0x{total_read_checksum:016x} \
         expected_checksum=0x{total_expected_checksum:016x} wire_bytes={total_wire} \
         frames={total_frames} read_frames={total_read_frames} write_frames={total_write_frames} \
         request_batches={total_request_batches} request_batch_frames={total_request_batch_frames} \
         max_request_batch_frames={total_max_request_batch_frames} \
         write_batches={total_write_batches} write_batch_frames={total_write_batch_frames} \
         max_write_batch_frames={total_max_write_batch_frames} \
         frames_per_sec={:.0}",
        total_frames as f64 / elapsed.as_secs_f64().max(f64::MIN_POSITIVE)
    );
    if latency_enabled {
        println!(
            "zcnblk-send-latency-summary: {} {}",
            zcnblk_latency_fields("write_ack", &total_write_ack_latency),
            zcnblk_latency_fields("read", &total_read_latency)
        );
    }
    print_tcp_bench_result("zcnblk-send", total_write + total_read, elapsed);
    Ok(())
}

#[derive(Default)]
struct ZcnblkReadFanStats {
    handler: usize,
    lane: usize,
    conn_index: usize,
    read_bytes: usize,
    write_bytes: usize,
    response_bytes: usize,
    frames: usize,
    batches: usize,
    read_frames: usize,
    write_frames: usize,
    leaf_read_bytes: Vec<usize>,
    leaf_write_bytes: Vec<usize>,
    elapsed: Duration,
    target_cpu: i32,
    affinity_applied: bool,
}

#[derive(Clone, Debug)]
struct ZcnblkFanLeafSpec {
    addr: String,
    base_port: Option<u16>,
}

impl ZcnblkFanLeafSpec {
    fn connect_port(&self, fallback_base_port: u16, lane: usize) -> io::Result<u16> {
        tcp_bench_port(self.base_port.unwrap_or(fallback_base_port), lane)
    }

    fn label(&self, fallback_base_port: u16) -> String {
        match self.base_port {
            Some(base_port) => format!("{}:{base_port}", self.addr),
            None => format!("{}:{fallback_base_port}", self.addr),
        }
    }
}

fn zcnblk_parse_fan_leaf_spec(entry: &str) -> io::Result<ZcnblkFanLeafSpec> {
    let entry = entry.trim();
    if entry.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "empty zcnblk fan leaf entry",
        ));
    }
    if let Some(rest) = entry.strip_prefix('[') {
        let (addr, tail) = rest.split_once(']').ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid bracketed zcnblk fan leaf {entry:?}"),
            )
        })?;
        let base_port = if let Some(port) = tail.strip_prefix(':') {
            Some(parse_u16_value(port, "leaf base port")?)
        } else if tail.is_empty() {
            None
        } else {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("invalid bracketed zcnblk fan leaf suffix {tail:?}"),
            ));
        };
        return Ok(ZcnblkFanLeafSpec {
            addr: addr.to_string(),
            base_port,
        });
    }
    if let Some((addr, port)) = entry.rsplit_once(':') {
        if !addr.contains(':') {
            return Ok(ZcnblkFanLeafSpec {
                addr: addr.to_string(),
                base_port: Some(parse_u16_value(port, "leaf base port")?),
            });
        }
    }
    Ok(ZcnblkFanLeafSpec {
        addr: entry.to_string(),
        base_port: None,
    })
}

fn zcnblk_read_fan_leaf_specs(spec: &str) -> io::Result<Vec<ZcnblkFanLeafSpec>> {
    let leaves = spec
        .split(',')
        .map(str::trim)
        .filter(|addr| !addr.is_empty())
        .map(zcnblk_parse_fan_leaf_spec)
        .collect::<io::Result<Vec<_>>>()?;
    if leaves.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-read-fan requires at least one leaf address",
        ));
    }
    Ok(leaves)
}

#[derive(Default)]
struct ZcnblkFanOrderInner {
    queues: BTreeMap<u64, VecDeque<u64>>,
}

struct ZcnblkFanOrderShard {
    inner: Mutex<ZcnblkFanOrderInner>,
    cv: Condvar,
}

struct ZcnblkFanOrder {
    next_seq: AtomicU64,
    shards: Vec<ZcnblkFanOrderShard>,
}

struct ZcnblkFanOrderGuard {
    order: Arc<ZcnblkFanOrder>,
    seq: u64,
    records: Vec<u64>,
    released: bool,
}

#[derive(Clone)]
struct ZcnblkFanOrderHandle {
    inner: Arc<ZcnblkFanOrderHandleInner>,
}

struct ZcnblkFanOrderHandleInner {
    seq: u64,
    records: Vec<u64>,
    guard: Mutex<Option<ZcnblkFanOrderGuard>>,
}

fn zcnblk_fan_order_queue_insert(queue: &mut VecDeque<u64>, seq: u64) {
    if let Some(pos) = queue.iter().position(|queued| *queued > seq) {
        queue.insert(pos, seq);
    } else {
        queue.push_back(seq);
    }
}

impl ZcnblkFanOrder {
    fn new() -> Self {
        let shard_count = env_usize_or(
            "URING_PLAY_ZCNBLK_FAN_ORDER_SHARDS",
            online_cpu_count().saturating_mul(4),
        )
        .max(1);
        Self {
            next_seq: AtomicU64::new(0),
            shards: (0..shard_count)
                .map(|_| ZcnblkFanOrderShard {
                    inner: Mutex::new(ZcnblkFanOrderInner::default()),
                    cv: Condvar::new(),
                })
                .collect(),
        }
    }

    fn shard_count(&self) -> usize {
        self.shards.len()
    }

    fn shard_index(&self, record: u64) -> usize {
        record as usize % self.shards.len()
    }

    fn reserve_records(self: &Arc<Self>, mut records: Vec<u64>) -> io::Result<ZcnblkFanOrderGuard> {
        if records.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan order reservation needs at least one record",
            ));
        }
        records.sort_unstable();
        records.dedup();
        let seq = self.next_seq.fetch_add(1, Ordering::Relaxed);
        for record in &records {
            let shard = &self.shards[self.shard_index(*record)];
            let mut inner = shard.inner.lock().map_err(|_| {
                io::Error::other("zcnblk-fan order lock poisoned while reserving request")
            })?;
            zcnblk_fan_order_queue_insert(inner.queues.entry(*record).or_default(), seq);
            shard.cv.notify_all();
        }
        Ok(ZcnblkFanOrderGuard {
            order: Arc::clone(self),
            seq,
            records,
            released: false,
        })
    }
}

impl ZcnblkFanOrderHandle {
    fn from_guard(guard: ZcnblkFanOrderGuard) -> Self {
        let seq = guard.seq;
        let records = guard.records.clone();
        Self {
            inner: Arc::new(ZcnblkFanOrderHandleInner {
                seq,
                records,
                guard: Mutex::new(Some(guard)),
            }),
        }
    }

    fn seq(&self) -> u64 {
        self.inner.seq
    }

    fn records(&self) -> &[u64] {
        &self.inner.records
    }

    fn wait_turn(&self) -> io::Result<()> {
        let guard = self
            .inner
            .guard
            .lock()
            .map_err(|_| io::Error::other("zcnblk-fan order handle lock poisoned"))?;
        if let Some(guard) = guard.as_ref() {
            guard.wait_turn()?;
        }
        Ok(())
    }

    fn is_turn(&self) -> io::Result<bool> {
        let guard = self
            .inner
            .guard
            .lock()
            .map_err(|_| io::Error::other("zcnblk-fan order handle lock poisoned"))?;
        if let Some(guard) = guard.as_ref() {
            return guard.is_turn();
        }
        Ok(true)
    }

    fn release(&self) {
        if let Ok(mut guard) = self.inner.guard.lock() {
            if let Some(mut guard) = guard.take() {
                guard.release();
            }
        }
    }
}

impl ZcnblkFanOrderGuard {
    fn is_turn(&self) -> io::Result<bool> {
        for record in &self.records {
            let shard = &self.order.shards[self.order.shard_index(*record)];
            let inner = shard.inner.lock().map_err(|_| {
                io::Error::other("zcnblk-fan order lock poisoned while checking request turn")
            })?;
            let ready = inner
                .queues
                .get(record)
                .and_then(|queue| queue.front().copied())
                == Some(self.seq);
            if !ready {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn wait_turn(&self) -> io::Result<()> {
        loop {
            let mut missing_record = None;
            for record in &self.records {
                let shard = &self.order.shards[self.order.shard_index(*record)];
                let inner = shard.inner.lock().map_err(|_| {
                    io::Error::other("zcnblk-fan order lock poisoned while waiting for request")
                })?;
                let ready = inner
                    .queues
                    .get(record)
                    .and_then(|queue| queue.front().copied())
                    == Some(self.seq);
                drop(inner);
                if !ready {
                    missing_record = Some(*record);
                    break;
                }
            }
            let Some(record) = missing_record else {
                return Ok(());
            };
            let shard = &self.order.shards[self.order.shard_index(record)];
            let mut inner = shard.inner.lock().map_err(|_| {
                io::Error::other("zcnblk-fan order lock poisoned while waiting for request")
            })?;
            while inner
                .queues
                .get(&record)
                .and_then(|queue| queue.front().copied())
                != Some(self.seq)
            {
                inner = shard
                    .cv
                    .wait(inner)
                    .map_err(|_| io::Error::other("zcnblk-fan order condvar lock poisoned"))?;
            }
        }
    }

    fn release(&mut self) {
        if self.released {
            return;
        }
        for record in &self.records {
            let shard = &self.order.shards[self.order.shard_index(*record)];
            if let Ok(mut inner) = shard.inner.lock() {
                let mut remove_record = false;
                if let Some(queue) = inner.queues.get_mut(record) {
                    if queue.front().copied() == Some(self.seq) {
                        queue.pop_front();
                    } else if let Some(pos) = queue.iter().position(|queued| *queued == self.seq) {
                        queue.remove(pos);
                    }
                    remove_record = queue.is_empty();
                }
                if remove_record {
                    inner.queues.remove(record);
                }
                shard.cv.notify_all();
            }
        }
        self.released = true;
    }
}

impl Drop for ZcnblkFanOrderGuard {
    fn drop(&mut self) {
        self.release();
    }
}

fn zcnblk_fan_order_records(offset: u64, len: usize) -> io::Result<Vec<u64>> {
    if len == 0 || len % ZC_WAL_RECORD_SIZE != 0 || offset % ZC_WAL_RECORD_SIZE as u64 != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-fan ordered records require 4K-aligned ranges, got offset={offset} len={len}"
            ),
        ));
    }
    let first = offset / ZC_WAL_RECORD_SIZE as u64;
    let count = len / ZC_WAL_RECORD_SIZE;
    let mut records = Vec::with_capacity(count);
    for idx in 0..count {
        records.push(first.checked_add(idx as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcnblk-fan record index overflow",
            )
        })?);
    }
    records.dedup();
    Ok(records)
}

fn zcnblk_read_fan_leaf_bytes(
    bytes_per_connection: usize,
    stripe_bytes: usize,
    leaf_count: usize,
    leaf_idx: usize,
) -> io::Result<usize> {
    if stripe_bytes == 0 || leaf_count == 0 || leaf_idx >= leaf_count {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-read-fan leaf-byte calculation got an empty stripe or leaf set",
        ));
    }
    let full_stripes = bytes_per_connection / stripe_bytes;
    let tail = bytes_per_connection % stripe_bytes;
    let base_stripes = full_stripes / leaf_count;
    let extra_stripes = full_stripes % leaf_count;
    let mut bytes = base_stripes
        .checked_mul(stripe_bytes)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "leaf byte count overflow"))?;
    if leaf_idx < extra_stripes {
        bytes = bytes.checked_add(stripe_bytes).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "leaf byte count overflow")
        })?;
    }
    if tail != 0 && leaf_idx == extra_stripes {
        bytes = bytes.checked_add(tail).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "leaf byte count overflow")
        })?;
    }
    Ok(bytes)
}

fn zcnblk_read_fan_leaf_byte_plan(
    bytes_per_connection: usize,
    stripe_bytes: usize,
    leaf_count: usize,
) -> io::Result<Vec<usize>> {
    (0..leaf_count)
        .map(|leaf_idx| {
            zcnblk_read_fan_leaf_bytes(bytes_per_connection, stripe_bytes, leaf_count, leaf_idx)
        })
        .collect()
}

#[derive(Clone, Copy)]
struct ZcnblkFanSegment {
    leaf_idx: usize,
    leaf_offset: u64,
    payload_offset: usize,
    len: usize,
}

struct ZcnblkFanPreparedFrame {
    frame: ZcnblkFrameHeader,
    len: usize,
    next_completed: usize,
    order: ZcnblkFanOrderHandle,
}

struct ZcnblkFanFramePlan {
    frame: ZcnblkFrameHeader,
    len: usize,
    next_completed: usize,
    records: Vec<u64>,
}

fn zcnblk_read_fan_map_segments(
    offset: u64,
    len: usize,
    stripe_bytes: usize,
    leaf_count: usize,
) -> io::Result<Vec<ZcnblkFanSegment>> {
    if stripe_bytes == 0 || leaf_count == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-fan requires non-zero stripe bytes and leaf count",
        ));
    }
    let stripe_bytes_u64 = stripe_bytes as u64;
    let mut segments = Vec::new();
    let mut logical_offset = offset;
    let mut payload_offset = 0usize;
    let mut remaining = len;
    while remaining != 0 {
        let stripe_off = logical_offset % stripe_bytes_u64;
        let stripe_remaining = stripe_bytes - stripe_off as usize;
        let seg_len = remaining.min(stripe_remaining);
        if seg_len == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan produced an empty stripe segment",
            ));
        }
        let stripe_no = logical_offset / stripe_bytes_u64;
        let leaf_idx = (stripe_no % leaf_count as u64) as usize;
        let row = stripe_no / leaf_count as u64;
        let leaf_offset = row
            .checked_mul(stripe_bytes_u64)
            .and_then(|base| base.checked_add(stripe_off))
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "zcnblk-fan offset overflow")
            })?;
        segments.push(ZcnblkFanSegment {
            leaf_idx,
            leaf_offset,
            payload_offset,
            len: seg_len,
        });
        logical_offset = logical_offset.checked_add(seg_len as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidInput, "zcnblk-fan offset overflow")
        })?;
        payload_offset = payload_offset.checked_add(seg_len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcnblk-fan payload offset overflow",
            )
        })?;
        remaining -= seg_len;
    }
    Ok(segments)
}

fn zcnblk_read_fan_plan_frame(
    frame: ZcnblkFrameHeader,
    stream_lane: usize,
    ports: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    completed: usize,
) -> io::Result<ZcnblkFanFramePlan> {
    if !matches!(frame.op, ZCNBLK_OP_READ | ZCNBLK_OP_WRITE) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk-fan request op {} is not supported", frame.op),
        ));
    }
    zcnblk_validate_frame_topology(frame, stream_lane, 0, ports)?;
    if frame.shard != 0 || frame.topology.tier_id != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "zcnblk-fan accepts only the client edge shard 0, got shard={} tier_id={}",
                frame.shard, frame.topology.tier_id
            ),
        ));
    }
    let len = frame.len as usize;
    if len == 0 || len > chunk_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk-fan frame length {len} invalid for chunk_bytes={chunk_bytes}"),
        ));
    }
    let next_completed = completed.checked_add(len).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidData, "zcnblk-fan byte count overflow")
    })?;
    if next_completed > bytes_per_connection {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcnblk-fan stream requested {next_completed}/{bytes_per_connection} bytes"),
        ));
    }
    let records = zcnblk_fan_order_records(frame.offset, len)?;
    Ok(ZcnblkFanFramePlan {
        frame,
        len,
        next_completed,
        records,
    })
}

fn zcnblk_read_fan_prepared_from_plan(
    plan: ZcnblkFanFramePlan,
    order: ZcnblkFanOrderHandle,
) -> ZcnblkFanPreparedFrame {
    ZcnblkFanPreparedFrame {
        frame: plan.frame,
        len: plan.len,
        next_completed: plan.next_completed,
        order,
    }
}

fn zcnblk_read_fan_prepared_batch_from_plans(
    plans: Vec<ZcnblkFanFramePlan>,
    order: ZcnblkFanOrderHandle,
) -> Vec<ZcnblkFanPreparedFrame> {
    plans
        .into_iter()
        .map(|plan| zcnblk_read_fan_prepared_from_plan(plan, order.clone()))
        .collect()
}

fn zcnblk_read_fan_prepare_frame(
    frame: ZcnblkFrameHeader,
    order: &Arc<ZcnblkFanOrder>,
    stream_lane: usize,
    ports: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    completed: usize,
) -> io::Result<ZcnblkFanPreparedFrame> {
    let plan = zcnblk_read_fan_plan_frame(
        frame,
        stream_lane,
        ports,
        bytes_per_connection,
        chunk_bytes,
        completed,
    )?;
    let guard = order.reserve_records(plan.records.clone())?;
    Ok(zcnblk_read_fan_prepared_from_plan(
        plan,
        ZcnblkFanOrderHandle::from_guard(guard),
    ))
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_read_fan_forward_frame(
    upstream: &mut ZcnblkTransport,
    leaves: &mut [ZcnblkTransport],
    prepared: ZcnblkFanPreparedFrame,
    stripe_bytes: usize,
    write_acks: bool,
    completed: &mut usize,
    payload: &mut Vec<u8>,
    leaf_read_bytes: &mut [usize],
    leaf_write_bytes: &mut [usize],
    total_read: &mut usize,
    total_write: &mut usize,
    total_response: &mut usize,
    frames: &mut usize,
    read_frames: &mut usize,
    write_frames: &mut usize,
) -> io::Result<()> {
    let frame = prepared.frame;
    let len = prepared.len;
    let segments = zcnblk_read_fan_map_segments(frame.offset, len, stripe_bytes, leaves.len())?;
    if frame.op == ZCNBLK_OP_WRITE {
        payload.resize(len, 0);
        let header = frame.encode();
        upstream.read_frame_payload(&header, &mut payload[..], false)?;
    } else if upstream.uses_payload_crypto() {
        let header = frame.encode();
        let mut empty = [];
        upstream.read_frame_payload(&header, &mut empty, false)?;
    }

    prepared.order.wait_turn()?;
    if frame.op == ZCNBLK_OP_READ {
        payload.resize(len, 0);
        for segment in &segments {
            let leaf_header = ZcnblkFrameHeader::with_topology(
                ZCNBLK_OP_READ,
                frame.flags,
                0,
                segment.len,
                segment.leaf_offset,
                frame.topology,
            )?
            .encode();
            leaves[segment.leaf_idx].write_frame_payload(&leaf_header, &[], false)?;

            let mut response_header = [0u8; ZCNBLK_FRAME_HEADER_LEN];
            leaves[segment.leaf_idx].read_exact(&mut response_header)?;
            let response = ZcnblkFrameHeader::decode(&response_header)?;
            if response.op != ZCNBLK_OP_READ_RESP
                || response.shard != 0
                || response.len as usize != segment.len
                || response.offset != segment.leaf_offset
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-fan leaf read response mismatch op={} shard={} len={} offset={} expected_leaf={} expected_offset={} expected_len={}",
                        response.op,
                        response.shard,
                        response.len,
                        response.offset,
                        segment.leaf_idx,
                        segment.leaf_offset,
                        segment.len
                    ),
                ));
            }
            let response_header = response.encode();
            let start = segment.payload_offset;
            let end = start.checked_add(segment.len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk-fan segment overflow")
            })?;
            leaves[segment.leaf_idx].read_frame_payload(
                &response_header,
                &mut payload[start..end],
                true,
            )?;
            leaf_read_bytes[segment.leaf_idx] = leaf_read_bytes[segment.leaf_idx]
                .checked_add(segment.len)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk-fan leaf read overflow")
                })?;
        }
        let upstream_header = ZcnblkFrameHeader::with_topology(
            ZCNBLK_OP_READ_RESP,
            frame.flags,
            frame.shard as usize,
            len,
            frame.offset,
            frame.topology,
        )?
        .encode();
        *total_response = total_response
            .checked_add(upstream.write_frame_payload(&upstream_header, &payload[..], true)?)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-fan response byte count overflow",
                )
            })?;
        *total_read = total_read.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan read byte count overflow",
            )
        })?;
        *read_frames = read_frames.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan read frame count overflow",
            )
        })?;
    } else {
        for segment in &segments {
            let start = segment.payload_offset;
            let end = start.checked_add(segment.len).ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidData, "zcnblk-fan segment overflow")
            })?;
            let leaf_header = ZcnblkFrameHeader::with_topology(
                ZCNBLK_OP_WRITE,
                frame.flags,
                0,
                segment.len,
                segment.leaf_offset,
                frame.topology,
            )?
            .encode();
            leaves[segment.leaf_idx].write_frame_payload(
                &leaf_header,
                &payload[start..end],
                false,
            )?;

            let mut ack_header = [0u8; ZCNBLK_FRAME_HEADER_LEN];
            leaves[segment.leaf_idx].read_exact(&mut ack_header)?;
            let ack = ZcnblkFrameHeader::decode(&ack_header)?;
            if ack.op != ZCNBLK_OP_WRITE_ACK
                || ack.shard != 0
                || ack.len as usize != segment.len
                || ack.offset != segment.leaf_offset
            {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "zcnblk-fan leaf write ack mismatch op={} shard={} len={} offset={} expected_leaf={} expected_offset={} expected_len={}",
                        ack.op,
                        ack.shard,
                        ack.len,
                        ack.offset,
                        segment.leaf_idx,
                        segment.leaf_offset,
                        segment.len
                    ),
                ));
            }
            let mut empty = [];
            leaves[segment.leaf_idx].read_frame_payload(&ack_header, &mut empty, true)?;
            leaf_write_bytes[segment.leaf_idx] = leaf_write_bytes[segment.leaf_idx]
                .checked_add(segment.len)
                .ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "zcnblk-fan leaf write overflow")
                })?;
        }
        if write_acks {
            let upstream_header = ZcnblkFrameHeader::with_topology(
                ZCNBLK_OP_WRITE_ACK,
                frame.flags,
                frame.shard as usize,
                len,
                frame.offset,
                frame.topology,
            )?
            .encode();
            *total_response = total_response
                .checked_add(upstream.write_frame_payload(&upstream_header, &[], true)?)
                .ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "zcnblk-fan write ack byte count overflow",
                    )
                })?;
        }
        *total_write = total_write.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan write byte count overflow",
            )
        })?;
        *write_frames = write_frames.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan write frame count overflow",
            )
        })?;
    }
    prepared.order.release();
    *completed = prepared.next_completed;
    *frames = frames.checked_add(1).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "zcnblk-fan frame count overflow",
        )
    })?;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_read_fan_handler(
    handler: usize,
    accepted: TcpBenchAcceptedStream,
    leaf_addrs: Arc<Vec<ZcnblkFanLeafSpec>>,
    order: Arc<ZcnblkFanOrder>,
    leaf_base_port: u16,
    ports: usize,
    connections_per_port: usize,
    total_connections: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    stripe_bytes: usize,
    write_acks: bool,
    source_ports: TcpSourcePortPlan,
    crypto_config: ZcnblkCryptoConfig,
    pin_handlers: bool,
) -> io::Result<ZcnblkReadFanStats> {
    let affinity =
        pin_current_thread_if_requested("zcnblk-read-fan-handler", handler, pin_handlers);
    let meta = accepted.meta();
    println!(
        "zcnblk-read-fan-upstream: handler={handler} peer={} lane={} port={} conn={} {}",
        meta.peer_addr,
        meta.lane,
        meta.port,
        meta.conn_index,
        socket_locality_label(meta.locality)
    );
    let conn_id = zcnblk_transport_conn_id(meta.lane, meta.conn_index, connections_per_port)?;
    let mut upstream = ZcnblkTransport::accept_target(accepted, conn_id, &crypto_config)?;

    let mut leaves = Vec::with_capacity(leaf_addrs.len());
    for (leaf_idx, leaf) in leaf_addrs.iter().enumerate() {
        let port = leaf.connect_port(leaf_base_port, meta.lane)?;
        let source_index = leaf_idx
            .checked_mul(total_connections)
            .and_then(|base| base.checked_add(handler))
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "zcnblk-read-fan source-port index overflow",
                )
            })?;
        let stream = tcp_bench_connect(&leaf.addr, port, source_ports.source_port(source_index)?)?;
        set_tcp_nodelay_from_env(&stream)?;
        set_tcp_bench_buffers(&stream);
        println!(
            "zcnblk-read-fan-leaf-stream: handler={handler} leaf={leaf_idx} addr={} port={port} lane={} conn={} source_port={}",
            leaf.addr,
            meta.lane,
            meta.conn_index,
            source_ports
                .source_port(source_index)?
                .map(|port| port.to_string())
                .unwrap_or_else(|| "kernel-ephemeral".to_string())
        );
        leaves.push(ZcnblkTransport::connect_client(
            stream,
            meta.lane,
            conn_id,
            &crypto_config,
        )?);
    }

    let mut completed = 0usize;
    let mut read_bytes = 0usize;
    let mut write_bytes = 0usize;
    let mut response_bytes = 0usize;
    let mut frames = 0usize;
    let mut batches = 0usize;
    let mut read_frames = 0usize;
    let mut write_frames = 0usize;
    let mut leaf_read_bytes = vec![0usize; leaf_addrs.len()];
    let mut leaf_write_bytes = vec![0usize; leaf_addrs.len()];
    let mut payload = Vec::with_capacity(chunk_bytes);
    let started = Instant::now();

    while completed < bytes_per_connection {
        let mut header_buf = [0u8; ZCNBLK_FRAME_HEADER_LEN];
        upstream.read_exact(&mut header_buf)?;
        let frame = ZcnblkFrameHeader::decode(&header_buf)?;
        if frame.op == ZCNBLK_OP_BATCH {
            batches = batches.checked_add(1).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-read-fan batch count overflow",
                )
            })?;
            let count = frame.len as usize;
            if count == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-read-fan got an empty request batch",
                ));
            }
            let batch_frames = zcnblk_read_batch_headers(&mut upstream, count, "zcnblk-read-fan")?;
            for batch_frame in batch_frames {
                let prepared = zcnblk_read_fan_prepare_frame(
                    batch_frame,
                    &order,
                    meta.lane,
                    ports,
                    bytes_per_connection,
                    chunk_bytes,
                    completed,
                )?;
                zcnblk_read_fan_forward_frame(
                    &mut upstream,
                    &mut leaves,
                    prepared,
                    stripe_bytes,
                    write_acks,
                    &mut completed,
                    &mut payload,
                    &mut leaf_read_bytes,
                    &mut leaf_write_bytes,
                    &mut read_bytes,
                    &mut write_bytes,
                    &mut response_bytes,
                    &mut frames,
                    &mut read_frames,
                    &mut write_frames,
                )?;
            }
        } else {
            let prepared = zcnblk_read_fan_prepare_frame(
                frame,
                &order,
                meta.lane,
                ports,
                bytes_per_connection,
                chunk_bytes,
                completed,
            )?;
            zcnblk_read_fan_forward_frame(
                &mut upstream,
                &mut leaves,
                prepared,
                stripe_bytes,
                write_acks,
                &mut completed,
                &mut payload,
                &mut leaf_read_bytes,
                &mut leaf_write_bytes,
                &mut read_bytes,
                &mut write_bytes,
                &mut response_bytes,
                &mut frames,
                &mut read_frames,
                &mut write_frames,
            )?;
        }
    }

    let _ = upstream.shutdown(Shutdown::Both);
    for leaf in &leaves {
        let _ = leaf.shutdown(Shutdown::Both);
    }

    Ok(ZcnblkReadFanStats {
        handler,
        lane: meta.lane,
        conn_index: meta.conn_index,
        read_bytes,
        write_bytes,
        response_bytes,
        frames,
        batches,
        read_frames,
        write_frames,
        leaf_read_bytes,
        leaf_write_bytes,
        elapsed: started.elapsed(),
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
    })
}

#[allow(clippy::too_many_arguments)]
fn zcnblk_read_fan(
    leaf_spec: &str,
    bind: &str,
    base_port: u16,
    ports: usize,
    connections_per_port: usize,
    bytes_per_connection: usize,
    chunk_bytes: usize,
    stripe_bytes: usize,
    leaf_base_port: u16,
    pin_handlers: bool,
) -> io::Result<()> {
    if bytes_per_connection == 0 || chunk_bytes == 0 || stripe_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-read-fan bytes-per-connection, chunk-bytes, and stripe-bytes must be non-zero",
        ));
    }
    if bytes_per_connection % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-read-fan bytes-per-connection must be a multiple of chunk-bytes",
        ));
    }
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    ensure_sector_aligned(stripe_bytes, "stripe-bytes")?;
    let leaf_addrs = Arc::new(zcnblk_read_fan_leaf_specs(leaf_spec)?);
    let leaf_bytes =
        zcnblk_read_fan_leaf_byte_plan(bytes_per_connection, stripe_bytes, leaf_addrs.len())?;
    if leaf_bytes.iter().any(|bytes| *bytes == 0) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-read-fan byte budget is too small to touch every leaf; reduce leaf count or stripe bytes",
        ));
    }
    if leaf_bytes.iter().any(|bytes| *bytes % chunk_bytes != 0) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-fan leaf byte budgets must be multiples of chunk-bytes so leaf zcnblk-target instances can use the same chunk size",
        ));
    }
    let total_connections = tcp_bench_total_connections(ports, connections_per_port)?;
    let source_ports = TcpSourcePortPlan::from_env()?;
    let source_ip = tcp_bench_source_ip_from_env()?;
    let crypto_config = ZcnblkCryptoConfig::from_env()?;
    let write_acks = env_enabled_or("URING_PLAY_ZCNBLK_WRITE_ACKS", false);
    if crypto_config.wire == ZcnblkCryptoWire::Payload {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-read-fan supports plaintext and stream AES only; payload AES depends on end-to-end conn_id ownership",
        ));
    }
    let order = Arc::new(ZcnblkFanOrder::new());

    let leaf_labels = leaf_addrs
        .iter()
        .enumerate()
        .map(|(idx, leaf)| format!("{idx}:{}:{}B", leaf.label(leaf_base_port), leaf_bytes[idx]))
        .collect::<Vec<_>>()
        .join(",");
    println!(
        "zcnblk-read-fan: leaves={} bind={bind} base_port={base_port} ports={ports} \
         connections_per_port={connections_per_port} total_connections={total_connections} \
         bytes_per_connection={bytes_per_connection} chunk_bytes={chunk_bytes} \
         stripe_bytes={stripe_bytes} leaf_base_port={leaf_base_port} source_ip={} \
         source_ports={} encryption={} aes_frame_bytes={} pin_handlers={pin_handlers} \
         read_only=false placement=userspace-stripe order=per-4k-record \
         write_acks={write_acks} leaf_write_acks=required",
        leaf_labels,
        source_ip
            .map(|ip| ip.to_string())
            .unwrap_or_else(|| "kernel-route".to_string()),
        source_ports.label(),
        crypto_config.label(),
        crypto_config.max_frame_bytes,
    );
    eprintln!(
        "zcnblk-fan-leaf-target-note: start each leaf zcnblk-target with URING_PLAY_ZCNBLK_WRITE_ACKS=1, the same ports/connections/chunk size, and its listed per-connection byte budget; /dev/zcbrd or other block media must remain terminal leaves behind those userspace targets"
    );

    let listeners = tcp_bench_mux_bind_listeners(bind, base_port, ports)?;
    let accepted = tcp_bench_mux_accept_tagged_listeners(listeners, ports, connections_per_port)?;
    let started = Instant::now();
    let mut handles = Vec::with_capacity(accepted.len());
    for (handler, accepted) in accepted.into_iter().enumerate() {
        let leaf_addrs = Arc::clone(&leaf_addrs);
        let order = Arc::clone(&order);
        let crypto_config = crypto_config.clone();
        handles.push(thread::spawn(move || {
            let result = zcnblk_read_fan_handler(
                handler,
                accepted,
                leaf_addrs,
                order,
                leaf_base_port,
                ports,
                connections_per_port,
                total_connections,
                bytes_per_connection,
                chunk_bytes,
                stripe_bytes,
                write_acks,
                source_ports,
                crypto_config,
                pin_handlers,
            );
            if let Err(err) = &result {
                eprintln!("zcnblk-read-fan-handler-error: handler={handler} error={err}");
            }
            result
        }));
    }

    let mut total_read = 0usize;
    let mut total_write = 0usize;
    let mut total_response = 0usize;
    let mut total_frames = 0usize;
    let mut total_batches = 0usize;
    let mut total_read_frames = 0usize;
    let mut total_write_frames = 0usize;
    let mut leaf_read_totals = vec![0usize; leaf_addrs.len()];
    let mut leaf_write_totals = vec![0usize; leaf_addrs.len()];
    let mut elapsed = started.elapsed();
    for handle in handles {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other("zcnblk-read-fan handler panicked"))??;
        let secs = stats.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        let leaf_label = stats
            .leaf_read_bytes
            .iter()
            .enumerate()
            .map(|(idx, bytes)| format!("{idx}:{bytes}"))
            .collect::<Vec<_>>()
            .join(",");
        let leaf_write_label = stats
            .leaf_write_bytes
            .iter()
            .enumerate()
            .map(|(idx, bytes)| format!("{idx}:{bytes}"))
            .collect::<Vec<_>>()
            .join(",");
        println!(
            "zcnblk-read-fan-handler: handler={} lane={} conn={} read_bytes={} write_bytes={} \
             response_bytes={} frames={} batches={} read_frames={} write_frames={} \
             leaf_read_bytes={} leaf_write_bytes={} frames_per_sec={:.0} \
             seconds={secs:.6} logical_MiBps={:.2} target_cpu={} affinity_applied={}",
            stats.handler,
            stats.lane,
            stats.conn_index,
            stats.read_bytes,
            stats.write_bytes,
            stats.response_bytes,
            stats.frames,
            stats.batches,
            stats.read_frames,
            stats.write_frames,
            leaf_label,
            leaf_write_label,
            stats.frames as f64 / secs,
            (stats.read_bytes + stats.write_bytes) as f64 / (1024.0 * 1024.0) / secs,
            stats.target_cpu,
            stats.affinity_applied
        );
        total_read = total_read.checked_add(stats.read_bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-read-fan total read overflow",
            )
        })?;
        total_write = total_write.checked_add(stats.write_bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-fan total write overflow",
            )
        })?;
        total_response = total_response
            .checked_add(stats.response_bytes)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-read-fan total response overflow",
                )
            })?;
        total_frames = total_frames.checked_add(stats.frames).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-read-fan frame count overflow",
            )
        })?;
        total_batches = total_batches.checked_add(stats.batches).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk-read-fan batch count overflow",
            )
        })?;
        total_read_frames = total_read_frames
            .checked_add(stats.read_frames)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-fan read frame count overflow",
                )
            })?;
        total_write_frames = total_write_frames
            .checked_add(stats.write_frames)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-fan write frame count overflow",
                )
            })?;
        for (idx, bytes) in stats.leaf_read_bytes.into_iter().enumerate() {
            leaf_read_totals[idx] = leaf_read_totals[idx].checked_add(bytes).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "zcnblk-read-fan leaf read total overflow",
                )
            })?;
        }
        for (idx, bytes) in stats.leaf_write_bytes.into_iter().enumerate() {
            leaf_write_totals[idx] =
                leaf_write_totals[idx].checked_add(bytes).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "zcnblk-fan leaf write total overflow",
                    )
                })?;
        }
        elapsed = elapsed.max(stats.elapsed);
    }
    let leaf_read_totals_label = leaf_read_totals
        .iter()
        .enumerate()
        .map(|(idx, bytes)| format!("{idx}:{bytes}"))
        .collect::<Vec<_>>()
        .join(",");
    let leaf_write_totals_label = leaf_write_totals
        .iter()
        .enumerate()
        .map(|(idx, bytes)| format!("{idx}:{bytes}"))
        .collect::<Vec<_>>()
        .join(",");
    println!(
        "zcnblk-read-fan-summary: read_bytes={total_read} write_bytes={total_write} \
         response_bytes={total_response} frames={total_frames} batches={total_batches} \
         read_frames={total_read_frames} write_frames={total_write_frames} \
         leaf_read_bytes={leaf_read_totals_label} leaf_write_bytes={leaf_write_totals_label} \
         frames_per_sec={:.0}",
        total_frames as f64 / elapsed.as_secs_f64().max(f64::MIN_POSITIVE)
    );
    print_tcp_bench_result("zcnblk-read-fan", total_read + total_write, elapsed);
    Ok(())
}

const ZCNBLK_FAN_WAL_MAGIC: &[u8; 8] = b"ZCFANW1\0";
const ZCNBLK_FAN_WAL_VERSION: u16 = 2;
const ZCNBLK_FAN_WAL_HEADER_LEN: usize = 128;
const ZCNBLK_FAN_WAL_OP_HELLO: u16 = 1;
const ZCNBLK_FAN_WAL_OP_WRITE_DESC: u16 = 2;
const ZCNBLK_FAN_WAL_OP_READ_DESC: u16 = 3;
const ZCNBLK_FAN_WAL_OP_RESULT: u16 = 4;
const ZCNBLK_FAN_WAL_OP_SYNC: u16 = 5;
const ZCNBLK_FAN_WAL_OP_EOF: u16 = 6;
const ZCNBLK_FAN_WAL_OP_WRITE_BATCH: u16 = 7;
const ZCNBLK_FAN_WAL_OP_RESULT_BATCH: u16 = 8;
const ZCNBLK_FAN_WAL_OP_RESULT_RANGE_BATCH: u16 = 9;
const ZCNBLK_FAN_WAL_OP_REQUEST_BATCH: u16 = 10;
const ZCNBLK_FAN_WAL_STATUS_OK: u32 = 0;
const ZCNBLK_FAN_WAL_FLAG_RESULT_RANGE_BATCH: u16 = 1 << 0;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ZcnblkFanEngine {
    Sync,
    Wal,
}

impl ZcnblkFanEngine {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "" | "sync" | "compat" | "compatibility" => Ok(Self::Sync),
            "wal" | "log" | "descriptor-wal" => Ok(Self::Wal),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown zcnblk-fan engine {other:?}; use sync or wal"),
            )),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ZcnblkFanPlacementMode {
    Stripe,
    Mirror,
    Raid10,
}

impl ZcnblkFanPlacementMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "" | "stripe" | "raid0" => Ok(Self::Stripe),
            "mirror" | "raid1" => Ok(Self::Mirror),
            "raid10" | "raid1+0" | "raid-10" | "raid-1+0" => Ok(Self::Raid10),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown zcnblk-fan mode {other:?}; use stripe, mirror, or raid10"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Stripe => "stripe",
            Self::Mirror => "mirror",
            Self::Raid10 => "raid10",
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct ZcnblkFanWalFrame {
    op: u16,
    flags: u16,
    status: u32,
    lane_id: u32,
    lane_count: u32,
    branch_id: u32,
    branch_count: u32,
    segment_index: u32,
    segment_count: u32,
    payload_len: u32,
    sequence: u64,
    request_id: u64,
    sync_epoch: u64,
    placement_epoch: u64,
    logical_offset: u64,
    leaf_offset: u64,
    logical_len: u32,
    zcnblk_op: u16,
    zcnblk_flags: u16,
    zcnblk_shard: u32,
    topology_preferred_worker: u32,
    topology_queue_id: u32,
    topology_tier_id: u32,
    topology_flags: u32,
    topology_preferred_cpu: i16,
    topology_numa_node: i16,
}

impl Default for ZcnblkFanWalFrame {
    fn default() -> Self {
        Self {
            op: 0,
            flags: 0,
            status: 0,
            lane_id: 0,
            lane_count: 0,
            branch_id: 0,
            branch_count: 0,
            segment_index: 0,
            segment_count: 0,
            payload_len: 0,
            sequence: 0,
            request_id: 0,
            sync_epoch: 0,
            placement_epoch: 0,
            logical_offset: 0,
            leaf_offset: 0,
            logical_len: 0,
            zcnblk_op: 0,
            zcnblk_flags: 0,
            zcnblk_shard: 0,
            topology_preferred_worker: 0,
            topology_queue_id: 0,
            topology_tier_id: 0,
            topology_flags: 0,
            topology_preferred_cpu: -1,
            topology_numa_node: -1,
        }
    }
}

impl ZcnblkFanWalFrame {
    fn encode(self) -> [u8; ZCNBLK_FAN_WAL_HEADER_LEN] {
        let mut out = [0u8; ZCNBLK_FAN_WAL_HEADER_LEN];
        out[0..8].copy_from_slice(ZCNBLK_FAN_WAL_MAGIC);
        out[8..10].copy_from_slice(&ZCNBLK_FAN_WAL_VERSION.to_le_bytes());
        out[10..12].copy_from_slice(&(ZCNBLK_FAN_WAL_HEADER_LEN as u16).to_le_bytes());
        out[12..14].copy_from_slice(&self.op.to_le_bytes());
        out[14..16].copy_from_slice(&self.flags.to_le_bytes());
        out[16..20].copy_from_slice(&self.status.to_le_bytes());
        out[20..24].copy_from_slice(&self.lane_id.to_le_bytes());
        out[24..28].copy_from_slice(&self.lane_count.to_le_bytes());
        out[28..32].copy_from_slice(&self.branch_id.to_le_bytes());
        out[32..36].copy_from_slice(&self.branch_count.to_le_bytes());
        out[36..40].copy_from_slice(&self.segment_index.to_le_bytes());
        out[40..44].copy_from_slice(&self.segment_count.to_le_bytes());
        out[44..48].copy_from_slice(&self.payload_len.to_le_bytes());
        out[48..56].copy_from_slice(&self.sequence.to_le_bytes());
        out[56..64].copy_from_slice(&self.request_id.to_le_bytes());
        out[64..72].copy_from_slice(&self.sync_epoch.to_le_bytes());
        out[72..80].copy_from_slice(&self.placement_epoch.to_le_bytes());
        out[80..88].copy_from_slice(&self.logical_offset.to_le_bytes());
        out[88..96].copy_from_slice(&self.leaf_offset.to_le_bytes());
        out[96..100].copy_from_slice(&self.logical_len.to_le_bytes());
        out[100..102].copy_from_slice(&self.zcnblk_op.to_le_bytes());
        out[102..104].copy_from_slice(&self.zcnblk_flags.to_le_bytes());
        out[104..108].copy_from_slice(&self.zcnblk_shard.to_le_bytes());
        out[108..112].copy_from_slice(&self.topology_preferred_worker.to_le_bytes());
        out[112..116].copy_from_slice(&self.topology_queue_id.to_le_bytes());
        out[116..120].copy_from_slice(&self.topology_tier_id.to_le_bytes());
        out[120..124].copy_from_slice(&self.topology_flags.to_le_bytes());
        out[124..126].copy_from_slice(&self.topology_preferred_cpu.to_le_bytes());
        out[126..128].copy_from_slice(&self.topology_numa_node.to_le_bytes());
        out
    }

    fn decode(input: &[u8; ZCNBLK_FAN_WAL_HEADER_LEN]) -> io::Result<Self> {
        if &input[0..8] != ZCNBLK_FAN_WAL_MAGIC {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "zcnblk fan WAL magic mismatch",
            ));
        }
        let version = u16::from_le_bytes(input[8..10].try_into().expect("u16"));
        let header_len = u16::from_le_bytes(input[10..12].try_into().expect("u16")) as usize;
        if version != ZCNBLK_FAN_WAL_VERSION || header_len != ZCNBLK_FAN_WAL_HEADER_LEN {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("unsupported zcnblk fan WAL version={version} header_len={header_len}"),
            ));
        }
        let op = u16::from_le_bytes(input[12..14].try_into().expect("u16"));
        if !matches!(
            op,
            ZCNBLK_FAN_WAL_OP_HELLO
                | ZCNBLK_FAN_WAL_OP_WRITE_DESC
                | ZCNBLK_FAN_WAL_OP_READ_DESC
                | ZCNBLK_FAN_WAL_OP_RESULT
                | ZCNBLK_FAN_WAL_OP_SYNC
                | ZCNBLK_FAN_WAL_OP_EOF
                | ZCNBLK_FAN_WAL_OP_WRITE_BATCH
                | ZCNBLK_FAN_WAL_OP_RESULT_BATCH
                | ZCNBLK_FAN_WAL_OP_RESULT_RANGE_BATCH
                | ZCNBLK_FAN_WAL_OP_REQUEST_BATCH
        ) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("unknown zcnblk fan WAL op {op}"),
            ));
        }
        Ok(Self {
            op,
            flags: u16::from_le_bytes(input[14..16].try_into().expect("u16")),
            status: u32::from_le_bytes(input[16..20].try_into().expect("u32")),
            lane_id: u32::from_le_bytes(input[20..24].try_into().expect("u32")),
            lane_count: u32::from_le_bytes(input[24..28].try_into().expect("u32")),
            branch_id: u32::from_le_bytes(input[28..32].try_into().expect("u32")),
            branch_count: u32::from_le_bytes(input[32..36].try_into().expect("u32")),
            segment_index: u32::from_le_bytes(input[36..40].try_into().expect("u32")),
            segment_count: u32::from_le_bytes(input[40..44].try_into().expect("u32")),
            payload_len: u32::from_le_bytes(input[44..48].try_into().expect("u32")),
            sequence: u64::from_le_bytes(input[48..56].try_into().expect("u64")),
            request_id: u64::from_le_bytes(input[56..64].try_into().expect("u64")),
            sync_epoch: u64::from_le_bytes(input[64..72].try_into().expect("u64")),
            placement_epoch: u64::from_le_bytes(input[72..80].try_into().expect("u64")),
            logical_offset: u64::from_le_bytes(input[80..88].try_into().expect("u64")),
            leaf_offset: u64::from_le_bytes(input[88..96].try_into().expect("u64")),
            logical_len: u32::from_le_bytes(input[96..100].try_into().expect("u32")),
            zcnblk_op: u16::from_le_bytes(input[100..102].try_into().expect("u16")),
            zcnblk_flags: u16::from_le_bytes(input[102..104].try_into().expect("u16")),
            zcnblk_shard: u32::from_le_bytes(input[104..108].try_into().expect("u32")),
            topology_preferred_worker: u32::from_le_bytes(input[108..112].try_into().expect("u32")),
            topology_queue_id: u32::from_le_bytes(input[112..116].try_into().expect("u32")),
            topology_tier_id: u32::from_le_bytes(input[116..120].try_into().expect("u32")),
            topology_flags: u32::from_le_bytes(input[120..124].try_into().expect("u32")),
            topology_preferred_cpu: i16::from_le_bytes(input[124..126].try_into().expect("i16")),
            topology_numa_node: i16::from_le_bytes(input[126..128].try_into().expect("i16")),
        })
    }

    fn from_zcnblk_request(
        op: u16,
        frame: ZcnblkFrameHeader,
        lane_id: usize,
        lane_count: usize,
        branch_id: usize,
        branch_count: usize,
        segment_index: usize,
        segment_count: usize,
        sequence: u64,
        logical_offset: u64,
        leaf_offset: u64,
        payload_len: usize,
    ) -> io::Result<Self> {
        Ok(Self {
            op,
            flags: 0,
            status: 0,
            lane_id: u32::try_from(lane_id).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "fan WAL lane exceeds u32")
            })?,
            lane_count: u32::try_from(lane_count).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "fan WAL lane count exceeds u32",
                )
            })?,
            branch_id: u32::try_from(branch_id).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "fan WAL branch exceeds u32")
            })?,
            branch_count: u32::try_from(branch_count).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "fan WAL branch count exceeds u32",
                )
            })?,
            segment_index: u32::try_from(segment_index).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "fan WAL segment exceeds u32")
            })?,
            segment_count: u32::try_from(segment_count).map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "fan WAL segment count exceeds u32",
                )
            })?,
            payload_len: u32::try_from(payload_len).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "fan WAL payload exceeds u32")
            })?,
            sequence,
            request_id: frame.topology.request_id,
            sync_epoch: 0,
            placement_epoch: 0,
            logical_offset,
            leaf_offset,
            logical_len: frame.len,
            zcnblk_op: frame.op,
            zcnblk_flags: frame.flags,
            zcnblk_shard: frame.shard,
            topology_preferred_worker: frame.topology.preferred_worker,
            topology_queue_id: frame.topology.queue_id,
            topology_tier_id: frame.topology.tier_id,
            topology_flags: frame.topology.topology_flags,
            topology_preferred_cpu: -1,
            topology_numa_node: -1,
        })
    }
}

fn zcnblk_fan_i16_topology_hint(value: i32) -> i16 {
    if value >= i16::MIN as i32 && value <= i16::MAX as i32 {
        value as i16
    } else {
        -1
    }
}

fn zcnblk_fan_wal_local_topology_hints(affinity: ThreadAffinity) -> (i16, i16) {
    let preferred_cpu = if affinity.target_cpu >= 0 {
        affinity.target_cpu
    } else {
        current_cpu()
    };
    let numa_node = if preferred_cpu >= 0 {
        cpu_numa_node(preferred_cpu as usize).unwrap_or(-1)
    } else {
        -1
    };
    (
        zcnblk_fan_i16_topology_hint(preferred_cpu),
        zcnblk_fan_i16_topology_hint(numa_node),
    )
}

fn zcnblk_fan_wal_attach_local_topology(
    mut frame: ZcnblkFanWalFrame,
    preferred_cpu: i16,
    numa_node: i16,
) -> ZcnblkFanWalFrame {
    frame.topology_preferred_cpu = preferred_cpu;
    frame.topology_numa_node = numa_node;
    frame
}

fn zcnblk_fan_wal_attach_placement_epoch(
    mut frame: ZcnblkFanWalFrame,
    plan: ZcPlanRuntime,
) -> ZcnblkFanWalFrame {
    frame.placement_epoch = plan.placement_epoch;
    frame
}

fn zcnblk_fan_wal_attach_stream_plan(
    mut frame: ZcnblkFanWalFrame,
    plan: ZcPlanRuntime,
) -> ZcnblkFanWalFrame {
    frame.request_id = plan.plan_hash;
    frame.placement_epoch = plan.placement_epoch;
    frame
}

fn zcnblk_fan_wal_result_ranges_enabled() -> bool {
    env_enabled_or("URING_PLAY_ZCNBLK_WAL_RESULT_RANGES", true)
}

fn zcnblk_fan_wal_write_frame(
    stream: &mut TcpStream,
    frame: ZcnblkFanWalFrame,
    payload: &[u8],
) -> io::Result<()> {
    let expected_payload_len = match frame.op {
        ZCNBLK_FAN_WAL_OP_WRITE_DESC
        | ZCNBLK_FAN_WAL_OP_RESULT
        | ZCNBLK_FAN_WAL_OP_WRITE_BATCH
        | ZCNBLK_FAN_WAL_OP_RESULT_BATCH
        | ZCNBLK_FAN_WAL_OP_REQUEST_BATCH => frame.payload_len as usize,
        ZCNBLK_FAN_WAL_OP_HELLO
        | ZCNBLK_FAN_WAL_OP_READ_DESC
        | ZCNBLK_FAN_WAL_OP_SYNC
        | ZCNBLK_FAN_WAL_OP_EOF
        | ZCNBLK_FAN_WAL_OP_RESULT_RANGE_BATCH => 0,
        _ => frame.payload_len as usize,
    };
    if payload.len() != expected_payload_len {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "fan WAL payload length mismatch header={} actual={}",
                expected_payload_len,
                payload.len()
            ),
        ));
    }
    stream.write_all(&frame.encode())?;
    if !payload.is_empty() {
        stream.write_all(payload)?;
    }
    Ok(())
}

fn zcnblk_fan_wal_write_vectored_payload(
    stream: &mut TcpStream,
    mut bufs: &mut [IoSlice<'_>],
) -> io::Result<()> {
    const MAX_IOV: usize = 1024;
    while !bufs.is_empty() {
        let take = bufs.len().min(MAX_IOV);
        let (head, tail) = bufs.split_at_mut(take);
        let mut current = head;
        while !current.is_empty() {
            let written = stream.write_vectored(current)?;
            if written == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    "fan WAL vectored payload write returned zero",
                ));
            }
            IoSlice::advance_slices(&mut current, written);
        }
        bufs = tail;
    }
    Ok(())
}

fn zcnblk_fan_wal_write_frame_vectored(
    stream: &mut TcpStream,
    frame: ZcnblkFanWalFrame,
    payloads: &mut [IoSlice<'_>],
) -> io::Result<()> {
    let actual_payload_len = payloads.iter().map(|payload| payload.len()).sum::<usize>();
    let expected_payload_len = match frame.op {
        ZCNBLK_FAN_WAL_OP_WRITE_DESC
        | ZCNBLK_FAN_WAL_OP_RESULT
        | ZCNBLK_FAN_WAL_OP_WRITE_BATCH
        | ZCNBLK_FAN_WAL_OP_RESULT_BATCH
        | ZCNBLK_FAN_WAL_OP_REQUEST_BATCH => frame.payload_len as usize,
        ZCNBLK_FAN_WAL_OP_HELLO
        | ZCNBLK_FAN_WAL_OP_READ_DESC
        | ZCNBLK_FAN_WAL_OP_SYNC
        | ZCNBLK_FAN_WAL_OP_EOF
        | ZCNBLK_FAN_WAL_OP_RESULT_RANGE_BATCH => 0,
        _ => frame.payload_len as usize,
    };
    if actual_payload_len != expected_payload_len {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "fan WAL vectored payload length mismatch header={} actual={}",
                expected_payload_len, actual_payload_len
            ),
        ));
    }
    stream.write_all(&frame.encode())?;
    zcnblk_fan_wal_write_vectored_payload(stream, payloads)
}

fn zcnblk_fan_wal_read_frame(stream: &mut TcpStream) -> io::Result<ZcnblkFanWalFrame> {
    let mut header = [0u8; ZCNBLK_FAN_WAL_HEADER_LEN];
    stream.read_exact(&mut header)?;
    ZcnblkFanWalFrame::decode(&header)
}

fn zcnblk_fan_wal_recv_exact_dontwait_spin(
    stream: &TcpStream,
    mut out: &mut [u8],
) -> io::Result<()> {
    while !out.is_empty() {
        let received = unsafe {
            libc::recv(
                stream.as_raw_fd(),
                out.as_mut_ptr() as *mut libc::c_void,
                out.len(),
                libc::MSG_DONTWAIT,
            )
        };
        if received > 0 {
            let received = received as usize;
            out = &mut out[received..];
            continue;
        }
        if received == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "fan WAL socket closed",
            ));
        }
        let err = io::Error::last_os_error();
        if matches!(
            err.kind(),
            io::ErrorKind::WouldBlock | io::ErrorKind::Interrupted
        ) {
            std::hint::spin_loop();
            continue;
        }
        return Err(err);
    }
    Ok(())
}

fn zcnblk_fan_wal_recv_exact_spin_then_block(
    stream: &mut TcpStream,
    mut out: &mut [u8],
    spin_budget: Option<usize>,
) -> io::Result<()> {
    let mut spins = 0usize;
    while !out.is_empty() {
        let received = unsafe {
            libc::recv(
                stream.as_raw_fd(),
                out.as_mut_ptr() as *mut libc::c_void,
                out.len(),
                libc::MSG_DONTWAIT,
            )
        };
        if received > 0 {
            let received = received as usize;
            out = &mut out[received..];
            continue;
        }
        if received == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "fan WAL socket closed",
            ));
        }
        let err = io::Error::last_os_error();
        if matches!(
            err.kind(),
            io::ErrorKind::WouldBlock | io::ErrorKind::Interrupted
        ) {
            if spin_budget.is_some_and(|budget| spins >= budget) {
                stream.read_exact(out)?;
                return Ok(());
            }
            spins = spins.saturating_add(1);
            std::hint::spin_loop();
            continue;
        }
        return Err(err);
    }
    Ok(())
}

fn zcnblk_fan_wal_read_frame_dontwait_spin(stream: &TcpStream) -> io::Result<ZcnblkFanWalFrame> {
    let mut header = [0u8; ZCNBLK_FAN_WAL_HEADER_LEN];
    zcnblk_fan_wal_recv_exact_dontwait_spin(stream, &mut header)?;
    ZcnblkFanWalFrame::decode(&header)
}

fn zcnblk_fan_wal_read_frame_spin_then_block(
    stream: &mut TcpStream,
    spin_budget: Option<usize>,
) -> io::Result<ZcnblkFanWalFrame> {
    let mut header = [0u8; ZCNBLK_FAN_WAL_HEADER_LEN];
    zcnblk_fan_wal_recv_exact_spin_then_block(stream, &mut header, spin_budget)?;
    ZcnblkFanWalFrame::decode(&header)
}

fn zcnblk_fan_wal_read_payload(
    stream: &mut TcpStream,
    frame: ZcnblkFanWalFrame,
) -> io::Result<Vec<u8>> {
    let mut payload = vec![0u8; frame.payload_len as usize];
    if !payload.is_empty() {
        stream.read_exact(&mut payload)?;
    }
    Ok(payload)
}

fn zcnblk_fan_wal_read_payload_dontwait_spin(
    stream: &TcpStream,
    frame: ZcnblkFanWalFrame,
) -> io::Result<Vec<u8>> {
    let mut payload = vec![0u8; frame.payload_len as usize];
    if !payload.is_empty() {
        zcnblk_fan_wal_recv_exact_dontwait_spin(stream, &mut payload)?;
    }
    Ok(payload)
}

fn zcnblk_fan_wal_read_payload_spin_then_block(
    stream: &mut TcpStream,
    frame: ZcnblkFanWalFrame,
    spin_budget: Option<usize>,
) -> io::Result<Vec<u8>> {
    let mut payload = vec![0u8; frame.payload_len as usize];
    if !payload.is_empty() {
        zcnblk_fan_wal_recv_exact_spin_then_block(stream, &mut payload, spin_budget)?;
    }
    Ok(payload)
}

fn zcnblk_fan_wal_decode_frame_slice(input: &[u8]) -> io::Result<ZcnblkFanWalFrame> {
    let header: &[u8; ZCNBLK_FAN_WAL_HEADER_LEN] = input.try_into().map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "fan WAL frame slice length {} is not {}",
                input.len(),
                ZCNBLK_FAN_WAL_HEADER_LEN
            ),
        )
    })?;
    ZcnblkFanWalFrame::decode(header)
}

fn zcnblk_fan_wal_segments(
    mode: ZcnblkFanPlacementMode,
    op: u16,
    offset: u64,
    len: usize,
    stripe_bytes: usize,
    leaf_count: usize,
) -> io::Result<Vec<ZcnblkFanSegment>> {
    match mode {
        ZcnblkFanPlacementMode::Stripe => {
            zcnblk_read_fan_map_segments(offset, len, stripe_bytes, leaf_count)
        }
        ZcnblkFanPlacementMode::Mirror => {
            if op == ZCNBLK_OP_READ {
                return zcnblk_fan_wal_mirror_read_segments(offset, len, stripe_bytes, leaf_count);
            }
            Ok((0..leaf_count)
                .map(|leaf_idx| ZcnblkFanSegment {
                    leaf_idx,
                    leaf_offset: offset,
                    payload_offset: 0,
                    len,
                })
                .collect())
        }
        ZcnblkFanPlacementMode::Raid10 => {
            zcnblk_fan_wal_raid10_segments(op, offset, len, stripe_bytes, leaf_count)
        }
    }
}

fn zcnblk_fan_wal_mirror_read_segments(
    offset: u64,
    len: usize,
    stripe_bytes: usize,
    leaf_count: usize,
) -> io::Result<Vec<ZcnblkFanSegment>> {
    if stripe_bytes == 0 || leaf_count == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-fan mirror reads require non-zero stripe bytes and leaf count",
        ));
    }
    let stripe_bytes_u64 = stripe_bytes as u64;
    let mut segments = Vec::new();
    let mut logical_offset = offset;
    let mut payload_offset = 0usize;
    let mut remaining = len;
    while remaining != 0 {
        let stripe_off = logical_offset % stripe_bytes_u64;
        let stripe_remaining = stripe_bytes - stripe_off as usize;
        let seg_len = remaining.min(stripe_remaining);
        let stripe_no = logical_offset / stripe_bytes_u64;
        segments.push(ZcnblkFanSegment {
            leaf_idx: stripe_no as usize % leaf_count,
            leaf_offset: logical_offset,
            payload_offset,
            len: seg_len,
        });
        logical_offset = logical_offset.checked_add(seg_len as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "fan WAL mirror offset overflow",
            )
        })?;
        payload_offset = payload_offset.checked_add(seg_len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "fan WAL mirror payload offset overflow",
            )
        })?;
        remaining -= seg_len;
    }
    Ok(segments)
}

fn zcnblk_fan_wal_raid10_segments(
    op: u16,
    offset: u64,
    len: usize,
    stripe_bytes: usize,
    leaf_count: usize,
) -> io::Result<Vec<ZcnblkFanSegment>> {
    if stripe_bytes == 0 || leaf_count < 4 || leaf_count % 2 != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcnblk-fan raid10 requires non-zero stripe bytes and an even leaf count of at least 4",
        ));
    }
    let pair_count = leaf_count / 2;
    let stripe_bytes_u64 = stripe_bytes as u64;
    let mut segments = Vec::new();
    let mut logical_offset = offset;
    let mut payload_offset = 0usize;
    let mut remaining = len;
    while remaining != 0 {
        let stripe_off = logical_offset % stripe_bytes_u64;
        let stripe_remaining = stripe_bytes - stripe_off as usize;
        let seg_len = remaining.min(stripe_remaining);
        let stripe_no = logical_offset / stripe_bytes_u64;
        let pair_idx = stripe_no as usize % pair_count;
        let row = stripe_no / pair_count as u64;
        let leaf_offset = row
            .checked_mul(stripe_bytes_u64)
            .and_then(|base| base.checked_add(stripe_off))
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "raid10 offset overflow"))?;
        let pair_base = pair_idx * 2;
        if op == ZCNBLK_OP_READ {
            let mirror_idx = row as usize & 1;
            segments.push(ZcnblkFanSegment {
                leaf_idx: pair_base + mirror_idx,
                leaf_offset,
                payload_offset,
                len: seg_len,
            });
        } else {
            for mirror_idx in 0..2 {
                segments.push(ZcnblkFanSegment {
                    leaf_idx: pair_base + mirror_idx,
                    leaf_offset,
                    payload_offset,
                    len: seg_len,
                });
            }
        }
        logical_offset = logical_offset.checked_add(seg_len as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "raid10 logical offset overflow",
            )
        })?;
        payload_offset = payload_offset.checked_add(seg_len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "raid10 payload offset overflow",
            )
        })?;
        remaining -= seg_len;
    }
    Ok(segments)
}

