fn ensure_aligned_to(value: usize, alignment: usize, name: &str) -> io::Result<()> {
    if value == 0 || value % alignment != 0 {
        Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name} must be a non-zero multiple of {alignment}"),
        ))
    } else {
        Ok(())
    }
}

fn validate_slot_wal_geometry_alignment(
    metadata: &fs::Metadata,
    total_bytes: usize,
    chunk_bytes: usize,
) -> io::Result<usize> {
    let queue_dir = queue_sysfs_dir(metadata)?;
    let logical_block = read_sysfs_usize(queue_dir.join("logical_block_size"))?;
    let physical_block = read_sysfs_usize(queue_dir.join("physical_block_size"))?;
    let minimum_io = read_sysfs_usize(queue_dir.join("minimum_io_size")).unwrap_or(logical_block);
    let optimal_io = read_sysfs_usize(queue_dir.join("optimal_io_size")).unwrap_or(0);
    let required_alignment = logical_block
        .max(physical_block)
        .max(minimum_io)
        .max(SECTOR_SIZE);

    ensure_aligned_to(total_bytes, required_alignment, "total-bytes")?;
    ensure_aligned_to(chunk_bytes, required_alignment, "chunk-bytes")?;

    let block_dir = block_sysfs_dir(metadata);
    let alignment_offset = read_sysfs_usize(block_dir.join("alignment_offset")).unwrap_or(0);
    if alignment_offset != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("block device alignment_offset={alignment_offset}; refusing unaligned raw IO"),
        ));
    }

    if let Ok(start_sectors) = read_sysfs_usize(block_dir.join("start")) {
        let start_bytes_mod = (start_sectors as u128).saturating_mul(logical_block as u128)
            % required_alignment as u128;
        if start_bytes_mod != 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "partition start is misaligned: start_sectors={start_sectors} \
                     logical_block_size={logical_block} required_alignment={required_alignment}"
                ),
            ));
        }
    }

    if optimal_io != 0 && chunk_bytes % optimal_io != 0 {
        eprintln!(
            "warning: chunk-bytes={chunk_bytes} is aligned to required geometry \
             ({required_alignment}) but not optimal_io_size={optimal_io}"
        );
    }

    Ok(required_alignment)
}

fn validate_slot_wal_queue_limits(
    metadata: &fs::Metadata,
    chunk_bytes: usize,
    segment_bytes: usize,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<()> {
    let queue_dir = queue_sysfs_dir(metadata)?;

    if let Ok(max_segments) = read_sysfs_usize(queue_dir.join("max_segments")) {
        let needed_segments = chunk_bytes.div_ceil(segment_bytes);
        if needed_segments > max_segments {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "chunk-bytes={chunk_bytes} needs {needed_segments} {} segments, but block \
                     queue max_segments={max_segments}; use <= {} bytes or a larger buffer backing",
                    buffer_mode.as_str(),
                    max_segments.saturating_mul(segment_bytes)
                ),
            ));
        }
    }

    if let Ok(max_hw_sectors_kb) = read_sysfs_usize(queue_dir.join("max_hw_sectors_kb")) {
        let max_hw_bytes = max_hw_sectors_kb.saturating_mul(1024);
        if chunk_bytes > max_hw_bytes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "chunk-bytes={chunk_bytes} exceeds block queue max_hw_sectors_kb={max_hw_sectors_kb}"
                ),
            ));
        }
    }

    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum SlotWalTargetKind {
    NullBlock,
    RamBlockDisk,
    ZcBlockRamDisk,
    ZcNetworkBlockClient,
    PartUuid(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SlotWalTarget {
    open_path: PathBuf,
    label: String,
    kind: SlotWalTargetKind,
}

impl SlotWalTarget {
    fn null_block(path: &str) -> Self {
        Self {
            open_path: PathBuf::from(path),
            label: path.to_owned(),
            kind: SlotWalTargetKind::NullBlock,
        }
    }

    fn ram_block_disk(path: &str) -> Self {
        Self {
            open_path: PathBuf::from(path),
            label: path.to_owned(),
            kind: SlotWalTargetKind::RamBlockDisk,
        }
    }

    fn zc_block_ramdisk(path: &str) -> Self {
        Self {
            open_path: PathBuf::from(path),
            label: path.to_owned(),
            kind: SlotWalTargetKind::ZcBlockRamDisk,
        }
    }

    fn zc_network_block_client(path: &str) -> Self {
        Self {
            open_path: PathBuf::from(path),
            label: path.to_owned(),
            kind: SlotWalTargetKind::ZcNetworkBlockClient,
        }
    }

    fn from_partuuid(uuid: &str) -> io::Result<Self> {
        let uuid = normalize_partuuid(uuid)?;
        Ok(Self {
            open_path: Path::new(BY_PARTUUID_DIR).join(&uuid),
            label: format!("PARTUUID={uuid}"),
            kind: SlotWalTargetKind::PartUuid(uuid),
        })
    }

    fn open_path(&self) -> &Path {
        &self.open_path
    }

    fn label(&self) -> &str {
        &self.label
    }

    fn is_synthetic_block(&self) -> bool {
        matches!(
            self.kind,
            SlotWalTargetKind::NullBlock
                | SlotWalTargetKind::RamBlockDisk
                | SlotWalTargetKind::ZcBlockRamDisk
                | SlotWalTargetKind::ZcNetworkBlockClient
        )
    }

    fn partuuid(&self) -> Option<&str> {
        match &self.kind {
            SlotWalTargetKind::PartUuid(uuid) => Some(uuid),
            SlotWalTargetKind::NullBlock
            | SlotWalTargetKind::RamBlockDisk
            | SlotWalTargetKind::ZcBlockRamDisk
            | SlotWalTargetKind::ZcNetworkBlockClient => None,
        }
    }
}

fn dev_block_name_suffix<'a>(arg: &'a str, prefix: &str) -> Option<&'a str> {
    let path = Path::new(arg);
    if path.parent() != Some(Path::new("/dev")) {
        return None;
    }

    path.file_name()?.to_str()?.strip_prefix(prefix)
}

fn is_numbered_dev_block(arg: &str, prefix: &str) -> bool {
    dev_block_name_suffix(arg, prefix).is_some_and(|suffix| {
        !suffix.is_empty() && suffix.bytes().all(|byte| byte.is_ascii_digit())
    })
}

fn strip_prefix_ci<'a>(value: &'a str, prefix: &str) -> Option<&'a str> {
    if value.len() >= prefix.len() && value[..prefix.len()].eq_ignore_ascii_case(prefix) {
        Some(&value[prefix.len()..])
    } else {
        None
    }
}

fn normalize_partuuid(value: &str) -> io::Result<String> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || !trimmed
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "PARTUUID must be non-empty and contain only ASCII letters, digits, and '-'",
        ));
    }

    Ok(trimmed.to_ascii_lowercase())
}

fn parse_slot_wal_target(arg: &str) -> io::Result<SlotWalTarget> {
    if is_numbered_dev_block(arg, "nullb") {
        return Ok(SlotWalTarget::null_block(arg));
    }
    if is_numbered_dev_block(arg, "ram") {
        return Ok(SlotWalTarget::ram_block_disk(arg));
    }
    if is_numbered_dev_block(arg, "zcbrd") {
        return Ok(SlotWalTarget::zc_block_ramdisk(arg));
    }
    if is_numbered_dev_block(arg, "zcnblk") {
        return Ok(SlotWalTarget::zc_network_block_client(arg));
    }

    if let Some(uuid) =
        strip_prefix_ci(arg, "PARTUUID=").or_else(|| strip_prefix_ci(arg, "partuuid:"))
    {
        return SlotWalTarget::from_partuuid(uuid);
    }

    let path = Path::new(arg);
    if let Ok(remainder) = path.strip_prefix(BY_PARTUUID_DIR) {
        if remainder.components().count() == 1 {
            if let Some(uuid) = remainder.file_name().and_then(|name| name.to_str()) {
                return SlotWalTarget::from_partuuid(uuid);
            }
        }
    }

    if arg.contains('-') && !arg.contains('/') {
        return SlotWalTarget::from_partuuid(arg);
    }

    Err(io::Error::new(
        io::ErrorKind::InvalidInput,
        "slot WAL bench targets must be /dev/nullbN, /dev/ramN, or /dev/zcbrdN for synthetic tests, \
         /dev/zcnblkN for the zcnblk client edge, or PARTUUID=<uuid> for explicitly allowlisted real raw block devices",
    ))
}

fn raw_partition_allowlist_path() -> PathBuf {
    if let Ok(path) = env::var("URING_PLAY_RAW_PARTITION_ALLOWLIST") {
        return PathBuf::from(path);
    }

    let cwd_path = PathBuf::from(RAW_PARTITION_ALLOWLIST);
    if cwd_path.exists() {
        return cwd_path;
    }

    Path::new(env!("CARGO_MANIFEST_DIR")).join(RAW_PARTITION_ALLOWLIST)
}

fn parse_partuuid_token(value: &str) -> io::Result<String> {
    let value = strip_prefix_ci(value.trim(), "PARTUUID=")
        .or_else(|| strip_prefix_ci(value.trim(), "partuuid:"))
        .unwrap_or(value.trim());
    normalize_partuuid(value)
}

fn allowed_raw_partuuids() -> io::Result<Vec<String>> {
    let path = raw_partition_allowlist_path();
    let contents = fs::read_to_string(&path).map_err(|err| {
        io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "cannot read raw partition allowlist {}: {err}",
                path.display()
            ),
        )
    })?;

    let mut allowed = Vec::new();
    for (line_idx, line) in contents.lines().enumerate() {
        let token = line.split('#').next().unwrap_or("").trim();
        if token.is_empty() {
            continue;
        }

        allowed.push(parse_partuuid_token(token).map_err(|err| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "invalid PARTUUID in raw partition allowlist {} line {}: {err}",
                    path.display(),
                    line_idx + 1
                ),
            )
        })?);
    }

    if allowed.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!("raw partition allowlist {} is empty", path.display()),
        ));
    }

    Ok(allowed)
}

fn ensure_partuuid_allowlisted(target_uuid: &str) -> io::Result<()> {
    let allowed = allowed_raw_partuuids()?;
    if allowed.iter().any(|uuid| uuid == target_uuid) {
        return Ok(());
    }

    Err(io::Error::new(
        io::ErrorKind::PermissionDenied,
        format!(
            "PARTUUID={target_uuid} is not in {}; refusing real raw block target",
            raw_partition_allowlist_path().display()
        ),
    ))
}

fn known_block_signature(prefix: &[u8]) -> Option<&'static str> {
    if prefix.get(0..6) == Some(b"LUKS\xba\xbe") {
        return Some("LUKS");
    }
    if prefix.get(0..4) == Some(b"XFSB") {
        return Some("XFS");
    }
    if prefix.get(3..11) == Some(b"NTFS    ") {
        return Some("NTFS");
    }
    if prefix.get(3..11) == Some(b"EXFAT   ") {
        return Some("exFAT");
    }
    if prefix.get(3..9) == Some(b"FVE-FS") {
        return Some("BitLocker");
    }
    if matches!(prefix.get(54..59), Some(b"FAT12" | b"FAT16"))
        || prefix.get(82..87) == Some(b"FAT32")
    {
        return Some("FAT");
    }
    if prefix.get(1080..1082) == Some(&[0x53, 0xef]) {
        return Some("ext filesystem");
    }
    if prefix.get(0x10040..0x10048) == Some(b"_BHRfS_M") {
        return Some("Btrfs");
    }
    if prefix.get(32..36) == Some(b"NXSB") {
        return Some("APFS");
    }

    None
}

fn ensure_no_known_filesystem_signature(target: &SlotWalTarget) -> io::Result<()> {
    let mut file = fs::File::open(target.open_path())?;
    let mut prefix = vec![0u8; 128 * 1024];
    let read = file.read(&mut prefix)?;
    prefix.truncate(read);

    if let Some(signature) = known_block_signature(&prefix) {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "refusing raw write to {} because it has a {signature} signature",
                target.label()
            ),
        ));
    }

    Ok(())
}

fn validate_raw_block_write_allowed(target: &SlotWalTarget) -> io::Result<()> {
    if target.is_synthetic_block() {
        return Ok(());
    }

    let Some(target_uuid) = target.partuuid() else {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            "raw block writes require a PARTUUID target",
        ));
    };

    ensure_partuuid_allowlisted(target_uuid)?;

    if !env_truthy("URING_PLAY_ALLOW_RAW_BLOCK_WRITE") {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "raw block writes to PARTUUID={target_uuid} are destructive; set \
                 URING_PLAY_ALLOW_RAW_BLOCK_WRITE=1 to override"
            ),
        ));
    }

    let expected = env::var("URING_PLAY_RAW_TARGET_PARTUUID").map_err(|_| {
        io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "raw block writes to PARTUUID={target_uuid} require explicit confirmation: \
                 set URING_PLAY_RAW_TARGET_PARTUUID={target_uuid}"
            ),
        )
    })?;
    let expected = normalize_partuuid(&expected)?;
    if expected != target_uuid {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "URING_PLAY_RAW_TARGET_PARTUUID={expected} does not match PARTUUID={target_uuid}"
            ),
        ));
    }

    Ok(())
}

fn validate_slot_wal_write_target_safety(
    target: &SlotWalTarget,
    metadata: &fs::Metadata,
) -> io::Result<()> {
    validate_raw_block_write_allowed(target)?;
    if target.is_synthetic_block() {
        return Ok(());
    }

    let major_minor = linux_dev_major_minor(metadata);
    let mountinfo = fs::read_to_string("/proc/self/mountinfo")?;
    for line in mountinfo.lines() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.get(2) == Some(&major_minor.as_str()) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!("refusing raw write to mounted {}", target.label()),
            ));
        }
    }

    let holders_dir = format!("/sys/dev/block/{major_minor}/holders");
    if let Ok(mut entries) = fs::read_dir(&holders_dir)
        && entries.next().transpose()?.is_some()
    {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "refusing raw write to {} while it has device holders",
                target.label()
            ),
        ));
    }

    let target_canonical = fs::canonicalize(target.open_path()).ok();
    if let Ok(swaps) = fs::read_to_string("/proc/swaps") {
        for line in swaps.lines().skip(1) {
            let Some(swap_path) = line.split_whitespace().next() else {
                continue;
            };
            if swap_path == target.open_path().to_string_lossy()
                || target_canonical
                    .as_ref()
                    .is_some_and(|path| fs::canonicalize(swap_path).ok().as_ref() == Some(path))
            {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    format!("refusing raw write to active swap {}", target.label()),
                ));
            }
        }
    }

    ensure_no_known_filesystem_signature(target)?;

    Ok(())
}

fn fill_slot_wal_buffers(buffers: &FixedSendBuffers, chunk_bytes: usize) {
    buffers.fill_each(chunk_bytes, |buf| {
        let mut seed = 0x9e37_79b9_7f4a_7c15u64;
        for word in buf.chunks_exact_mut(8) {
            seed = seed
                .wrapping_mul(0xbf58_476d_1ce4_e5b9)
                .wrapping_add(0x94d0_49bb_1331_11ebu64);
            word.copy_from_slice(&seed.to_le_bytes());
        }
        let remainder = buf.len() & 7;
        if remainder != 0 {
            let start = buf.len() - remainder;
            let tail = seed.to_le_bytes();
            buf[start..].copy_from_slice(&tail[..remainder]);
        }
    });
}

#[derive(Clone, Copy)]
struct SlotWalWorkerResult {
    worker: usize,
    bytes: usize,
    ops: usize,
    elapsed: Duration,
    base_offset: u64,
    region_bytes: usize,
    slot_count: usize,
    target_cpu: i32,
    affinity_applied: bool,
    local_cpu: i32,
    worker_numa_node: Option<i32>,
    completion_batch: usize,
    buffer_base: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    buffer_alignment: usize,
    buffer_mode: SlotWalBufferMode,
    segment_bytes: usize,
    slot_buffer_layout: SlotBufferLayout,
    memory_policy: &'static str,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UringWriteMode {
    Write,
    WriteFixed,
    WriteFixedFile,
}

impl UringWriteMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "write" | "normal" | "plain" => Ok(Self::Write),
            "fixed" | "write-fixed" | "fixedbuf" | "fixedbufs" => Ok(Self::WriteFixed),
            "fixed-file" | "fixedfile" | "fixedbufs-registerfiles" | "fio-fixed" => {
                Ok(Self::WriteFixedFile)
            }
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown uring write mode {other:?}; use write, fixed, or fixed-file"),
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Write => "write",
            Self::WriteFixed => "fixed",
            Self::WriteFixedFile => "fixed-file",
        }
    }

    fn uses_registered_buffers(self) -> bool {
        matches!(self, Self::WriteFixed | Self::WriteFixedFile)
    }

    fn uses_registered_file(self) -> bool {
        matches!(self, Self::WriteFixedFile)
    }
}

struct UringWriteWorkerResult {
    worker: usize,
    bytes: usize,
    ops: usize,
    elapsed: Duration,
    base_offset: u64,
    completion_batch: usize,
    target_cpu: i32,
    affinity_applied: bool,
    local_cpu: i32,
    buffer_base: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    buffer_alignment: usize,
    memory_policy: &'static str,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct WalRegionPlan {
    worker: usize,
    base_offset: u64,
    len_bytes: usize,
}

impl WalRegionPlan {
    fn end_offset(self) -> io::Result<u64> {
        self.base_offset
            .checked_add(self.len_bytes as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "WAL region end overflow"))
    }
}

fn validate_slot_wal_common(
    target_arg: &str,
    total_bytes: usize,
    chunk_bytes: usize,
    mode: SlotWalMode,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<(SlotWalTarget, u64, usize, usize)> {
    ensure_sector_aligned(total_bytes, "total-bytes")?;
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    if total_bytes % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "total-bytes must be an exact multiple of chunk-bytes",
        ));
    }

    let target = parse_slot_wal_target(target_arg)?;
    if let Some(partuuid) = target.partuuid() {
        ensure_partuuid_allowlisted(partuuid)?;
    }
    let metadata = fs::metadata(target.open_path())?;
    if !metadata.file_type().is_block_device() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "slot WAL bench target must resolve to a raw block device",
        ));
    }
    if matches!(mode, SlotWalMode::Write) {
        validate_slot_wal_write_target_safety(&target, &metadata)?;
    }
    let required_alignment =
        validate_slot_wal_geometry_alignment(&metadata, total_bytes, chunk_bytes)?;
    let segment_bytes = buffer_mode.segment_bytes()?;
    validate_slot_wal_queue_limits(&metadata, chunk_bytes, segment_bytes, buffer_mode)?;

    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC)
        .open(target.open_path())?;
    let device_bytes = block_device_size(file.as_raw_fd())?;
    if total_bytes as u64 > device_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("total-bytes exceeds block device size {device_bytes}"),
        ));
    }

    Ok((target, device_bytes, required_alignment, segment_bytes))
}

fn validate_slot_wal_plan_common(
    target_arg: &str,
    total_bytes: usize,
    chunk_bytes: usize,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<(SlotWalTarget, fs::Metadata, u64, usize, usize)> {
    ensure_sector_aligned(total_bytes, "total-bytes")?;
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    if total_bytes % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "total-bytes must be an exact multiple of chunk-bytes",
        ));
    }

    let target = parse_slot_wal_target(target_arg)?;
    if let Some(partuuid) = target.partuuid() {
        ensure_partuuid_allowlisted(partuuid)?;
    }
    let metadata = fs::metadata(target.open_path())?;
    if !metadata.file_type().is_block_device() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "slot WAL target must resolve to a raw block device",
        ));
    }

    let required_alignment =
        validate_slot_wal_geometry_alignment(&metadata, total_bytes, chunk_bytes)?;
    let segment_bytes = buffer_mode.segment_bytes()?;
    validate_slot_wal_queue_limits(&metadata, chunk_bytes, segment_bytes, buffer_mode)?;

    let file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_CLOEXEC)
        .open(target.open_path())?;
    let device_bytes = block_device_size(file.as_raw_fd())?;
    if total_bytes as u64 > device_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("total-bytes exceeds block device size {device_bytes}"),
        ));
    }

    Ok((
        target,
        metadata,
        device_bytes,
        required_alignment,
        segment_bytes,
    ))
}

fn make_linear_wal_regions(
    workers: usize,
    bytes_per_worker: usize,
) -> io::Result<Vec<WalRegionPlan>> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    let mut regions = Vec::with_capacity(workers);
    for worker in 0..workers {
        let base_offset = (worker as u64)
            .checked_mul(bytes_per_worker as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
        regions.push(WalRegionPlan {
            worker,
            base_offset,
            len_bytes: bytes_per_worker,
        });
    }
    Ok(regions)
}

fn validate_wal_regions(regions: &[WalRegionPlan], device_bytes: u64) -> io::Result<()> {
    if regions.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "at least one WAL region is required",
        ));
    }

    let mut sorted = regions.to_vec();
    sorted.sort_by_key(|region| region.base_offset);
    let mut previous_end = None;
    for region in &sorted {
        if region.len_bytes == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("worker {} has an empty WAL region", region.worker),
            ));
        }
        let end = region.end_offset()?;
        if end > device_bytes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "worker {} WAL region [{}..{}) exceeds block device size {device_bytes}",
                    region.worker, region.base_offset, end
                ),
            ));
        }
        if let Some((prev_worker, prev_end)) = previous_end
            && region.base_offset < prev_end
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "WAL regions overlap: worker {prev_worker} ends at {prev_end}, \
                     worker {} starts at {}",
                    region.worker, region.base_offset
                ),
            ));
        }
        previous_end = Some((region.worker, end));
    }

    Ok(())
}

fn address_alignment(addr: usize) -> usize {
    if addr == 0 {
        0
    } else {
        1usize << addr.trailing_zeros()
    }
}

fn validate_slot_wal_pipeline(pipeline: usize, ring_entries: u32) -> io::Result<()> {
    if pipeline == 0 || pipeline > u16::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("pipeline must be between 1 and {}", u16::MAX),
        ));
    }
    if pipeline > ring_entries as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "pipeline must be <= ring-entries",
        ));
    }
    Ok(())
}

const BATON_SOURCE_CQE_TAG: u64 = 1u64 << 63;
const BATON_WRITE_CQE_TAG: u64 = 1u64 << 62;
const BATON_CREDIT_CQE_TAG: u64 = 1u64 << 61;
const BATON_VALUE_MASK: u64 = BATON_CREDIT_CQE_TAG - 1;

#[derive(Clone)]
enum BatonSink {
    Null,
    Block(SlotWalTarget),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BatonMode {
    RoundTrip,
    Credit { batch: usize },
}

impl BatonMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "roundtrip" | "return" | "token" | "per-token" | "1" => Ok(Self::RoundTrip),
            "credit" | "credit:64" | "batch" | "batch:64" => Ok(Self::Credit { batch: 64 }),
            other => {
                if let Some(batch) = other
                    .strip_prefix("credit:")
                    .or_else(|| other.strip_prefix("batch:"))
                    .or_else(|| other.strip_prefix("credits:"))
                {
                    let batch = batch.parse::<usize>().map_err(|err| {
                        io::Error::new(
                            io::ErrorKind::InvalidInput,
                            format!("invalid baton credit batch {batch:?}: {err}"),
                        )
                    })?;
                    if batch == 0 || batch > u32::MAX as usize {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "baton credit batch must be between 1 and u32::MAX",
                        ));
                    }
                    return Ok(Self::Credit { batch });
                }

                Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!(
                        "unknown baton mode {other:?}; use roundtrip, credit, or credit:<batch>"
                    ),
                ))
            }
        }
    }

    fn label(self) -> String {
        match self {
            Self::RoundTrip => "roundtrip".to_string(),
            Self::Credit { batch } => format!("credit:{batch}"),
        }
    }

    fn credit_batch(self) -> Option<usize> {
        match self {
            Self::RoundTrip => None,
            Self::Credit { batch } => Some(batch),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BatonPinMode {
    Off,
    Pair,
    Hctx,
    HctxLocal,
}

impl BatonPinMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "0" | "false" | "no" | "off" | "unpin" => Ok(Self::Off),
            "1" | "true" | "yes" | "pin" | "pair" => Ok(Self::Pair),
            "hctx" | "mq" | "blk-mq" | "block-mq" | "hctx-spread" => Ok(Self::Hctx),
            "hctx-local" | "mq-local" | "blk-mq-local" => Ok(Self::HctxLocal),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown baton pin mode {other:?}; use true, false, hctx, or hctx-local"),
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Off => "off",
            Self::Pair => "pair",
            Self::Hctx => "hctx",
            Self::HctxLocal => "hctx-local",
        }
    }

    fn pin_requested(self) -> bool {
        !matches!(self, Self::Off)
    }
}

#[derive(Clone, Copy)]
struct BatonPinAssignment {
    producer_cpu: Option<usize>,
    writer_cpu: Option<usize>,
}

struct BatonPinPlan {
    mode: BatonPinMode,
    assignments: Vec<BatonPinAssignment>,
    detail: String,
}

struct BatonTargetPlan {
    label: String,
    worker_sinks: Vec<BatonSink>,
    regions: Vec<WalRegionPlan>,
    segment_bytes: usize,
}

fn baton_hctx_cpu_groups(target: &SlotWalTarget) -> io::Result<Vec<(usize, Vec<usize>)>> {
    let metadata = fs::metadata(target.open_path())?;
    let mq_dir = disk_sysfs_dir(&metadata)?.join("mq");
    let online_cpus = online_cpu_count();
    let mut groups = Vec::new();

    for entry in fs::read_dir(&mq_dir)? {
        let entry = entry?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        let Ok(queue_id) = name.parse::<usize>() else {
            continue;
        };
        let cpu_list_path = entry.path().join("cpu_list");
        let Ok(cpu_list) = fs::read_to_string(&cpu_list_path) else {
            continue;
        };
        let mut cpus = parse_cpu_list(&cpu_list)?;
        cpus.retain(|cpu| *cpu < online_cpus);
        if cpus.is_empty() {
            continue;
        }
        // null_blk exposes its poll hctx as an all-CPU map. For baton writes we
        // want the normal submit hctxs that current CPU selection hashes into.
        if cpus.len() >= online_cpus {
            continue;
        }
        groups.push((queue_id, cpus));
    }

    groups.sort_by_key(|(queue_id, _)| *queue_id);
    Ok(groups)
}

fn baton_pin_plan(
    worker_sinks: &[BatonSink],
    mode: BatonPinMode,
    workers: usize,
) -> io::Result<BatonPinPlan> {
    let default_assignments = || {
        vec![
            BatonPinAssignment {
                producer_cpu: None,
                writer_cpu: None,
            };
            workers
        ]
    };

    match mode {
        BatonPinMode::Off | BatonPinMode::Pair => Ok(BatonPinPlan {
            mode,
            assignments: default_assignments(),
            detail: "default-index-map".to_string(),
        }),
        BatonPinMode::Hctx | BatonPinMode::HctxLocal => {
            let mut hctx_cache = BTreeMap::<String, Vec<(usize, Vec<usize>)>>::new();
            let mut target_worker_counts = BTreeMap::<String, usize>::new();
            let mut assignments = Vec::with_capacity(workers);
            for worker in 0..workers {
                let BatonSink::Block(target) = &worker_sinks[worker] else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "hctx pin mode requires block sinks for every worker",
                    ));
                };
                let key = target.open_path().display().to_string();
                if !hctx_cache.contains_key(&key) {
                    let groups = baton_hctx_cpu_groups(target)?;
                    if groups.is_empty() {
                        return Err(io::Error::new(
                            io::ErrorKind::NotFound,
                            format!("no blk-mq hctx CPU map found for {}", target.label()),
                        ));
                    }
                    hctx_cache.insert(key.clone(), groups);
                }
                let groups = hctx_cache
                    .get(&key)
                    .expect("hctx cache entry inserted above");
                let pin_index = if matches!(mode, BatonPinMode::HctxLocal) {
                    let local_worker = target_worker_counts.entry(key).or_insert(0);
                    let local_index = *local_worker;
                    *local_worker += 1;
                    local_index
                } else {
                    worker
                };
                let (_, cpus) = &groups[pin_index % groups.len()];
                let round = pin_index / groups.len();
                let writer_cpu = cpus[round % cpus.len()];
                let producer_cpu = if cpus.len() > 1 {
                    Some(cpus[(round + 1) % cpus.len()])
                } else {
                    None
                };
                assignments.push(BatonPinAssignment {
                    producer_cpu,
                    writer_cpu: Some(writer_cpu),
                });
            }

            let hctxs: Vec<String> = hctx_cache
                .iter()
                .map(|(target, groups)| {
                    let maps: Vec<String> = groups
                        .iter()
                        .map(|(queue_id, cpus)| format!("{queue_id}:{}", format_cpu_list(cpus)))
                        .collect();
                    format!("{target} hctxs={} [{}]", groups.len(), maps.join(" "))
                })
                .collect();
            Ok(BatonPinPlan {
                mode,
                assignments,
                detail: hctxs.join("; "),
            })
        }
    }
}

#[derive(Clone, Copy)]
struct BatonProducerResult {
    worker: usize,
    tokens: usize,
    bytes: usize,
    elapsed: Duration,
    target_cpu: i32,
    affinity_applied: bool,
    start_cpu: i32,
    end_cpu: i32,
    cpu: Duration,
    ignored_source_cqes: usize,
    ring_stats: RawRingStats,
}

#[derive(Clone, Copy)]
struct BatonWriterResult {
    worker: usize,
    tokens: usize,
    bytes: usize,
    elapsed: Duration,
    target_cpu: i32,
    affinity_applied: bool,
    start_cpu: i32,
    end_cpu: i32,
    cpu: Duration,
    writes: usize,
    ignored_source_cqes: usize,
    buffer_base: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    memory_policy: &'static str,
    ring_stats: RawRingStats,
}

#[derive(Clone, Copy)]
struct BatonWorkerResult {
    producer: BatonProducerResult,
    writer: BatonWriterResult,
}

fn baton_source_user_data(slot: usize) -> u64 {
    BATON_SOURCE_CQE_TAG | slot as u64
}

fn baton_write_user_data(slot: usize) -> u64 {
    BATON_WRITE_CQE_TAG | slot as u64
}

fn baton_slot_from_user_data(user_data: u64, pipeline: usize, label: &str) -> io::Result<usize> {
    let slot = (user_data & BATON_VALUE_MASK) as usize;
    if slot >= pipeline {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} returned invalid slot user_data={user_data:#x} slot={slot}"),
        ));
    }
    Ok(slot)
}

fn baton_value_from_user_data(user_data: u64, label: &str) -> io::Result<usize> {
    if user_data & !BATON_VALUE_MASK != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} returned tagged user_data={user_data:#x}"),
        ));
    }
    usize::try_from(user_data & BATON_VALUE_MASK).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} value does not fit usize: {user_data:#x}"),
        )
    })
}

fn baton_send_token(
    ring: &mut RawRing,
    target_ring_fd: i32,
    slot: usize,
    chunk_bytes: u32,
    skip_source_cqe: bool,
) -> io::Result<()> {
    ring.queue_msg_ring(
        target_ring_fd,
        chunk_bytes,
        slot as u64,
        0,
        skip_source_cqe,
        baton_source_user_data(slot),
    )
}

fn baton_send_value(
    ring: &mut RawRing,
    target_ring_fd: i32,
    value: usize,
    chunk_bytes: u32,
    skip_source_cqe: bool,
) -> io::Result<()> {
    if value as u64 > BATON_VALUE_MASK {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "baton value exceeds user_data value mask",
        ));
    }
    ring.queue_msg_ring(
        target_ring_fd,
        chunk_bytes,
        value as u64,
        0,
        skip_source_cqe,
        baton_source_user_data(value),
    )
}

fn baton_send_credit(
    ring: &mut RawRing,
    target_ring_fd: i32,
    credit_count: usize,
    skip_source_cqe: bool,
) -> io::Result<()> {
    if credit_count == 0 || credit_count > u32::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "baton credit count must fit in MSG_RING result",
        ));
    }
    ring.queue_msg_ring(
        target_ring_fd,
        credit_count as u32,
        BATON_CREDIT_CQE_TAG,
        0,
        skip_source_cqe,
        baton_source_user_data(credit_count),
    )
}

fn baton_next_completion_ignoring_source(
    ring: &mut RawRing,
    ignored_source_cqes: &mut usize,
) -> io::Result<IoUringCqe32> {
    loop {
        let cqe = ring.wait_cqe()?;
        if cqe.user_data & BATON_SOURCE_CQE_TAG != 0 {
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            *ignored_source_cqes += 1;
            continue;
        }
        return Ok(cqe);
    }
}

#[allow(clippy::too_many_arguments)]
fn uring_baton_producer_worker(
    worker: usize,
    producer_fd_tx: mpsc::Sender<io::Result<i32>>,
    writer_fd_rx: mpsc::Receiver<i32>,
    release_rx: mpsc::Receiver<()>,
    tokens: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    pin_mode: BatonPinMode,
    planned_cpu: Option<usize>,
    baton_mode: BatonMode,
    skip_source_cqe: bool,
    ring_stats_enabled: bool,
) -> io::Result<BatonProducerResult> {
    let affinity = pin_current_thread_if_requested_to_cpu(
        "uring-baton-producer",
        worker * 2,
        pin_mode.pin_requested(),
        planned_cpu,
    );
    let start_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let mut ring = RawRing::new_with_stats(
        ring_entries,
        ring_entries.saturating_mul(2),
        ring_stats_enabled,
    )?;
    let producer_fd = ring.fd();
    producer_fd_tx
        .send(Ok(producer_fd))
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton producer fd channel"))?;
    let writer_fd = writer_fd_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton writer fd channel"))?;
    release_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton release channel"))?;

    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "chunk-bytes must fit in u32 for MSG_RING res",
        )
    })?;
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut submitted = 0usize;
    let mut returned = 0usize;
    let mut inflight = 0usize;
    let mut ignored_source_cqes = 0usize;
    let started = Instant::now();

    match baton_mode {
        BatonMode::RoundTrip => {
            while returned < tokens {
                while submitted < tokens && !free_slots.is_empty() {
                    let slot = free_slots.pop().expect("free slot");
                    baton_send_token(&mut ring, writer_fd, slot, chunk_bytes_u32, skip_source_cqe)?;
                    submitted += 1;
                    inflight += 1;
                }
                ring.submit_pending()?;
                if inflight == 0 {
                    break;
                }

                let mut drained = 0usize;
                loop {
                    let cqe = match ring.try_pop_cqe() {
                        Some(cqe) => cqe,
                        None if drained == 0 => baton_next_completion_ignoring_source(
                            &mut ring,
                            &mut ignored_source_cqes,
                        )?,
                        None => break,
                    };
                    drained += 1;
                    if cqe.user_data & BATON_SOURCE_CQE_TAG != 0 {
                        if cqe.res < 0 {
                            return Err(io::Error::from_raw_os_error(-cqe.res));
                        }
                        ignored_source_cqes += 1;
                        continue;
                    }
                    if cqe.res < 0 {
                        return Err(io::Error::from_raw_os_error(-cqe.res));
                    }
                    let slot = baton_slot_from_user_data(cqe.user_data, pipeline, "baton return")?;
                    returned += 1;
                    inflight -= 1;
                    free_slots.push(slot);
                }
            }
        }
        BatonMode::Credit { .. } => {
            let mut free_credit = pipeline;
            while returned < tokens {
                while submitted < tokens && free_credit > 0 {
                    baton_send_value(
                        &mut ring,
                        writer_fd,
                        submitted,
                        chunk_bytes_u32,
                        skip_source_cqe,
                    )?;
                    submitted += 1;
                    inflight += 1;
                    free_credit -= 1;
                }
                ring.submit_pending()?;

                let mut drained = 0usize;
                loop {
                    let cqe = match ring.try_pop_cqe() {
                        Some(cqe) => cqe,
                        None if drained == 0 => baton_next_completion_ignoring_source(
                            &mut ring,
                            &mut ignored_source_cqes,
                        )?,
                        None => break,
                    };
                    drained += 1;
                    if cqe.user_data & BATON_SOURCE_CQE_TAG != 0 {
                        if cqe.res < 0 {
                            return Err(io::Error::from_raw_os_error(-cqe.res));
                        }
                        ignored_source_cqes += 1;
                        continue;
                    }
                    if cqe.res < 0 {
                        return Err(io::Error::from_raw_os_error(-cqe.res));
                    }
                    if cqe.user_data & BATON_CREDIT_CQE_TAG == 0 {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!(
                                "baton credit mode expected credit CQE, got user_data={:#x}",
                                cqe.user_data
                            ),
                        ));
                    }
                    let credit = usize::try_from(cqe.res).map_err(|_| {
                        io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!("negative baton credit result {}", cqe.res),
                        )
                    })?;
                    if credit == 0 || credit > inflight {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!("invalid baton credit {credit} with inflight={inflight}"),
                        ));
                    }
                    returned += credit;
                    inflight -= credit;
                    free_credit += credit;
                }
            }
        }
    }

    let elapsed = started.elapsed();
    let end_cpu = current_cpu();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);
    let ring_stats = ring.stats();
    Ok(BatonProducerResult {
        worker,
        tokens,
        bytes: tokens * chunk_bytes,
        elapsed,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        cpu,
        ignored_source_cqes,
        ring_stats,
    })
}

#[allow(clippy::too_many_arguments)]
fn uring_baton_writer_worker(
    worker: usize,
    sink: BatonSink,
    base_offset: u64,
    producer_fd_rx: mpsc::Receiver<i32>,
    writer_fd_tx: mpsc::Sender<io::Result<i32>>,
    release_rx: mpsc::Receiver<()>,
    tokens: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    pin_mode: BatonPinMode,
    planned_cpu: Option<usize>,
    baton_mode: BatonMode,
    skip_source_cqe: bool,
    ring_stats_enabled: bool,
) -> io::Result<BatonWriterResult> {
    let affinity = pin_current_thread_if_requested_to_cpu(
        "uring-baton-writer",
        worker * 2 + 1,
        pin_mode.pin_requested(),
        planned_cpu,
    );
    let start_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "chunk-bytes must fit in u32 for SQE len field",
        )
    })?;
    let mut ring = RawRing::new_with_stats(
        ring_entries,
        ring_entries.saturating_mul(2),
        ring_stats_enabled,
    )?;

    let mut file = None;
    let mut slot_ids = Vec::new();
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    fill_slot_wal_buffers(&buffers, chunk_bytes);
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let memory_policy = buffers.memory_policy();

    if let BatonSink::Block(target) = &sink {
        let opened = OpenOptions::new()
            .read(true)
            .write(true)
            .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
            .open(target.open_path())?;
        let fd = opened.as_raw_fd();
        let mut fds = [fd];
        ring.register_files(&mut fds)?;
        let mut iovecs = buffers.iovecs(chunk_bytes);
        ring.register_buffers(&mut iovecs)?;
        for buf_index in 0..pipeline {
            slot_ids.push(ring.register_io_slot(buf_index as u32, 0)?);
        }
        file = Some(opened);
    }

    let writer_fd = ring.fd();
    writer_fd_tx
        .send(Ok(writer_fd))
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton writer fd channel"))?;
    let producer_fd = producer_fd_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton producer fd channel"))?;
    release_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton release channel"))?;

    let started = Instant::now();
    let mut received_tokens = 0usize;
    let mut returned_tokens = 0usize;
    let mut writes = 0usize;
    let mut ignored_source_cqes = 0usize;
    let mut completed_prefix = 0usize;
    let mut pending_credit = 0usize;
    let mut completed_tokens = if baton_mode.credit_batch().is_some() {
        vec![false; pipeline]
    } else {
        Vec::new()
    };

    while returned_tokens < tokens {
        let mut drained = 0usize;
        loop {
            let cqe = match ring.try_pop_cqe() {
                Some(cqe) => cqe,
                None if drained == 0 => {
                    baton_next_completion_ignoring_source(&mut ring, &mut ignored_source_cqes)?
                }
                None => break,
            };
            drained += 1;
            if cqe.user_data & BATON_SOURCE_CQE_TAG != 0 {
                if cqe.res < 0 {
                    return Err(io::Error::from_raw_os_error(-cqe.res));
                }
                ignored_source_cqes += 1;
                continue;
            }
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }

            if cqe.user_data & BATON_WRITE_CQE_TAG != 0 {
                let value = cqe.user_data & BATON_VALUE_MASK;
                let token = value as usize;
                let slot = match baton_mode {
                    BatonMode::RoundTrip => {
                        baton_slot_from_user_data(cqe.user_data, pipeline, "baton write")?
                    }
                    BatonMode::Credit { .. } => token % pipeline,
                };
                if cqe.res != chunk_bytes_u32 as i32 {
                    return Err(io::Error::new(
                        io::ErrorKind::WriteZero,
                        format!(
                            "short baton slot write: slot={slot} res={} expected={chunk_bytes}",
                            cqe.res
                        ),
                    ));
                }
                writes += 1;
                match baton_mode {
                    BatonMode::RoundTrip => {
                        baton_send_token(
                            &mut ring,
                            producer_fd,
                            slot,
                            chunk_bytes_u32,
                            skip_source_cqe,
                        )?;
                        returned_tokens += 1;
                    }
                    BatonMode::Credit { batch } => {
                        if token >= tokens {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!("baton write token {token} exceeds token count {tokens}"),
                            ));
                        }
                        let complete_slot = token % pipeline;
                        if completed_tokens[complete_slot] {
                            return Err(io::Error::new(
                                io::ErrorKind::InvalidData,
                                format!(
                                    "baton credit completion bitmap collision at slot {complete_slot}"
                                ),
                            ));
                        }
                        completed_tokens[complete_slot] = true;
                        while completed_prefix < tokens
                            && completed_tokens[completed_prefix % pipeline]
                        {
                            completed_tokens[completed_prefix % pipeline] = false;
                            completed_prefix += 1;
                            pending_credit += 1;
                        }
                        if pending_credit >= batch || completed_prefix == tokens {
                            baton_send_credit(
                                &mut ring,
                                producer_fd,
                                pending_credit,
                                skip_source_cqe,
                            )?;
                            returned_tokens += pending_credit;
                            pending_credit = 0;
                        }
                    }
                }
                continue;
            }

            let token = match baton_mode {
                BatonMode::RoundTrip => {
                    baton_slot_from_user_data(cqe.user_data, pipeline, "baton incoming")?
                }
                BatonMode::Credit { .. } => {
                    let token = baton_value_from_user_data(cqe.user_data, "baton incoming")?;
                    if token >= tokens {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            format!("baton incoming token {token} exceeds token count {tokens}"),
                        ));
                    }
                    token
                }
            };
            let slot = token % pipeline;
            received_tokens += 1;
            match &sink {
                BatonSink::Null => match baton_mode {
                    BatonMode::RoundTrip => {
                        baton_send_token(
                            &mut ring,
                            producer_fd,
                            slot,
                            chunk_bytes_u32,
                            skip_source_cqe,
                        )?;
                        returned_tokens += 1;
                    }
                    BatonMode::Credit { batch } => {
                        completed_tokens[slot] = true;
                        while completed_prefix < tokens
                            && completed_tokens[completed_prefix % pipeline]
                        {
                            completed_tokens[completed_prefix % pipeline] = false;
                            completed_prefix += 1;
                            pending_credit += 1;
                        }
                        if pending_credit >= batch || completed_prefix == tokens {
                            baton_send_credit(
                                &mut ring,
                                producer_fd,
                                pending_credit,
                                skip_source_cqe,
                            )?;
                            returned_tokens += pending_credit;
                            pending_credit = 0;
                        }
                    }
                },
                BatonSink::Block(_) => {
                    let file_offset = base_offset
                        .checked_add((received_tokens - 1) as u64 * chunk_bytes as u64)
                        .ok_or_else(|| {
                            io::Error::new(io::ErrorKind::InvalidInput, "baton WAL offset overflow")
                        })?;
                    ring.queue_slot_rw(
                        slot_ids[slot],
                        0,
                        file_offset,
                        chunk_bytes_u32,
                        io_slots::SlotRw::Write,
                        baton_write_user_data(token),
                    )?;
                }
            }
        }
    }

    ring.submit_pending()?;
    let elapsed = started.elapsed();

    for slot_id in slot_ids {
        ring.unregister_io_slot(slot_id)?;
    }
    if file.is_some() {
        ring.unregister_buffers()?;
        ring.unregister_files()?;
    }

    let end_cpu = current_cpu();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);
    let ring_stats = ring.stats();
    Ok(BatonWriterResult {
        worker,
        tokens: received_tokens,
        bytes: received_tokens * chunk_bytes,
        elapsed,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        start_cpu,
        end_cpu,
        cpu,
        writes,
        ignored_source_cqes,
        buffer_base,
        buffer_stride,
        buffer_map_len,
        memory_policy,
        ring_stats,
    })
}

#[allow(clippy::too_many_arguments)]
fn uring_baton_worker_pair(
    worker: usize,
    sink: BatonSink,
    base_offset: u64,
    tokens: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    pin_mode: BatonPinMode,
    pin_assignment: BatonPinAssignment,
    baton_mode: BatonMode,
    skip_source_cqe: bool,
    ring_stats_enabled: bool,
    release_rx: mpsc::Receiver<()>,
) -> io::Result<BatonWorkerResult> {
    let (producer_fd_tx, producer_fd_rx) = mpsc::channel::<io::Result<i32>>();
    let (writer_fd_tx, writer_fd_rx) = mpsc::channel::<io::Result<i32>>();
    let (producer_writer_fd_tx, producer_writer_fd_rx) = mpsc::channel::<i32>();
    let (writer_producer_fd_tx, writer_producer_fd_rx) = mpsc::channel::<i32>();
    let (producer_release_tx, producer_release_rx) = mpsc::channel::<()>();
    let (writer_release_tx, writer_release_rx) = mpsc::channel::<()>();

    let producer_handle = thread::spawn(move || {
        uring_baton_producer_worker(
            worker,
            producer_fd_tx,
            producer_writer_fd_rx,
            producer_release_rx,
            tokens,
            chunk_bytes,
            pipeline,
            ring_entries,
            pin_mode,
            pin_assignment.producer_cpu,
            baton_mode,
            skip_source_cqe,
            ring_stats_enabled,
        )
    });
    let writer_handle = thread::spawn(move || {
        uring_baton_writer_worker(
            worker,
            sink,
            base_offset,
            writer_producer_fd_rx,
            writer_fd_tx,
            writer_release_rx,
            tokens,
            chunk_bytes,
            pipeline,
            ring_entries,
            buffer_mode,
            pin_mode,
            pin_assignment.writer_cpu,
            baton_mode,
            skip_source_cqe,
            ring_stats_enabled,
        )
    });

    let producer_fd = producer_fd_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "producer fd channel"))??;
    let writer_fd = writer_fd_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "writer fd channel"))??;
    producer_writer_fd_tx
        .send(writer_fd)
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "producer writer-fd channel"))?;
    writer_producer_fd_tx
        .send(producer_fd)
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "writer producer-fd channel"))?;

    release_rx
        .recv()
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "worker pair release channel"))?;
    producer_release_tx
        .send(())
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "producer release channel"))?;
    writer_release_tx
        .send(())
        .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "writer release channel"))?;

    let producer = producer_handle
        .join()
        .map_err(|_| io::Error::other("uring baton producer thread panicked"))??;
    let writer = writer_handle
        .join()
        .map_err(|_| io::Error::other("uring baton writer thread panicked"))??;
    Ok(BatonWorkerResult { producer, writer })
}

fn uring_baton_target_plan(
    target_arg: &str,
    workers: usize,
    bytes_per_worker: usize,
    chunk_bytes: usize,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<BatonTargetPlan> {
    if target_arg == "null" || target_arg == "discard" || target_arg == "none" {
        let segment_bytes = buffer_mode.segment_bytes()?;
        return Ok(BatonTargetPlan {
            label: "null".to_string(),
            worker_sinks: vec![BatonSink::Null; workers],
            regions: make_linear_wal_regions(workers, bytes_per_worker)?,
            segment_bytes,
        });
    }

    let target_args: Vec<&str> = target_arg
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect();
    if target_args.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "baton target list is empty",
        ));
    }

    if target_args.len() == 1 {
        let total_bytes = workers.checked_mul(bytes_per_worker).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "baton aggregate byte count overflow",
            )
        })?;
        let (target, device_bytes, _required_alignment, segment_bytes) = validate_slot_wal_common(
            target_args[0],
            total_bytes,
            chunk_bytes,
            SlotWalMode::Write,
            buffer_mode,
        )?;
        let regions = make_linear_wal_regions(workers, bytes_per_worker)?;
        validate_wal_regions(&regions, device_bytes)?;
        return Ok(BatonTargetPlan {
            label: target.label().to_string(),
            worker_sinks: vec![BatonSink::Block(target); workers],
            regions,
            segment_bytes,
        });
    }

    let mut target_worker_counts = vec![0usize; target_args.len()];
    for worker in 0..workers {
        target_worker_counts[worker % target_args.len()] += 1;
    }

    let mut targets = Vec::with_capacity(target_args.len());
    let mut segment_bytes = None;
    for (target_idx, target_arg) in target_args.iter().enumerate() {
        let target_bytes = target_worker_counts[target_idx]
            .checked_mul(bytes_per_worker)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "baton target byte count overflow",
                )
            })?;
        let (target, _device_bytes, _required_alignment, target_segment_bytes) =
            validate_slot_wal_common(
                target_arg,
                target_bytes,
                chunk_bytes,
                SlotWalMode::Write,
                buffer_mode,
            )?;
        if let Some(segment_bytes) = segment_bytes {
            if segment_bytes != target_segment_bytes {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "multi-target baton segment sizes differ",
                ));
            }
        } else {
            segment_bytes = Some(target_segment_bytes);
        }
        targets.push(target);
    }

    let mut worker_sinks = Vec::with_capacity(workers);
    let mut regions = Vec::with_capacity(workers);
    let mut local_worker_index = vec![0usize; targets.len()];
    for worker in 0..workers {
        let target_idx = worker % targets.len();
        let base_offset = local_worker_index[target_idx]
            .checked_mul(bytes_per_worker)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?
            as u64;
        local_worker_index[target_idx] += 1;
        worker_sinks.push(BatonSink::Block(targets[target_idx].clone()));
        regions.push(WalRegionPlan {
            worker,
            base_offset,
            len_bytes: bytes_per_worker,
        });
    }

    let labels: Vec<&str> = targets.iter().map(|target| target.label()).collect();
    Ok(BatonTargetPlan {
        label: labels.join(","),
        worker_sinks,
        regions,
        segment_bytes: segment_bytes.unwrap_or(buffer_mode.segment_bytes()?),
    })
}

#[allow(clippy::too_many_arguments)]
fn uring_baton_bench(
    target_arg: &str,
    workers: usize,
    bytes_per_worker: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    pin_mode: BatonPinMode,
    baton_mode: BatonMode,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    if let Some(batch) = baton_mode.credit_batch()
        && batch > pipeline
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "baton credit batch must be <= pipeline to avoid credit starvation",
        ));
    }
    ensure_sector_aligned(bytes_per_worker, "bytes-per-worker")?;
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    if bytes_per_worker % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "bytes-per-worker must be an exact multiple of chunk-bytes",
        ));
    }
    let tokens = bytes_per_worker / chunk_bytes;
    if tokens as u64 > BATON_VALUE_MASK {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "tokens per worker exceed baton user_data value range",
        ));
    }
    let target_plan = uring_baton_target_plan(
        target_arg,
        workers,
        bytes_per_worker,
        chunk_bytes,
        buffer_mode,
    )?;
    let skip_source_cqe = env_enabled_or("URING_PLAY_BATON_SKIP_SOURCE_CQE", true);
    let ring_stats_enabled = env_truthy("URING_PLAY_BATON_RING_STATS");
    let pin_plan = baton_pin_plan(&target_plan.worker_sinks, pin_mode, workers)?;

    println!(
        "uring-baton-bench: sink={} workers={workers} bytes_per_worker={bytes_per_worker} \
         total_bytes={} chunk_bytes={chunk_bytes} tokens_per_worker={tokens} \
         pipeline={pipeline} ring_entries={ring_entries} buffer_mode={} \
         segment_bytes={} pin_mode={} baton_mode={} pin_detail=\"{}\" \
         skip_source_cqe={} ring_stats={} msg_ring_op={IORING_OP_MSG_RING}",
        target_plan.label,
        workers * bytes_per_worker,
        buffer_mode.as_str(),
        target_plan.segment_bytes,
        pin_plan.mode.as_str(),
        baton_mode.label(),
        pin_plan.detail,
        yes(skip_source_cqe),
        yes(ring_stats_enabled)
    );

    let mut release_senders = Vec::with_capacity(workers);
    let mut handles = Vec::with_capacity(workers);
    for region in target_plan.regions {
        let (release_tx, release_rx) = mpsc::channel::<()>();
        release_senders.push(release_tx);
        let sink = target_plan.worker_sinks[region.worker].clone();
        let pin_mode = pin_plan.mode;
        let pin_assignment = pin_plan.assignments[region.worker];
        handles.push(thread::spawn(move || {
            uring_baton_worker_pair(
                region.worker,
                sink,
                region.base_offset,
                tokens,
                chunk_bytes,
                pipeline,
                ring_entries,
                buffer_mode,
                pin_mode,
                pin_assignment,
                baton_mode,
                skip_source_cqe,
                ring_stats_enabled,
                release_rx,
            )
        }));
    }

    let started = Instant::now();
    for release_tx in release_senders {
        release_tx
            .send(())
            .map_err(|_| io::Error::new(io::ErrorKind::BrokenPipe, "baton release broadcast"))?;
    }

    let mut results = Vec::with_capacity(workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("uring baton worker pair thread panicked"))??,
        );
    }
    results.sort_by_key(|result| result.producer.worker);
    let wall = started.elapsed();
    let wall_seconds = wall.as_secs_f64().max(f64::MIN_POSITIVE);
    let total_bytes: usize = results.iter().map(|result| result.writer.bytes).sum();
    let total_tokens: usize = results.iter().map(|result| result.writer.tokens).sum();
    let total_writes: usize = results.iter().map(|result| result.writer.writes).sum();

    for result in &results {
        let producer_secs = result.producer.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        let writer_secs = result.writer.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        println!(
            "uring-baton-producer: worker={} tokens={} bytes={} seconds={producer_secs:.6} \
             token_ops_per_sec={:.0} Gbitps={:.3} target_cpu={} affinity_applied={} \
             start_cpu={} end_cpu={} thread_cpu_seconds={:.6} ignored_source_cqes={}",
            result.producer.worker,
            result.producer.tokens,
            result.producer.bytes,
            result.producer.tokens as f64 / producer_secs,
            result.producer.bytes as f64 * 8.0 / 1_000_000_000.0 / producer_secs,
            result.producer.target_cpu,
            result.producer.affinity_applied,
            result.producer.start_cpu,
            result.producer.end_cpu,
            result.producer.cpu.as_secs_f64(),
            result.producer.ignored_source_cqes
        );
        println!(
            "uring-baton-writer: worker={} tokens={} bytes={} writes={} seconds={writer_secs:.6} \
             token_ops_per_sec={:.0} Gbitps={:.3} target_cpu={} affinity_applied={} \
             start_cpu={} end_cpu={} thread_cpu_seconds={:.6} buffer_base=0x{:x} \
             buffer_stride={} buffer_map_len={} memory_policy={} ignored_source_cqes={}",
            result.writer.worker,
            result.writer.tokens,
            result.writer.bytes,
            result.writer.writes,
            result.writer.tokens as f64 / writer_secs,
            result.writer.bytes as f64 * 8.0 / 1_000_000_000.0 / writer_secs,
            result.writer.target_cpu,
            result.writer.affinity_applied,
            result.writer.start_cpu,
            result.writer.end_cpu,
            result.writer.cpu.as_secs_f64(),
            result.writer.buffer_base,
            result.writer.buffer_stride,
            result.writer.buffer_map_len,
            result.writer.memory_policy,
            result.writer.ignored_source_cqes
        );
        if ring_stats_enabled {
            let ps = result.producer.ring_stats;
            let ws = result.writer.ring_stats;
            println!(
                "uring-baton-ring-stats: role=producer worker={} sqes={} submitted={} \
                 submit_syscalls={} wait_syscalls={} wait_cqe_calls={} cqes={} \
                 try_pop_empty={} submit_short={} cqe_spin_loops={}",
                result.producer.worker,
                ps.sqes_queued,
                ps.sqes_submitted,
                ps.submit_syscalls,
                ps.wait_syscalls,
                ps.wait_cqe_calls,
                ps.cqes_popped,
                ps.try_pop_empty,
                ps.submit_short,
                ps.cqe_spin_loops,
            );
            println!(
                "uring-baton-ring-stats: role=writer worker={} sqes={} submitted={} \
                 submit_syscalls={} wait_syscalls={} wait_cqe_calls={} cqes={} \
                 try_pop_empty={} submit_short={} cqe_spin_loops={}",
                result.writer.worker,
                ws.sqes_queued,
                ws.sqes_submitted,
                ws.submit_syscalls,
                ws.wait_syscalls,
                ws.wait_cqe_calls,
                ws.cqes_popped,
                ws.try_pop_empty,
                ws.submit_short,
                ws.cqe_spin_loops,
            );
        }
    }

    println!(
        "uring-baton-bench-summary: sink={} workers={workers} tokens={total_tokens} \
         writes={total_writes} bytes={total_bytes} wall_seconds={wall_seconds:.6} \
         token_ops_per_sec={:.0} MiBps={:.2} Gbitps={:.3}",
        target_plan.label,
        total_tokens as f64 / wall_seconds,
        total_bytes as f64 / (1024.0 * 1024.0) / wall_seconds,
        total_bytes as f64 * 8.0 / 1_000_000_000.0 / wall_seconds
    );
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn uring_write_bench_worker(
    target: SlotWalTarget,
    worker: usize,
    base_offset: u64,
    total_bytes: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    write_mode: UringWriteMode,
    pin_workers: bool,
) -> io::Result<UringWriteWorkerResult> {
    let affinity = pin_current_thread_if_requested("uring-write-worker", worker, pin_workers);
    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "chunk-bytes must fit in u32 for write SQEs",
        )
    })?;

    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
        .open(target.open_path())?;
    let fd = file.as_raw_fd();

    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    let mut registered_fds = [fd];
    if write_mode.uses_registered_file() {
        ring.register_files(&mut registered_fds)?;
    }

    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    fill_slot_wal_buffers(&buffers, chunk_bytes);
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    if write_mode.uses_registered_buffers() {
        let mut iovecs = buffers.iovecs(chunk_bytes);
        ring.register_buffers(&mut iovecs)?;
    }

    let completion_batch =
        env_usize_or("URING_PLAY_URING_WRITE_COMPLETION_BATCH", 64).clamp(1, pipeline);
    let total_ops = total_bytes / chunk_bytes;
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let local_cpu = current_cpu();
    let started = Instant::now();

    while completed < total_ops {
        while submitted < total_ops && !free_slots.is_empty() {
            let slot = free_slots.pop().expect("free slot");
            let file_offset = (submitted as u64)
                .checked_mul(chunk_bytes as u64)
                .and_then(|offset| base_offset.checked_add(offset))
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            let buf = buffers.ptr(slot).cast_const();
            match write_mode {
                UringWriteMode::Write => {
                    ring.queue_write(fd, buf, chunk_bytes_u32, file_offset, slot as u64)?;
                }
                UringWriteMode::WriteFixed => {
                    ring.queue_write_fixed(
                        fd,
                        buf,
                        chunk_bytes_u32,
                        file_offset,
                        slot as u16,
                        slot as u64,
                    )?;
                }
                UringWriteMode::WriteFixedFile => {
                    ring.queue_write_fixed_file(
                        0,
                        buf,
                        chunk_bytes_u32,
                        file_offset,
                        slot as u16,
                        slot as u64,
                    )?;
                }
            }
            submitted += 1;
        }

        ring.submit_pending()?;
        for batch_idx in 0..completion_batch {
            let cqe = if batch_idx == 0 {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => ring.wait_cqe()?,
                }
            } else {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => break,
                }
            };
            let slot = cqe.user_data as usize;
            if slot >= pipeline {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("uring write CQE returned invalid slot user_data={slot}"),
                ));
            }
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            if cqe.res != chunk_bytes_u32 as i32 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short uring write completion: res={} expected={chunk_bytes}",
                        cqe.res
                    ),
                ));
            }
            completed += 1;
            free_slots.push(slot);
            if completed == total_ops {
                break;
            }
        }
    }

    let elapsed = started.elapsed();
    if write_mode.uses_registered_buffers() {
        ring.unregister_buffers()?;
    }
    if write_mode.uses_registered_file() {
        ring.unregister_files()?;
    }

    Ok(UringWriteWorkerResult {
        worker,
        bytes: total_bytes,
        ops: total_ops,
        elapsed,
        base_offset,
        completion_batch,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        buffer_base,
        buffer_stride,
        buffer_map_len,
        buffer_alignment,
        memory_policy,
    })
}

#[allow(clippy::too_many_arguments)]
fn uring_write_bench(
    target_arg: &str,
    workers: usize,
    bytes_per_worker: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    write_mode: UringWriteMode,
    pin_workers: bool,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    ensure_sector_aligned(bytes_per_worker, "bytes-per-worker")?;
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    if bytes_per_worker % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "bytes-per-worker must be an exact multiple of chunk-bytes",
        ));
    }
    let total_bytes = bytes_per_worker.checked_mul(workers).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "aggregate byte count overflow")
    })?;
    let (target, device_bytes, required_alignment, segment_bytes) = validate_slot_wal_common(
        target_arg,
        total_bytes,
        chunk_bytes,
        SlotWalMode::Write,
        buffer_mode,
    )?;
    let regions = make_linear_wal_regions(workers, bytes_per_worker)?;
    validate_wal_regions(&regions, device_bytes)?;

    println!(
        "uring-write-bench: target={} workers={workers} bytes_per_worker={bytes_per_worker} \
         total_bytes={total_bytes} chunk_bytes={chunk_bytes} pipeline_per_worker={pipeline} \
         total_pipeline={} ring_entries={ring_entries} buffers={} segment_bytes={segment_bytes} \
         required_alignment={required_alignment} write_mode={} pin_workers={pin_workers}",
        target.label(),
        workers * pipeline,
        buffer_mode.as_str(),
        write_mode.as_str()
    );

    let started = Instant::now();
    let mut handles = Vec::with_capacity(workers);
    for region in regions {
        let target = target.clone();
        handles.push(thread::spawn(move || {
            uring_write_bench_worker(
                target,
                region.worker,
                region.base_offset,
                region.len_bytes,
                chunk_bytes,
                pipeline,
                ring_entries,
                buffer_mode,
                write_mode,
                pin_workers,
            )
        }));
    }

    let mut results = Vec::with_capacity(workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("uring write worker thread panicked"))??,
        );
    }
    results.sort_by_key(|result| result.worker);

    let wall_seconds = started.elapsed().as_secs_f64().max(f64::MIN_POSITIVE);
    let total_ops: usize = results.iter().map(|result| result.ops).sum();
    let total_bytes: usize = results.iter().map(|result| result.bytes).sum();
    for result in &results {
        let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        println!(
            "uring-write-worker: worker={} bytes={} ops={} seconds={seconds:.6} \
             ops_per_sec={:.0} base_offset={} completion_batch={} target_cpu={} \
             affinity_applied={} local_cpu={} buffer_base=0x{:x} buffer_alignment={} \
             buffer_stride={} buffer_map_len={} memory_policy={}",
            result.worker,
            result.bytes,
            result.ops,
            result.ops as f64 / seconds,
            result.base_offset,
            result.completion_batch,
            result.target_cpu,
            result.affinity_applied,
            result.local_cpu,
            result.buffer_base,
            result.buffer_alignment,
            result.buffer_stride,
            result.buffer_map_len,
            result.memory_policy
        );
    }
    println!(
        "uring-write-bench-summary: target={} workers={workers} write_mode={} \
         tokens={total_ops} writes={total_ops} bytes={total_bytes} wall_seconds={wall_seconds:.6} \
         ops_per_sec={:.0} MiBps={:.2} Gbitps={:.3}",
        target.label(),
        write_mode.as_str(),
        total_ops as f64 / wall_seconds,
        total_bytes as f64 / (1024.0 * 1024.0) / wall_seconds,
        total_bytes as f64 * 8.0 / 1_000_000_000.0 / wall_seconds
    );
    Ok(())
}

fn slot_wal_bench_worker(
    target: SlotWalTarget,
    worker: usize,
    base_offset: u64,
    total_bytes: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotWalMode,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
) -> io::Result<SlotWalWorkerResult> {
    let affinity = pin_current_thread_if_requested("slot-wal-worker", worker, pin);
    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "chunk-bytes must fit in u32 for the SQE len field",
        )
    })?;

    let file = OpenOptions::new()
        .read(true)
        .write(matches!(mode, SlotWalMode::Write))
        .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
        .open(target.open_path())?;
    let fd = file.as_raw_fd();

    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    let mut fds = [fd];
    ring.register_files(&mut fds)?;

    // Allocate and first-touch after optional CPU pinning. The mmap base is page
    // aligned, which is also cacheline aligned for the 4K path.
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let segment_bytes = buffer_mode.segment_bytes()?;
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    if matches!(mode, SlotWalMode::Write) {
        fill_slot_wal_buffers(&buffers, chunk_bytes);
    }
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let local_cpu = current_cpu();
    let worker_numa_node = preferred_numa_node.or_else(|| {
        (local_cpu >= 0)
            .then(|| cpu_numa_node(local_cpu as usize))
            .flatten()
    });
    let memory_policy = buffers.memory_policy();
    let slot_buffer_layout = SlotBufferLayout::from_env()?;
    slot_buffer_layout.register_buffers(&ring, &buffers, chunk_bytes)?;
    let slot_ids = slot_buffer_layout.register_io_slots(&ring, pipeline)?;

    let completion_batch = env_usize_or("URING_PLAY_SLOT_COMPLETION_BATCH", 1).clamp(1, pipeline);
    let total_ops = total_bytes / chunk_bytes;
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let started = Instant::now();

    while completed < total_ops {
        while submitted < total_ops && !free_slots.is_empty() {
            let slot = free_slots.pop().expect("free slot");
            let file_offset = (submitted as u64)
                .checked_mul(chunk_bytes as u64)
                .and_then(|offset| base_offset.checked_add(offset))
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            let buf_offset = slot_buffer_layout.buf_offset(&buffers, slot)?;
            ring.queue_slot_rw(
                slot_ids[slot],
                buf_offset,
                file_offset,
                chunk_bytes_u32,
                mode.direction(),
                slot as u64,
            )?;
            submitted += 1;
        }

        ring.submit_pending()?;
        for batch_idx in 0..completion_batch {
            let cqe = if batch_idx == 0 {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => ring.wait_cqe()?,
                }
            } else {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => break,
                }
            };
            let slot = cqe.user_data as usize;
            if slot >= pipeline {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("slot WAL CQE returned invalid slot user_data={slot}"),
                ));
            }
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            if cqe.res != chunk_bytes_u32 as i32 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short slot WAL completion: res={} expected={chunk_bytes}",
                        cqe.res
                    ),
                ));
            }
            completed += 1;
            free_slots.push(slot);
            if completed == total_ops {
                break;
            }
        }
    }

    let elapsed = started.elapsed();

    for slot_id in slot_ids {
        ring.unregister_io_slot(slot_id)?;
    }
    ring.unregister_buffers()?;
    ring.unregister_files()?;
    Ok(SlotWalWorkerResult {
        worker,
        bytes: total_bytes,
        ops: total_ops,
        elapsed,
        base_offset,
        region_bytes: total_bytes,
        slot_count: pipeline,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node,
        completion_batch,
        buffer_base,
        buffer_stride,
        buffer_map_len,
        buffer_alignment,
        buffer_mode,
        segment_bytes,
        slot_buffer_layout,
        memory_policy,
    })
}

fn slot_wal_bench(
    target_arg: &str,
    total_bytes: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotWalMode,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<()> {
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    let (target, _device_bytes, required_alignment, segment_bytes) =
        validate_slot_wal_common(target_arg, total_bytes, chunk_bytes, mode, buffer_mode)?;

    let result = slot_wal_bench_worker(
        target.clone(),
        0,
        0,
        total_bytes,
        chunk_bytes,
        pipeline,
        ring_entries,
        mode,
        buffer_mode,
        false,
    )?;
    let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
    let mib = total_bytes as f64 / (1024.0 * 1024.0);
    println!(
        "slot-wal-bench: target={} mode={} total_bytes={total_bytes} \
         chunk_bytes={chunk_bytes} ops={} pipeline={pipeline} \
         ring_entries={ring_entries} buffers={} slot_buffer_layout={} segment_bytes={segment_bytes} \
         required_alignment={required_alignment} slot_backend={} \
         completion_batch={} \
         buffer_base=0x{:x} buffer_alignment={} buffer_stride={} \
         buffer_map_len={} memory_policy={} seconds={seconds:.6} \
         MiBps={:.2} ops_per_sec={:.0}",
        target.label(),
        mode.as_str(),
        result.ops,
        buffer_mode.as_str(),
        result.slot_buffer_layout.as_str(),
        io_slots::submission_backend_label(),
        result.completion_batch,
        result.buffer_base,
        result.buffer_alignment,
        result.buffer_stride,
        result.buffer_map_len,
        result.memory_policy,
        mib / seconds,
        result.ops as f64 / seconds
    );
    Ok(())
}

fn splitmix64_next(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut value = *state;
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

const LATENCY_FINE_STEP_NS: u64 = 100;
const LATENCY_FINE_BUCKETS: usize = 10;
const LATENCY_MID_START_NS: u64 = 1_000;
const LATENCY_MID_STEP_NS: u64 = 1_000;
const LATENCY_MID_BUCKETS: usize = 999;
const LATENCY_HIGH_START_NS: u64 = 1_000_000;
const LATENCY_HIGH_STEP_NS: u64 = 1_000_000;
const LATENCY_HIGH_BUCKETS: usize = 1_000;
const LATENCY_BUCKETS: usize =
    LATENCY_FINE_BUCKETS + LATENCY_MID_BUCKETS + LATENCY_HIGH_BUCKETS + 1;

#[derive(Clone)]
struct LatencyHistogram {
    buckets: Box<[u64; LATENCY_BUCKETS]>,
    count: u64,
    total_ns: u128,
    min_ns: u64,
    max_ns: u64,
}

impl LatencyHistogram {
    fn new() -> Self {
        Self {
            buckets: Box::new([0; LATENCY_BUCKETS]),
            count: 0,
            total_ns: 0,
            min_ns: u64::MAX,
            max_ns: 0,
        }
    }

    fn record_duration(&mut self, duration: Duration) {
        let ns = duration.as_nanos().min(u128::from(u64::MAX)) as u64;
        self.record_ns(ns);
    }

    fn record_ns(&mut self, ns: u64) {
        let index = latency_bucket_index(ns);
        self.buckets[index] = self.buckets[index].saturating_add(1);
        self.count = self.count.saturating_add(1);
        self.total_ns = self.total_ns.saturating_add(u128::from(ns));
        self.min_ns = self.min_ns.min(ns);
        self.max_ns = self.max_ns.max(ns);
    }

    fn merge(&mut self, other: &Self) {
        for (dst, src) in self.buckets.iter_mut().zip(other.buckets.iter()) {
            *dst = dst.saturating_add(*src);
        }
        self.count = self.count.saturating_add(other.count);
        self.total_ns = self.total_ns.saturating_add(other.total_ns);
        self.min_ns = self.min_ns.min(other.min_ns);
        self.max_ns = self.max_ns.max(other.max_ns);
    }

    fn avg_ns(&self) -> u64 {
        if self.count == 0 {
            0
        } else {
            (self.total_ns / u128::from(self.count)).min(u128::from(u64::MAX)) as u64
        }
    }

    fn min_ns(&self) -> u64 {
        if self.count == 0 { 0 } else { self.min_ns }
    }

    fn max_ns(&self) -> u64 {
        if self.count == 0 { 0 } else { self.max_ns }
    }

    fn percentile_ns(&self, numerator: u64, denominator: u64) -> u64 {
        if self.count == 0 || denominator == 0 {
            return 0;
        }
        let rank = self
            .count
            .saturating_mul(numerator)
            .saturating_add(denominator - 1)
            / denominator;
        let mut seen = 0u64;
        for (index, value) in self.buckets.iter().enumerate() {
            seen = seen.saturating_add(*value);
            if seen >= rank.max(1) {
                return latency_bucket_upper_ns(index);
            }
        }
        self.max_ns
    }
}

impl Default for LatencyHistogram {
    fn default() -> Self {
        Self::new()
    }
}

fn latency_bucket_index(ns: u64) -> usize {
    if ns < LATENCY_MID_START_NS {
        return (ns / LATENCY_FINE_STEP_NS).min((LATENCY_FINE_BUCKETS - 1) as u64) as usize;
    }
    if ns < LATENCY_HIGH_START_NS {
        return LATENCY_FINE_BUCKETS
            + ((ns - LATENCY_MID_START_NS) / LATENCY_MID_STEP_NS)
                .min((LATENCY_MID_BUCKETS - 1) as u64) as usize;
    }
    let high_index =
        ((ns - LATENCY_HIGH_START_NS) / LATENCY_HIGH_STEP_NS).min(LATENCY_HIGH_BUCKETS as u64);
    LATENCY_FINE_BUCKETS + LATENCY_MID_BUCKETS + high_index as usize
}

fn latency_bucket_upper_ns(index: usize) -> u64 {
    if index < LATENCY_FINE_BUCKETS {
        return ((index as u64) + 1).saturating_mul(LATENCY_FINE_STEP_NS);
    }
    let mid_end = LATENCY_FINE_BUCKETS + LATENCY_MID_BUCKETS;
    if index < mid_end {
        let mid_index = index - LATENCY_FINE_BUCKETS;
        return LATENCY_MID_START_NS
            .saturating_add(((mid_index as u64) + 1).saturating_mul(LATENCY_MID_STEP_NS));
    }
    let high_index = index - mid_end;
    if high_index >= LATENCY_HIGH_BUCKETS {
        return u64::MAX;
    }
    LATENCY_HIGH_START_NS
        .saturating_add(((high_index as u64) + 1).saturating_mul(LATENCY_HIGH_STEP_NS))
}

#[allow(clippy::too_many_arguments)]
fn slot_rand_worker(
    target: SlotWalTarget,
    worker: usize,
    base_offset: u64,
    region_bytes: usize,
    ops: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotRandMode,
    read_percent: u8,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
    planned_cpu: Option<usize>,
    start_barrier: Option<Arc<Barrier>>,
) -> io::Result<SlotRandWorkerResult> {
    let region_blocks = region_bytes / chunk_bytes;
    if region_blocks == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes must cover at least one chunk",
        ));
    }

    let affinity =
        pin_current_thread_if_requested_to_cpu("slot-rand-worker", worker, pin, planned_cpu);
    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "chunk-bytes must fit in u32 for the SQE len field",
        )
    })?;

    let file = OpenOptions::new()
        .read(true)
        .write(mode.needs_write())
        .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
        .open(target.open_path())?;
    let fd = file.as_raw_fd();

    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    let mut fds = [fd];
    ring.register_files(&mut fds)?;

    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    if mode.needs_write() {
        fill_slot_wal_buffers(&buffers, chunk_bytes);
    }
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let slot_buffer_layout = SlotBufferLayout::from_env()?;
    slot_buffer_layout.register_buffers(&ring, &buffers, chunk_bytes)?;

    let slot_ids = slot_buffer_layout.register_io_slots(&ring, pipeline)?;

    let completion_batch = env_usize_or(
        "URING_PLAY_SLOT_RAND_COMPLETION_BATCH",
        env_usize_or("URING_PLAY_SLOT_COMPLETION_BATCH", 64),
    )
    .clamp(1, pipeline);
    let mut rng = 0x6a09_e667_f3bc_c909u64
        ^ (ops as u64)
        ^ ((chunk_bytes as u64) << 32)
        ^ ((worker as u64) << 48)
        ^ base_offset.rotate_left(17);
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let mut reads = 0usize;
    let mut writes = 0usize;
    if let Some(start_barrier) = start_barrier.as_ref() {
        start_barrier.wait();
    }
    let local_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let started = Instant::now();

    while completed < ops {
        while submitted < ops && !free_slots.is_empty() {
            let slot = free_slots.pop().expect("free slot");
            let block = splitmix64_next(&mut rng) as usize % region_blocks;
            let file_offset = (block as u64)
                .checked_mul(chunk_bytes as u64)
                .and_then(|offset| base_offset.checked_add(offset))
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            let direction = match mode {
                SlotRandMode::Read => {
                    reads += 1;
                    io_slots::SlotRw::Read
                }
                SlotRandMode::Write => {
                    writes += 1;
                    io_slots::SlotRw::Write
                }
                SlotRandMode::Mixed => {
                    if (splitmix64_next(&mut rng) % 100) < read_percent as u64 {
                        reads += 1;
                        io_slots::SlotRw::Read
                    } else {
                        writes += 1;
                        io_slots::SlotRw::Write
                    }
                }
            };
            let buf_offset = slot_buffer_layout.buf_offset(&buffers, slot)?;
            ring.queue_slot_rw(
                slot_ids[slot],
                buf_offset,
                file_offset,
                chunk_bytes_u32,
                direction,
                slot as u64,
            )?;
            submitted += 1;
        }

        ring.submit_pending()?;
        for batch_idx in 0..completion_batch {
            let cqe = if batch_idx == 0 {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => ring.wait_cqe()?,
                }
            } else {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => break,
                }
            };
            let slot = cqe.user_data as usize;
            if slot >= pipeline {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("slot random CQE returned invalid slot user_data={slot}"),
                ));
            }
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            if cqe.res != chunk_bytes_u32 as i32 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short slot random completion: res={} expected={chunk_bytes}",
                        cqe.res
                    ),
                ));
            }
            completed += 1;
            free_slots.push(slot);
            if completed == ops {
                break;
            }
        }
    }

    let elapsed = started.elapsed();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);
    for slot_id in slot_ids {
        ring.unregister_io_slot(slot_id)?;
    }
    ring.unregister_buffers()?;
    ring.unregister_files()?;

    Ok(SlotRandWorkerResult {
        worker,
        ops,
        reads,
        writes,
        elapsed,
        cpu,
        base_offset,
        region_bytes,
        slot_count: pipeline,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node: preferred_numa_node.or_else(|| {
            (local_cpu >= 0)
                .then(|| cpu_numa_node(local_cpu as usize))
                .flatten()
        }),
        completion_batch,
        buffer_base,
        buffer_stride,
        buffer_map_len,
        buffer_alignment,
        buffer_mode,
        segment_bytes: buffer_mode.segment_bytes()?,
        slot_buffer_layout,
        memory_policy,
    })
}

#[derive(Clone, Copy)]
struct SlotRandWorkerResult {
    worker: usize,
    ops: usize,
    reads: usize,
    writes: usize,
    elapsed: Duration,
    cpu: Duration,
    base_offset: u64,
    region_bytes: usize,
    slot_count: usize,
    target_cpu: i32,
    affinity_applied: bool,
    local_cpu: i32,
    worker_numa_node: Option<i32>,
    completion_batch: usize,
    buffer_base: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    buffer_alignment: usize,
    buffer_mode: SlotWalBufferMode,
    segment_bytes: usize,
    slot_buffer_layout: SlotBufferLayout,
    memory_policy: &'static str,
}

#[allow(clippy::too_many_arguments)]
fn slot_rand_bench(
    target_arg: &str,
    ops: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotRandMode,
    read_percent: u8,
    region_bytes: usize,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
) -> io::Result<()> {
    if ops == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ops must be non-zero",
        ));
    }
    if matches!(mode, SlotRandMode::Mixed) && read_percent > 100 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "read-percent must be 0..=100",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    let safety_mode = if mode.needs_write() {
        SlotWalMode::Write
    } else {
        SlotWalMode::Read
    };
    let (target, _device_bytes, required_alignment, segment_bytes) = validate_slot_wal_common(
        target_arg,
        region_bytes,
        chunk_bytes,
        safety_mode,
        buffer_mode,
    )?;

    let result = slot_rand_worker(
        target.clone(),
        0,
        0,
        region_bytes,
        ops,
        chunk_bytes,
        pipeline,
        ring_entries,
        mode,
        read_percent,
        buffer_mode,
        pin,
        None,
        None,
    )?;
    let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
    let bytes = ops.checked_mul(chunk_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "slot random byte count overflow",
        )
    })?;
    let cpu_seconds = result.cpu.as_secs_f64();
    let cpu_percent = cpu_seconds / seconds * 100.0;
    let cpu_ns_per_op = cpu_seconds * 1_000_000_000.0 / ops as f64;
    let completion_batch = result.completion_batch;
    let buffer_base = result.buffer_base;
    let buffer_alignment = result.buffer_alignment;
    let buffer_stride = result.buffer_stride;
    let buffer_map_len = result.buffer_map_len;
    let memory_policy = result.memory_policy;
    println!(
        "slot-rand-bench: target={} mode={} ops={ops} reads={} writes={} \
         read_percent={} region_bytes={region_bytes} chunk_bytes={chunk_bytes} \
         pipeline={pipeline} ring_entries={ring_entries} completion_batch={completion_batch} \
         buffers={} slot_buffer_layout={} segment_bytes={segment_bytes} \
         required_alignment={required_alignment} slot_backend={} pin={pin} \
         target_cpu={} affinity_applied={} local_cpu={} \
         buffer_base=0x{buffer_base:x} buffer_alignment={buffer_alignment} \
         buffer_stride={buffer_stride} buffer_map_len={buffer_map_len} \
         memory_policy={memory_policy} seconds={seconds:.6} cpu_seconds={cpu_seconds:.6} \
         cpu_percent={cpu_percent:.2} cpu_ns_per_op={cpu_ns_per_op:.1} \
         MiBps={:.2} ops_per_sec={:.0}",
        target.label(),
        mode.as_str(),
        result.reads,
        result.writes,
        read_percent,
        buffer_mode.as_str(),
        result.slot_buffer_layout.as_str(),
        io_slots::submission_backend_label(),
        result.target_cpu,
        result.affinity_applied,
        result.local_cpu,
        bytes as f64 / (1024.0 * 1024.0) / seconds,
        ops as f64 / seconds
    );
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn slot_rand_sharded_bench(
    target_arg: &str,
    workers: usize,
    ops_per_worker: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotRandMode,
    read_percent: u8,
    region_bytes_per_worker: usize,
    buffer_mode: SlotWalBufferMode,
    pin_workers: bool,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    if ops_per_worker == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ops-per-worker must be non-zero",
        ));
    }
    if matches!(mode, SlotRandMode::Mixed) && read_percent > 100 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "read-percent must be 0..=100",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    ensure_sector_aligned(region_bytes_per_worker, "region-bytes-per-worker")?;
    if region_bytes_per_worker % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes-per-worker must be an exact multiple of chunk-bytes",
        ));
    }
    let total_region_bytes = region_bytes_per_worker
        .checked_mul(workers)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "aggregate region byte count overflow",
            )
        })?;
    let safety_mode = if mode.needs_write() {
        SlotWalMode::Write
    } else {
        SlotWalMode::Read
    };
    let (target, device_bytes, required_alignment, segment_bytes) = validate_slot_wal_common(
        target_arg,
        total_region_bytes,
        chunk_bytes,
        safety_mode,
        buffer_mode,
    )?;
    let metadata = fs::metadata(target.open_path())?;
    let topology = BlockDeviceTopology::from_metadata(&metadata)?;
    let planned_cpus = if pin_workers {
        topology.planned_cpus(workers, true)
    } else {
        Vec::new()
    };
    let regions = make_linear_wal_regions(workers, region_bytes_per_worker)?;
    validate_wal_regions(&regions, device_bytes)?;
    for region in &regions {
        let planned_cpu = planned_cpus.get(region.worker).copied();
        let queue_label = planned_cpu
            .map(|cpu| topology.queue_for_cpu(region.worker, cpu).index.to_string())
            .unwrap_or_else(|| "none".to_string());
        println!(
            "slot-rand-sharded-region: worker={} base_offset={} len_bytes={} end_offset={} \
             planned_cpu={} planned_nvme_queue={}",
            region.worker,
            region.base_offset,
            region.len_bytes,
            region.end_offset()?,
            planned_cpu
                .map(|cpu| cpu.to_string())
                .unwrap_or_else(|| "none".to_string()),
            queue_label
        );
    }

    let started = Instant::now();
    let mut handles = Vec::with_capacity(workers);
    let start_barrier = Arc::new(Barrier::new(workers));
    for region in regions {
        let target = target.clone();
        let planned_cpu = planned_cpus.get(region.worker).copied();
        let start_barrier = Arc::clone(&start_barrier);
        handles.push(thread::spawn(move || {
            slot_rand_worker(
                target,
                region.worker,
                region.base_offset,
                region.len_bytes,
                ops_per_worker,
                chunk_bytes,
                pipeline,
                ring_entries,
                mode,
                read_percent,
                buffer_mode,
                pin_workers,
                planned_cpu,
                Some(start_barrier),
            )
        }));
    }

    let mut results = Vec::with_capacity(workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("slot random worker thread panicked"))??,
        );
    }
    results.sort_by_key(|result| result.worker);

    let wall_seconds = started.elapsed().as_secs_f64().max(f64::MIN_POSITIVE);
    let total_ops: usize = results.iter().map(|result| result.ops).sum();
    let total_reads: usize = results.iter().map(|result| result.reads).sum();
    let total_writes: usize = results.iter().map(|result| result.writes).sum();
    let total_bytes = total_ops.checked_mul(chunk_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "slot random aggregate byte count overflow",
        )
    })?;
    let total_cpu_seconds: f64 = results.iter().map(|result| result.cpu.as_secs_f64()).sum();
    let slowest_worker_seconds = results
        .iter()
        .map(|result| result.elapsed)
        .max()
        .unwrap_or_default()
        .as_secs_f64()
        .max(f64::MIN_POSITIVE);
    let io_seconds = slowest_worker_seconds;

    for result in &results {
        let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        let cpu_seconds = result.cpu.as_secs_f64();
        println!(
            "slot-rand-sharded-worker: worker={} ops={} reads={} writes={} \
             seconds={seconds:.6} ops_per_sec={:.0} cpu_seconds={cpu_seconds:.6} \
             cpu_percent={:.2} cpu_ns_per_op={:.1} base_offset={} region_bytes={} \
             slots={} completion_batch={} target_cpu={} affinity_applied={} local_cpu={} \
             worker_numa_node={} buffers={} slot_buffer_layout={} segment_bytes={} \
             buffer_base=0x{:x} buffer_alignment={} buffer_stride={} buffer_map_len={} \
             memory_policy={}",
            result.worker,
            result.ops,
            result.reads,
            result.writes,
            result.ops as f64 / seconds,
            cpu_seconds / seconds * 100.0,
            cpu_seconds * 1_000_000_000.0 / result.ops as f64,
            result.base_offset,
            result.region_bytes,
            result.slot_count,
            result.completion_batch,
            result.target_cpu,
            result.affinity_applied,
            result.local_cpu,
            option_i32_label(result.worker_numa_node),
            result.buffer_mode.as_str(),
            result.slot_buffer_layout.as_str(),
            result.segment_bytes,
            result.buffer_base,
            result.buffer_alignment,
            result.buffer_stride,
            result.buffer_map_len,
            result.memory_policy
        );
    }

    println!(
        "slot-rand-sharded-bench: target={} mode={} workers={workers} \
         ops_per_worker={ops_per_worker} total_ops={total_ops} reads={total_reads} \
         writes={total_writes} read_percent={read_percent} chunk_bytes={chunk_bytes} \
         region_bytes_per_worker={region_bytes_per_worker} total_region_bytes={total_region_bytes} \
         pipeline_per_worker={pipeline} total_pipeline={} ring_entries={ring_entries} \
         completion_batch={} buffers={} slot_buffer_layout={} segment_bytes={segment_bytes} \
         required_alignment={required_alignment} slot_backend={} pin_workers={pin_workers} \
	         wall_seconds={wall_seconds:.6} io_seconds={io_seconds:.6} \
	         slowest_worker_seconds={slowest_worker_seconds:.6} \
	         total_cpu_seconds={total_cpu_seconds:.6} aggregate_cpu_percent={:.2} \
	         cpu_ns_per_op={:.1} MiBps={:.2} ops_per_sec={:.0}",
        target.label(),
        mode.as_str(),
        pipeline * workers,
        results
            .first()
            .map(|result| result.completion_batch)
            .unwrap_or(1),
        buffer_mode.as_str(),
        results
            .first()
            .map(|result| result.slot_buffer_layout.as_str())
            .unwrap_or(SlotBufferLayout::PerSlot.as_str()),
        io_slots::submission_backend_label(),
        total_cpu_seconds / io_seconds * 100.0,
        total_cpu_seconds * 1_000_000_000.0 / total_ops as f64,
        total_bytes as f64 / (1024.0 * 1024.0) / io_seconds,
        total_ops as f64 / io_seconds
    );
    Ok(())
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct LinuxAioIocb {
    aio_data: u64,
    aio_key: u32,
    aio_rw_flags: u32,
    aio_lio_opcode: u16,
    aio_reqprio: i16,
    aio_fildes: u32,
    aio_buf: u64,
    aio_nbytes: u64,
    aio_offset: i64,
    aio_reserved2: u64,
    aio_flags: u32,
    aio_resfd: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct LinuxAioEvent {
    data: u64,
    obj: u64,
    res: i64,
    res2: i64,
}

struct LinuxAioContext {
    ctx: u64,
}

impl LinuxAioContext {
    fn setup(nr_events: usize) -> io::Result<Self> {
        let mut ctx = 0u64;
        let nr_events = u32::try_from(nr_events).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "native AIO event count does not fit in u32",
            )
        })?;
        let ret = unsafe { libc::syscall(libc::SYS_io_setup, nr_events, &mut ctx) };
        if ret < 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(Self { ctx })
    }

    fn submit_all(&self, iocbs: &mut [*mut LinuxAioIocb]) -> io::Result<()> {
        let mut submitted = 0usize;
        while submitted < iocbs.len() {
            let remaining = iocbs.len() - submitted;
            let ret = unsafe {
                libc::syscall(
                    libc::SYS_io_submit,
                    self.ctx,
                    remaining as libc::c_long,
                    iocbs[submitted..].as_mut_ptr(),
                )
            };
            if ret < 0 {
                return Err(io::Error::last_os_error());
            }
            if ret == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::WouldBlock,
                    "native AIO submitted zero iocbs",
                ));
            }
            submitted += ret as usize;
        }
        Ok(())
    }

    fn getevents(&self, min: usize, events: &mut [LinuxAioEvent]) -> io::Result<usize> {
        let ret = unsafe {
            libc::syscall(
                libc::SYS_io_getevents,
                self.ctx,
                min as libc::c_long,
                events.len() as libc::c_long,
                events.as_mut_ptr(),
                ptr::null::<libc::timespec>(),
            )
        };
        if ret < 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(ret as usize)
    }
}

impl Drop for LinuxAioContext {
    fn drop(&mut self) {
        if self.ctx != 0 {
            unsafe {
                libc::syscall(libc::SYS_io_destroy, self.ctx);
            }
            self.ctx = 0;
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BlockBenchEngine {
    UringPlain,
    UringFixed,
    UringSlot,
    Aio,
    Sync,
    Suite,
}

impl BlockBenchEngine {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "suite" | "all" => Ok(Self::Suite),
            "uring-plain" | "plain" | "nonfixed" | "non-fixed" | "not-fixed" | "without-fixed"
            | "unregistered" | "uring-unregistered" => Ok(Self::UringPlain),
            "uring" | "uring-fixed" | "io-uring" | "io_uring" | "fixed" | "fixed-file"
            | "liburing" | "liburing-fixed" | "no-slot" | "without-slot" => Ok(Self::UringFixed),
            "slot" | "uring-slot" | "io-slot" | "io_slots" | "slot-aligned" | "with-slot"
            | "liburing-slot" => Ok(Self::UringSlot),
            "aio" | "linux-aio" | "native-aio" | "conventional-aio" | "conventional" => {
                Ok(Self::Aio)
            }
            "sync" | "blocking" | "syscall" | "readwrite" | "read-write" => Ok(Self::Sync),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "unknown zcblockbench engine {other:?}; use suite, uring-plain, uring-fixed, uring-slot, aio, or sync"
                ),
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::UringPlain => "uring-plain",
            Self::UringFixed => "uring-fixed",
            Self::UringSlot => "uring-slot",
            Self::Aio => "aio",
            Self::Sync => "sync",
            Self::Suite => "suite",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BlockBenchRingMode {
    Normal,
    NoSqArray,
    SqRewind,
    SqPoll,
    SqPollNoSqArray,
}

impl BlockBenchRingMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "normal" | "default" => Ok(Self::Normal),
            "no-sqarray" | "nosqarray" | "no_sqarray" => Ok(Self::NoSqArray),
            "sq-rewind" | "sq_rewind" | "rewind" => Ok(Self::SqRewind),
            "sqpoll" | "sq-poll" | "sq_poll" => Ok(Self::SqPoll),
            "sqpoll-no-sqarray" | "sqpoll-nosqarray" | "sq-poll-no-sqarray" => {
                Ok(Self::SqPollNoSqArray)
            }
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "unknown zcblockbench ring mode {other:?}; use normal, no-sqarray, sq-rewind, sqpoll, or sqpoll-no-sqarray"
                ),
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Normal => "normal",
            Self::NoSqArray => "no-sqarray",
            Self::SqRewind => "sq-rewind",
            Self::SqPoll => "sqpoll",
            Self::SqPollNoSqArray => "sqpoll-no-sqarray",
        }
    }

    fn uses_sqpoll(self) -> bool {
        matches!(self, Self::SqPoll | Self::SqPollNoSqArray)
    }

    fn raw_mode(self, sqpoll_cpu: Option<usize>) -> RawRingSqMode {
        match self {
            Self::Normal => RawRingSqMode::Normal,
            Self::NoSqArray => RawRingSqMode::NoSqArray,
            Self::SqRewind => RawRingSqMode::SqRewind,
            Self::SqPoll => RawRingSqMode::SqPoll {
                cpu: sqpoll_cpu,
                no_sqarray: false,
            },
            Self::SqPollNoSqArray => RawRingSqMode::SqPoll {
                cpu: sqpoll_cpu,
                no_sqarray: true,
            },
        }
    }
}

fn parse_blockbench_cqe_mode(value: &str) -> io::Result<RawRingCqeMode> {
    match value {
        "16" | "cqe16" | "cqe-16" => Ok(RawRingCqeMode::Cqe16),
        "32" | "cqe32" | "cqe-32" => Ok(RawRingCqeMode::Cqe32),
        other => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("unknown zcblockbench CQE mode {other:?}; use 16 or 32"),
        )),
    }
}

fn blockbench_cqe_mode_label(mode: RawRingCqeMode) -> &'static str {
    match mode {
        RawRingCqeMode::Cqe16 => "16",
        RawRingCqeMode::Cqe32 => "32",
    }
}

#[derive(Clone, Debug)]
enum BlockBenchTarget {
    NullChar,
    ZeroChar,
    Block(SlotWalTarget),
}

impl BlockBenchTarget {
    fn parse(arg: &str) -> io::Result<Self> {
        match arg {
            "/dev/null" | "null" | "char-null" => Ok(Self::NullChar),
            "/dev/zero" | "zero" | "char-zero" => Ok(Self::ZeroChar),
            other => parse_slot_wal_target(other).map(Self::Block),
        }
    }

    fn label(&self) -> &str {
        match self {
            Self::NullChar => "/dev/null",
            Self::ZeroChar => "/dev/zero",
            Self::Block(target) => target.label(),
        }
    }

    fn is_block(&self) -> bool {
        matches!(self, Self::Block(_))
    }
}

#[derive(Clone)]
struct BlockBenchConfig {
    target: String,
    workers: usize,
    ops_per_worker: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotRandMode,
    read_percent: u8,
    region_bytes_per_worker: usize,
    buffer_mode: SlotWalBufferMode,
    pin_workers: bool,
    engine: BlockBenchEngine,
    ring_mode: BlockBenchRingMode,
    cqe_mode: RawRingCqeMode,
    registered_ring_fd: bool,
    sqpoll_cpu_list: Option<Vec<usize>>,
    sqpoll_idle_ms: u32,
}

impl Default for BlockBenchConfig {
    fn default() -> Self {
        Self {
            target: "/dev/null".to_string(),
            workers: 8,
            ops_per_worker: 1_000_000,
            chunk_bytes: 4096,
            pipeline: 64,
            ring_entries: 256,
            mode: SlotRandMode::Write,
            read_percent: 80,
            region_bytes_per_worker: 1024 * 1024 * 1024,
            buffer_mode: SlotWalBufferMode::SmallPages,
            pin_workers: true,
            engine: BlockBenchEngine::Suite,
            ring_mode: BlockBenchRingMode::Normal,
            cqe_mode: RawRingCqeMode::Cqe16,
            registered_ring_fd: false,
            sqpoll_cpu_list: None,
            sqpoll_idle_ms: 1000,
        }
    }
}

#[derive(Clone, Copy)]
struct BlockBenchWorkerResult {
    worker: usize,
    ops: usize,
    reads: usize,
    writes: usize,
    elapsed: Duration,
    cpu: Duration,
    base_offset: u64,
    region_bytes: usize,
    slot_count: usize,
    target_cpu: i32,
    affinity_applied: bool,
    local_cpu: i32,
    worker_numa_node: Option<i32>,
    completion_batch: usize,
    buffer_base: usize,
    buffer_alignment: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    buffer_mode: SlotWalBufferMode,
    memory_policy: &'static str,
    sqpoll_cpu: i32,
}

fn blockbench_perf_warning(message: &str) {
    if env_enabled_or("URING_PLAY_BLOCKBENCH_PERF_WARN", true) {
        eprintln!("PERF WARNING: zcblockbench: {message}");
    }
}

fn zcblockbench_help() {
    println!(
        "zcblockbench - purpose-built multithreaded 4K random block IOPS bench\n\
         \n\
         zcblockbench [TARGET] [--engine suite|uring-plain|uring-fixed|uring-slot|aio|sync]\n\
           [--mode read|write|rw] [--workers N] [--ops-per-worker N]\n\
           [--bs BYTES] [--iodepth N] [--region-bytes-per-worker BYTES]\n\
           [--read-percent N] [--ring-entries N] [--buffer-mode small-pages|hugetlb]\n\
           [--pin true|false] [--ring-mode normal|no-sqarray|sq-rewind|sqpoll|sqpoll-no-sqarray]\n\
           [--cqe 16|32] [--registered-ring true|false] [--sqpoll-cpus CPU-LIST]\n\
         \n\
         Defaults run a short multithreaded write suite against /dev/null.\n\
         Reads against /dev/null use /dev/zero because /dev/null reads EOF.\n\
         Raw real devices must be allowlisted PARTUUID targets; destructive writes\n\
         still require URING_PLAY_ALLOW_RAW_BLOCK_WRITE=1 and matching\n\
         URING_PLAY_RAW_TARGET_PARTUUID."
    );
}

fn parse_zcblockbench_args(args: impl Iterator<Item = String>) -> io::Result<BlockBenchConfig> {
    let mut cfg = BlockBenchConfig::default();
    let mut positional = Vec::new();
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "help" | "--help" | "-h" => {
                zcblockbench_help();
                return Err(io::Error::new(io::ErrorKind::Interrupted, "help printed"));
            }
            "--target" => cfg.target = next_flag_value(&mut args, "--target")?,
            "--engine" => {
                cfg.engine = BlockBenchEngine::parse(&next_flag_value(&mut args, "--engine")?)?
            }
            "--mode" | "--rw" => {
                cfg.mode = SlotRandMode::parse(&next_flag_value(&mut args, &arg)?)?
            }
            "--workers" | "--threads" | "-j" => {
                cfg.workers = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--ops" | "--ops-per-worker" => {
                cfg.ops_per_worker = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--bs" | "--block-size" | "--chunk-bytes" => {
                cfg.chunk_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--iodepth" | "--depth" | "--pipeline" => {
                cfg.pipeline = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--ring-entries" => {
                cfg.ring_entries = parse_u32_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--read-percent" => {
                cfg.read_percent = parse_u8_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--region-bytes-per-worker" | "--region" => {
                cfg.region_bytes_per_worker =
                    parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--buffer-mode" | "--buffers" => {
                cfg.buffer_mode = SlotWalBufferMode::parse(&next_flag_value(&mut args, &arg)?)?
            }
            "--pin" | "--pin-workers" => {
                cfg.pin_workers = parse_bool_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--ring-mode" | "--uring-mode" => {
                cfg.ring_mode = BlockBenchRingMode::parse(&next_flag_value(&mut args, &arg)?)?
            }
            "--cqe" | "--cqe-mode" => {
                cfg.cqe_mode = parse_blockbench_cqe_mode(&next_flag_value(&mut args, &arg)?)?
            }
            "--registered-ring" | "--registered-ring-fd" => {
                cfg.registered_ring_fd = parse_bool_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--sqpoll-cpus" | "--sq-poll-cpus" => {
                let value = next_flag_value(&mut args, &arg)?;
                let cpus = parse_cpu_list(&value).map_err(|err| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("{arg}={value:?}: {err}"),
                    )
                })?;
                if cpus.is_empty() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("{arg} must contain at least one CPU"),
                    ));
                }
                cfg.sqpoll_cpu_list = Some(cpus);
            }
            "--sqpoll-idle-ms" | "--sq-poll-idle-ms" => {
                cfg.sqpoll_idle_ms = parse_u32_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--suite" => cfg.engine = BlockBenchEngine::Suite,
            "--uring-plain" => cfg.engine = BlockBenchEngine::UringPlain,
            "--uring-fixed" => cfg.engine = BlockBenchEngine::UringFixed,
            "--uring-slot" => cfg.engine = BlockBenchEngine::UringSlot,
            "--aio" => cfg.engine = BlockBenchEngine::Aio,
            "--sync" => cfg.engine = BlockBenchEngine::Sync,
            other if other.starts_with('-') => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcblockbench option {other:?}"),
                ));
            }
            other => positional.push(other.to_string()),
        }
    }

    if let Some(first) = positional.first() {
        if first == "suite" {
            cfg.engine = BlockBenchEngine::Suite;
        } else if let Ok(engine) = BlockBenchEngine::parse(first) {
            cfg.engine = engine;
        } else {
            cfg.target = first.clone();
        }
    }
    if positional.len() > 1 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcblockbench accepts at most one positional argument: TARGET or ENGINE",
        ));
    }
    Ok(cfg)
}

fn parse_u8_value(value: &str, name: &str) -> io::Result<u8> {
    value
        .parse::<u8>()
        .map_err(|err| io::Error::new(io::ErrorKind::InvalidInput, format!("{name}: {err}")))
}

fn blockbench_sqpoll_cpu_list(cfg: &BlockBenchConfig) -> io::Result<Option<Vec<usize>>> {
    if let Some(cpus) = cfg.sqpoll_cpu_list.clone() {
        return Ok(Some(cpus));
    }
    let Ok(value) = env::var("URING_PLAY_SQPOLL_CPU_LIST") else {
        return Ok(None);
    };
    if value.trim().is_empty() {
        return Ok(None);
    }
    let cpus = parse_cpu_list(&value).map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("URING_PLAY_SQPOLL_CPU_LIST={value:?}: {err}"),
        )
    })?;
    if cpus.is_empty() {
        return Ok(None);
    }
    Ok(Some(cpus))
}

fn zcblockbench_validate_config(cfg: &BlockBenchConfig) -> io::Result<()> {
    if cfg.workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    if cfg.ops_per_worker == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ops-per-worker must be non-zero",
        ));
    }
    if cfg.pipeline == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "iodepth/pipeline must be non-zero",
        ));
    }
    validate_slot_wal_pipeline(cfg.pipeline, cfg.ring_entries)?;
    if matches!(cfg.mode, SlotRandMode::Mixed) && cfg.read_percent > 100 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "read-percent must be 0..=100",
        ));
    }
    ensure_sector_aligned(cfg.chunk_bytes, "bs/chunk-bytes")?;
    ensure_sector_aligned(cfg.region_bytes_per_worker, "region-bytes-per-worker")?;
    if cfg.region_bytes_per_worker % cfg.chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes-per-worker must be an exact multiple of bs",
        ));
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct BlockBenchTargetValidation {
    total_region_bytes: usize,
    device_bytes: u64,
    required_alignment: usize,
    segment_bytes: usize,
}

fn zcblockbench_prepare_target(
    cfg: &BlockBenchConfig,
) -> io::Result<(BlockBenchTarget, Option<BlockBenchTargetValidation>)> {
    let target = BlockBenchTarget::parse(&cfg.target)?;
    let BlockBenchTarget::Block(_) = target else {
        return Ok((target, None));
    };
    let total_region_bytes = cfg
        .region_bytes_per_worker
        .checked_mul(cfg.workers)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "aggregate region overflow"))?;
    let safety_mode = if cfg.mode.needs_write() {
        SlotWalMode::Write
    } else {
        SlotWalMode::Read
    };
    let (validated_target, device_bytes, required_alignment, segment_bytes) =
        validate_slot_wal_common(
            &cfg.target,
            total_region_bytes,
            cfg.chunk_bytes,
            safety_mode,
            cfg.buffer_mode,
        )?;
    Ok((
        BlockBenchTarget::Block(validated_target),
        Some(BlockBenchTargetValidation {
            total_region_bytes,
            device_bytes,
            required_alignment,
            segment_bytes,
        }),
    ))
}

fn zcblockbench_open_files(
    target: &BlockBenchTarget,
    mode: SlotRandMode,
    direct: bool,
) -> io::Result<(Vec<fs::File>, u32, u32)> {
    match target {
        BlockBenchTarget::NullChar => {
            let mut files = Vec::new();
            let mut read_idx = 0u32;
            let mut write_idx = 0u32;
            if !matches!(mode, SlotRandMode::Write) {
                read_idx = files.len() as u32;
                files.push(
                    OpenOptions::new()
                        .read(true)
                        .custom_flags(libc::O_CLOEXEC)
                        .open("/dev/zero")?,
                );
            }
            if mode.needs_write() {
                write_idx = files.len() as u32;
                files.push(
                    OpenOptions::new()
                        .write(true)
                        .custom_flags(libc::O_CLOEXEC)
                        .open("/dev/null")?,
                );
            }
            Ok((files, read_idx, write_idx))
        }
        BlockBenchTarget::ZeroChar => {
            let mut files = Vec::new();
            let mut read_idx = 0u32;
            let mut write_idx = 0u32;
            if !matches!(mode, SlotRandMode::Write) {
                read_idx = files.len() as u32;
                files.push(
                    OpenOptions::new()
                        .read(true)
                        .custom_flags(libc::O_CLOEXEC)
                        .open("/dev/zero")?,
                );
            }
            if mode.needs_write() {
                write_idx = files.len() as u32;
                files.push(
                    OpenOptions::new()
                        .write(true)
                        .custom_flags(libc::O_CLOEXEC)
                        .open("/dev/zero")?,
                );
            }
            Ok((files, read_idx, write_idx))
        }
        BlockBenchTarget::Block(target) => {
            let mut open = OpenOptions::new();
            open.read(true).write(mode.needs_write());
            let flags = libc::O_CLOEXEC | if direct { libc::O_DIRECT } else { 0 };
            let file = open.custom_flags(flags).open(target.open_path())?;
            Ok((vec![file], 0, 0))
        }
    }
}

fn zcblockbench_direction(
    mode: SlotRandMode,
    read_percent: u8,
    rng: &mut u64,
    reads: &mut usize,
    writes: &mut usize,
) -> io_slots::SlotRw {
    match mode {
        SlotRandMode::Read => {
            *reads += 1;
            io_slots::SlotRw::Read
        }
        SlotRandMode::Write => {
            *writes += 1;
            io_slots::SlotRw::Write
        }
        SlotRandMode::Mixed => {
            if (splitmix64_next(rng) % 100) < read_percent as u64 {
                *reads += 1;
                io_slots::SlotRw::Read
            } else {
                *writes += 1;
                io_slots::SlotRw::Write
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn zcblockbench_uring_fixed_worker(
    target: BlockBenchTarget,
    worker: usize,
    base_offset: u64,
    region_bytes: usize,
    ops: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotRandMode,
    read_percent: u8,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
    planned_cpu: Option<usize>,
    ring_mode: BlockBenchRingMode,
    cqe_mode: RawRingCqeMode,
    registered_ring_fd: bool,
    sqpoll_cpu: Option<usize>,
    sqpoll_idle_ms: u32,
    registered_io: bool,
    start_barrier: Arc<Barrier>,
) -> io::Result<BlockBenchWorkerResult> {
    let region_blocks = region_bytes / chunk_bytes;
    let affinity =
        pin_current_thread_if_requested_to_cpu("zcblockbench-worker", worker, pin, planned_cpu);
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let (files, read_file_index, write_file_index) = zcblockbench_open_files(&target, mode, true)?;
    let mut fds: Vec<i32> = files.iter().map(AsRawFd::as_raw_fd).collect();
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    if mode.needs_write() {
        fill_slot_wal_buffers(&buffers, chunk_bytes);
    }
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let slot_buffer_layout = SlotBufferLayout::PerSlot;
    let mut iovecs = buffers.iovecs(chunk_bytes);

    let mut ring = RawRing::new_with_options(
        ring_entries,
        ring_entries.saturating_mul(2),
        RawRingOptions {
            stats_enabled: false,
            cqe_mode,
            sq_mode: ring_mode.raw_mode(sqpoll_cpu),
            registered_ring_fd,
            sq_thread_idle_ms: sqpoll_idle_ms,
        },
    )?;
    if registered_io {
        ring.register_files(&mut fds)?;
        ring.register_buffers(&mut iovecs)?;
    }

    let completion_batch =
        env_usize_or("URING_PLAY_BLOCKBENCH_COMPLETION_BATCH", 64).clamp(1, pipeline);
    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "bs/chunk-bytes must fit in u32",
        )
    })?;
    let mut rng = 0x243f_6a88_85a3_08d3u64
        ^ ((worker as u64) << 48)
        ^ ((ops as u64) << 7)
        ^ base_offset.rotate_left(11);
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let mut reads = 0usize;
    let mut writes = 0usize;
    start_barrier.wait();
    let local_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let started = Instant::now();

    while completed < ops {
        while submitted < ops && !free_slots.is_empty() {
            let slot = free_slots.pop().expect("free slot");
            let block = splitmix64_next(&mut rng) as usize % region_blocks;
            let file_offset = (block as u64)
                .checked_mul(chunk_bytes as u64)
                .and_then(|offset| base_offset.checked_add(offset))
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            let io_offset = if target.is_block() { file_offset } else { 0 };
            let direction =
                zcblockbench_direction(mode, read_percent, &mut rng, &mut reads, &mut writes);
            let buf_index = slot_buffer_layout.fixed_buf_index(slot)?;
            let ptr = buffers.ptr(slot);
            match direction {
                io_slots::SlotRw::Read => {
                    if registered_io {
                        ring.queue_read_fixed_file(
                            read_file_index,
                            ptr,
                            chunk_bytes_u32,
                            io_offset,
                            buf_index,
                            slot as u64,
                        )?
                    } else {
                        ring.queue_read(
                            fds[read_file_index as usize],
                            ptr,
                            chunk_bytes_u32,
                            io_offset,
                            slot as u64,
                        )?
                    }
                }
                io_slots::SlotRw::Write => {
                    if registered_io {
                        ring.queue_write_fixed_file(
                            write_file_index,
                            ptr.cast_const(),
                            chunk_bytes_u32,
                            io_offset,
                            buf_index,
                            slot as u64,
                        )?
                    } else {
                        ring.queue_write(
                            fds[write_file_index as usize],
                            ptr.cast_const(),
                            chunk_bytes_u32,
                            io_offset,
                            slot as u64,
                        )?
                    }
                }
            }
            submitted += 1;
        }

        ring.submit_pending()?;
        for batch_idx in 0..completion_batch {
            let cqe = if batch_idx == 0 {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => ring.wait_cqe()?,
                }
            } else {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => break,
                }
            };
            let slot = cqe.user_data as usize;
            if slot >= pipeline {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("zcblockbench CQE returned invalid slot user_data={slot}"),
                ));
            }
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            if cqe.res != chunk_bytes_u32 as i32 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short zcblockbench completion: res={} expected={chunk_bytes}",
                        cqe.res
                    ),
                ));
            }
            completed += 1;
            free_slots.push(slot);
            if completed == ops {
                break;
            }
        }
    }

    let elapsed = started.elapsed();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);
    if registered_io {
        ring.unregister_buffers()?;
        ring.unregister_files()?;
    }

    Ok(BlockBenchWorkerResult {
        worker,
        ops,
        reads,
        writes,
        elapsed,
        cpu,
        base_offset,
        region_bytes,
        slot_count: pipeline,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node: preferred_numa_node.or_else(|| {
            (local_cpu >= 0)
                .then(|| cpu_numa_node(local_cpu as usize))
                .flatten()
        }),
        completion_batch,
        buffer_base,
        buffer_alignment,
        buffer_stride,
        buffer_map_len,
        buffer_mode,
        memory_policy,
        sqpoll_cpu: sqpoll_cpu.map(|cpu| cpu as i32).unwrap_or(-1),
    })
}

fn zcblockbench_sync_transfer(
    fd: i32,
    ptr: *mut u8,
    len: usize,
    mut offset: u64,
    positional: bool,
    write: bool,
) -> io::Result<()> {
    let mut done = 0usize;
    while done < len {
        let remaining = len - done;
        let current = unsafe { ptr.add(done) };
        let ret = if positional {
            let off = libc::off_t::try_from(offset).map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "sync offset overflows off_t")
            })?;
            if write {
                unsafe { libc::pwrite(fd, current.cast_const().cast(), remaining, off) }
            } else {
                unsafe { libc::pread(fd, current.cast(), remaining, off) }
            }
        } else if write {
            unsafe { libc::write(fd, current.cast_const().cast(), remaining) }
        } else {
            unsafe { libc::read(fd, current.cast(), remaining) }
        };
        if ret < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        if ret == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "short sync transfer",
            ));
        }
        let transferred = ret as usize;
        done += transferred;
        offset = offset.saturating_add(transferred as u64);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn zcblockbench_sync_worker(
    target: BlockBenchTarget,
    worker: usize,
    base_offset: u64,
    region_bytes: usize,
    ops: usize,
    chunk_bytes: usize,
    pipeline: usize,
    mode: SlotRandMode,
    read_percent: u8,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
    planned_cpu: Option<usize>,
    start_barrier: Arc<Barrier>,
) -> io::Result<BlockBenchWorkerResult> {
    let region_blocks = region_bytes / chunk_bytes;
    let affinity =
        pin_current_thread_if_requested_to_cpu("zcblockbench-worker", worker, pin, planned_cpu);
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let (files, read_file_index, write_file_index) = zcblockbench_open_files(&target, mode, true)?;
    let fds: Vec<i32> = files.iter().map(AsRawFd::as_raw_fd).collect();
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    if mode.needs_write() {
        fill_slot_wal_buffers(&buffers, chunk_bytes);
    }
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let mut rng = 0x243f_6a88_85a3_08d3u64
        ^ ((worker as u64) << 48)
        ^ ((ops as u64) << 7)
        ^ base_offset.rotate_left(11);
    let mut reads = 0usize;
    let mut writes = 0usize;
    start_barrier.wait();
    let local_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let started = Instant::now();

    for op_index in 0..ops {
        let block = splitmix64_next(&mut rng) as usize % region_blocks;
        let file_offset = (block as u64)
            .checked_mul(chunk_bytes as u64)
            .and_then(|offset| base_offset.checked_add(offset))
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
        let slot = op_index % pipeline;
        let direction =
            zcblockbench_direction(mode, read_percent, &mut rng, &mut reads, &mut writes);
        match direction {
            io_slots::SlotRw::Read => zcblockbench_sync_transfer(
                fds[read_file_index as usize],
                buffers.ptr(slot),
                chunk_bytes,
                file_offset,
                target.is_block(),
                false,
            )?,
            io_slots::SlotRw::Write => zcblockbench_sync_transfer(
                fds[write_file_index as usize],
                buffers.ptr(slot),
                chunk_bytes,
                file_offset,
                target.is_block(),
                true,
            )?,
        }
    }

    let elapsed = started.elapsed();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);

    Ok(BlockBenchWorkerResult {
        worker,
        ops,
        reads,
        writes,
        elapsed,
        cpu,
        base_offset,
        region_bytes,
        slot_count: pipeline,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node: preferred_numa_node.or_else(|| {
            (local_cpu >= 0)
                .then(|| cpu_numa_node(local_cpu as usize))
                .flatten()
        }),
        completion_batch: 1,
        buffer_base,
        buffer_alignment,
        buffer_stride,
        buffer_map_len,
        buffer_mode,
        memory_policy,
        sqpoll_cpu: -1,
    })
}

#[allow(clippy::too_many_arguments)]
fn zcblockbench_aio_worker(
    target: BlockBenchTarget,
    worker: usize,
    base_offset: u64,
    region_bytes: usize,
    ops: usize,
    chunk_bytes: usize,
    pipeline: usize,
    mode: SlotRandMode,
    read_percent: u8,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
    planned_cpu: Option<usize>,
    start_barrier: Arc<Barrier>,
) -> io::Result<BlockBenchWorkerResult> {
    let region_blocks = region_bytes / chunk_bytes;
    let affinity =
        pin_current_thread_if_requested_to_cpu("zcblockbench-aio-worker", worker, pin, planned_cpu);
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };
    let (files, read_file_index, write_file_index) = zcblockbench_open_files(&target, mode, true)?;
    let buffers = buffer_mode.allocate_for_worker(pipeline, chunk_bytes, preferred_numa_node)?;
    if mode.needs_write() {
        fill_slot_wal_buffers(&buffers, chunk_bytes);
    }
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let aio = LinuxAioContext::setup(pipeline)?;
    let completion_batch =
        env_usize_or("URING_PLAY_BLOCKBENCH_COMPLETION_BATCH", 64).clamp(1, pipeline);
    let mut iocbs = vec![LinuxAioIocb::default(); pipeline];
    let mut events = vec![LinuxAioEvent::default(); completion_batch];
    let mut rng = 0x1319_8a2e_0370_7344u64
        ^ ((worker as u64) << 48)
        ^ ((ops as u64) << 9)
        ^ base_offset.rotate_left(13);
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let mut reads = 0usize;
    let mut writes = 0usize;
    start_barrier.wait();
    let local_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let started = Instant::now();

    while completed < ops {
        let mut submit_ptrs = Vec::<*mut LinuxAioIocb>::new();
        while submitted < ops && !free_slots.is_empty() {
            let slot = free_slots.pop().expect("free slot");
            let block = splitmix64_next(&mut rng) as usize % region_blocks;
            let file_offset = (block as u64)
                .checked_mul(chunk_bytes as u64)
                .and_then(|offset| base_offset.checked_add(offset))
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            let direction =
                zcblockbench_direction(mode, read_percent, &mut rng, &mut reads, &mut writes);
            let (opcode, file_index) = match direction {
                io_slots::SlotRw::Read => (IOCB_CMD_PREAD, read_file_index),
                io_slots::SlotRw::Write => (IOCB_CMD_PWRITE, write_file_index),
            };
            let fd = files
                .get(file_index as usize)
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "AIO fd index missing"))?
                .as_raw_fd();
            iocbs[slot] = LinuxAioIocb {
                aio_data: slot as u64,
                aio_lio_opcode: opcode,
                aio_fildes: fd as u32,
                aio_buf: buffers.ptr(slot) as u64,
                aio_nbytes: chunk_bytes as u64,
                aio_offset: file_offset as i64,
                ..LinuxAioIocb::default()
            };
            submit_ptrs.push(&mut iocbs[slot] as *mut LinuxAioIocb);
            submitted += 1;
        }

        if !submit_ptrs.is_empty() {
            aio.submit_all(&mut submit_ptrs)?;
        }
        let min_complete = usize::from(completed < ops);
        let got = aio.getevents(min_complete, &mut events)?;
        for event in &events[..got] {
            let slot = event.data as usize;
            if slot >= pipeline {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("native AIO returned invalid slot data={slot}"),
                ));
            }
            if event.res < 0 {
                return Err(io::Error::from_raw_os_error((-event.res) as i32));
            }
            if event.res != chunk_bytes as i64 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short native AIO completion: res={} expected={chunk_bytes}",
                        event.res
                    ),
                ));
            }
            completed += 1;
            free_slots.push(slot);
            if completed == ops {
                break;
            }
        }
    }

    let elapsed = started.elapsed();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);

    Ok(BlockBenchWorkerResult {
        worker,
        ops,
        reads,
        writes,
        elapsed,
        cpu,
        base_offset,
        region_bytes,
        slot_count: pipeline,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node: preferred_numa_node.or_else(|| {
            (local_cpu >= 0)
                .then(|| cpu_numa_node(local_cpu as usize))
                .flatten()
        }),
        completion_batch,
        buffer_base,
        buffer_alignment,
        buffer_stride,
        buffer_map_len,
        buffer_mode,
        memory_policy,
        sqpoll_cpu: -1,
    })
}

fn zcblockbench_print_results(
    target: &BlockBenchTarget,
    engine: BlockBenchEngine,
    cfg: &BlockBenchConfig,
    results: &mut [BlockBenchWorkerResult],
    started: Instant,
) -> io::Result<()> {
    results.sort_by_key(|result| result.worker);
    let wall_seconds = started.elapsed().as_secs_f64().max(f64::MIN_POSITIVE);
    let total_ops: usize = results.iter().map(|result| result.ops).sum();
    let total_reads: usize = results.iter().map(|result| result.reads).sum();
    let total_writes: usize = results.iter().map(|result| result.writes).sum();
    let total_bytes = total_ops.checked_mul(cfg.chunk_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcblockbench aggregate byte count overflow",
        )
    })?;
    let total_cpu_seconds: f64 = results.iter().map(|result| result.cpu.as_secs_f64()).sum();
    let slowest_worker_seconds = results
        .iter()
        .map(|result| result.elapsed)
        .max()
        .unwrap_or_default()
        .as_secs_f64()
        .max(f64::MIN_POSITIVE);
    let io_seconds = slowest_worker_seconds;

    for result in results.iter() {
        let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        let cpu_seconds = result.cpu.as_secs_f64();
        println!(
            "zcblockbench-worker: engine={} worker={} ops={} reads={} writes={} \
             seconds={seconds:.6} ops_per_sec={:.0} cpu_seconds={cpu_seconds:.6} \
             cpu_percent={:.2} cpu_ns_per_op={:.1} base_offset={} region_bytes={} \
             depth={} completion_batch={} target_cpu={} affinity_applied={} local_cpu={} \
             worker_numa_node={} sqpoll_cpu={} buffers={} buffer_base=0x{:x} buffer_alignment={} \
             buffer_stride={} buffer_map_len={} memory_policy={}",
            engine.as_str(),
            result.worker,
            result.ops,
            result.reads,
            result.writes,
            result.ops as f64 / seconds,
            cpu_seconds / seconds * 100.0,
            cpu_seconds * 1_000_000_000.0 / result.ops as f64,
            result.base_offset,
            result.region_bytes,
            result.slot_count,
            result.completion_batch,
            result.target_cpu,
            result.affinity_applied,
            result.local_cpu,
            option_i32_label(result.worker_numa_node),
            result.sqpoll_cpu,
            result.buffer_mode.as_str(),
            result.buffer_base,
            result.buffer_alignment,
            result.buffer_stride,
            result.buffer_map_len,
            result.memory_policy
        );
    }

    println!(
        "zcblockbench-result: target={} engine={} mode={} workers={} \
         ops_per_worker={} total_ops={} reads={} writes={} read_percent={} \
         chunk_bytes={} region_bytes_per_worker={} pipeline_per_worker={} \
         total_pipeline={} ring_entries={} ring_mode={} cqe={} registered_ring={} \
         buffers={} pin_workers={} \
	         wall_seconds={wall_seconds:.6} io_seconds={io_seconds:.6} \
	         slowest_worker_seconds={slowest_worker_seconds:.6} \
	         total_cpu_seconds={total_cpu_seconds:.6} aggregate_cpu_percent={:.2} \
	         cpu_ns_per_op={:.1} MiBps={:.2} ops_per_sec={:.0}",
        target.label(),
        engine.as_str(),
        cfg.mode.as_str(),
        cfg.workers,
        cfg.ops_per_worker,
        total_ops,
        total_reads,
        total_writes,
        cfg.read_percent,
        cfg.chunk_bytes,
        cfg.region_bytes_per_worker,
        cfg.pipeline,
        cfg.pipeline * cfg.workers,
        cfg.ring_entries,
        cfg.ring_mode.as_str(),
        blockbench_cqe_mode_label(cfg.cqe_mode),
        cfg.registered_ring_fd,
        cfg.buffer_mode.as_str(),
        cfg.pin_workers,
        total_cpu_seconds / io_seconds * 100.0,
        total_cpu_seconds * 1_000_000_000.0 / total_ops as f64,
        total_bytes as f64 / (1024.0 * 1024.0) / io_seconds,
        total_ops as f64 / io_seconds
    );
    Ok(())
}

fn zcblockbench_planned_cpus(
    target: &BlockBenchTarget,
    workers: usize,
    pin_workers: bool,
) -> io::Result<Vec<usize>> {
    if !pin_workers {
        return Ok(Vec::new());
    }
    if let Ok(cpu_list) = env::var("URING_PLAY_PIN_CPU_LIST")
        && !cpu_list.trim().is_empty()
    {
        let cpus = parse_cpu_list(&cpu_list).map_err(|err| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("URING_PLAY_PIN_CPU_LIST={cpu_list:?}: {err}"),
            )
        })?;
        if cpus.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "URING_PLAY_PIN_CPU_LIST must contain at least one CPU",
            ));
        }
        return Ok((0..workers).map(|index| cpus[index % cpus.len()]).collect());
    }
    match target {
        BlockBenchTarget::Block(target) => {
            let metadata = fs::metadata(target.open_path())?;
            let topology = BlockDeviceTopology::from_metadata(&metadata)?;
            Ok(topology.planned_cpus(workers, true))
        }
        BlockBenchTarget::NullChar | BlockBenchTarget::ZeroChar => {
            Ok((0..workers).map(configured_affinity_target_cpu).collect())
        }
    }
}

fn zcblockbench_run_direct_engine(
    target: BlockBenchTarget,
    engine: BlockBenchEngine,
    cfg: &BlockBenchConfig,
) -> io::Result<()> {
    let planned_cpus = zcblockbench_planned_cpus(&target, cfg.workers, cfg.pin_workers)?;
    let sqpoll_cpu_list = blockbench_sqpoll_cpu_list(cfg)?;
    let regions = make_linear_wal_regions(cfg.workers, cfg.region_bytes_per_worker)?;
    let started = Instant::now();
    let mut handles = Vec::with_capacity(cfg.workers);
    let start_barrier = Arc::new(Barrier::new(cfg.workers));
    for region in regions {
        let target = target.clone();
        let planned_cpu = planned_cpus.get(region.worker).copied();
        let sqpoll_cpu = sqpoll_cpu_list
            .as_ref()
            .filter(|_| cfg.ring_mode.uses_sqpoll())
            .map(|cpus| cpus[region.worker % cpus.len()]);
        let cfg = cfg.clone();
        let start_barrier = Arc::clone(&start_barrier);
        handles.push(thread::spawn(move || match engine {
            BlockBenchEngine::UringPlain | BlockBenchEngine::UringFixed => {
                zcblockbench_uring_fixed_worker(
                    target,
                    region.worker,
                    region.base_offset,
                    region.len_bytes,
                    cfg.ops_per_worker,
                    cfg.chunk_bytes,
                    cfg.pipeline,
                    cfg.ring_entries,
                    cfg.mode,
                    cfg.read_percent,
                    cfg.buffer_mode,
                    cfg.pin_workers,
                    planned_cpu,
                    cfg.ring_mode,
                    cfg.cqe_mode,
                    cfg.registered_ring_fd,
                    sqpoll_cpu,
                    cfg.sqpoll_idle_ms,
                    engine == BlockBenchEngine::UringFixed,
                    start_barrier,
                )
            }
            BlockBenchEngine::Aio => zcblockbench_aio_worker(
                target,
                region.worker,
                region.base_offset,
                region.len_bytes,
                cfg.ops_per_worker,
                cfg.chunk_bytes,
                cfg.pipeline,
                cfg.mode,
                cfg.read_percent,
                cfg.buffer_mode,
                cfg.pin_workers,
                planned_cpu,
                start_barrier,
            ),
            BlockBenchEngine::Sync => zcblockbench_sync_worker(
                target,
                region.worker,
                region.base_offset,
                region.len_bytes,
                cfg.ops_per_worker,
                cfg.chunk_bytes,
                cfg.pipeline,
                cfg.mode,
                cfg.read_percent,
                cfg.buffer_mode,
                cfg.pin_workers,
                planned_cpu,
                start_barrier,
            ),
            BlockBenchEngine::UringSlot | BlockBenchEngine::Suite => unreachable!(),
        }));
    }
    let mut results = Vec::with_capacity(cfg.workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("zcblockbench worker thread panicked"))??,
        );
    }
    zcblockbench_print_results(&target, engine, cfg, &mut results, started)
}

fn zcblockbench_run_slot_engine(
    target: &BlockBenchTarget,
    cfg: &BlockBenchConfig,
) -> io::Result<()> {
    let BlockBenchTarget::Block(target) = target else {
        println!(
            "zcblockbench-skip: target={} engine=uring-slot reason=requires-block-target",
            target.label()
        );
        return Ok(());
    };
    slot_rand_sharded_bench(
        target.label(),
        cfg.workers,
        cfg.ops_per_worker,
        cfg.chunk_bytes,
        cfg.pipeline,
        cfg.ring_entries,
        cfg.mode,
        cfg.read_percent,
        cfg.region_bytes_per_worker,
        cfg.buffer_mode,
        cfg.pin_workers,
    )
}

fn zcblockbench(args: impl Iterator<Item = String>) -> io::Result<()> {
    let cfg = match parse_zcblockbench_args(args) {
        Ok(cfg) => cfg,
        Err(err) if err.kind() == io::ErrorKind::Interrupted => return Ok(()),
        Err(err) => return Err(err),
    };
    zcblockbench_validate_config(&cfg)?;
    let (target, target_validation) = zcblockbench_prepare_target(&cfg)?;
    if cfg.pin_workers
        && env::var("URING_PLAY_PIN_CPU_LIST")
            .ok()
            .is_none_or(|value| value.trim().is_empty())
    {
        blockbench_perf_warning(
            "pinning is enabled but URING_PLAY_PIN_CPU_LIST is unset; set an explicit CPU list before treating IOPS as a topology result",
        );
    }
    if cfg.buffer_mode == SlotWalBufferMode::SmallPages {
        blockbench_perf_warning(
            "small-page buffers are fine for smoke tests; use --buffer-mode hugetlb with enough huge pages for high-IOPS claims",
        );
    }
    if cfg.pipeline < 32 {
        blockbench_perf_warning("iodepth below 32 is a latency shape, not an IOPS ceiling run");
    }
    if cfg.ring_mode.uses_sqpoll() && blockbench_sqpoll_cpu_list(&cfg)?.is_none() {
        blockbench_perf_warning(
            "SQPOLL requested without --sqpoll-cpus or URING_PLAY_SQPOLL_CPU_LIST; the kernel poll thread is not topologically pinned",
        );
    }
    if cfg.ring_mode.uses_sqpoll()
        && !matches!(
            cfg.engine,
            BlockBenchEngine::UringPlain | BlockBenchEngine::UringFixed
        )
    {
        blockbench_perf_warning(
            "SQPOLL ring mode currently applies to uring engines; slot, AIO, and sync suite legs will not use it",
        );
    }
    if (cfg.ring_mode != BlockBenchRingMode::Normal
        || cfg.cqe_mode != RawRingCqeMode::Cqe16
        || cfg.registered_ring_fd)
        && cfg.engine == BlockBenchEngine::Aio
    {
        blockbench_perf_warning("io_uring ring knobs do not apply to --engine aio");
    }
    if (cfg.ring_mode != BlockBenchRingMode::Normal
        || cfg.cqe_mode != RawRingCqeMode::Cqe16
        || cfg.registered_ring_fd)
        && cfg.engine == BlockBenchEngine::Sync
    {
        blockbench_perf_warning("io_uring ring knobs do not apply to --engine sync");
    }
    if cfg.engine == BlockBenchEngine::UringSlot && !target.is_block() {
        blockbench_perf_warning(
            "uring-slot needs a real block target; char devices are baseline-only targets",
        );
    }

    println!(
        "zcblockbench-plan: target={} engine={} mode={} workers={} ops_per_worker={} \
         chunk_bytes={} iodepth={} ring_entries={} read_percent={} region_bytes_per_worker={} \
         ring_mode={} cqe={} registered_ring={} sqpoll_idle_ms={} buffers={} pin_workers={} \
         target_kind={}",
        target.label(),
        cfg.engine.as_str(),
        cfg.mode.as_str(),
        cfg.workers,
        cfg.ops_per_worker,
        cfg.chunk_bytes,
        cfg.pipeline,
        cfg.ring_entries,
        cfg.read_percent,
        cfg.region_bytes_per_worker,
        cfg.ring_mode.as_str(),
        blockbench_cqe_mode_label(cfg.cqe_mode),
        cfg.registered_ring_fd,
        cfg.sqpoll_idle_ms,
        cfg.buffer_mode.as_str(),
        cfg.pin_workers,
        match &target {
            BlockBenchTarget::Block(_) => "block",
            BlockBenchTarget::NullChar => "char-null",
            BlockBenchTarget::ZeroChar => "char-zero",
        }
    );
    if let Some(validation) = target_validation {
        println!(
            "zcblockbench-target: target={} total_region_bytes={} device_bytes={} \
             required_alignment={} segment_bytes={}",
            target.label(),
            validation.total_region_bytes,
            validation.device_bytes,
            validation.required_alignment,
            validation.segment_bytes
        );
    }

    match cfg.engine {
        BlockBenchEngine::Suite => {
            zcblockbench_run_direct_engine(target.clone(), BlockBenchEngine::UringPlain, &cfg)?;
            zcblockbench_run_direct_engine(target.clone(), BlockBenchEngine::UringFixed, &cfg)?;
            zcblockbench_run_slot_engine(&target, &cfg)?;
            zcblockbench_run_direct_engine(target.clone(), BlockBenchEngine::Aio, &cfg)?;
            zcblockbench_run_direct_engine(target, BlockBenchEngine::Sync, &cfg)
        }
        BlockBenchEngine::UringPlain
        | BlockBenchEngine::UringFixed
        | BlockBenchEngine::Aio
        | BlockBenchEngine::Sync => zcblockbench_run_direct_engine(target, cfg.engine, &cfg),
        BlockBenchEngine::UringSlot => zcblockbench_run_slot_engine(&target, &cfg),
    }
}

fn zckv_key_hash(worker: usize, key: usize) -> u64 {
    let mut state = 0x243f_6a88_85a3_08d3u64
        ^ ((worker as u64) << 40)
        ^ (key as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
    splitmix64_next(&mut state)
}

#[derive(Clone, Copy)]
struct ZckvPageWorkerResult {
    worker: usize,
    ops: usize,
    gets: usize,
    sets: usize,
    elapsed: Duration,
    cpu: Duration,
    base_offset: u64,
    region_bytes: usize,
    key_count: usize,
    slot_count: usize,
    target_cpu: i32,
    affinity_applied: bool,
    local_cpu: i32,
    worker_numa_node: Option<i32>,
    completion_batch: usize,
    buffer_base: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    buffer_alignment: usize,
    buffer_mode: SlotWalBufferMode,
    segment_bytes: usize,
    slot_buffer_layout: SlotBufferLayout,
    memory_policy: &'static str,
    metadata_checksum: u64,
    read_checksum: u64,
}

#[allow(clippy::too_many_arguments)]
fn zckv_page_worker(
    target: SlotWalTarget,
    backend: ZckvPageBackend,
    worker: usize,
    base_offset: u64,
    region_bytes: usize,
    ops: usize,
    page_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    read_percent: u8,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
    planned_cpu: Option<usize>,
) -> io::Result<ZckvPageWorkerResult> {
    let key_count = region_bytes / page_bytes;
    if key_count == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes must cover at least one page",
        ));
    }
    let page_bytes_u32 = u32::try_from(page_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "page-bytes must fit in u32 for the SQE len field",
        )
    })?;

    let affinity =
        pin_current_thread_if_requested_to_cpu("zckv-page-worker", worker, pin, planned_cpu);
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };

    let file = OpenOptions::new()
        .read(true)
        .write(read_percent < 100)
        .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
        .open(target.open_path())?;
    let fd = file.as_raw_fd();

    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    let mut fds = [fd];
    ring.register_files(&mut fds)?;

    let buffers = buffer_mode.allocate_for_worker(pipeline, page_bytes, preferred_numa_node)?;
    fill_slot_wal_buffers(&buffers, page_bytes);
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let slot_buffer_layout = SlotBufferLayout::from_env()?;
    slot_buffer_layout.register_buffers(&ring, &buffers, page_bytes)?;

    let slot_ids = if matches!(backend, ZckvPageBackend::Slot) {
        slot_buffer_layout.register_io_slots(&ring, pipeline)?
    } else {
        Vec::new()
    };

    let key_hashes: Vec<u64> = (0..key_count)
        .map(|key| zckv_key_hash(worker, key))
        .collect();
    let mut in_flight_get = vec![false; pipeline];
    let completion_batch = env_usize_or(
        "URING_PLAY_ZCKV_COMPLETION_BATCH",
        env_usize_or("URING_PLAY_SLOT_COMPLETION_BATCH", 64),
    )
    .clamp(1, pipeline);
    let mut free_slots: Vec<usize> = (0..pipeline).rev().collect();
    let mut rng = 0x1319_8a2e_0370_7344u64
        ^ ((worker as u64) << 48)
        ^ (ops as u64)
        ^ ((page_bytes as u64) << 24)
        ^ base_offset.rotate_left(11);
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let mut gets = 0usize;
    let mut sets = 0usize;
    let mut metadata_checksum = 0u64;
    let mut read_checksum = 0u64;
    let local_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let started = Instant::now();

    while completed < ops {
        while submitted < ops && !free_slots.is_empty() {
            let slot = free_slots.pop().expect("free slot");
            let key = splitmix64_next(&mut rng) as usize % key_count;
            let key_hash = key_hashes[key];
            metadata_checksum = metadata_checksum
                .wrapping_add(key_hash)
                .rotate_left((key & 31) as u32);
            let file_offset = (key as u64)
                .checked_mul(page_bytes as u64)
                .and_then(|offset| base_offset.checked_add(offset))
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            let is_get = (splitmix64_next(&mut rng) % 100) < read_percent as u64;
            in_flight_get[slot] = is_get;
            if is_get {
                gets += 1;
            } else {
                sets += 1;
            }

            match backend {
                ZckvPageBackend::FixedFile => {
                    let ptr = buffers.ptr(slot);
                    let buf_index = slot_buffer_layout.fixed_buf_index(slot)?;
                    if is_get {
                        ring.queue_read_fixed_file(
                            0,
                            ptr,
                            page_bytes_u32,
                            file_offset,
                            buf_index,
                            slot as u64,
                        )?;
                    } else {
                        ring.queue_write_fixed_file(
                            0,
                            ptr.cast_const(),
                            page_bytes_u32,
                            file_offset,
                            buf_index,
                            slot as u64,
                        )?;
                    }
                }
                ZckvPageBackend::Slot => {
                    let direction = if is_get {
                        io_slots::SlotRw::Read
                    } else {
                        io_slots::SlotRw::Write
                    };
                    let buf_offset = slot_buffer_layout.buf_offset(&buffers, slot)?;
                    ring.queue_slot_rw(
                        slot_ids[slot],
                        buf_offset,
                        file_offset,
                        page_bytes_u32,
                        direction,
                        slot as u64,
                    )?;
                }
            }
            submitted += 1;
        }

        ring.submit_pending()?;
        for batch_idx in 0..completion_batch {
            let cqe = if batch_idx == 0 {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => ring.wait_cqe()?,
                }
            } else {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => break,
                }
            };
            let slot = cqe.user_data as usize;
            if slot >= pipeline {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("zckv CQE returned invalid slot user_data={slot}"),
                ));
            }
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            if cqe.res != page_bytes_u32 as i32 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short zckv page completion: res={} expected={page_bytes}",
                        cqe.res
                    ),
                ));
            }
            if in_flight_get[slot] {
                let byte = unsafe { ptr::read_volatile(buffers.ptr(slot).cast_const()) };
                read_checksum = read_checksum.wrapping_add(byte as u64).rotate_left(1);
            }
            completed += 1;
            free_slots.push(slot);
            if completed == ops {
                break;
            }
        }
    }

    let elapsed = started.elapsed();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);
    for slot_id in slot_ids {
        ring.unregister_io_slot(slot_id)?;
    }
    ring.unregister_buffers()?;
    ring.unregister_files()?;

    Ok(ZckvPageWorkerResult {
        worker,
        ops,
        gets,
        sets,
        elapsed,
        cpu,
        base_offset,
        region_bytes,
        key_count,
        slot_count: pipeline,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node: preferred_numa_node.or_else(|| {
            (local_cpu >= 0)
                .then(|| cpu_numa_node(local_cpu as usize))
                .flatten()
        }),
        completion_batch,
        buffer_base,
        buffer_stride,
        buffer_map_len,
        buffer_alignment,
        buffer_mode,
        segment_bytes: buffer_mode.segment_bytes()?,
        slot_buffer_layout,
        memory_policy,
        metadata_checksum,
        read_checksum,
    })
}

#[allow(clippy::too_many_arguments)]
fn zckv_page_bench(
    target_arg: &str,
    backend: ZckvPageBackend,
    workers: usize,
    ops_per_worker: usize,
    page_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    read_percent: u8,
    region_bytes_per_worker: usize,
    buffer_mode: SlotWalBufferMode,
    pin_workers: bool,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    if ops_per_worker == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ops-per-worker must be non-zero",
        ));
    }
    if read_percent > 100 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "read-percent must be 0..=100",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    ensure_sector_aligned(region_bytes_per_worker, "region-bytes-per-worker")?;
    ensure_sector_aligned(page_bytes, "page-bytes")?;
    if region_bytes_per_worker % page_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes-per-worker must be an exact multiple of page-bytes",
        ));
    }
    let total_region_bytes = region_bytes_per_worker
        .checked_mul(workers)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "aggregate region byte count overflow",
            )
        })?;
    let safety_mode = if read_percent < 100 {
        SlotWalMode::Write
    } else {
        SlotWalMode::Read
    };
    let (target, device_bytes, required_alignment, segment_bytes) = validate_slot_wal_common(
        target_arg,
        total_region_bytes,
        page_bytes,
        safety_mode,
        buffer_mode,
    )?;
    let metadata = fs::metadata(target.open_path())?;
    let topology = BlockDeviceTopology::from_metadata(&metadata)?;
    let planned_cpus = if pin_workers {
        topology.planned_cpus(workers, true)
    } else {
        Vec::new()
    };
    let regions = make_linear_wal_regions(workers, region_bytes_per_worker)?;
    validate_wal_regions(&regions, device_bytes)?;
    for region in &regions {
        let planned_cpu = planned_cpus.get(region.worker).copied();
        let queue_label = planned_cpu
            .map(|cpu| topology.queue_for_cpu(region.worker, cpu).index.to_string())
            .unwrap_or_else(|| "none".to_string());
        println!(
            "zckv-page-region: worker={} base_offset={} len_bytes={} end_offset={} \
             planned_cpu={} planned_nvme_queue={}",
            region.worker,
            region.base_offset,
            region.len_bytes,
            region.end_offset()?,
            planned_cpu
                .map(|cpu| cpu.to_string())
                .unwrap_or_else(|| "none".to_string()),
            queue_label
        );
    }

    let started = Instant::now();
    let mut handles = Vec::with_capacity(workers);
    for region in regions {
        let target = target.clone();
        let planned_cpu = planned_cpus.get(region.worker).copied();
        handles.push(thread::spawn(move || {
            zckv_page_worker(
                target,
                backend,
                region.worker,
                region.base_offset,
                region.len_bytes,
                ops_per_worker,
                page_bytes,
                pipeline,
                ring_entries,
                read_percent,
                buffer_mode,
                pin_workers,
                planned_cpu,
            )
        }));
    }

    let mut results = Vec::with_capacity(workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("zckv page worker thread panicked"))??,
        );
    }
    results.sort_by_key(|result| result.worker);

    let wall_seconds = started.elapsed().as_secs_f64().max(f64::MIN_POSITIVE);
    let total_ops: usize = results.iter().map(|result| result.ops).sum();
    let total_gets: usize = results.iter().map(|result| result.gets).sum();
    let total_sets: usize = results.iter().map(|result| result.sets).sum();
    let total_cpu_seconds: f64 = results.iter().map(|result| result.cpu.as_secs_f64()).sum();
    let total_bytes = total_ops.checked_mul(page_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zckv aggregate byte count overflow",
        )
    })?;
    let slowest_worker_seconds = results
        .iter()
        .map(|result| result.elapsed)
        .max()
        .unwrap_or_default()
        .as_secs_f64()
        .max(f64::MIN_POSITIVE);
    let metadata_checksum = results
        .iter()
        .fold(0u64, |acc, result| acc ^ result.metadata_checksum);
    let read_checksum = results
        .iter()
        .fold(0u64, |acc, result| acc ^ result.read_checksum);

    for result in &results {
        let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        let cpu_seconds = result.cpu.as_secs_f64();
        println!(
            "zckv-page-worker: worker={} backend={} ops={} gets={} sets={} \
             seconds={seconds:.6} qps={:.0} cpu_seconds={cpu_seconds:.6} \
             cpu_percent={:.2} cpu_ns_per_op={:.1} base_offset={} region_bytes={} \
             key_count={} slots={} completion_batch={} target_cpu={} affinity_applied={} \
             local_cpu={} worker_numa_node={} buffers={} segment_bytes={} \
             slot_buffer_layout={} buffer_base=0x{:x} buffer_alignment={} buffer_stride={} \
             buffer_map_len={} memory_policy={} metadata_checksum={} read_checksum={}",
            result.worker,
            backend.as_str(),
            result.ops,
            result.gets,
            result.sets,
            result.ops as f64 / seconds,
            cpu_seconds / seconds * 100.0,
            cpu_seconds * 1_000_000_000.0 / result.ops as f64,
            result.base_offset,
            result.region_bytes,
            result.key_count,
            result.slot_count,
            result.completion_batch,
            result.target_cpu,
            result.affinity_applied,
            result.local_cpu,
            option_i32_label(result.worker_numa_node),
            result.buffer_mode.as_str(),
            result.segment_bytes,
            result.slot_buffer_layout.as_str(),
            result.buffer_base,
            result.buffer_alignment,
            result.buffer_stride,
            result.buffer_map_len,
            result.memory_policy,
            result.metadata_checksum,
            result.read_checksum
        );
    }

    println!(
        "zckv-page-bench: target={} backend={} workers={workers} \
         ops_per_worker={ops_per_worker} total_ops={total_ops} gets={total_gets} sets={total_sets} \
         read_percent={read_percent} page_bytes={page_bytes} \
         region_bytes_per_worker={region_bytes_per_worker} total_region_bytes={total_region_bytes} \
         pipeline_per_worker={pipeline} total_pipeline={} ring_entries={ring_entries} \
         completion_batch={} buffers={} slot_buffer_layout={} segment_bytes={segment_bytes} \
         required_alignment={required_alignment} slot_backend={} pin_workers={pin_workers} \
         wall_seconds={wall_seconds:.6} slowest_worker_seconds={slowest_worker_seconds:.6} \
         total_cpu_seconds={total_cpu_seconds:.6} aggregate_cpu_percent={:.2} \
         cpu_ns_per_op={:.1} MiBps={:.2} qps={:.0} metadata_checksum={metadata_checksum} \
         read_checksum={read_checksum}",
        target.label(),
        backend.as_str(),
        pipeline * workers,
        results
            .first()
            .map(|result| result.completion_batch)
            .unwrap_or(1),
        buffer_mode.as_str(),
        results
            .first()
            .map(|result| result.slot_buffer_layout.as_str())
            .unwrap_or(SlotBufferLayout::PerSlot.as_str()),
        io_slots::submission_backend_label(),
        total_cpu_seconds / wall_seconds * 100.0,
        total_cpu_seconds * 1_000_000_000.0 / total_ops as f64,
        total_bytes as f64 / (1024.0 * 1024.0) / wall_seconds,
        total_ops as f64 / wall_seconds
    );
    Ok(())
}

#[derive(Clone, Copy, Default)]
struct CompactionLaneState {
    left_done: bool,
    right_done: bool,
    seq: usize,
    left_page: usize,
    right_page: usize,
}

#[derive(Clone, Copy)]
enum CompactionCqeKind {
    ReadLeft = 0,
    ReadRight = 1,
    WriteOutput = 2,
}

impl CompactionCqeKind {
    fn from_bits(bits: u64) -> Option<Self> {
        match bits {
            0 => Some(Self::ReadLeft),
            1 => Some(Self::ReadRight),
            2 => Some(Self::WriteOutput),
            _ => None,
        }
    }
}

fn compaction_user_data(kind: CompactionCqeKind, lane: usize) -> u64 {
    ((kind as u64) << 32) | lane as u64
}

fn compaction_cqe_parts(user_data: u64, pipeline: usize) -> io::Result<(CompactionCqeKind, usize)> {
    let lane = (user_data & 0xffff_ffff) as usize;
    let kind = CompactionCqeKind::from_bits(user_data >> 32).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("unknown compaction CQE kind in user_data={user_data}"),
        )
    })?;
    if lane >= pipeline {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("compaction CQE returned invalid lane={lane}"),
        ));
    }
    Ok((kind, lane))
}

fn read_u64_prefix(bytes: &[u8], offset: usize) -> u64 {
    let mut raw = [0u8; 8];
    if offset < bytes.len() {
        let available = (bytes.len() - offset).min(raw.len());
        raw[..available].copy_from_slice(&bytes[offset..offset + available]);
    }
    u64::from_ne_bytes(raw)
}

fn write_u64_prefix(bytes: &mut [u8], offset: usize, value: u64) {
    if offset + 8 <= bytes.len() {
        bytes[offset..offset + 8].copy_from_slice(&value.to_ne_bytes());
    }
}

fn compact_page_pair(
    buffers: &FixedSendBuffers,
    left_buffer: usize,
    right_buffer: usize,
    output_buffer: usize,
    page_bytes: usize,
    copy_bytes: usize,
    worker: usize,
    state: CompactionLaneState,
) -> u64 {
    unsafe {
        let left = slice::from_raw_parts(buffers.ptr(left_buffer).cast_const(), page_bytes);
        let right = slice::from_raw_parts(buffers.ptr(right_buffer).cast_const(), page_bytes);
        let output = slice::from_raw_parts_mut(buffers.ptr(output_buffer), page_bytes);
        let left_key = read_u64_prefix(left, 0)
            ^ zckv_key_hash(worker, state.left_page)
            ^ (state.seq as u64).rotate_left(7);
        let right_key = read_u64_prefix(right, 0)
            ^ zckv_key_hash(worker, state.right_page)
            ^ (state.seq as u64).rotate_left(17);
        let selected = if left_key <= right_key { left } else { right };
        let copy_len = copy_bytes.min(page_bytes);
        if copy_len > 0 {
            output[..copy_len].copy_from_slice(&selected[..copy_len]);
        }
        let digest = left_key
            .wrapping_add(right_key.rotate_left(13))
            .wrapping_add((state.seq as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15));
        write_u64_prefix(output, 0, 0x7a63_636d_7063_7431);
        write_u64_prefix(output, 8, state.seq as u64);
        write_u64_prefix(output, 16, state.left_page as u64);
        write_u64_prefix(output, 24, state.right_page as u64);
        write_u64_prefix(output, 32, left_key);
        write_u64_prefix(output, 40, right_key);
        write_u64_prefix(output, 48, digest);
        digest ^ read_u64_prefix(output, page_bytes.saturating_sub(8))
    }
}

#[allow(clippy::too_many_arguments)]
fn queue_page_backend_io(
    ring: &mut RawRing,
    backend: ZckvPageBackend,
    slot_buffer_layout: SlotBufferLayout,
    buffers: &FixedSendBuffers,
    slot_ids: &[io_slots::IoSlotId],
    buffer_index: usize,
    file_offset: u64,
    len: u32,
    direction: io_slots::SlotRw,
    user_data: u64,
) -> io::Result<()> {
    match backend {
        ZckvPageBackend::FixedFile => {
            let ptr = buffers.ptr(buffer_index);
            let buf_index = slot_buffer_layout.fixed_buf_index(buffer_index)?;
            match direction {
                io_slots::SlotRw::Read => {
                    ring.queue_read_fixed_file(0, ptr, len, file_offset, buf_index, user_data)
                }
                io_slots::SlotRw::Write => ring.queue_write_fixed_file(
                    0,
                    ptr.cast_const(),
                    len,
                    file_offset,
                    buf_index,
                    user_data,
                ),
            }
        }
        ZckvPageBackend::Slot => {
            let buf_offset = slot_buffer_layout.buf_offset(buffers, buffer_index)?;
            ring.queue_slot_rw(
                slot_ids[buffer_index],
                buf_offset,
                file_offset,
                len,
                direction,
                user_data,
            )
        }
    }
}

#[derive(Clone, Copy)]
struct ZckvCompactionWorkerResult {
    worker: usize,
    ops: usize,
    read_ops: usize,
    write_ops: usize,
    elapsed: Duration,
    cpu: Duration,
    base_offset: u64,
    region_bytes: usize,
    run_bytes: usize,
    run_pages: usize,
    page_bytes: usize,
    pipeline: usize,
    buffer_count: usize,
    completion_batch: usize,
    target_cpu: i32,
    affinity_applied: bool,
    local_cpu: i32,
    worker_numa_node: Option<i32>,
    buffer_base: usize,
    buffer_stride: usize,
    buffer_map_len: usize,
    buffer_alignment: usize,
    buffer_mode: SlotWalBufferMode,
    segment_bytes: usize,
    slot_buffer_layout: SlotBufferLayout,
    memory_policy: &'static str,
    copy_bytes: usize,
    merge_checksum: u64,
    read_checksum: u64,
}

#[allow(clippy::too_many_arguments)]
fn zckv_compaction_worker(
    target: SlotWalTarget,
    backend: ZckvPageBackend,
    worker: usize,
    base_offset: u64,
    region_bytes: usize,
    ops: usize,
    page_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
    pin: bool,
    planned_cpu: Option<usize>,
) -> io::Result<ZckvCompactionWorkerResult> {
    let page_bytes_u32 = u32::try_from(page_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "page-bytes must fit in u32 for the SQE len field",
        )
    })?;
    let run_bytes = region_bytes / 3;
    let run_pages = run_bytes / page_bytes;
    if run_pages == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes-per-worker must contain at least one page per compaction run",
        ));
    }
    if ops > run_pages {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "ops-per-worker={ops} exceeds output run capacity {run_pages}; \
                 increase region-bytes-per-worker or reduce ops"
            ),
        ));
    }

    let affinity =
        pin_current_thread_if_requested_to_cpu("zckv-compaction-worker", worker, pin, planned_cpu);
    let preferred_numa_node = if affinity.target_cpu >= 0 {
        cpu_numa_node(affinity.target_cpu as usize)
    } else {
        None
    };

    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
        .open(target.open_path())?;
    let fd = file.as_raw_fd();

    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    let mut fds = [fd];
    ring.register_files(&mut fds)?;

    let buffer_count = checked_buffer_count(pipeline, 3, "zckv-compact-bench")?;
    let buffers = buffer_mode.allocate_for_worker(buffer_count, page_bytes, preferred_numa_node)?;
    fill_slot_wal_buffers(&buffers, page_bytes);
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let slot_buffer_layout = SlotBufferLayout::from_env()?;
    slot_buffer_layout.register_buffers(&ring, &buffers, page_bytes)?;
    let slot_ids = if matches!(backend, ZckvPageBackend::Slot) {
        slot_buffer_layout.register_io_slots(&ring, buffer_count)?
    } else {
        Vec::new()
    };

    let left_base = base_offset;
    let right_base = base_offset + run_bytes as u64;
    let output_base = base_offset + (run_bytes as u64).saturating_mul(2);
    let copy_bytes = env_usize_or("URING_PLAY_COMPACTION_COPY_BYTES", page_bytes).min(page_bytes);
    let completion_batch = env_usize_or(
        "URING_PLAY_COMPACTION_COMPLETION_BATCH",
        env_usize_or("URING_PLAY_SLOT_COMPLETION_BATCH", 64),
    )
    .clamp(1, buffer_count);
    let mut lane_states = vec![CompactionLaneState::default(); pipeline];
    let mut free_lanes: Vec<usize> = (0..pipeline).rev().collect();
    let mut rng = 0x7a63_636f_6d70_6163u64
        ^ ((worker as u64) << 48)
        ^ (ops as u64)
        ^ ((page_bytes as u64) << 16)
        ^ base_offset.rotate_left(9);
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let mut read_ops = 0usize;
    let mut write_ops = 0usize;
    let mut merge_checksum = 0u64;
    let mut read_checksum = 0u64;
    let local_cpu = current_cpu();
    let start_thread_cpu = thread_cpu_time().unwrap_or_default();
    let started = Instant::now();

    while completed < ops {
        while submitted < ops && !free_lanes.is_empty() {
            let lane = free_lanes.pop().expect("free lane");
            let left_page = splitmix64_next(&mut rng) as usize % run_pages;
            let right_page = splitmix64_next(&mut rng) as usize % run_pages;
            lane_states[lane] = CompactionLaneState {
                left_done: false,
                right_done: false,
                seq: submitted,
                left_page,
                right_page,
            };
            let left_buffer = lane * 3;
            let right_buffer = left_buffer + 1;
            let left_offset = left_base + (left_page as u64) * page_bytes as u64;
            let right_offset = right_base + (right_page as u64) * page_bytes as u64;
            queue_page_backend_io(
                &mut ring,
                backend,
                slot_buffer_layout,
                &buffers,
                &slot_ids,
                left_buffer,
                left_offset,
                page_bytes_u32,
                io_slots::SlotRw::Read,
                compaction_user_data(CompactionCqeKind::ReadLeft, lane),
            )?;
            queue_page_backend_io(
                &mut ring,
                backend,
                slot_buffer_layout,
                &buffers,
                &slot_ids,
                right_buffer,
                right_offset,
                page_bytes_u32,
                io_slots::SlotRw::Read,
                compaction_user_data(CompactionCqeKind::ReadRight, lane),
            )?;
            read_ops += 2;
            submitted += 1;
        }

        ring.submit_pending()?;
        for batch_idx in 0..completion_batch {
            let cqe = if batch_idx == 0 {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => ring.wait_cqe()?,
                }
            } else {
                match ring.try_pop_cqe() {
                    Some(cqe) => cqe,
                    None => break,
                }
            };
            if cqe.res < 0 {
                return Err(io::Error::from_raw_os_error(-cqe.res));
            }
            if cqe.res != page_bytes_u32 as i32 {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    format!(
                        "short compaction completion: res={} expected={page_bytes}",
                        cqe.res
                    ),
                ));
            }
            let (kind, lane) = compaction_cqe_parts(cqe.user_data, pipeline)?;
            let base_buffer = lane * 3;
            match kind {
                CompactionCqeKind::ReadLeft => {
                    lane_states[lane].left_done = true;
                    let byte = unsafe { ptr::read_volatile(buffers.ptr(base_buffer).cast_const()) };
                    read_checksum = read_checksum.wrapping_add(byte as u64).rotate_left(1);
                }
                CompactionCqeKind::ReadRight => {
                    lane_states[lane].right_done = true;
                    let byte =
                        unsafe { ptr::read_volatile(buffers.ptr(base_buffer + 1).cast_const()) };
                    read_checksum = read_checksum.wrapping_add(byte as u64).rotate_left(1);
                }
                CompactionCqeKind::WriteOutput => {
                    completed += 1;
                    free_lanes.push(lane);
                    if completed == ops {
                        break;
                    }
                    continue;
                }
            }

            if lane_states[lane].left_done && lane_states[lane].right_done {
                let state = lane_states[lane];
                merge_checksum ^= compact_page_pair(
                    &buffers,
                    base_buffer,
                    base_buffer + 1,
                    base_buffer + 2,
                    page_bytes,
                    copy_bytes,
                    worker,
                    state,
                );
                let output_offset = output_base + (state.seq as u64) * page_bytes as u64;
                queue_page_backend_io(
                    &mut ring,
                    backend,
                    slot_buffer_layout,
                    &buffers,
                    &slot_ids,
                    base_buffer + 2,
                    output_offset,
                    page_bytes_u32,
                    io_slots::SlotRw::Write,
                    compaction_user_data(CompactionCqeKind::WriteOutput, lane),
                )?;
                write_ops += 1;
            }
        }
    }

    let elapsed = started.elapsed();
    let cpu = thread_cpu_time()
        .unwrap_or(start_thread_cpu)
        .saturating_sub(start_thread_cpu);
    for slot_id in slot_ids {
        ring.unregister_io_slot(slot_id)?;
    }
    ring.unregister_buffers()?;
    ring.unregister_files()?;

    Ok(ZckvCompactionWorkerResult {
        worker,
        ops,
        read_ops,
        write_ops,
        elapsed,
        cpu,
        base_offset,
        region_bytes,
        run_bytes,
        run_pages,
        page_bytes,
        pipeline,
        buffer_count,
        completion_batch,
        target_cpu: affinity.target_cpu,
        affinity_applied: affinity.applied,
        local_cpu,
        worker_numa_node: preferred_numa_node.or_else(|| {
            (local_cpu >= 0)
                .then(|| cpu_numa_node(local_cpu as usize))
                .flatten()
        }),
        buffer_base,
        buffer_stride,
        buffer_map_len,
        buffer_alignment,
        buffer_mode,
        segment_bytes: buffer_mode.segment_bytes()?,
        slot_buffer_layout,
        memory_policy,
        copy_bytes,
        merge_checksum,
        read_checksum,
    })
}

#[allow(clippy::too_many_arguments)]
fn zckv_compaction_bench(
    target_arg: &str,
    backend: ZckvPageBackend,
    workers: usize,
    ops_per_worker: usize,
    page_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    region_bytes_per_worker: usize,
    buffer_mode: SlotWalBufferMode,
    pin_workers: bool,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    if ops_per_worker == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ops-per-worker must be non-zero",
        ));
    }
    let buffer_count = checked_buffer_count(pipeline, 3, "zckv-compact-bench")?;
    validate_slot_wal_pipeline(buffer_count, ring_entries)?;
    ensure_sector_aligned(region_bytes_per_worker, "region-bytes-per-worker")?;
    ensure_sector_aligned(page_bytes, "page-bytes")?;
    let layout_unit = page_bytes.checked_mul(3).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "compaction layout byte count overflow",
        )
    })?;
    if region_bytes_per_worker % layout_unit != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "region-bytes-per-worker must be an exact multiple of page-bytes * 3",
        ));
    }
    let run_pages = region_bytes_per_worker / 3 / page_bytes;
    if ops_per_worker > run_pages {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "ops-per-worker={ops_per_worker} exceeds output run capacity {run_pages}; \
                 increase region-bytes-per-worker or reduce ops"
            ),
        ));
    }
    let total_region_bytes = region_bytes_per_worker
        .checked_mul(workers)
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "aggregate compaction byte count overflow",
            )
        })?;
    let (target, device_bytes, required_alignment, segment_bytes) = validate_slot_wal_common(
        target_arg,
        total_region_bytes,
        page_bytes,
        SlotWalMode::Write,
        buffer_mode,
    )?;
    let metadata = fs::metadata(target.open_path())?;
    let topology = BlockDeviceTopology::from_metadata(&metadata)?;
    let planned_cpus = if pin_workers {
        topology.planned_cpus(workers, true)
    } else {
        Vec::new()
    };
    let regions = make_linear_wal_regions(workers, region_bytes_per_worker)?;
    validate_wal_regions(&regions, device_bytes)?;
    for region in &regions {
        let run_bytes = region.len_bytes / 3;
        let planned_cpu = planned_cpus.get(region.worker).copied();
        let queue_label = planned_cpu
            .map(|cpu| topology.queue_for_cpu(region.worker, cpu).index.to_string())
            .unwrap_or_else(|| "none".to_string());
        println!(
            "zckv-compact-region: worker={} base_offset={} source_a_base={} \
             source_b_base={} output_base={} run_bytes={} output_end={} \
             planned_cpu={} planned_nvme_queue={}",
            region.worker,
            region.base_offset,
            region.base_offset,
            region.base_offset + run_bytes as u64,
            region.base_offset + (run_bytes as u64).saturating_mul(2),
            run_bytes,
            region.end_offset()?,
            planned_cpu
                .map(|cpu| cpu.to_string())
                .unwrap_or_else(|| "none".to_string()),
            queue_label
        );
    }

    let started = Instant::now();
    let mut handles = Vec::with_capacity(workers);
    for region in regions {
        let target = target.clone();
        let planned_cpu = planned_cpus.get(region.worker).copied();
        handles.push(thread::spawn(move || {
            zckv_compaction_worker(
                target,
                backend,
                region.worker,
                region.base_offset,
                region.len_bytes,
                ops_per_worker,
                page_bytes,
                pipeline,
                ring_entries,
                buffer_mode,
                pin_workers,
                planned_cpu,
            )
        }));
    }

    let mut results = Vec::with_capacity(workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("zckv compaction worker thread panicked"))??,
        );
    }
    results.sort_by_key(|result| result.worker);

    let wall_seconds = started.elapsed().as_secs_f64().max(f64::MIN_POSITIVE);
    let total_ops: usize = results.iter().map(|result| result.ops).sum();
    let total_read_ops: usize = results.iter().map(|result| result.read_ops).sum();
    let total_write_ops: usize = results.iter().map(|result| result.write_ops).sum();
    let total_cpu_seconds: f64 = results.iter().map(|result| result.cpu.as_secs_f64()).sum();
    let read_bytes = total_read_ops.checked_mul(page_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "compaction read byte count overflow",
        )
    })?;
    let write_bytes = total_write_ops.checked_mul(page_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "compaction write byte count overflow",
        )
    })?;
    let total_io_bytes = read_bytes.checked_add(write_bytes).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "compaction IO byte count overflow",
        )
    })?;
    let slowest_worker_seconds = results
        .iter()
        .map(|result| result.elapsed)
        .max()
        .unwrap_or_default()
        .as_secs_f64()
        .max(f64::MIN_POSITIVE);
    let merge_checksum = results
        .iter()
        .fold(0u64, |acc, result| acc ^ result.merge_checksum);
    let read_checksum = results
        .iter()
        .fold(0u64, |acc, result| acc ^ result.read_checksum);

    for result in &results {
        let seconds = result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE);
        let cpu_seconds = result.cpu.as_secs_f64();
        println!(
            "zckv-compact-worker: worker={} backend={} ops={} read_ops={} write_ops={} \
             seconds={seconds:.6} compact_ops_per_sec={:.0} io_ops_per_sec={:.0} \
             cpu_seconds={cpu_seconds:.6} cpu_percent={:.2} cpu_ns_per_compaction={:.1} \
             base_offset={} region_bytes={} run_bytes={} run_pages={} page_bytes={} \
             pipeline={} buffers_per_worker={} completion_batch={} target_cpu={} \
             affinity_applied={} local_cpu={} worker_numa_node={} buffers={} \
             slot_buffer_layout={} segment_bytes={} copy_bytes={} buffer_base=0x{:x} \
             buffer_alignment={} buffer_stride={} buffer_map_len={} memory_policy={} \
             merge_checksum={} read_checksum={}",
            result.worker,
            backend.as_str(),
            result.ops,
            result.read_ops,
            result.write_ops,
            result.ops as f64 / seconds,
            (result.read_ops + result.write_ops) as f64 / seconds,
            cpu_seconds / seconds * 100.0,
            cpu_seconds * 1_000_000_000.0 / result.ops as f64,
            result.base_offset,
            result.region_bytes,
            result.run_bytes,
            result.run_pages,
            result.page_bytes,
            result.pipeline,
            result.buffer_count,
            result.completion_batch,
            result.target_cpu,
            result.affinity_applied,
            result.local_cpu,
            option_i32_label(result.worker_numa_node),
            result.buffer_mode.as_str(),
            result.slot_buffer_layout.as_str(),
            result.segment_bytes,
            result.copy_bytes,
            result.buffer_base,
            result.buffer_alignment,
            result.buffer_stride,
            result.buffer_map_len,
            result.memory_policy,
            result.merge_checksum,
            result.read_checksum
        );
    }

    println!(
        "zckv-compact-bench: target={} backend={} workers={workers} \
         ops_per_worker={ops_per_worker} total_ops={total_ops} read_ops={total_read_ops} \
         write_ops={total_write_ops} page_bytes={page_bytes} region_bytes_per_worker={} \
         total_region_bytes={total_region_bytes} run_bytes_per_worker={} pipeline_per_worker={pipeline} \
         buffers_per_worker={buffer_count} total_pipeline={} total_buffers={} \
         ring_entries={ring_entries} completion_batch={} buffers={} slot_buffer_layout={} \
         segment_bytes={segment_bytes} required_alignment={required_alignment} \
         slot_backend={} pin_workers={pin_workers} copy_bytes={} \
         wall_seconds={wall_seconds:.6} slowest_worker_seconds={slowest_worker_seconds:.6} \
         total_cpu_seconds={total_cpu_seconds:.6} aggregate_cpu_percent={:.2} \
         cpu_ns_per_compaction={:.1} compact_ops_per_sec={:.0} io_ops_per_sec={:.0} \
         read_MiBps={:.2} write_MiBps={:.2} total_io_MiBps={:.2} \
         merge_checksum={merge_checksum} read_checksum={read_checksum}",
        target.label(),
        backend.as_str(),
        region_bytes_per_worker,
        region_bytes_per_worker / 3,
        pipeline * workers,
        buffer_count * workers,
        results
            .first()
            .map(|result| result.completion_batch)
            .unwrap_or(1),
        buffer_mode.as_str(),
        results
            .first()
            .map(|result| result.slot_buffer_layout.as_str())
            .unwrap_or(SlotBufferLayout::PerSlot.as_str()),
        io_slots::submission_backend_label(),
        results.first().map(|result| result.copy_bytes).unwrap_or(0),
        total_cpu_seconds / wall_seconds * 100.0,
        total_cpu_seconds * 1_000_000_000.0 / total_ops as f64,
        total_ops as f64 / wall_seconds,
        (total_read_ops + total_write_ops) as f64 / wall_seconds,
        read_bytes as f64 / (1024.0 * 1024.0) / wall_seconds,
        write_bytes as f64 / (1024.0 * 1024.0) / wall_seconds,
        total_io_bytes as f64 / (1024.0 * 1024.0) / wall_seconds
    );
    Ok(())
}

fn slot_rw_same_slot_test(
    target_arg: &str,
    ops: usize,
    chunk_bytes: usize,
    inflight: usize,
    ring_entries: u32,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<()> {
    if ops == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "ops must be non-zero",
        ));
    }
    if inflight < 2 || inflight > u16::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("inflight must be between 2 and {}", u16::MAX),
        ));
    }
    if inflight > ring_entries as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "inflight must be <= ring-entries",
        ));
    }
    let chunk_bytes_u32 = u32::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "chunk-bytes must fit in u32 for the SQE len field",
        )
    })?;
    let total_bytes = ops.checked_mul(chunk_bytes).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "aggregate byte count overflow")
    })?;
    let (target, _device_bytes, required_alignment, segment_bytes) = validate_slot_wal_common(
        target_arg,
        total_bytes,
        chunk_bytes,
        SlotWalMode::Write,
        buffer_mode,
    )?;

    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .custom_flags(libc::O_DIRECT | libc::O_CLOEXEC)
        .open(target.open_path())?;
    let fd = file.as_raw_fd();

    let mut ring = RawRing::new(ring_entries, ring_entries.saturating_mul(2))?;
    let mut fds = [fd];
    ring.register_files(&mut fds)?;

    let buffers = buffer_mode.allocate(1, chunk_bytes)?;
    fill_slot_wal_buffers(&buffers, chunk_bytes);
    let buffer_base = buffers.base_addr();
    let buffer_stride = buffers.stride();
    let buffer_map_len = buffers.map_len();
    let buffer_alignment = address_alignment(buffer_base);
    let memory_policy = buffers.memory_policy();
    let mut iovecs = buffers.iovecs(chunk_bytes);
    ring.register_buffers(&mut iovecs)?;
    let slot_id = ring.register_io_slot(0, 0)?;

    let started = Instant::now();
    let mut submitted = 0usize;
    let mut completed = 0usize;
    let mut max_observed_inflight = 0usize;
    let mut first_error = None;

    while completed < ops || completed < submitted {
        while first_error.is_none()
            && submitted < ops
            && submitted.saturating_sub(completed) < inflight
        {
            let file_offset = (submitted as u64)
                .checked_mul(chunk_bytes as u64)
                .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "offset overflow"))?;
            ring.queue_slot_rw(
                slot_id,
                0,
                file_offset,
                chunk_bytes_u32,
                io_slots::SlotRw::Write,
                submitted as u64,
            )?;
            submitted += 1;
            max_observed_inflight = max_observed_inflight.max(submitted - completed);
        }

        if completed == submitted {
            break;
        }

        let cqe = ring.wait_cqe()?;
        let seq = cqe.user_data as usize;
        if seq >= ops && first_error.is_none() {
            first_error = Some(format!("invalid same-slot CQE user_data={seq} ops={ops}"));
        }
        if cqe.res < 0 && first_error.is_none() {
            first_error = Some(format!(
                "same-slot write seq={seq} failed with errno {}",
                -cqe.res
            ));
        } else if cqe.res != chunk_bytes_u32 as i32 && first_error.is_none() {
            first_error = Some(format!(
                "short same-slot write completion: seq={seq} res={} expected={chunk_bytes}",
                cqe.res
            ));
        }
        completed += 1;
    }

    let elapsed = started.elapsed();
    let seconds = elapsed.as_secs_f64().max(f64::MIN_POSITIVE);

    ring.unregister_io_slot(slot_id)?;
    ring.unregister_buffers()?;
    ring.unregister_files()?;

    if let Some(error) = first_error {
        return Err(io::Error::new(io::ErrorKind::WriteZero, error));
    }

    println!(
        "slot-rw-same-slot-test: ok target={} ops={ops} total_bytes={total_bytes} \
         chunk_bytes={chunk_bytes} inflight={inflight} max_observed_inflight={max_observed_inflight} \
         ring_entries={ring_entries} buffers={} segment_bytes={segment_bytes} \
         required_alignment={required_alignment} slot_backend={} \
         buffer_base=0x{buffer_base:x} buffer_alignment={buffer_alignment} \
         buffer_stride={buffer_stride} buffer_map_len={buffer_map_len} \
         memory_policy={memory_policy} seconds={seconds:.6} ops_per_sec={:.0} MiBps={:.2}",
        target.label(),
        buffer_mode.as_str(),
        io_slots::submission_backend_label(),
        ops as f64 / seconds,
        total_bytes as f64 / (1024.0 * 1024.0) / seconds
    );
    Ok(())
}

fn slot_wal_sharded_bench(
    target_arg: &str,
    workers: usize,
    bytes_per_worker: usize,
    chunk_bytes: usize,
    pipeline: usize,
    ring_entries: u32,
    mode: SlotWalMode,
    buffer_mode: SlotWalBufferMode,
    pin_workers: bool,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    validate_slot_wal_pipeline(pipeline, ring_entries)?;
    ensure_sector_aligned(bytes_per_worker, "bytes-per-worker")?;
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    if bytes_per_worker % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "bytes-per-worker must be an exact multiple of chunk-bytes",
        ));
    }
    let total_bytes = bytes_per_worker.checked_mul(workers).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "aggregate byte count overflow")
    })?;
    let (target, device_bytes, required_alignment, segment_bytes) =
        validate_slot_wal_common(target_arg, total_bytes, chunk_bytes, mode, buffer_mode)?;
    if total_bytes as u64 > device_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("aggregate total-bytes exceeds block device size {device_bytes}"),
        ));
    }
    let regions = make_linear_wal_regions(workers, bytes_per_worker)?;
    validate_wal_regions(&regions, device_bytes)?;
    for region in &regions {
        println!(
            "slot-wal-sharded-region: worker={} base_offset={} len_bytes={} end_offset={}",
            region.worker,
            region.base_offset,
            region.len_bytes,
            region.end_offset()?
        );
    }

    let started = Instant::now();
    let mut handles = Vec::with_capacity(workers);
    for region in regions {
        let target = target.clone();
        handles.push(thread::spawn(move || {
            slot_wal_bench_worker(
                target,
                region.worker,
                region.base_offset,
                region.len_bytes,
                chunk_bytes,
                pipeline,
                ring_entries,
                mode,
                buffer_mode,
                pin_workers,
            )
        }));
    }

    let mut results = Vec::with_capacity(workers);
    for handle in handles {
        results.push(
            handle
                .join()
                .map_err(|_| io::Error::other("slot WAL worker thread panicked"))??,
        );
    }
    results.sort_by_key(|result| result.worker);

    let wall = started.elapsed();
    let wall_seconds = wall.as_secs_f64().max(f64::MIN_POSITIVE);
    let total_ops: usize = results.iter().map(|result| result.ops).sum();
    let total_bytes: usize = results.iter().map(|result| result.bytes).sum();
    let slowest = results
        .iter()
        .map(|result| result.elapsed)
        .max()
        .unwrap_or_default()
        .as_secs_f64()
        .max(f64::MIN_POSITIVE);
    for result in &results {
        println!(
            "slot-wal-sharded-worker: worker={} bytes={} ops={} seconds={:.6} \
             ops_per_sec={:.0} base_offset={} region_bytes={} slots={} \
             completion_batch={} target_cpu={} affinity_applied={} local_cpu={} worker_numa_node={} \
             buffer_mode={} segment_bytes={} buffer_base=0x{:x} \
             buffer_alignment={} buffer_stride={} buffer_map_len={} memory_policy={}",
            result.worker,
            result.bytes,
            result.ops,
            result.elapsed.as_secs_f64(),
            result.ops as f64 / result.elapsed.as_secs_f64().max(f64::MIN_POSITIVE),
            result.base_offset,
            result.region_bytes,
            result.slot_count,
            result.completion_batch,
            result.target_cpu,
            result.affinity_applied,
            result.local_cpu,
            option_i32_label(result.worker_numa_node),
            result.buffer_mode.as_str(),
            result.segment_bytes,
            result.buffer_base,
            result.buffer_alignment,
            result.buffer_stride,
            result.buffer_map_len,
            result.memory_policy
        );
    }
    println!(
        "slot-wal-sharded-bench: target={} mode={} workers={workers} \
         bytes_per_worker={bytes_per_worker} total_bytes={total_bytes} \
         chunk_bytes={chunk_bytes} ops={total_ops} pipeline_per_worker={pipeline} \
         total_pipeline={} completion_batch={} ring_entries={ring_entries} buffers={} \
         segment_bytes={segment_bytes} required_alignment={required_alignment} \
         slot_backend={} \
         pin_workers={pin_workers} wall_seconds={wall_seconds:.6} \
         slowest_worker_seconds={slowest:.6} MiBps={:.2} ops_per_sec={:.0}",
        target.label(),
        mode.as_str(),
        pipeline * workers,
        results
            .first()
            .map(|result| result.completion_batch)
            .unwrap_or(1),
        buffer_mode.as_str(),
        io_slots::submission_backend_label(),
        total_bytes as f64 / (1024.0 * 1024.0) / wall_seconds,
        total_ops as f64 / wall_seconds
    );
    Ok(())
}

fn slot_topology_plan(
    target_arg: &str,
    workers: usize,
    bytes_per_worker: usize,
    chunk_bytes: usize,
    pipeline: usize,
    buffer_mode: SlotWalBufferMode,
) -> io::Result<()> {
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "workers must be non-zero",
        ));
    }
    if pipeline == 0 || pipeline > u16::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("pipeline must be between 1 and {}", u16::MAX),
        ));
    }
    ensure_sector_aligned(bytes_per_worker, "bytes-per-worker")?;
    ensure_sector_aligned(chunk_bytes, "chunk-bytes")?;
    if bytes_per_worker % chunk_bytes != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "bytes-per-worker must be an exact multiple of chunk-bytes",
        ));
    }
    let total_bytes = bytes_per_worker.checked_mul(workers).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "aggregate byte count overflow")
    })?;
    let (target, metadata, device_bytes, required_alignment, segment_bytes) =
        validate_slot_wal_plan_common(target_arg, total_bytes, chunk_bytes, buffer_mode)?;
    let topology = BlockDeviceTopology::from_metadata(&metadata)?;
    let regions = make_linear_wal_regions(workers, bytes_per_worker)?;
    validate_wal_regions(&regions, device_bytes)?;
    let env_pin = env_truthy("URING_PLAY_PIN_CPUS");
    let numa_mismatches = regions
        .iter()
        .filter(|region| {
            let cpu = topology.planned_cpu(region.worker);
            topology.device_numa_node.is_some()
                && cpu_numa_node(cpu).is_some()
                && cpu_numa_node(cpu) != topology.device_numa_node
        })
        .count();

    println!(
        "slot-topology-plan: target={} device_bytes={} block_sysfs={} disk_sysfs={} \
         queue_count={} device_numa_node={} workers={workers} \
         bytes_per_worker={bytes_per_worker} total_bytes={total_bytes} \
         chunk_bytes={chunk_bytes} pipeline_per_worker={pipeline} total_slots={} \
         buffer_mode={} segment_bytes={segment_bytes} required_alignment={required_alignment} \
         pin_env={} numa_mismatches={}",
        target.label(),
        device_bytes,
        topology.block_dir.display(),
        topology.disk_dir.display(),
        topology.queues.len(),
        option_i32_label(topology.device_numa_node),
        pipeline * workers,
        buffer_mode.as_str(),
        env_pin,
        numa_mismatches
    );
    for queue in &topology.queues {
        println!(
            "slot-topology-queue: queue={} cpus={}",
            queue.index,
            format_cpu_list(&queue.cpus)
        );
    }
    for region in &regions {
        let cpu = topology.planned_cpu(region.worker);
        let queue = topology.queue_for_cpu(region.worker, cpu);
        let cpu_numa = cpu_numa_node(cpu);
        let end_offset = region.end_offset()?;
        let numa_local = topology.device_numa_node.is_none()
            || cpu_numa.is_none()
            || topology.device_numa_node == cpu_numa;
        println!(
            "slot-topology-worker: worker={} cpu={} cpu_numa_node={} \
             nvme_queue={} queue_cpus={} ring={} slots={} region_base={} \
             region_len={} region_end={} numa_local={}",
            region.worker,
            cpu,
            option_i32_label(cpu_numa),
            queue.index,
            format_cpu_list(&queue.cpus),
            region.worker,
            pipeline,
            region.base_offset,
            region.len_bytes,
            end_offset,
            numa_local
        );
    }

    Ok(())
}

fn parse_u8_arg(value: &str) -> Result<u8, std::num::ParseIntError> {
    if let Some(hex) = value
        .strip_prefix("0x")
        .or_else(|| value.strip_prefix("0X"))
    {
        u8::from_str_radix(hex, 16)
    } else {
        value.parse::<u8>()
    }
}

fn set_env_for_command(name: &str, value: impl AsRef<str>) {
    // zcutils mutates process env only during single-threaded command setup.
    unsafe { env::set_var(name, value.as_ref()) };
}

fn next_flag_value<I>(args: &mut I, flag: &str) -> io::Result<String>
where
    I: Iterator<Item = String>,
{
    args.next().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{flag} requires a value"),
        )
    })
}

fn parse_usize_value(value: &str, name: &str) -> io::Result<usize> {
    value.parse::<usize>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name}={value:?} is invalid: {err}"),
        )
    })
}

fn parse_u16_value(value: &str, name: &str) -> io::Result<u16> {
    value.parse::<u16>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name}={value:?} is invalid: {err}"),
        )
    })
}

fn parse_u32_value(value: &str, name: &str) -> io::Result<u32> {
    value.parse::<u32>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name}={value:?} is invalid: {err}"),
        )
    })
}

fn parse_u64_value(value: &str, name: &str) -> io::Result<u64> {
    value.parse::<u64>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name}={value:?} is invalid: {err}"),
        )
    })
}

fn parse_i32_value(value: &str, name: &str) -> io::Result<i32> {
    value.parse::<i32>().map_err(|err| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{name}={value:?} is invalid: {err}"),
        )
    })
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ZcRecvMode {
    Recv,
    Zcrx,
    Auto,
}

impl ZcRecvMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "recv" | "normal" => Ok(Self::Recv),
            "zcrx" | "recv-zc" | "zero-copy-rx" => Ok(Self::Zcrx),
            "auto" | "auto-zcrx" | "zero-copy-auto" => Ok(Self::Auto),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown receive mode {other:?}; use recv, zcrx, or auto"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Recv => "recv",
            Self::Zcrx => "zcrx",
            Self::Auto => "auto",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ZcZeroCopyPolicy {
    Required,
    Auto,
    Off,
}

impl ZcZeroCopyPolicy {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "required" | "require" | "on" | "yes" | "true" | "1" | "zero-copy" | "zc" => {
                Ok(Self::Required)
            }
            "auto" | "try" | "fallback" => Ok(Self::Auto),
            "off" | "no" | "false" | "0" | "copy" | "copied" | "recv" | "send" => Ok(Self::Off),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown zero-copy policy {other:?}; use required, auto, or off"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Required => "required",
            Self::Auto => "auto",
            Self::Off => "off",
        }
    }

    fn apply_to_recv(self, recv: &mut ZcRecvOptions) {
        match self {
            Self::Required => {
                if recv.mode == ZcRecvMode::Recv {
                    recv.mode = ZcRecvMode::Auto;
                }
                recv.must_zero_copy = true;
            }
            Self::Auto => {
                recv.mode = ZcRecvMode::Auto;
                recv.must_zero_copy = false;
            }
            Self::Off => {
                recv.mode = ZcRecvMode::Recv;
                recv.must_zero_copy = false;
            }
        }
    }

    fn send_mode(self) -> UringSendMode {
        match self {
            Self::Required | Self::Auto => UringSendMode::SendZc,
            Self::Off => UringSendMode::Send,
        }
    }
}

struct ZcRecvOptions {
    mode: ZcRecvMode,
    ifname: Option<String>,
    rxq: u32,
    rxq_count: Option<usize>,
    must_zero_copy: bool,
}

impl ZcRecvOptions {
    fn zero_copy_policy(&self) -> ZcZeroCopyPolicy {
        if self.mode == ZcRecvMode::Recv {
            ZcZeroCopyPolicy::Off
        } else if self.must_zero_copy {
            ZcZeroCopyPolicy::Required
        } else {
            ZcZeroCopyPolicy::Auto
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ZcPrimitiveDescriptorMode {
    Auto,
    Bytes,
}

impl ZcPrimitiveDescriptorMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "auto" => Ok(Self::Auto),
            "bytes" | "byte" | "compat" | "byte-compatible" => Ok(Self::Bytes),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown descriptor mode {other:?}; use auto or bytes"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Bytes => "bytes",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ZcPrimitiveOrdering {
    Global,
    PerLane,
}

impl ZcPrimitiveOrdering {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "global" => Ok(Self::Global),
            "per-lane" | "lane" | "lanes" => Ok(Self::PerLane),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown ordering {other:?}; use global or per-lane"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Global => "global",
            Self::PerLane => "per-lane",
        }
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct ZcPrimitiveAppliedTopology {
    target_cpu: i32,
    affinity_applied: bool,
    start_cpu: i32,
    end_cpu: i32,
    target_numa_node: Option<i32>,
    end_numa_node: Option<i32>,
}

impl ZcPrimitiveAppliedTopology {
    fn log_fields(self) -> String {
        format!(
            "topology_target_cpu={} topology_affinity_applied={} topology_start_cpu={} topology_end_cpu={} topology_target_numa_node={} topology_end_numa_node={}",
            self.target_cpu,
            yes(self.affinity_applied),
            self.start_cpu,
            self.end_cpu,
            ZcPrimitiveTopology::option_i32_label(self.target_numa_node),
            ZcPrimitiveTopology::option_i32_label(self.end_numa_node)
        )
    }
}

#[derive(Clone)]
struct ZcPrimitiveTopology {
    descriptor_mode: ZcPrimitiveDescriptorMode,
    zero_copy: ZcZeroCopyPolicy,
    preserve_lanes: bool,
    preserve_topology: bool,
    ordered: ZcPrimitiveOrdering,
    topology: Option<String>,
    lane_id: Option<u64>,
    lane_count: Option<u64>,
    queue_id: Option<u64>,
    preferred_worker: Option<u64>,
    lane_map: Option<String>,
    preferred_cpu: Option<usize>,
    numa_node: Option<i32>,
}

impl Default for ZcPrimitiveTopology {
    fn default() -> Self {
        Self {
            descriptor_mode: ZcPrimitiveDescriptorMode::Auto,
            zero_copy: ZcZeroCopyPolicy::Auto,
            preserve_lanes: false,
            preserve_topology: false,
            ordered: ZcPrimitiveOrdering::Global,
            topology: None,
            lane_id: None,
            lane_count: None,
            queue_id: None,
            preferred_worker: None,
            lane_map: None,
            preferred_cpu: None,
            numa_node: None,
        }
    }
}

impl ZcPrimitiveTopology {
    fn with_ordered(ordered: ZcPrimitiveOrdering) -> Self {
        Self {
            ordered,
            ..Self::default()
        }
    }

    fn parse_common_flag<I>(&mut self, args: &mut I, arg: &str) -> io::Result<bool>
    where
        I: Iterator<Item = String>,
    {
        match arg {
            "--descriptor-mode" => {
                self.descriptor_mode =
                    ZcPrimitiveDescriptorMode::parse(&next_flag_value(args, arg)?)?;
                Ok(true)
            }
            "--zero-copy" | "--zero-copy-primitives" | "--zero-copy-descriptors" => {
                self.zero_copy = ZcZeroCopyPolicy::parse(&next_flag_value(args, arg)?)?;
                Ok(true)
            }
            "--must-zero-copy" => {
                self.zero_copy = ZcZeroCopyPolicy::Required;
                Ok(true)
            }
            "--preserve-lanes" => {
                self.preserve_lanes = true;
                Ok(true)
            }
            "--preserve-topology" => {
                self.preserve_lanes = true;
                self.preserve_topology = true;
                Ok(true)
            }
            "--topology" => {
                self.topology = Some(next_flag_value(args, arg)?);
                Ok(true)
            }
            "--ordered" => {
                self.ordered = ZcPrimitiveOrdering::parse(&next_flag_value(args, arg)?)?;
                Ok(true)
            }
            "--lane-id" => {
                self.lane_id = Some(parse_u64_value(&next_flag_value(args, arg)?, arg)?);
                Ok(true)
            }
            "--lane-count" => {
                self.lane_count = Some(parse_u64_value(&next_flag_value(args, arg)?, arg)?);
                Ok(true)
            }
            "--queue-id" => {
                self.queue_id = Some(parse_u64_value(&next_flag_value(args, arg)?, arg)?);
                Ok(true)
            }
            "--preferred-worker" | "--worker-id" => {
                self.preferred_worker = Some(parse_u64_value(&next_flag_value(args, arg)?, arg)?);
                Ok(true)
            }
            "--lane-map" => {
                self.lane_map = Some(next_flag_value(args, arg)?);
                Ok(true)
            }
            "--preferred-cpu" => {
                self.preferred_cpu = Some(parse_usize_value(&next_flag_value(args, arg)?, arg)?);
                Ok(true)
            }
            "--numa-node" => {
                self.numa_node = Some(parse_i32_value(&next_flag_value(args, arg)?, arg)?);
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    fn validate_lane_bounds(&self, label: &str) -> io::Result<()> {
        if let Some(lane_count) = self.lane_count
            && lane_count == 0
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("{label} lane-count must be greater than zero"),
            ));
        }
        if let (Some(lane_id), Some(lane_count)) = (self.lane_id, self.lane_count)
            && lane_id >= lane_count
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("{label} lane-id={lane_id} must be less than lane-count={lane_count}"),
            ));
        }
        Ok(())
    }

    fn ensure_byte_compatible_zero_copy(&self, label: &str) -> io::Result<()> {
        if self.zero_copy == ZcZeroCopyPolicy::Required {
            return Err(io::Error::new(
                io::ErrorKind::Unsupported,
                format!(
                    "{label} --must-zero-copy requires descriptor-native transport; the current primitive path is byte-compatible"
                ),
            ));
        }
        Ok(())
    }

    fn lane_index(&self) -> usize {
        self.lane_id
            .or(self.queue_id)
            .and_then(|value| usize::try_from(value).ok())
            .unwrap_or(0)
    }

    fn effective_preferred_worker(&self) -> Option<u64> {
        self.preferred_worker.or(self.lane_id).or(self.queue_id)
    }

    fn first_cpu_for_numa_node(numa_node: i32) -> Option<usize> {
        if numa_node < 0 {
            return None;
        }
        let cpulist =
            read_trimmed_path(format!("/sys/devices/system/node/node{numa_node}/cpulist"))?;
        parse_cpu_list(&cpulist)
            .ok()?
            .into_iter()
            .find(|cpu| cpu_online(*cpu))
    }

    fn target_cpu(&self) -> Option<usize> {
        self.preferred_cpu
            .or_else(|| self.numa_node.and_then(Self::first_cpu_for_numa_node))
    }

    fn activate_topology_only(&self, label: &str) -> io::Result<ZcPrimitiveAppliedTopology> {
        self.validate_lane_bounds(label)?;

        let start_cpu = current_cpu();
        let target_cpu = self.target_cpu();
        let target_numa_node = target_cpu.and_then(cpu_numa_node).or(self.numa_node);
        let mut target_cpu_label = -1;
        let mut affinity_applied = false;

        if let Some(cpu) = target_cpu {
            target_cpu_label = i32::try_from(cpu).unwrap_or(i32::MAX);
            match set_current_thread_affinity(cpu) {
                Ok(()) => affinity_applied = true,
                Err(err) => eprintln!(
                    "{label}-topology-apply: target_cpu={cpu} status=error error={err} {}",
                    self.log_fields()
                ),
            }
        } else if self.numa_node.is_some() {
            eprintln!(
                "{label}-topology-apply: target_cpu=-1 status=no-cpu-for-numa {}",
                self.log_fields()
            );
        }

        let end_cpu = current_cpu();
        let end_numa_node = (end_cpu >= 0)
            .then_some(end_cpu as usize)
            .and_then(cpu_numa_node);
        let applied = ZcPrimitiveAppliedTopology {
            target_cpu: target_cpu_label,
            affinity_applied,
            start_cpu,
            end_cpu,
            target_numa_node,
            end_numa_node,
        };

        if target_cpu.is_some()
            || self.topology.is_some()
            || self.preserve_lanes
            || self.preserve_topology
            || self.lane_id.is_some()
            || self.lane_count.is_some()
            || self.queue_id.is_some()
            || self.preferred_worker.is_some()
            || self.lane_map.is_some()
        {
            eprintln!(
                "{label}-topology: {} {}",
                self.log_fields(),
                applied.log_fields()
            );
        }

        Ok(applied)
    }

    fn activate_byte_compatible(&self, label: &str) -> io::Result<ZcPrimitiveAppliedTopology> {
        self.ensure_byte_compatible_zero_copy(label)?;
        self.activate_topology_only(label)
    }

    fn child_env_pairs(&self) -> Vec<(&'static str, String)> {
        let mut pairs = vec![
            (
                "ZC_DESCRIPTOR_MODE",
                self.descriptor_mode.label().to_string(),
            ),
            ("ZC_ZERO_COPY", self.zero_copy.label().to_string()),
            ("ZC_PRESERVE_LANES", yes(self.preserve_lanes).to_string()),
            (
                "ZC_PRESERVE_TOPOLOGY",
                yes(self.preserve_topology).to_string(),
            ),
            ("ZC_ORDERED", self.ordered.label().to_string()),
            ("ZC_LANE_INDEX", self.lane_index().to_string()),
        ];
        if let Some(topology) = self.topology.as_ref() {
            pairs.push(("ZC_TOPOLOGY", topology.clone()));
        }
        if let Some(lane_id) = self.lane_id {
            pairs.push(("ZC_LANE_ID", lane_id.to_string()));
        }
        if let Some(lane_count) = self.lane_count {
            pairs.push(("ZC_LANE_COUNT", lane_count.to_string()));
        }
        if let Some(queue_id) = self.queue_id {
            pairs.push(("ZC_QUEUE_ID", queue_id.to_string()));
        }
        if let Some(preferred_worker) = self.effective_preferred_worker() {
            pairs.push(("ZC_PREFERRED_WORKER", preferred_worker.to_string()));
        }
        if let Some(lane_map) = self.lane_map.as_ref() {
            pairs.push(("ZC_LANE_MAP", lane_map.clone()));
        }
        if let Some(preferred_cpu) = self.preferred_cpu {
            pairs.push(("ZC_PREFERRED_CPU", preferred_cpu.to_string()));
        }
        if let Some(numa_node) = self.numa_node {
            pairs.push(("ZC_NUMA_NODE", numa_node.to_string()));
        }
        pairs
    }

    fn apply_child_env(&self, command: &mut Command) {
        for (key, value) in self.child_env_pairs() {
            command.env(key, value);
        }
    }

    fn topology_label(&self) -> &str {
        self.topology.as_deref().unwrap_or("-")
    }

    fn option_u64_label(value: Option<u64>) -> String {
        value
            .map(|value| value.to_string())
            .unwrap_or_else(|| "-".to_string())
    }

    fn option_usize_label(value: Option<usize>) -> String {
        value
            .map(|value| value.to_string())
            .unwrap_or_else(|| "-".to_string())
    }

    fn option_i32_label(value: Option<i32>) -> String {
        value
            .map(|value| value.to_string())
            .unwrap_or_else(|| "-".to_string())
    }

    fn log_fields(&self) -> String {
        format!(
            "descriptor_mode={} zero_copy={} preserve_lanes={} preserve_topology={} topology={} lane_id={} lane_count={} queue_id={} preferred_worker={} lane_map={} preferred_cpu={} numa_node={} ordered={}",
            self.descriptor_mode.label(),
            self.zero_copy.label(),
            yes(self.preserve_lanes),
            yes(self.preserve_topology),
            self.topology_label(),
            Self::option_u64_label(self.lane_id),
            Self::option_u64_label(self.lane_count),
            Self::option_u64_label(self.queue_id),
            Self::option_u64_label(self.effective_preferred_worker()),
            self.lane_map.as_deref().unwrap_or("-"),
            Self::option_usize_label(self.preferred_cpu),
            Self::option_i32_label(self.numa_node),
            self.ordered.label()
        )
    }
}

fn netdev_driver_name(ifname: &str) -> Option<String> {
    let path = format!("/sys/class/net/{ifname}/device/driver");
    fs::read_link(path).ok().and_then(|target| {
        target
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
    })
}

fn sorted_netdev_names() -> io::Result<Vec<String>> {
    let mut names = Vec::new();
    for entry in fs::read_dir("/sys/class/net")? {
        let entry = entry?;
        if let Some(name) = entry.file_name().to_str() {
            names.push(name.to_string());
        }
    }
    names.sort();
    Ok(names)
}

fn default_zcrx_ifname() -> io::Result<String> {
    for env_name in ["ZCUTILS_ZCRX_IFNAME", "URING_PLAY_ZCRX_IFNAME"] {
        if let Ok(value) = env::var(env_name) {
            let value = value.trim();
            if !value.is_empty() {
                return Ok(value.to_string());
            }
        }
    }

    let names = sorted_netdev_names()?;
    for name in &names {
        if netdev_driver_name(name).as_deref() == Some("ena") {
            return Ok(name.clone());
        }
    }
    for name in &names {
        if name != "lo" && netdev_driver_name(name).is_some() {
            return Ok(name.clone());
        }
    }
    names.into_iter().find(|name| name != "lo").ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::NotFound,
            "could not discover a non-loopback interface for ZCRX; pass --ifname",
        )
    })
}

fn netdev_rx_queue_count(ifname: &str) -> io::Result<usize> {
    let mut count = 0usize;
    let path = format!("/sys/class/net/{ifname}/queues");
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        if entry
            .file_name()
            .to_str()
            .map(|name| name.starts_with("rx-"))
            .unwrap_or(false)
        {
            count += 1;
        }
    }
    Ok(count.max(1))
}

#[allow(clippy::too_many_arguments)]
fn tcp_bench_uring_mux_server_auto_zcrx(
    bind: &str,
    base_port: u16,
    ports: usize,
    connections_per_port: usize,
    expected_bytes: usize,
    workers: usize,
    recv_bytes: usize,
    ring_entries: u32,
    recv_options: ZcRecvOptions,
) -> io::Result<()> {
    if recv_options.mode == ZcRecvMode::Recv {
        if recv_options.must_zero_copy {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "--must-zero-copy requires --recv-mode auto or --recv-mode zcrx",
            ));
        }
        return tcp_bench_uring_mux_server(
            bind,
            base_port,
            ports,
            connections_per_port,
            expected_bytes,
            workers,
            recv_bytes,
            ring_entries,
        );
    }

    let must_zero_copy = recv_options.must_zero_copy || recv_options.mode == ZcRecvMode::Zcrx;
    let ifname = match recv_options.ifname {
        Some(ifname) => ifname,
        None => match default_zcrx_ifname() {
            Ok(ifname) => ifname,
            Err(err) if !must_zero_copy => {
                eprintln!(
                    "zcdemux-zcrx-auto: interface discovery failed: {err}; falling back to recv"
                );
                return tcp_bench_uring_mux_server(
                    bind,
                    base_port,
                    ports,
                    connections_per_port,
                    expected_bytes,
                    workers,
                    recv_bytes,
                    ring_entries,
                );
            }
            Err(err) => return Err(err),
        },
    };
    let estimated_workers = if workers == 0 { ports.max(1) } else { workers };
    let discovered_rxq_count = netdev_rx_queue_count(&ifname).unwrap_or(estimated_workers.max(1));
    let rxq_count = recv_options
        .rxq_count
        .unwrap_or_else(|| discovered_rxq_count.min(estimated_workers.max(1)).max(1))
        .max(1);
    println!(
        "zcdemux-zcrx-auto: mode={} must_zero_copy={} ifname={ifname} rxq={} \
         rxq_count={rxq_count} discovered_rxq_count={discovered_rxq_count}",
        recv_options.mode.label(),
        yes(must_zero_copy),
        recv_options.rxq
    );

    match tcp_bench_uring_zcrx_mux_server(
        &ifname,
        recv_options.rxq,
        rxq_count,
        bind,
        base_port,
        ports,
        connections_per_port,
        expected_bytes,
        recv_bytes,
        ring_entries,
    ) {
        Ok(()) => Ok(()),
        Err(err) if !must_zero_copy => {
            eprintln!("zcdemux-zcrx-auto: ZCRX unavailable ({err}); falling back to recv");
            tcp_bench_uring_mux_server(
                bind,
                base_port,
                ports,
                connections_per_port,
                expected_bytes,
                workers,
                recv_bytes,
                ring_entries,
            )
        }
        Err(err) => Err(io::Error::new(
            err.kind(),
            format!("zero-copy receive is required but ZCRX setup failed: {err}"),
        )),
    }
}

fn parse_legacy_recv_tail(
    tail: Vec<String>,
    default_mode: ZcRecvMode,
) -> io::Result<ZcRecvOptions> {
    let mut index = 0usize;
    let mut mode = default_mode;
    let mut explicit_mode = false;
    let mut must_zero_copy = default_mode == ZcRecvMode::Zcrx;

    if tail
        .get(index)
        .map(|value| !value.starts_with("--"))
        .unwrap_or(false)
    {
        mode = ZcRecvMode::parse(&tail[index])?;
        explicit_mode = true;
        must_zero_copy = mode == ZcRecvMode::Zcrx;
        index += 1;
    }

    let mut ifname = None;
    let mut rxq = 0u32;
    let mut rxq_count = None;
    if mode != ZcRecvMode::Recv {
        if tail
            .get(index)
            .map(|value| !value.starts_with("--"))
            .unwrap_or(false)
        {
            ifname = Some(tail[index].clone());
            index += 1;
        }
        if tail
            .get(index)
            .map(|value| !value.starts_with("--"))
            .unwrap_or(false)
        {
            rxq = parse_u32_value(&tail[index], "rxq")?;
            index += 1;
        }
        if tail
            .get(index)
            .map(|value| !value.starts_with("--"))
            .unwrap_or(false)
        {
            rxq_count = Some(parse_usize_value(&tail[index], "rxq-count")?);
            index += 1;
        }
    }

    while index < tail.len() {
        match tail[index].as_str() {
            "--must-zero-copy" => {
                must_zero_copy = true;
                index += 1;
            }
            "--zero-copy-receive" | "--zero-copy" => {
                let policy_value = tail.get(index + 1).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--zero-copy-receive requires required, auto, or off",
                    )
                })?;
                let policy = ZcZeroCopyPolicy::parse(policy_value)?;
                let mut recv = ZcRecvOptions {
                    mode,
                    ifname: ifname.clone(),
                    rxq,
                    rxq_count,
                    must_zero_copy,
                };
                policy.apply_to_recv(&mut recv);
                mode = recv.mode;
                must_zero_copy = recv.must_zero_copy;
                index += 2;
            }
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown receive option {other:?}"),
                ));
            }
        }
    }
    if must_zero_copy && !explicit_mode && mode == ZcRecvMode::Recv {
        mode = ZcRecvMode::Auto;
    }
    Ok(ZcRecvOptions {
        mode,
        ifname,
        rxq,
        rxq_count,
        must_zero_copy,
    })
}

