struct ZcTcpmuxParallelStats {
    bytes: u64,
    chunks: u64,
    max_end: u64,
    topology: Option<ZcTcpmuxTopologyHint>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ZcTcpmuxReceiveAssembly {
    Direct,
    Ordered,
    Shards,
}

impl ZcTcpmuxReceiveAssembly {
    fn parse(value: &str, flag: &str) -> io::Result<Self> {
        match value {
            "direct" | "pwrite" | "parallel" => Ok(Self::Direct),
            "ordered" | "sequential" | "reorder" => Ok(Self::Ordered),
            "shards" | "shard-files" | "per-lane" | "per-worker" => Ok(Self::Shards),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("{flag} must be direct, ordered, or shards, got {other:?}"),
            )),
        }
    }

    fn as_arg(self) -> &'static str {
        match self {
            Self::Direct => "direct",
            Self::Ordered => "ordered",
            Self::Shards => "shards",
        }
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct ZcTcpmuxTopologyHint {
    lane_id: u32,
    lane_count: u32,
    preferred_worker: u32,
    queue_id: u32,
    preferred_cpu: i32,
    numa_node: i32,
    flags: u32,
    chunk_bytes: u32,
    plan_hash: u64,
    placement_epoch: u64,
}

impl ZcTcpmuxTopologyHint {
    fn legacy(lane_id: u32) -> Self {
        Self {
            lane_id,
            lane_count: 0,
            preferred_worker: lane_id,
            queue_id: lane_id,
            preferred_cpu: -1,
            numa_node: -1,
            flags: 0,
            chunk_bytes: 0,
            plan_hash: 0,
            placement_epoch: 0,
        }
    }

    fn log_fields(self) -> String {
        format!(
            "lane_id={} lane_count={} preferred_worker={} queue_id={} preferred_cpu={} numa_node={} flags=0x{:x} chunk_bytes={} plan_hash=0x{:016x} placement_epoch={}",
            self.lane_id,
            self.lane_count,
            self.preferred_worker,
            self.queue_id,
            self.preferred_cpu,
            self.numa_node,
            self.flags,
            self.chunk_bytes,
            self.plan_hash,
            self.placement_epoch
        )
    }
}

#[derive(Clone, Debug, Default)]
struct ZcTcpmuxAffinityConfig {
    pin_cpus: bool,
    cpu_list: Option<Arc<Vec<usize>>>,
    cpu_list_label: Option<String>,
}

impl ZcTcpmuxAffinityConfig {
    fn from_cli(pin_cpus: bool, cpu_list: Option<&str>, _flag: &str) -> io::Result<Self> {
        let parsed = cpu_list
            .map(parse_cpu_list)
            .transpose()?
            .filter(|cpus| !cpus.is_empty());
        Ok(Self {
            pin_cpus: pin_cpus || parsed.is_some(),
            cpu_list_label: parsed.as_deref().map(format_cpu_list),
            cpu_list: parsed.map(Arc::new),
        })
    }

    fn target_cpu(&self, index: usize) -> Option<usize> {
        if !self.pin_cpus {
            return None;
        }
        if let Some(cpus) = self.cpu_list.as_deref()
            && !cpus.is_empty()
        {
            return Some(cpus[index % cpus.len()]);
        }
        Some(configured_affinity_target_cpu(index))
    }

    fn pin_current_thread(&self, label: &str, index: usize) -> ThreadAffinity {
        let Some(cpu) = self.target_cpu(index) else {
            return ThreadAffinity {
                target_cpu: -1,
                applied: false,
            };
        };
        pin_current_thread_to(label, index, cpu)
    }

    fn describe(&self) -> String {
        format!(
            "pin_cpus={} cpu_list={}",
            self.pin_cpus,
            self.cpu_list_label.as_deref().unwrap_or("-")
        )
    }
}

#[derive(Clone, Debug)]
struct ZcTcpmuxDataPath {
    data_host: String,
    local_data_address: Option<String>,
    receive_listen_address: String,
}

impl ZcTcpmuxDataPath {
    fn log_fields(&self) -> String {
        format!(
            "data_host={} local_data_address={} receive_listen_address={}",
            self.data_host,
            self.local_data_address.as_deref().unwrap_or("-"),
            self.receive_listen_address
        )
    }
}

fn zc_tcpmux_path_index(lane: usize, lanes: usize, path_count: usize) -> usize {
    if path_count <= 1 {
        return 0;
    }
    lane.saturating_mul(path_count) / lanes.max(1)
}

fn zc_tcpmux_path_summary(paths: &[ZcTcpmuxDataPath]) -> String {
    paths
        .iter()
        .enumerate()
        .map(|(index, path)| format!("{index}:{}", path.log_fields()))
        .collect::<Vec<_>>()
        .join(";")
}

fn zc_tcpmux_csv_values(value: &str, flag: &str) -> io::Result<Vec<String>> {
    let values = value
        .split(',')
        .map(str::trim)
        .map(str::to_string)
        .collect::<Vec<_>>();
    if values.is_empty() || values.iter().any(|item| item.is_empty()) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{flag} requires a non-empty comma-separated list"),
        ));
    }
    Ok(values)
}

fn zc_tcpmux_expand_values(
    values: Option<&[String]>,
    single: &str,
    count: usize,
    flag: &str,
) -> io::Result<Vec<String>> {
    match values {
        Some(values) if values.len() == count => Ok(values.to_vec()),
        Some(values) if values.len() == 1 => Ok(vec![values[0].clone(); count]),
        Some(values) => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "{flag} has {} entries but multipath requires 1 or {count}",
                values.len()
            ),
        )),
        None => Ok(vec![single.to_string(); count]),
    }
}

fn zc_tcpmux_expand_optional_values(
    values: Option<&[String]>,
    single: Option<&str>,
    count: usize,
    flag: &str,
) -> io::Result<Vec<Option<String>>> {
    let expanded = match (values, single) {
        (Some(values), _) if values.len() == count => values.to_vec(),
        (Some(values), _) if values.len() == 1 => vec![values[0].clone(); count],
        (Some(values), _) => {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "{flag} has {} entries but multipath requires 1 or {count}",
                    values.len()
                ),
            ));
        }
        (None, Some(single)) => vec![single.to_string(); count],
        (None, None) => return Ok(vec![None; count]),
    };
    expanded
        .into_iter()
        .map(|value| {
            if value == "-" || value.eq_ignore_ascii_case("none") {
                Ok(None)
            } else {
                value.parse::<IpAddr>().map_err(|err| {
                    io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("parse {flag} entry {value:?}: {err}"),
                    )
                })?;
                Ok(Some(value))
            }
        })
        .collect()
}

fn zc_tcpmux_build_data_paths(
    host: &str,
    data_host: Option<&str>,
    data_hosts: Option<&[String]>,
    local_data_address: Option<&str>,
    local_data_addresses: Option<&[String]>,
    receive_listen_address: &str,
    receive_listen_addresses: Option<&[String]>,
    lanes: usize,
) -> io::Result<Vec<ZcTcpmuxDataPath>> {
    let path_count = [
        data_hosts.map(|values| values.len()).unwrap_or(1),
        local_data_addresses
            .map(|values| values.len())
            .unwrap_or_else(|| usize::from(local_data_address.is_some()).max(1)),
        receive_listen_addresses
            .map(|values| values.len())
            .unwrap_or(1),
    ]
    .into_iter()
    .max()
    .unwrap_or(1);
    if path_count == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "multipath requires at least one path",
        ));
    }
    if path_count > lanes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("multipath has {path_count} paths but only {lanes} lanes"),
        ));
    }

    let data_hosts = zc_tcpmux_expand_values(
        data_hosts,
        data_host.unwrap_or(host),
        path_count,
        "--data-hosts",
    )?;
    let local_data_addresses = zc_tcpmux_expand_optional_values(
        local_data_addresses,
        local_data_address,
        path_count,
        "--local-data-addresses",
    )?;
    let receive_listen_addresses = zc_tcpmux_expand_values(
        receive_listen_addresses,
        receive_listen_address,
        path_count,
        "--receive-listen-addresses",
    )?;
    Ok(data_hosts
        .into_iter()
        .zip(local_data_addresses)
        .zip(receive_listen_addresses)
        .map(
            |((data_host, local_data_address), receive_listen_address)| ZcTcpmuxDataPath {
                data_host,
                local_data_address,
                receive_listen_address,
            },
        )
        .collect())
}

fn current_cpu_usize() -> Option<usize> {
    let cpu = current_cpu();
    (cpu >= 0).then_some(cpu as usize)
}

fn zc_tcpmux_topology_hint(
    lane: usize,
    lanes: usize,
    chunk_bytes: usize,
    affinity: ThreadAffinity,
) -> io::Result<ZcTcpmuxTopologyHint> {
    let lane_id = u32::try_from(lane)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "lane id exceeds u32 range"))?;
    let lane_count = u32::try_from(lanes)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "lane count exceeds u32 range"))?;
    let chunk_bytes = u32::try_from(chunk_bytes).unwrap_or(u32::MAX);
    let actual_cpu = current_cpu_usize().map(|cpu| cpu as i32);
    let preferred_cpu = actual_cpu
        .or_else(|| affinity.applied.then_some(affinity.target_cpu))
        .unwrap_or(-1);
    let numa_node = if preferred_cpu >= 0 {
        cpu_numa_node(preferred_cpu as usize).unwrap_or(-1)
    } else {
        -1
    };
    let mut flags = 0u32;
    let plan = zc_plan_runtime_from_env()?;
    if affinity.applied {
        flags |= ZC_TCPMUX_TOPOLOGY_F_AFFINITY_APPLIED;
    }
    if preferred_cpu >= 0 {
        flags |= ZC_TCPMUX_TOPOLOGY_F_CPU_KNOWN;
    }
    if numa_node >= 0 {
        flags |= ZC_TCPMUX_TOPOLOGY_F_NUMA_KNOWN;
    }
    Ok(ZcTcpmuxTopologyHint {
        lane_id,
        lane_count,
        preferred_worker: lane_id,
        queue_id: lane_id,
        preferred_cpu,
        numa_node,
        flags,
        chunk_bytes,
        plan_hash: plan.plan_hash,
        placement_epoch: plan.placement_epoch,
    })
}

fn zc_read_coalesced_chunk<R: Read>(reader: &mut R, chunk_bytes: usize) -> io::Result<Vec<u8>> {
    let mut data = vec![0u8; chunk_bytes.max(4096)];
    let mut filled = 0usize;
    while filled < data.len() {
        match reader.read(&mut data[filled..]) {
            Ok(0) => break,
            Ok(n) => filled += n,
            Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        }
    }
    data.truncate(filled);
    Ok(data)
}

fn zc_write_all_at(file: &fs::File, mut buf: &[u8], mut offset: u64) -> io::Result<()> {
    while !buf.is_empty() {
        let n = file.write_at(buf, offset)?;
        if n == 0 {
            return Err(io::Error::new(
                io::ErrorKind::WriteZero,
                "write_at wrote zero bytes",
            ));
        }
        buf = &buf[n..];
        offset = offset.checked_add(n as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "write_at offset overflow")
        })?;
    }
    Ok(())
}

fn zc_tcpmux_open_output_path(path: &Path, label: &str) -> io::Result<(fs::File, bool)> {
    let is_block = fs::metadata(path)
        .map(|metadata| metadata.file_type().is_block_device())
        .unwrap_or(false);
    let mut options = OpenOptions::new();
    options.write(true);
    if is_block {
        options.read(true);
    } else {
        options.create(true).truncate(true);
    }
    let file = options.open(path).map_err(|err| {
        io::Error::new(
            err.kind(),
            format!("open {label} {}: {err}", path.display()),
        )
    })?;
    Ok((file, is_block))
}

fn zc_tcpmux_write_parallel_header(
    stream: &mut TcpStream,
    topology: ZcTcpmuxTopologyHint,
    nonce_base: &[u8; 12],
) -> io::Result<()> {
    stream.write_all(ZC_TCPMUX_PARALLEL_MAGIC)?;
    stream.write_all(&ZC_TCPMUX_TOPOLOGY_DESC_VERSION.to_be_bytes())?;
    stream.write_all(&ZC_TCPMUX_TOPOLOGY_DESC_EXTENDED_BODY_LEN.to_be_bytes())?;
    stream.write_all(&topology.lane_id.to_be_bytes())?;
    stream.write_all(&topology.lane_count.to_be_bytes())?;
    stream.write_all(&topology.preferred_worker.to_be_bytes())?;
    stream.write_all(&topology.queue_id.to_be_bytes())?;
    stream.write_all(&topology.preferred_cpu.to_be_bytes())?;
    stream.write_all(&topology.numa_node.to_be_bytes())?;
    stream.write_all(&topology.flags.to_be_bytes())?;
    stream.write_all(&topology.chunk_bytes.to_be_bytes())?;
    stream.write_all(nonce_base)?;
    stream.write_all(&topology.plan_hash.to_be_bytes())?;
    stream.write_all(&topology.placement_epoch.to_be_bytes())?;
    Ok(())
}

fn zc_tcpmux_read_parallel_header<R: Read>(
    reader: &mut R,
) -> io::Result<(ZcTcpmuxTopologyHint, [u8; 12])> {
    let mut magic = vec![0u8; ZC_TCPMUX_PARALLEL_MAGIC.len()];
    reader.read_exact(&mut magic)?;
    if magic == ZC_TCPMUX_PARALLEL_MAGIC_V1 {
        let mut lane = [0u8; 4];
        reader.read_exact(&mut lane)?;
        let mut nonce_base = [0u8; 12];
        reader.read_exact(&mut nonce_base)?;
        return Ok((
            ZcTcpmuxTopologyHint::legacy(u32::from_be_bytes(lane)),
            nonce_base,
        ));
    }
    if magic != ZC_TCPMUX_PARALLEL_MAGIC_V2 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "missing zc-tcpmux parallel lane header",
        ));
    }
    let mut version = [0u8; 2];
    let mut body_len = [0u8; 2];
    reader.read_exact(&mut version)?;
    reader.read_exact(&mut body_len)?;
    let version = u16::from_be_bytes(version);
    let body_len = u16::from_be_bytes(body_len);
    if version < ZC_TCPMUX_TOPOLOGY_DESC_VERSION {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("unsupported zc-tcpmux topology version {version}"),
        ));
    }
    if body_len < ZC_TCPMUX_TOPOLOGY_DESC_BODY_LEN {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("short zc-tcpmux topology header body {body_len}"),
        ));
    }
    let mut body = vec![0u8; ZC_TCPMUX_TOPOLOGY_DESC_BODY_LEN as usize];
    reader.read_exact(&mut body)?;
    let mut extension = Vec::new();
    if body_len > ZC_TCPMUX_TOPOLOGY_DESC_BODY_LEN {
        extension.resize((body_len - ZC_TCPMUX_TOPOLOGY_DESC_BODY_LEN) as usize, 0);
        reader.read_exact(&mut extension)?;
    }
    let read_u32 = |start: usize| -> u32 {
        u32::from_be_bytes([
            body[start],
            body[start + 1],
            body[start + 2],
            body[start + 3],
        ])
    };
    let read_i32 = |start: usize| -> i32 {
        i32::from_be_bytes([
            body[start],
            body[start + 1],
            body[start + 2],
            body[start + 3],
        ])
    };
    let topology = ZcTcpmuxTopologyHint {
        lane_id: read_u32(0),
        lane_count: read_u32(4),
        preferred_worker: read_u32(8),
        queue_id: read_u32(12),
        preferred_cpu: read_i32(16),
        numa_node: read_i32(20),
        flags: read_u32(24),
        chunk_bytes: read_u32(28),
        plan_hash: if extension.len() >= 8 {
            u64::from_be_bytes(extension[0..8].try_into().expect("u64"))
        } else {
            0
        },
        placement_epoch: if extension.len() >= 16 {
            u64::from_be_bytes(extension[8..16].try_into().expect("u64"))
        } else {
            0
        },
    };
    let mut nonce_base = [0u8; 12];
    nonce_base.copy_from_slice(&body[32..44]);
    Ok((topology, nonce_base))
}

fn zc_tcpmux_connect_parallel_sender(
    lane: usize,
    lanes: usize,
    chunk_bytes: usize,
    data_host: &str,
    port: u16,
    local_data_address: Option<&str>,
    token: Option<&str>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    affinity: &ZcTcpmuxAffinityConfig,
) -> io::Result<(
    TcpStream,
    ZcTcpmuxTopologyHint,
    [u8; 12],
    Option<ZcAes256Cipher>,
)> {
    let affinity_result = affinity.pin_current_thread("zc-tcpmux-xfer-send-lane", lane);
    let topology = zc_tcpmux_topology_hint(lane, lanes, chunk_bytes, affinity_result)?;
    let mut stream = zc_tcpmux_connect_tcp(
        data_host,
        port,
        local_data_address,
        &format!("connect zc-tcpmux lane {lane}"),
    )?;
    stream.set_nodelay(true)?;
    if let Some(token) = token {
        zc_tcpmux_validate_token(token)?;
        stream.write_all(zc_tcpmux_token_auth_line(token).as_bytes())?;
    }

    let mut nonce_base = [0u8; 12];
    let cipher = if encryption == ZcTcpmuxEncryption::Aes256 && !already_encrypted {
        zc_random_bytes(&mut nonce_base)?;
        Some(zc_aes256_lane_cipher(
            token.ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "AES-256 lane requires --token")
            })?,
            topology.lane_id,
        )?)
    } else {
        None
    };
    zc_tcpmux_write_parallel_header(&mut stream, topology, &nonce_base)?;
    eprintln!(
        "zc-tcpmux-send-lane-topology: lane={lane} {} local_data_address={} affinity={}",
        topology.log_fields(),
        local_data_address.unwrap_or("-"),
        affinity.describe()
    );
    Ok((stream, topology, nonce_base, cipher))
}

fn zc_tcpmux_parallel_write_data_frame(
    stream: &mut TcpStream,
    cipher: Option<&ZcAes256Cipher>,
    lane: usize,
    lane_id: u32,
    nonce_base: &[u8; 12],
    sequence: u64,
    offset: u64,
    data: Vec<u8>,
) -> io::Result<(u32, u64)> {
    let plaintext_len = u32::try_from(data.len()).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel xfer chunk exceeds u32 length",
        )
    })?;
    let payload = if let Some(cipher) = cipher {
        let nonce = zc_aes256_nonce(nonce_base, sequence);
        let aad = zc_aes256_lane_aad(lane_id, sequence, offset, plaintext_len);
        zc_aes256_encrypt_frame(cipher, nonce, &aad, data, || {
            format!("AES-256-GCM lane {lane} encrypt frame {sequence}")
        })?
    } else {
        data
    };
    let payload_len = u32::try_from(payload.len()).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel xfer payload exceeds u32 length",
        )
    })?;
    stream.write_all(&offset.to_be_bytes())?;
    stream.write_all(&plaintext_len.to_be_bytes())?;
    stream.write_all(&payload_len.to_be_bytes())?;
    stream.write_all(&payload)?;
    let end = offset.checked_add(plaintext_len as u64).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidData, "parallel xfer offset overflow")
    })?;
    Ok((plaintext_len, end))
}

fn zc_tcpmux_parallel_write_eof(stream: &mut TcpStream) -> io::Result<()> {
    stream.write_all(&0u64.to_be_bytes())?;
    stream.write_all(&ZC_TCPMUX_PARALLEL_EOF.to_be_bytes())?;
    stream.write_all(&ZC_TCPMUX_PARALLEL_EOF.to_be_bytes())?;
    stream.shutdown(Shutdown::Write)?;
    Ok(())
}

fn zc_tcpmux_parallel_send_worker(
    lane: usize,
    lanes: usize,
    data_host: String,
    port: u16,
    local_data_address: Option<String>,
    token: Option<String>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    chunk_bytes: usize,
    affinity: ZcTcpmuxAffinityConfig,
    rx: mpsc::Receiver<ZcTcpmuxParallelChunk>,
) -> io::Result<ZcTcpmuxParallelStats> {
    let (mut stream, topology, nonce_base, cipher) = zc_tcpmux_connect_parallel_sender(
        lane,
        lanes,
        chunk_bytes,
        &data_host,
        port,
        local_data_address.as_deref(),
        token.as_deref(),
        encryption,
        already_encrypted,
        &affinity,
    )?;

    let mut stats = ZcTcpmuxParallelStats::default();
    stats.topology = Some(topology);
    let mut sequence = 0u64;
    for chunk in rx {
        let (plaintext_len, end) = zc_tcpmux_parallel_write_data_frame(
            &mut stream,
            cipher.as_ref(),
            lane,
            topology.lane_id,
            &nonce_base,
            sequence,
            chunk.offset,
            chunk.data,
        )?;
        stats.bytes = stats
            .bytes
            .checked_add(plaintext_len as u64)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "parallel xfer byte count overflow",
                )
            })?;
        stats.chunks = stats.chunks.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel xfer chunk count overflow",
            )
        })?;
        stats.max_end = stats.max_end.max(end);
        sequence = sequence.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel xfer sequence overflow",
            )
        })?;
    }
    zc_tcpmux_parallel_write_eof(&mut stream)?;
    Ok(stats)
}

fn zc_tcpmux_copy_reader_to_tcp_parallel<R: Read>(
    mut reader: R,
    data_paths: &[ZcTcpmuxDataPath],
    ports: &[u16],
    token: Option<&str>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    chunk_bytes: usize,
    affinity: &ZcTcpmuxAffinityConfig,
) -> io::Result<u64> {
    if ports.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel xfer requires at least one port",
        ));
    }
    if data_paths.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel xfer requires at least one data path",
        ));
    }
    if token.is_none() && encryption.requires_token() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel AES-256 xfer requires --token",
        ));
    }

    let mut senders = Vec::with_capacity(ports.len());
    let mut handles = Vec::with_capacity(ports.len());
    for (lane, port) in ports.iter().copied().enumerate() {
        let (tx, rx) = mpsc::sync_channel::<ZcTcpmuxParallelChunk>(2);
        senders.push(tx);
        let path = data_paths[zc_tcpmux_path_index(lane, ports.len(), data_paths.len())].clone();
        let host = path.data_host;
        let local_data_address = path.local_data_address;
        let token = token.map(str::to_string);
        let affinity = affinity.clone();
        let lanes = ports.len();
        handles.push(thread::spawn(move || {
            zc_tcpmux_parallel_send_worker(
                lane,
                lanes,
                host,
                port,
                local_data_address,
                token,
                encryption,
                already_encrypted,
                chunk_bytes,
                affinity,
                rx,
            )
        }));
    }

    let mut offset = 0u64;
    let mut chunk_index = 0usize;
    let mut total = 0u64;
    loop {
        let data = zc_read_coalesced_chunk(&mut reader, chunk_bytes)?;
        if data.is_empty() {
            break;
        }
        let n = data.len();
        let lane = chunk_index % senders.len();
        senders[lane]
            .send(ZcTcpmuxParallelChunk { offset, data })
            .map_err(|err| {
                io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    format!("parallel xfer lane {lane} worker exited: {err}"),
                )
            })?;
        offset = offset.checked_add(n as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "parallel xfer offset overflow")
        })?;
        total = total.checked_add(n as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel xfer byte count overflow",
            )
        })?;
        chunk_index = chunk_index.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel xfer chunk count overflow",
            )
        })?;
    }
    drop(senders);

    let mut worker_total = 0u64;
    for (lane, handle) in handles.into_iter().enumerate() {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other(format!("parallel send lane {lane} panicked")))??;
        worker_total = worker_total.checked_add(stats.bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel xfer worker total overflow",
            )
        })?;
        eprintln!(
            "zc-tcpmux-xfer-send-lane-result: lane={lane} bytes={} chunks={} max_end={} topology={}",
            stats.bytes,
            stats.chunks,
            stats.max_end,
            stats
                .topology
                .map(ZcTcpmuxTopologyHint::log_fields)
                .unwrap_or_else(|| "-".to_string())
        );
    }
    if worker_total != total {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("parallel xfer byte mismatch reader={total} workers={worker_total}"),
        ));
    }
    Ok(total)
}

fn zc_read_file_chunk_at(file: &fs::File, offset: u64, len: usize) -> io::Result<Vec<u8>> {
    let mut data = vec![0u8; len];
    let mut filled = 0usize;
    while filled < data.len() {
        let read_offset = offset.checked_add(filled as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel file read offset overflow",
            )
        })?;
        match file.read_at(&mut data[filled..], read_offset) {
            Ok(0) => break,
            Ok(n) => filled += n,
            Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        }
    }
    data.truncate(filled);
    Ok(data)
}

fn zc_tcpmux_parallel_send_file_worker(
    lane: usize,
    lanes: usize,
    data_host: String,
    port: u16,
    local_data_address: Option<String>,
    token: Option<String>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    file: Arc<fs::File>,
    file_len: u64,
    chunk_bytes: usize,
    affinity: ZcTcpmuxAffinityConfig,
) -> io::Result<ZcTcpmuxParallelStats> {
    let (mut stream, topology, nonce_base, cipher) = zc_tcpmux_connect_parallel_sender(
        lane,
        lanes,
        chunk_bytes,
        &data_host,
        port,
        local_data_address.as_deref(),
        token.as_deref(),
        encryption,
        already_encrypted,
        &affinity,
    )?;
    let chunk_bytes = chunk_bytes.max(4096);
    let chunk_u64 = u64::try_from(chunk_bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel file chunk size exceeds u64",
        )
    })?;
    let lane_u64 = u64::try_from(lane)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "lane exceeds u64 range"))?;
    let lanes_u64 = u64::try_from(lanes)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "lanes exceeds u64 range"))?;
    let stride = chunk_u64.checked_mul(lanes_u64).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel file lane stride overflow",
        )
    })?;
    let mut offset = chunk_u64.checked_mul(lane_u64).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel file lane offset overflow",
        )
    })?;
    let mut sequence = 0u64;
    let mut stats = ZcTcpmuxParallelStats::default();
    stats.topology = Some(topology);

    while offset < file_len {
        let len = file_len.saturating_sub(offset).min(chunk_u64) as usize;
        let data = zc_read_file_chunk_at(&file, offset, len)?;
        if data.is_empty() {
            break;
        }
        let (plaintext_len, end) = zc_tcpmux_parallel_write_data_frame(
            &mut stream,
            cipher.as_ref(),
            lane,
            topology.lane_id,
            &nonce_base,
            sequence,
            offset,
            data,
        )?;
        stats.bytes = stats
            .bytes
            .checked_add(plaintext_len as u64)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "parallel file xfer byte count overflow",
                )
            })?;
        stats.chunks = stats.chunks.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel file xfer chunk count overflow",
            )
        })?;
        stats.max_end = stats.max_end.max(end);
        sequence = sequence.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel file xfer sequence overflow",
            )
        })?;
        offset = offset.checked_add(stride).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "parallel file offset overflow")
        })?;
    }
    zc_tcpmux_parallel_write_eof(&mut stream)?;
    Ok(stats)
}

fn zc_tcpmux_copy_file_to_tcp_parallel(
    file: fs::File,
    file_len: u64,
    data_paths: &[ZcTcpmuxDataPath],
    ports: &[u16],
    token: Option<&str>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    chunk_bytes: usize,
    affinity: &ZcTcpmuxAffinityConfig,
) -> io::Result<u64> {
    if ports.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel file xfer requires at least one port",
        ));
    }
    if data_paths.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel file xfer requires at least one data path",
        ));
    }
    if token.is_none() && encryption.requires_token() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel AES-256 file xfer requires --token",
        ));
    }

    let file = Arc::new(file);
    let lane_count = ports.len();
    let mut handles = Vec::with_capacity(ports.len());
    for (lane, port) in ports.iter().copied().enumerate() {
        let path = data_paths[zc_tcpmux_path_index(lane, lane_count, data_paths.len())].clone();
        let host = path.data_host;
        let local_data_address = path.local_data_address;
        let token = token.map(str::to_string);
        let file = Arc::clone(&file);
        let affinity = affinity.clone();
        handles.push(thread::spawn(move || {
            zc_tcpmux_parallel_send_file_worker(
                lane,
                lane_count,
                host,
                port,
                local_data_address,
                token,
                encryption,
                already_encrypted,
                file,
                file_len,
                chunk_bytes,
                affinity,
            )
        }));
    }

    let mut total = 0u64;
    for (lane, handle) in handles.into_iter().enumerate() {
        let stats = handle
            .join()
            .map_err(|_| io::Error::other(format!("parallel file send lane {lane} panicked")))??;
        total = total.checked_add(stats.bytes).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel file xfer worker total overflow",
            )
        })?;
        eprintln!(
            "zc-tcpmux-xfer-file-send-lane-result: lane={lane} bytes={} chunks={} max_end={} topology={}",
            stats.bytes,
            stats.chunks,
            stats.max_end,
            stats
                .topology
                .map(ZcTcpmuxTopologyHint::log_fields)
                .unwrap_or_else(|| "-".to_string())
        );
    }
    if total != file_len {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            format!("parallel file xfer copied {total} bytes but source length was {file_len}"),
        ));
    }
    Ok(total)
}

fn zc_tcpmux_parallel_receive_worker(
    lane: usize,
    expected_lane_id: usize,
    listener: TcpListener,
    output: Option<Arc<fs::File>>,
    shard_output: Option<PathBuf>,
    chunk_tx: Option<mpsc::SyncSender<ZcTcpmuxReceivedChunk>>,
    discard: bool,
    token: Option<String>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    affinity: ZcTcpmuxAffinityConfig,
) -> io::Result<ZcTcpmuxParallelStats> {
    let affinity_result = affinity.pin_current_thread("zc-tcpmux-receive-lane", lane);
    let local_cpu = current_cpu_usize().map(|cpu| cpu as i32).unwrap_or(-1);
    let local_numa = if local_cpu >= 0 {
        cpu_numa_node(local_cpu as usize).unwrap_or(-1)
    } else {
        -1
    };
    let (stream, peer) = listener.accept()?;
    let mut reader = BufReader::new(stream);
    if let Some(expected) = token.as_deref() {
        zc_tcpmux_validate_token(expected)?;
        let mut auth_line = String::new();
        reader.read_line(&mut auth_line)?;
        let expected_line = zc_tcpmux_token_auth_line(expected);
        if auth_line != expected_line {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!("zc-tcpmux lane {lane} token authentication failed"),
            ));
        }
    }
    let (topology, nonce_base) = zc_tcpmux_read_parallel_header(&mut reader)?;
    if topology.lane_id as usize != expected_lane_id {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "parallel lane id mismatch listener={lane} expected={expected_lane_id} header={}",
                topology.lane_id
            ),
        ));
    }
    eprintln!(
        "zc-tcpmux-receive-lane-topology: lane={lane} expected_lane_id={expected_lane_id} sender={} receiver_cpu={} receiver_numa_node={} affinity_target_cpu={} affinity_applied={} affinity={}",
        topology.log_fields(),
        local_cpu,
        local_numa,
        affinity_result.target_cpu,
        affinity_result.applied,
        affinity.describe()
    );
    let cipher = if encryption == ZcTcpmuxEncryption::Aes256 && !already_encrypted {
        Some(zc_aes256_lane_cipher(
            token.as_deref().ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "AES-256 lane requires --token")
            })?,
            topology.lane_id,
        )?)
    } else {
        None
    };
    let (shard_file, shard_file_is_block) = if let Some(path) = shard_output.as_ref() {
        let (file, is_block) = zc_tcpmux_open_output_path(path, "shard")?;
        (Some(file), is_block)
    } else {
        (None, false)
    };

    let mut stats = ZcTcpmuxParallelStats::default();
    stats.topology = Some(topology);
    let mut sequence = 0u64;
    let mut shard_offset = 0u64;
    let mut offset_buf = [0u8; 8];
    let mut plain_len_buf = [0u8; 4];
    let mut payload_len_buf = [0u8; 4];
    let mut direct_plain_payload = Vec::<u8>::new();
    loop {
        reader.read_exact(&mut offset_buf)?;
        reader.read_exact(&mut plain_len_buf)?;
        reader.read_exact(&mut payload_len_buf)?;
        let offset = u64::from_be_bytes(offset_buf);
        let plaintext_len = u32::from_be_bytes(plain_len_buf);
        let payload_len = u32::from_be_bytes(payload_len_buf);
        if plaintext_len == ZC_TCPMUX_PARALLEL_EOF && payload_len == ZC_TCPMUX_PARALLEL_EOF {
            break;
        }
        let payload_len_usize = payload_len as usize;
        if cipher.is_none() && chunk_tx.is_none() {
            direct_plain_payload.resize(payload_len_usize, 0);
            reader.read_exact(&mut direct_plain_payload)?;
            if direct_plain_payload.len() != plaintext_len as usize {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "parallel lane {lane} plaintext length mismatch header={} actual={}",
                        plaintext_len,
                        direct_plain_payload.len()
                    ),
                ));
            }
            if !discard {
                if let Some(file) = output.as_ref() {
                    zc_write_all_at(file, &direct_plain_payload, offset)?;
                } else if let Some(file) = shard_file.as_ref() {
                    zc_write_all_at(file, &direct_plain_payload, shard_offset)?;
                    shard_offset = shard_offset
                        .checked_add(direct_plain_payload.len() as u64)
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidData,
                                "parallel receive shard offset overflow",
                            )
                        })?;
                } else {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "parallel receive missing output file",
                    ));
                }
            }
        } else {
            let mut payload = vec![0u8; payload_len_usize];
            reader.read_exact(&mut payload)?;
            let plaintext = if let Some(cipher) = &cipher {
                let nonce = zc_aes256_nonce(&nonce_base, sequence);
                let aad = zc_aes256_lane_aad(topology.lane_id, sequence, offset, plaintext_len);
                zc_aes256_decrypt_frame(cipher, nonce, &aad, payload, || {
                    format!("AES-256-GCM lane {lane} decrypt frame {sequence}")
                })?
            } else {
                payload
            };
            if plaintext.len() != plaintext_len as usize {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!(
                        "parallel lane {lane} plaintext length mismatch header={} actual={}",
                        plaintext_len,
                        plaintext.len()
                    ),
                ));
            }
            if !discard {
                if let Some(tx) = &chunk_tx {
                    tx.send(ZcTcpmuxReceivedChunk {
                        offset,
                        data: plaintext,
                    })
                    .map_err(|err| {
                        io::Error::new(
                            io::ErrorKind::BrokenPipe,
                            format!("parallel ordered receive writer exited: {err}"),
                        )
                    })?;
                } else {
                    if let Some(file) = output.as_ref() {
                        zc_write_all_at(file, &plaintext, offset)?;
                    } else if let Some(file) = shard_file.as_ref() {
                        zc_write_all_at(file, &plaintext, shard_offset)?;
                        shard_offset = shard_offset
                            .checked_add(plaintext.len() as u64)
                            .ok_or_else(|| {
                                io::Error::new(
                                    io::ErrorKind::InvalidData,
                                    "parallel receive shard offset overflow",
                                )
                            })?;
                    } else {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            "parallel receive missing output file",
                        ));
                    }
                }
            }
        }
        stats.bytes = stats
            .bytes
            .checked_add(plaintext_len as u64)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "parallel receive byte count overflow",
                )
            })?;
        stats.chunks = stats.chunks.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel receive chunk count overflow",
            )
        })?;
        let end = offset.checked_add(plaintext_len as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel receive offset overflow",
            )
        })?;
        stats.max_end = stats.max_end.max(end);
        sequence = sequence.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "parallel receive sequence overflow",
            )
        })?;
    }
    if let Some(file) = shard_file.as_ref()
        && !shard_file_is_block
    {
        file.set_len(shard_offset)?;
    }
    eprintln!(
        "zc-tcpmux-receive-lane-result: lane={lane} peer={peer} bytes={} chunks={} max_end={} topology={}",
        stats.bytes,
        stats.chunks,
        stats.max_end,
        stats
            .topology
            .map(ZcTcpmuxTopologyHint::log_fields)
            .unwrap_or_else(|| "-".to_string())
    );
    Ok(stats)
}

fn zc_tcpmux_ordered_receive_writer(
    file: Arc<fs::File>,
    rx: mpsc::Receiver<ZcTcpmuxReceivedChunk>,
    expected_bytes: Option<u64>,
) -> io::Result<(u64, u64)> {
    let mut pending = BTreeMap::<u64, Vec<u8>>::new();
    let mut next_offset = 0u64;
    let mut total = 0u64;
    let mut max_end = 0u64;

    for chunk in rx {
        let len = chunk.data.len() as u64;
        let end = chunk.offset.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "ordered receive chunk offset overflow",
            )
        })?;
        if chunk.offset < next_offset {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "ordered receive duplicate or overlapping chunk at offset {} next_offset={next_offset}",
                    chunk.offset
                ),
            ));
        }
        total = total.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "ordered receive byte count overflow",
            )
        })?;
        max_end = max_end.max(end);

        if chunk.offset == next_offset {
            zc_write_all_at(file.as_ref(), &chunk.data, next_offset)?;
            next_offset = end;
            while let Some(data) = pending.remove(&next_offset) {
                let len = data.len() as u64;
                zc_write_all_at(file.as_ref(), &data, next_offset)?;
                next_offset = next_offset.checked_add(len).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "ordered receive next offset overflow",
                    )
                })?;
            }
        } else if pending.insert(chunk.offset, chunk.data).is_some() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("ordered receive duplicate chunk at offset {}", chunk.offset),
            ));
        }
    }

    if !pending.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            format!(
                "ordered receive is missing chunk at offset {next_offset}; pending_chunks={}",
                pending.len()
            ),
        ));
    }
    if let Some(expected_bytes) = expected_bytes
        && next_offset != expected_bytes
    {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            format!("ordered receive wrote {next_offset} bytes but expected {expected_bytes}"),
        ));
    }

    eprintln!("zc-tcpmux-ordered-writer-result: bytes={total} max_end={max_end} pending_chunks=0");
    Ok((total, max_end))
}

fn zc_tcpmux_ordered_receive_stream_writer<W: Write>(
    mut writer: W,
    rx: mpsc::Receiver<ZcTcpmuxReceivedChunk>,
    expected_bytes: Option<u64>,
) -> io::Result<(u64, u64)> {
    let mut pending = BTreeMap::<u64, Vec<u8>>::new();
    let mut next_offset = 0u64;
    let mut total = 0u64;
    let mut max_end = 0u64;

    for chunk in rx {
        let len = chunk.data.len() as u64;
        let end = chunk.offset.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "ordered stream receive chunk offset overflow",
            )
        })?;
        if chunk.offset < next_offset {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "ordered stream receive duplicate or overlapping chunk at offset {} next_offset={next_offset}",
                    chunk.offset
                ),
            ));
        }
        total = total.checked_add(len).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "ordered stream receive byte count overflow",
            )
        })?;
        max_end = max_end.max(end);

        if chunk.offset == next_offset {
            writer.write_all(&chunk.data)?;
            next_offset = end;
            while let Some(data) = pending.remove(&next_offset) {
                let len = data.len() as u64;
                writer.write_all(&data)?;
                next_offset = next_offset.checked_add(len).ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::InvalidData,
                        "ordered stream receive next offset overflow",
                    )
                })?;
            }
        } else if pending.insert(chunk.offset, chunk.data).is_some() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "ordered stream receive duplicate chunk at offset {}",
                    chunk.offset
                ),
            ));
        }
    }

    if !pending.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            format!(
                "ordered stream receive is missing chunk at offset {next_offset}; pending_chunks={}",
                pending.len()
            ),
        ));
    }
    if let Some(expected_bytes) = expected_bytes
        && next_offset != expected_bytes
    {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            format!(
                "ordered stream receive wrote {next_offset} bytes but expected {expected_bytes}"
            ),
        ));
    }

    writer.flush()?;
    eprintln!(
        "zc-tcpmux-ordered-stream-writer-result: bytes={total} max_end={max_end} pending_chunks=0"
    );
    Ok((total, max_end))
}

fn zc_tcpmux_receive_shard_path(
    base: &Path,
    lane: usize,
    shard_device_prefix: Option<&str>,
) -> PathBuf {
    if let Some(prefix) = shard_device_prefix {
        PathBuf::from(format!("{prefix}{lane}"))
    } else {
        PathBuf::from(format!("{}.lane{lane:04}", base.display()))
    }
}

fn zc_tcpmux_receive_shard_manifest_path(base: &Path) -> PathBuf {
    PathBuf::from(format!("{}.zcshards", base.display()))
}

fn zc_remove_file_if_exists(path: &Path) -> io::Result<()> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(err) => Err(err),
    }
}

fn zc_tcpmux_write_shard_manifest(
    output: &Path,
    shard_device_prefix: Option<&str>,
    expected_bytes: Option<u64>,
    lane_stats: &[(usize, ZcTcpmuxParallelStats)],
) -> io::Result<()> {
    let manifest_path = zc_tcpmux_receive_shard_manifest_path(output);
    let mut text = String::new();
    text.push_str("zc-tcpmux-shards-v1\n");
    text.push_str(&format!("base={}\n", output.display()));
    text.push_str(&format!(
        "expected_bytes={}\n",
        expected_bytes
            .map(|value| value.to_string())
            .unwrap_or_else(|| "-".to_string())
    ));
    text.push_str(&format!("lanes={}\n", lane_stats.len()));
    text.push_str("layout=lane-contiguous-round-robin\n");
    if let Some(prefix) = shard_device_prefix {
        text.push_str(&format!("shard_device_prefix={prefix}\n"));
    }
    for (lane, stats) in lane_stats {
        text.push_str(&format!(
            "lane={} path={} bytes={} chunks={} max_end={} topology={}\n",
            lane,
            zc_tcpmux_receive_shard_path(output, *lane, shard_device_prefix).display(),
            stats.bytes,
            stats.chunks,
            stats.max_end,
            stats
                .topology
                .map(ZcTcpmuxTopologyHint::log_fields)
                .unwrap_or_else(|| "-".to_string())
        ));
    }
    fs::write(&manifest_path, text).map_err(|err| {
        io::Error::new(
            err.kind(),
            format!("write shard manifest {}: {err}", manifest_path.display()),
        )
    })
}

fn zc_tcpmux_receive_parallel(
    listeners: Vec<TcpListener>,
    lane_base: usize,
    output: &Path,
    expected_bytes: Option<u64>,
    assembly: ZcTcpmuxReceiveAssembly,
    shard_device_prefix: Option<&str>,
    token: Option<&str>,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    affinity: &ZcTcpmuxAffinityConfig,
) -> io::Result<u64> {
    let output_is_stdout = output.as_os_str() == "-";
    if output_is_stdout && assembly != ZcTcpmuxReceiveAssembly::Ordered {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "parallel zc-tcpmux stdout receive requires --receive-assembly ordered",
        ));
    }
    let discard = output == Path::new("/dev/null");
    let sharded = !discard && assembly == ZcTcpmuxReceiveAssembly::Shards;
    let output_is_block = if discard || sharded || output_is_stdout {
        false
    } else {
        fs::metadata(output)
            .map(|metadata| metadata.file_type().is_block_device())
            .unwrap_or(false)
    };
    if sharded {
        zc_remove_file_if_exists(&zc_tcpmux_receive_shard_manifest_path(output))?;
        if shard_device_prefix.is_none() {
            zc_remove_file_if_exists(output)?;
            for lane in 0..listeners.len() {
                zc_remove_file_if_exists(&zc_tcpmux_receive_shard_path(
                    output,
                    lane_base + lane,
                    None,
                ))?;
            }
        }
    }
    let file = if discard || sharded || output_is_stdout {
        None
    } else {
        let (opened, _) = zc_tcpmux_open_output_path(output, "output")?;
        let file = Some(Arc::new(opened));
        if let Some(expected_bytes) = expected_bytes {
            if let Some(file) = file.as_ref()
                && !output_is_block
            {
                file.set_len(expected_bytes)?;
            }
        }
        file
    };

    let (chunk_tx, writer_handle) = if !discard && assembly == ZcTcpmuxReceiveAssembly::Ordered {
        let (tx, rx) = mpsc::sync_channel::<ZcTcpmuxReceivedChunk>(
            listeners.len().saturating_mul(4).clamp(16, 1024),
        );
        let handle = if output_is_stdout {
            thread::spawn(move || {
                zc_tcpmux_ordered_receive_stream_writer(
                    BufWriter::new(io::stdout()),
                    rx,
                    expected_bytes,
                )
            })
        } else {
            let file = file.as_ref().ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "ordered receive assembly requires an output file",
                )
            })?;
            let writer_file = Arc::clone(file);
            thread::spawn(move || zc_tcpmux_ordered_receive_writer(writer_file, rx, expected_bytes))
        };
        (Some(tx), Some(handle))
    } else {
        (None, None)
    };

    let mut handles = Vec::with_capacity(listeners.len());
    for (lane, listener) in listeners.into_iter().enumerate() {
        let expected_lane_id = lane_base.checked_add(lane).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "parallel receive lane base overflow",
            )
        })?;
        let worker_chunk_tx = chunk_tx.as_ref().cloned();
        let shard_output = sharded
            .then(|| zc_tcpmux_receive_shard_path(output, expected_lane_id, shard_device_prefix));
        let file = if worker_chunk_tx.is_some() || shard_output.is_some() {
            None
        } else {
            file.clone()
        };
        let token = token.map(str::to_string);
        let affinity = affinity.clone();
        handles.push(thread::spawn(move || {
            zc_tcpmux_parallel_receive_worker(
                lane,
                expected_lane_id,
                listener,
                file,
                shard_output,
                worker_chunk_tx,
                discard,
                token,
                encryption,
                already_encrypted,
                affinity,
            )
        }));
    }
    drop(chunk_tx);

    let mut total = 0u64;
    let mut max_end = 0u64;
    let mut first_error = None::<io::Error>;
    let mut lane_stats = Vec::<(usize, ZcTcpmuxParallelStats)>::new();
    for (lane, handle) in handles.into_iter().enumerate() {
        match handle.join() {
            Ok(Ok(stats)) => {
                match total.checked_add(stats.bytes) {
                    Some(next) => total = next,
                    None if first_error.is_none() => {
                        first_error = Some(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "parallel receive total overflow",
                        ));
                    }
                    None => {}
                }
                max_end = max_end.max(stats.max_end);
                lane_stats.push((lane_base + lane, stats));
            }
            Ok(Err(err)) if first_error.is_none() => first_error = Some(err),
            Ok(Err(_)) => {}
            Err(_) if first_error.is_none() => {
                first_error = Some(io::Error::other(format!(
                    "parallel receive lane {lane} panicked"
                )))
            }
            Err(_) => {}
        }
    }

    let writer_result = writer_handle
        .map(|handle| {
            handle
                .join()
                .map_err(|_| io::Error::other("ordered receive writer panicked"))?
        })
        .transpose();
    if let Some(err) = first_error {
        return Err(err);
    }
    if let Some((writer_total, writer_max_end)) = writer_result? {
        if writer_total != total {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("ordered receive writer total={writer_total} lane_total={total}"),
            ));
        }
        max_end = writer_max_end;
    }
    if let Some(expected_bytes) = expected_bytes
        && total != expected_bytes
    {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            format!("parallel receive got {total} bytes but expected {expected_bytes}"),
        ));
    }
    if let Some(file) = file
        && !output_is_block
    {
        file.set_len(expected_bytes.unwrap_or(max_end))?;
    }
    if sharded {
        zc_tcpmux_write_shard_manifest(output, shard_device_prefix, expected_bytes, &lane_stats)?;
    }
    Ok(total)
}

fn zc_tcpmux_remote_parent(path: &str) -> Option<String> {
    let parent = Path::new(path).parent()?.to_str()?;
    if parent.is_empty() {
        None
    } else {
        Some(parent.to_string())
    }
}

fn zc_tcpmux_parse_port_range(value: &str) -> io::Result<(u16, u16)> {
    if let Some((start, end)) = value.split_once('-') {
        let start = parse_u16_value(start, "--listen-port-range")?;
        let end = parse_u16_value(end, "--listen-port-range")?;
        if start > end {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "--listen-port-range start must be <= end",
            ));
        }
        Ok((start, end))
    } else {
        let port = parse_u16_value(value, "--listen-port-range")?;
        Ok((port, port))
    }
}

fn zc_tcpmux_consecutive_ports(base: u16, lanes: usize, label: &str) -> io::Result<Vec<u16>> {
    if lanes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{label} requires at least one lane"),
        ));
    }
    let end = base as usize + lanes - 1;
    if end > u16::MAX as usize {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{label} overflows TCP port range: base={base} lanes={lanes}"),
        ));
    }
    Ok((0..lanes).map(|lane| base + lane as u16).collect())
}

fn zc_tcpmux_parse_ports_csv(value: &str, label: &str) -> io::Result<Vec<u16>> {
    let ports = value
        .split(',')
        .map(str::trim)
        .map(|item| parse_u16_value(item, label))
        .collect::<io::Result<Vec<_>>>()?;
    if ports.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{label} requires at least one port"),
        ));
    }
    Ok(ports)
}

fn zc_tcpmux_bind_listener(
    listen_address: &str,
    port_range: (u16, u16),
) -> io::Result<TcpListener> {
    let (start, end) = port_range;
    if start == 0 && end == 0 {
        return TcpListener::bind((listen_address, 0)).map_err(|err| {
            io::Error::new(
                err.kind(),
                format!("bind zc-tcpmux-receive {listen_address}:0: {err}"),
            )
        });
    }
    let mut last_err = None;
    for port in start..=end {
        match TcpListener::bind((listen_address, port)) {
            Ok(listener) => return Ok(listener),
            Err(err) => last_err = Some(err),
        }
    }
    Err(io::Error::new(
        last_err
            .map(|err| err.kind())
            .unwrap_or(io::ErrorKind::AddrNotAvailable),
        format!("no bindable port in {listen_address}:{start}-{end}"),
    ))
}

fn zc_tcpmux_bind_listeners(
    listen_address: &str,
    port_range: (u16, u16),
    lanes: usize,
) -> io::Result<Vec<TcpListener>> {
    if lanes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--lanes must be greater than zero",
        ));
    }
    if lanes == 1 {
        return Ok(vec![zc_tcpmux_bind_listener(listen_address, port_range)?]);
    }
    let (start, end) = port_range;
    if start != 0 || end != 0 {
        let available = end.saturating_sub(start) as usize + 1;
        if available < lanes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("--listen-port-range has {available} ports but --lanes requires {lanes}"),
            ));
        }
    }
    let mut listeners = Vec::with_capacity(lanes);
    if start == 0 && end == 0 {
        for _ in 0..lanes {
            listeners.push(zc_tcpmux_bind_listener(listen_address, (0, 0))?);
        }
        return Ok(listeners);
    }
    let mut port = start;
    while listeners.len() < lanes {
        let listener = zc_tcpmux_bind_listener(listen_address, (port, end))?;
        port = listener
            .local_addr()?
            .port()
            .checked_add(1)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::AddrNotAvailable,
                    "listen port range overflow",
                )
            })?;
        listeners.push(listener);
    }
    Ok(listeners)
}

fn zc_tcpmux_bind_listeners_on_addresses(
    listen_addresses: &[String],
    port_range: (u16, u16),
    lanes: usize,
) -> io::Result<Vec<TcpListener>> {
    if listen_addresses.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--listen-addresses requires at least one address",
        ));
    }
    if listen_addresses.len() == 1 {
        return zc_tcpmux_bind_listeners(&listen_addresses[0], port_range, lanes);
    }
    if lanes < listen_addresses.len() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "--listen-addresses has {} paths but --lanes is only {lanes}",
                listen_addresses.len()
            ),
        ));
    }

    let (start, end) = port_range;
    if start != 0 || end != 0 {
        let available = end.saturating_sub(start) as usize + 1;
        let mut per_path = vec![0usize; listen_addresses.len()];
        for lane in 0..lanes {
            per_path[zc_tcpmux_path_index(lane, lanes, listen_addresses.len())] += 1;
        }
        if let Some(required) = per_path.iter().copied().max()
            && available < required
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "--listen-port-range has {available} ports per address but multipath requires up to {required}"
                ),
            ));
        }
    }

    let mut next_port = vec![start; listen_addresses.len()];
    let mut listeners = Vec::with_capacity(lanes);
    for lane in 0..lanes {
        let path = zc_tcpmux_path_index(lane, lanes, listen_addresses.len());
        let listener = if start == 0 && end == 0 {
            zc_tcpmux_bind_listener(&listen_addresses[path], (0, 0))?
        } else {
            let listener =
                zc_tcpmux_bind_listener(&listen_addresses[path], (next_port[path], end))?;
            next_port[path] = listener
                .local_addr()?
                .port()
                .checked_add(1)
                .ok_or_else(|| {
                    io::Error::new(
                        io::ErrorKind::AddrNotAvailable,
                        "listen port range overflow",
                    )
                })?;
            listener
        };
        listeners.push(listener);
    }
    Ok(listeners)
}

fn zc_tcpmux_receive(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut listen_address = "0.0.0.0".to_string();
    let mut listen_addresses = None::<Vec<String>>;
    let mut listen_port_range = (0u16, 0u16);
    let mut output = None::<PathBuf>;
    let mut buffer_bytes = 1024 * 1024usize;
    let mut expected_bytes = None::<u64>;
    let mut assembly = ZcTcpmuxReceiveAssembly::Direct;
    let mut lanes = 1usize;
    let mut lane_base = 0usize;
    let mut shard_device_prefix = None::<String>;
    let mut encryption = ZcTcpmuxEncryption::Aes256;
    let mut already_encrypted = false;
    let mut ready_stderr = false;
    let mut token = None::<String>;
    let mut disable_authentication = false;
    let mut generate_token = false;
    let mut pin_cpus = false;
    let mut cpu_list = None::<String>;
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--generate-token" => generate_token = true,
            "--disable-authentication" => disable_authentication = true,
            "--token" | "--receive-token" => token = Some(next_flag_value(&mut args, &arg)?),
            "--listen-address" | "--bind" => listen_address = next_flag_value(&mut args, &arg)?,
            "--listen-addresses" => {
                listen_addresses = Some(zc_tcpmux_csv_values(
                    &next_flag_value(&mut args, &arg)?,
                    &arg,
                )?)
            }
            "--listen-port-range" => {
                listen_port_range =
                    zc_tcpmux_parse_port_range(&next_flag_value(&mut args, "--listen-port-range")?)?
            }
            "--port" => {
                let port = parse_u16_value(&next_flag_value(&mut args, "--port")?, "--port")?;
                listen_port_range = (port, port);
            }
            "--output" | "-o" => output = Some(PathBuf::from(next_flag_value(&mut args, &arg)?)),
            "--buffer-bytes" | "--chunk-bytes" => {
                buffer_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--expected-bytes" => {
                expected_bytes = Some(parse_u64_value(
                    &next_flag_value(&mut args, &arg)?,
                    "--expected-bytes",
                )?)
            }
            "--assembly" | "--receive-assembly" => {
                assembly = ZcTcpmuxReceiveAssembly::parse(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--ordered-assembly" | "--receive-ordered-assembly" => {
                assembly = ZcTcpmuxReceiveAssembly::Ordered
            }
            "--shard-device-prefix" | "--receive-shard-device-prefix" => {
                shard_device_prefix = Some(next_flag_value(&mut args, &arg)?)
            }
            "--lanes" | "--receive-lanes" => {
                lanes = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--lane-base" | "--receive-lane-base" => {
                lane_base = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--encryption" | "--receive-encryption" => {
                encryption = ZcTcpmuxEncryption::parse(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--already-encrypted" | "--receive-already-encrypted" => already_encrypted = true,
            "--ready-stderr" => ready_stderr = true,
            "--pin-cpus" => pin_cpus = true,
            "--cpu-list" | "--pin-cpu-list" => cpu_list = Some(next_flag_value(&mut args, &arg)?),
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zc-tcpmux-receive option {other:?}"),
                ));
            }
        }
    }
    if generate_token {
        println!("{}", zc_tcpmux_generate_token()?);
        return Ok(());
    }
    if disable_authentication && token.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cannot combine --token and --disable-authentication",
        ));
    }
    if disable_authentication && encryption.requires_token() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--disable-authentication requires --encryption none",
        ));
    }
    if already_encrypted && encryption != ZcTcpmuxEncryption::Aes256 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--already-encrypted requires --encryption aes-256",
        ));
    }
    if lanes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--lanes must be greater than zero",
        ));
    }
    if shard_device_prefix.is_some() && assembly != ZcTcpmuxReceiveAssembly::Shards {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--shard-device-prefix requires --receive-assembly shards",
        ));
    }
    if !disable_authentication && token.is_none() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-receive requires --token, --generate-token, or --disable-authentication",
        ));
    }
    if let Some(token) = token.as_deref() {
        zc_tcpmux_validate_token(token)?;
    }
    let affinity = ZcTcpmuxAffinityConfig::from_cli(pin_cpus, cpu_list.as_deref(), "--cpu-list")?;
    let output = output.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-receive requires --output PATH",
        )
    })?;
    if output.as_os_str() != "-" {
        if let Some(parent) = output.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| {
                    io::Error::new(
                        err.kind(),
                        format!("create output directory {}: {err}", parent.display()),
                    )
                })?;
            }
        }
    }
    let listen_addresses = listen_addresses.unwrap_or_else(|| vec![listen_address.clone()]);
    let listeners =
        zc_tcpmux_bind_listeners_on_addresses(&listen_addresses, listen_port_range, lanes)?;
    let ready_ports = listeners
        .iter()
        .map(|listener| listener.local_addr().map(|addr| addr.port()))
        .collect::<io::Result<Vec<_>>>()?;
    let ready_port = ready_ports[0];
    let ready_ports_csv = ready_ports
        .iter()
        .map(u16::to_string)
        .collect::<Vec<_>>()
        .join(",");
    let ready_line = format!(
        "ZC_TCPMUX_READY listen_address={} listen_addresses={} port={} ports={} lanes={} lane_base={} authentication={} encryption={}",
        listen_addresses[0],
        listen_addresses.join(","),
        ready_port,
        ready_ports_csv,
        lanes,
        lane_base,
        if disable_authentication {
            "disabled"
        } else {
            "token"
        },
        encryption.as_arg()
    );
    let output_is_stdout = output.as_os_str() == "-";
    if ready_stderr || output_is_stdout {
        eprintln!("{ready_line}");
    } else {
        println!("{ready_line}");
        io::stdout().flush()?;
    }

    if lanes > 1 {
        let total = zc_tcpmux_receive_parallel(
            listeners,
            lane_base,
            &output,
            expected_bytes,
            assembly,
            shard_device_prefix.as_deref(),
            token.as_deref(),
            encryption,
            already_encrypted,
            &affinity,
        )?;
        eprintln!(
            "zc-tcpmux-receive-result: peer=parallel lanes={lanes} bytes={total} assembly={} encryption={} already_encrypted={} output={}",
            assembly.as_arg(),
            encryption.as_arg(),
            already_encrypted,
            output.display()
        );
        return Ok(());
    }

    let listener = listeners.into_iter().next().expect("one listener");
    let single_affinity = affinity.pin_current_thread("zc-tcpmux-receive", 0);
    eprintln!(
        "zc-tcpmux-receive-topology: lane=0 receiver_cpu={} receiver_numa_node={} affinity_target_cpu={} affinity_applied={} affinity={}",
        current_cpu_usize().map(|cpu| cpu as i32).unwrap_or(-1),
        current_cpu_usize().and_then(cpu_numa_node).unwrap_or(-1),
        single_affinity.target_cpu,
        single_affinity.applied,
        affinity.describe()
    );
    let (stream, peer) = listener.accept()?;
    let total = if output_is_stdout {
        zc_tcpmux_copy_tcp_to_writer(
            stream,
            io::stdout().lock(),
            token.as_deref(),
            encryption,
            already_encrypted,
            buffer_bytes,
        )?
    } else {
        let output_is_block = fs::metadata(&output)
            .map(|metadata| metadata.file_type().is_block_device())
            .unwrap_or(false);
        let mut options = OpenOptions::new();
        options.write(true);
        if output_is_block {
            options.read(true);
        } else {
            options.create(true).truncate(true);
        }
        let file = BufWriter::new(options.open(&output).map_err(|err| {
            io::Error::new(
                err.kind(),
                format!("open output {}: {err}", output.display()),
            )
        })?);
        zc_tcpmux_copy_tcp_to_writer(
            stream,
            file,
            token.as_deref(),
            encryption,
            already_encrypted,
            buffer_bytes,
        )?
    };
    eprintln!(
        "zc-tcpmux-receive-result: peer={peer} bytes={total} encryption={} already_encrypted={} output={}",
        encryption.as_arg(),
        already_encrypted,
        output.display()
    );
    Ok(())
}

fn zc_tcpmux_send(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut peer_address = None::<String>;
    let mut port = None::<u16>;
    let mut ports = None::<Vec<u16>>;
    let mut input = None::<PathBuf>;
    let mut buffer_bytes = 1024 * 1024usize;
    let mut lanes = 1usize;
    let mut encryption = ZcTcpmuxEncryption::Aes256;
    let mut already_encrypted = false;
    let mut token = None::<String>;
    let mut disable_authentication = false;
    let mut local_data_address = None::<String>;
    let mut pin_cpus = false;
    let mut cpu_list = None::<String>;
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--peer-address" | "--peer-addr" | "--host" => {
                peer_address = Some(next_flag_value(&mut args, &arg)?)
            }
            "--port" => {
                port = Some(parse_u16_value(
                    &next_flag_value(&mut args, "--port")?,
                    "--port",
                )?)
            }
            "--ports" => {
                ports = Some(zc_tcpmux_parse_ports_csv(
                    &next_flag_value(&mut args, "--ports")?,
                    "--ports",
                )?)
            }
            "--local-data-address" | "--send-local-address" | "--source-address" => {
                local_data_address = Some(next_flag_value(&mut args, &arg)?)
            }
            "--input" | "-i" => input = Some(PathBuf::from(next_flag_value(&mut args, &arg)?)),
            "--buffer-bytes" | "--chunk-bytes" => {
                buffer_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--lanes" | "--send-lanes" => {
                lanes = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--token" => token = Some(next_flag_value(&mut args, &arg)?),
            "--disable-authentication" => disable_authentication = true,
            "--encryption" => {
                encryption = ZcTcpmuxEncryption::parse(
                    &next_flag_value(&mut args, "--encryption")?,
                    "--encryption",
                )?
            }
            "--already-encrypted" => already_encrypted = true,
            "--pin-cpus" => pin_cpus = true,
            "--cpu-list" | "--pin-cpu-list" => cpu_list = Some(next_flag_value(&mut args, &arg)?),
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zc-tcpmux-send option {other:?}"),
                ));
            }
        }
    }
    if disable_authentication && token.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cannot combine --token and --disable-authentication",
        ));
    }
    if disable_authentication && encryption.requires_token() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--disable-authentication requires --encryption none",
        ));
    }
    if already_encrypted && encryption != ZcTcpmuxEncryption::Aes256 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--already-encrypted requires --encryption aes-256",
        ));
    }
    if lanes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--lanes must be greater than zero",
        ));
    }
    if let Some(ports) = ports.as_ref() {
        if lanes == 1 {
            lanes = ports.len();
        } else if ports.len() != lanes {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("--ports has {} entries but --lanes is {lanes}", ports.len()),
            ));
        }
    }
    if !disable_authentication && token.is_none() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-send requires --token or --disable-authentication",
        ));
    }
    let peer_address = peer_address.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-send requires --peer-address",
        )
    })?;
    let port = port.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-send requires --port",
        )
    })?;
    let affinity = ZcTcpmuxAffinityConfig::from_cli(pin_cpus, cpu_list.as_deref(), "--cpu-list")?;
    let parallel_ports = |lanes| {
        if let Some(ports) = ports.clone() {
            Ok(ports)
        } else {
            zc_tcpmux_consecutive_ports(port, lanes, "--port/--lanes")
        }
    };
    let bytes = if let Some(input) = input {
        let source = fs::File::open(&input).map_err(|err| {
            io::Error::new(err.kind(), format!("open input {}: {err}", input.display()))
        })?;
        if lanes == 1 {
            zc_tcpmux_copy_reader_to_tcp(
                source,
                &peer_address,
                port,
                local_data_address.as_deref(),
                token.as_deref(),
                encryption,
                already_encrypted,
                buffer_bytes,
            )?
        } else {
            let ports = parallel_ports(lanes)?;
            let paths = vec![ZcTcpmuxDataPath {
                data_host: peer_address.clone(),
                local_data_address: local_data_address.clone(),
                receive_listen_address: peer_address.clone(),
            }];
            zc_tcpmux_copy_reader_to_tcp_parallel(
                source,
                &paths,
                &ports,
                token.as_deref(),
                encryption,
                already_encrypted,
                buffer_bytes,
                &affinity,
            )?
        }
    } else {
        let stdin = io::stdin().lock();
        if lanes == 1 {
            zc_tcpmux_copy_reader_to_tcp(
                stdin,
                &peer_address,
                port,
                local_data_address.as_deref(),
                token.as_deref(),
                encryption,
                already_encrypted,
                buffer_bytes,
            )?
        } else {
            let ports = parallel_ports(lanes)?;
            let paths = vec![ZcTcpmuxDataPath {
                data_host: peer_address.clone(),
                local_data_address: local_data_address.clone(),
                receive_listen_address: peer_address.clone(),
            }];
            zc_tcpmux_copy_reader_to_tcp_parallel(
                stdin,
                &paths,
                &ports,
                token.as_deref(),
                encryption,
                already_encrypted,
                buffer_bytes,
                &affinity,
            )?
        }
    };
    eprintln!(
        "zc-tcpmux-send-result: peer={peer_address}:{port} lanes={lanes} local_data_address={} bytes={bytes} encryption={} already_encrypted={}",
        local_data_address.as_deref().unwrap_or("-"),
        encryption.as_arg(),
        already_encrypted
    );
    Ok(())
}

fn zcencrypt(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut input = None::<PathBuf>;
    let mut output = None::<PathBuf>;
    let mut token = None::<String>;
    let mut primitive = ZcPrimitiveTopology::default();
    let mut buffer_bytes = 1024 * 1024usize;
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "help" | "--help" | "-h" => {
                println!(
                    "zcencrypt - encrypt a zc descriptor/frame stream with AES-256-GCM\n\
                     \n\
                     zcencrypt --token TOKEN [--input PATH] [--output PATH]\n\
                     \n\
                     Topology hint flags are accepted for descriptor pipelines:\n\
                     --topology NAME --lane-id N --lane-count N --queue-id N --preferred-cpu N --numa-node N --ordered global|per-lane"
                );
                return Ok(());
            }
            _ if primitive.parse_common_flag(&mut args, &arg)? => {}
            "--token" => token = Some(next_flag_value(&mut args, "--token")?),
            "--input" | "-i" => input = Some(PathBuf::from(next_flag_value(&mut args, &arg)?)),
            "--output" | "-o" => output = Some(PathBuf::from(next_flag_value(&mut args, &arg)?)),
            "--buffer-bytes" | "--chunk-bytes" => {
                buffer_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcencrypt option {other:?}"),
                ));
            }
        }
    }
    primitive.activate_byte_compatible("zcencrypt")?;
    let token = token
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcencrypt requires --token"))?;
    zc_tcpmux_validate_token(&token)?;

    let mut reader: Box<dyn Read> = match input {
        Some(path) if path.as_os_str() != "-" => {
            Box::new(fs::File::open(&path).map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!("open plaintext input {}: {err}", path.display()),
                )
            })?)
        }
        _ => Box::new(io::stdin().lock()),
    };
    let mut writer: Box<dyn Write> = match output {
        Some(path) if path.as_os_str() != "-" => {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|err| {
                        io::Error::new(
                            err.kind(),
                            format!("create output directory {}: {err}", parent.display()),
                        )
                    })?;
                }
            }
            Box::new(BufWriter::new(
                OpenOptions::new()
                    .create(true)
                    .write(true)
                    .truncate(true)
                    .open(&path)
                    .map_err(|err| {
                        io::Error::new(
                            err.kind(),
                            format!("open encrypted output {}: {err}", path.display()),
                        )
                    })?,
            ))
        }
        _ => Box::new(io::stdout().lock()),
    };
    let total = zc_encrypt_aes256_stream(&mut reader, &mut writer, &token, buffer_bytes)?;
    writer.flush()?;
    eprintln!("zcencrypt-result: bytes={total} {}", primitive.log_fields());
    Ok(())
}

fn zcdecrypt(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut input = None::<PathBuf>;
    let mut output = None::<PathBuf>;
    let mut token = None::<String>;
    let mut primitive = ZcPrimitiveTopology::default();
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "help" | "--help" | "-h" => {
                println!(
                    "zcdecrypt - decrypt a zc AES-256-GCM descriptor/frame stream\n\
                     \n\
                     zcdecrypt --token TOKEN [--input PATH] [--output PATH]\n\
                     \n\
                     Topology hint flags are accepted for descriptor pipelines:\n\
                     --topology NAME --lane-id N --lane-count N --queue-id N --preferred-cpu N --numa-node N --ordered global|per-lane"
                );
                return Ok(());
            }
            _ if primitive.parse_common_flag(&mut args, &arg)? => {}
            "--token" => token = Some(next_flag_value(&mut args, "--token")?),
            "--input" | "-i" => input = Some(PathBuf::from(next_flag_value(&mut args, &arg)?)),
            "--output" | "-o" => output = Some(PathBuf::from(next_flag_value(&mut args, &arg)?)),
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcdecrypt option {other:?}"),
                ));
            }
        }
    }
    primitive.activate_byte_compatible("zcdecrypt")?;
    let token = token
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zcdecrypt requires --token"))?;
    zc_tcpmux_validate_token(&token)?;

    let mut reader: Box<dyn Read> = match input {
        Some(path) if path.as_os_str() != "-" => {
            Box::new(fs::File::open(&path).map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!("open encrypted input {}: {err}", path.display()),
                )
            })?)
        }
        _ => Box::new(io::stdin().lock()),
    };
    let mut writer: Box<dyn Write> = match output {
        Some(path) if path.as_os_str() != "-" => {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|err| {
                        io::Error::new(
                            err.kind(),
                            format!("create output directory {}: {err}", parent.display()),
                        )
                    })?;
                }
            }
            Box::new(BufWriter::new(
                OpenOptions::new()
                    .create(true)
                    .write(true)
                    .truncate(true)
                    .open(&path)
                    .map_err(|err| {
                        io::Error::new(
                            err.kind(),
                            format!("open decrypted output {}: {err}", path.display()),
                        )
                    })?,
            ))
        }
        _ => Box::new(io::stdout().lock()),
    };
    let total = zc_decrypt_aes256_stream(&mut reader, &mut writer, &token)?;
    writer.flush()?;
    eprintln!("zcdecrypt-result: bytes={total} {}", primitive.log_fields());
    Ok(())
}

fn zc_tcpmux_xfer_push(
    host: &str,
    data_paths: &[ZcTcpmuxDataPath],
    source_path: Option<&str>,
    remote_dest: &str,
    ssh_command: &str,
    remote_path: &str,
    buffer_bytes: usize,
    lanes: usize,
    receive_listen_port_range: &str,
    token: Option<&str>,
    disable_authentication: bool,
    dry_run: bool,
    encryption: ZcTcpmuxEncryption,
    already_encrypted: bool,
    receive_already_encrypted: bool,
    receive_assembly: ZcTcpmuxReceiveAssembly,
    send_affinity: &ZcTcpmuxAffinityConfig,
    receive_affinity: &ZcTcpmuxAffinityConfig,
) -> io::Result<()> {
    if disable_authentication && token.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cannot combine --token and --disable-authentication",
        ));
    }
    if disable_authentication && encryption.requires_token() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--disable-authentication requires --encryption none",
        ));
    }
    if (already_encrypted || receive_already_encrypted) && encryption != ZcTcpmuxEncryption::Aes256
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--already-encrypted requires --encryption aes-256",
        ));
    }
    if !disable_authentication && token.is_none() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-xfer requires --token unless --disable-authentication is used",
        ));
    }
    if let Some(token) = token {
        zc_tcpmux_validate_token(token)?;
    }
    if lanes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--lanes must be greater than zero",
        ));
    }
    if data_paths.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-xfer requires at least one data path",
        ));
    }
    if data_paths.len() > lanes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!(
                "zc-tcpmux-xfer has {} data paths but only {lanes} lanes",
                data_paths.len()
            ),
        ));
    }
    let source_expected_bytes = source_path
        .map(|source_path| {
            fs::metadata(source_path).map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!("metadata for source {source_path}: {err}"),
                )
            })
        })
        .transpose()?
        .and_then(|metadata| metadata.file_type().is_file().then_some(metadata.len()));

    let mut remote_command = String::new();
    if let Some(parent) = zc_tcpmux_remote_parent(remote_dest) {
        remote_command.push_str("mkdir -p -- ");
        remote_command.push_str(&shell_quote(&parent));
        remote_command.push_str(" && ");
    }
    remote_command.push_str("exec ");
    remote_command.push_str(&shell_quote(remote_path));
    remote_command.push_str(" zc-tcpmux-receive --output ");
    remote_command.push_str(&shell_quote(remote_dest));
    if data_paths.len() == 1 {
        remote_command.push_str(" --listen-address ");
        remote_command.push_str(&shell_quote(&data_paths[0].receive_listen_address));
    } else {
        remote_command.push_str(" --listen-addresses ");
        remote_command.push_str(&shell_quote(
            &data_paths
                .iter()
                .map(|path| path.receive_listen_address.as_str())
                .collect::<Vec<_>>()
                .join(","),
        ));
    }
    remote_command.push_str(" --listen-port-range ");
    remote_command.push_str(&shell_quote(receive_listen_port_range));
    remote_command.push_str(" --buffer-bytes ");
    remote_command.push_str(&buffer_bytes.to_string());
    if let Some(expected_bytes) = source_expected_bytes {
        remote_command.push_str(" --expected-bytes ");
        remote_command.push_str(&expected_bytes.to_string());
    }
    remote_command.push_str(" --receive-assembly ");
    remote_command.push_str(receive_assembly.as_arg());
    remote_command.push_str(" --lanes ");
    remote_command.push_str(&lanes.to_string());
    remote_command.push_str(" --encryption ");
    remote_command.push_str(encryption.as_arg());
    if receive_affinity.pin_cpus {
        remote_command.push_str(" --pin-cpus");
    }
    if let Some(cpu_list) = receive_affinity.cpu_list_label.as_deref() {
        remote_command.push_str(" --cpu-list ");
        remote_command.push_str(&shell_quote(cpu_list));
    }
    if receive_already_encrypted {
        remote_command.push_str(" --already-encrypted");
    }
    if disable_authentication {
        remote_command.push_str(" --disable-authentication");
    } else if let Some(token) = token {
        remote_command.push_str(" --token ");
        remote_command.push_str(&shell_quote(token));
    }

    let shell_command = zc_tcpmux_ssh_shell_command(ssh_command, host, &remote_command);
    if dry_run {
        println!(
            "zc-tcpmux-xfer-dry-run: mode=push host={} paths={} source={} remote_dest={} \
             lanes={} expected_bytes={} receive_listen_port_range={} authentication={} \
             encryption={} already_encrypted={} receive_already_encrypted={} receive_assembly={} send_affinity={} receive_affinity={} control_command={} data_plane={}",
            host,
            zc_tcpmux_path_summary(data_paths),
            source_path.unwrap_or("-"),
            remote_dest,
            lanes,
            source_expected_bytes
                .map(|value| value.to_string())
                .unwrap_or_else(|| "-".to_string()),
            receive_listen_port_range,
            if disable_authentication {
                "disabled"
            } else {
                "token"
            },
            encryption.as_arg(),
            already_encrypted,
            receive_already_encrypted,
            receive_assembly.as_arg(),
            send_affinity.describe(),
            receive_affinity.describe(),
            shell_command,
            encryption.transport_label()
        );
        return Ok(());
    }

    let mut command = Command::new("sh");
    command.arg("-c").arg(&shell_command);
    command
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit());
    let mut child = command.spawn().map_err(|err| {
        io::Error::new(
            err.kind(),
            format!(
                "start zc-tcpmux remote receiver with control command {shell_command:?}: {err}"
            ),
        )
    })?;
    let stdout = child.stdout.take().ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::BrokenPipe,
            "zc-tcpmux remote receiver stdout was not captured",
        )
    })?;
    let mut ready_reader = BufReader::new(stdout);
    let mut ready_line = String::new();
    ready_reader.read_line(&mut ready_line)?;
    let ports = zc_tcpmux_parse_ready_ports(&ready_line)?;
    if ports.len() != lanes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "remote ready line returned {} ports but xfer expected {lanes}: {ready_line:?}",
                ports.len()
            ),
        ));
    }

    eprintln!(
        "zc-tcpmux-xfer: SSH control plane started receiver; payload transport is {}, not SSH, paths={} ports={} lanes={lanes}",
        encryption.transport_label(),
        zc_tcpmux_path_summary(data_paths),
        ports
            .iter()
            .map(u16::to_string)
            .collect::<Vec<_>>()
            .join(",")
    );
    let bytes = if let Some(source_path) = source_path {
        let source = fs::File::open(source_path).map_err(|err| {
            io::Error::new(err.kind(), format!("open source {source_path}: {err}"))
        })?;
        let source_metadata = source.metadata().map_err(|err| {
            io::Error::new(
                err.kind(),
                format!("metadata for source {source_path}: {err}"),
            )
        })?;
        if lanes == 1 {
            zc_tcpmux_copy_reader_to_tcp(
                source,
                &data_paths[0].data_host,
                ports[0],
                data_paths[0].local_data_address.as_deref(),
                token,
                encryption,
                already_encrypted,
                buffer_bytes,
            )?
        } else if source_metadata.file_type().is_file() {
            zc_tcpmux_copy_file_to_tcp_parallel(
                source,
                source_metadata.len(),
                data_paths,
                &ports,
                token,
                encryption,
                already_encrypted,
                buffer_bytes,
                send_affinity,
            )?
        } else {
            zc_tcpmux_copy_reader_to_tcp_parallel(
                source,
                data_paths,
                &ports,
                token,
                encryption,
                already_encrypted,
                buffer_bytes,
                send_affinity,
            )?
        }
    } else {
        let stdin = io::stdin().lock();
        if lanes == 1 {
            zc_tcpmux_copy_reader_to_tcp(
                stdin,
                &data_paths[0].data_host,
                ports[0],
                data_paths[0].local_data_address.as_deref(),
                token,
                encryption,
                already_encrypted,
                buffer_bytes,
            )?
        } else {
            zc_tcpmux_copy_reader_to_tcp_parallel(
                stdin,
                data_paths,
                &ports,
                token,
                encryption,
                already_encrypted,
                buffer_bytes,
                send_affinity,
            )?
        }
    };
    drop(ready_reader);

    let status = child.wait().map_err(|err| {
        io::Error::new(
            err.kind(),
            format!("wait for zc-tcpmux remote receiver {shell_command:?}: {err}"),
        )
    })?;
    if status.success() {
        eprintln!(
            "zc-tcpmux-xfer-result: mode=push bytes={bytes} lanes={lanes} paths={} receive_assembly={} encryption={} already_encrypted={} remote={host}:{remote_dest}",
            data_paths.len(),
            receive_assembly.as_arg(),
            encryption.as_arg(),
            already_encrypted
        );
        Ok(())
    } else {
        Err(io::Error::other(format!(
            "zc-tcpmux-xfer remote receive command exited with {status}"
        )))
    }
}

fn zc_tcpmux_default_xfer_lanes() -> usize {
    let cpus = thread::available_parallelism()
        .map(|count| count.get())
        .unwrap_or(ZC_TCPMUX_DEFAULT_MIN_LANES);
    cpus.saturating_mul(2)
        .checked_next_power_of_two()
        .unwrap_or(ZC_TCPMUX_DEFAULT_MAX_LANES)
        .clamp(ZC_TCPMUX_DEFAULT_MIN_LANES, ZC_TCPMUX_DEFAULT_MAX_LANES)
}

fn zc_tcpmux_default_sharded_xfer_lanes() -> usize {
    let cpus = thread::available_parallelism()
        .map(|count| count.get())
        .unwrap_or(ZC_TCPMUX_DEFAULT_MIN_LANES);
    cpus.saturating_mul(2).clamp(
        ZC_TCPMUX_DEFAULT_MIN_LANES,
        ZC_TCPMUX_DEFAULT_SHARDED_MAX_LANES,
    )
}

fn zc_tcpmux_xfer(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut args = args.peekable();
    if matches!(
        args.peek().map(String::as_str),
        None | Some("help" | "--help" | "-h")
    ) {
        println!(
            "zc-tcpmux-xfer - SSH-coordinated TCP transfer\n\
	             \n\
             zc-tcpmux-xfer HOST:DEST\n\
	             zc-tcpmux-xfer SRC HOST:DEST\n\
	             \n\
	             SSH is only used to coordinate the remote receiver and pass a one-use token.\n\
	             Payload bytes are NOT sent over SSH. AES-256-GCM is the default;\n\
	             use --encryption none only for explicit plaintext tests.\n\
                     Use --local-data-address IP with --data-host IP to bind the sender side to a NIC-local address.\n\
                     Use --data-hosts A,B --local-data-addresses X,Y --receive-listen-addresses A,B for multipath.\n\
                     Use --receive-assembly shards to keep lane-contiguous shard files for faster materialization."
        );
        return Ok(());
    }
    let mut mode = None::<String>;
    let mut positional = Vec::<String>::new();
    let mut source = None::<String>;
    let mut sink = None::<String>;
    let mut lanes = zc_tcpmux_default_xfer_lanes();
    let mut lanes_explicit = false;
    let mut base_port = 9000u16;
    let mut remote_path = "zcutils".to_string();
    let mut ssh_command = "ssh".to_string();
    let mut dry_run = false;
    let mut encryption = ZcTcpmuxEncryption::Aes256;
    let mut already_encrypted = false;
    let mut token = None::<String>;
    let mut disable_authentication = false;
    let mut receive_listen_address = "0.0.0.0".to_string();
    let mut receive_listen_port_range = "0".to_string();
    let mut receive_buffer_bytes = ZC_TCPMUX_DEFAULT_CHUNK_BYTES;
    let mut receive_already_encrypted = false;
    let mut receive_assembly = ZcTcpmuxReceiveAssembly::Direct;
    let mut data_host = None::<String>;
    let mut data_hosts = None::<Vec<String>>;
    let mut local_data_address = None::<String>;
    let mut local_data_addresses = None::<Vec<String>>;
    let mut receive_listen_addresses = None::<Vec<String>>;
    let mut send_pin_cpus = false;
    let mut receive_pin_cpus = false;
    let mut send_cpu_list = None::<String>;
    let mut receive_cpu_list = None::<String>;

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "push" | "pull" if mode.is_none() && positional.is_empty() => mode = Some(arg),
            "--source" => source = Some(next_flag_value(&mut args, "--source")?),
            "--sink" => sink = Some(next_flag_value(&mut args, "--sink")?),
            "--lanes" => {
                lanes = parse_usize_value(&next_flag_value(&mut args, "--lanes")?, "--lanes")?;
                lanes_explicit = true;
            }
            "--base-port" => {
                base_port =
                    parse_u16_value(&next_flag_value(&mut args, "--base-port")?, "--base-port")?
            }
            "--remote-path" => remote_path = next_flag_value(&mut args, "--remote-path")?,
            "--ssh-command" => ssh_command = next_flag_value(&mut args, "--ssh-command")?,
            "--dry-run" => dry_run = true,
            "--unencrypted" => encryption = ZcTcpmuxEncryption::None,
            "--encrypt" => encryption = ZcTcpmuxEncryption::Aes256,
            "--encryption" | "--receive-encryption" => {
                encryption = ZcTcpmuxEncryption::parse(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--already-encrypted" => already_encrypted = true,
            "--receive-already-encrypted" => receive_already_encrypted = true,
            "--token" | "--receive-token" => token = Some(next_flag_value(&mut args, &arg)?),
            "--disable-authentication" | "--receive-disable-authentication" => {
                disable_authentication = true
            }
            "--data-host" => data_host = Some(next_flag_value(&mut args, "--data-host")?),
            "--data-hosts" => {
                data_hosts = Some(zc_tcpmux_csv_values(
                    &next_flag_value(&mut args, &arg)?,
                    &arg,
                )?)
            }
            "--local-data-address" | "--send-local-address" | "--source-address" => {
                local_data_address = Some(next_flag_value(&mut args, &arg)?)
            }
            "--local-data-addresses" | "--send-local-addresses" | "--source-addresses" => {
                local_data_addresses = Some(zc_tcpmux_csv_values(
                    &next_flag_value(&mut args, &arg)?,
                    &arg,
                )?)
            }
            "--receive-listen-address" => {
                receive_listen_address = next_flag_value(&mut args, "--receive-listen-address")?
            }
            "--receive-listen-addresses" => {
                receive_listen_addresses = Some(zc_tcpmux_csv_values(
                    &next_flag_value(&mut args, &arg)?,
                    &arg,
                )?)
            }
            "--receive-listen-port-range" => {
                receive_listen_port_range =
                    next_flag_value(&mut args, "--receive-listen-port-range")?
            }
            "--receive-buffer-bytes" | "--receive-chunk-bytes" => {
                receive_buffer_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--receive-assembly" => {
                receive_assembly =
                    ZcTcpmuxReceiveAssembly::parse(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--receive-ordered-assembly" => receive_assembly = ZcTcpmuxReceiveAssembly::Ordered,
            "--pin-cpus" => {
                send_pin_cpus = true;
                receive_pin_cpus = true;
            }
            "--send-pin-cpus" => send_pin_cpus = true,
            "--receive-pin-cpus" => receive_pin_cpus = true,
            "--cpu-list" | "--pin-cpu-list" => {
                let value = next_flag_value(&mut args, &arg)?;
                send_cpu_list = Some(value.clone());
                receive_cpu_list = Some(value);
            }
            "--send-cpu-list" | "--send-pin-cpu-list" => {
                send_cpu_list = Some(next_flag_value(&mut args, &arg)?)
            }
            "--receive-cpu-list" | "--receive-pin-cpu-list" => {
                receive_cpu_list = Some(next_flag_value(&mut args, &arg)?)
            }
            other => {
                if other.starts_with('-') {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("unknown zcxfer option {other:?}"),
                    ));
                }
                positional.push(other.to_string());
            }
        }
    }
    if !lanes_explicit && receive_assembly == ZcTcpmuxReceiveAssembly::Shards {
        lanes = zc_tcpmux_default_sharded_xfer_lanes();
    }

    if disable_authentication && token.is_some() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "cannot combine --token and --disable-authentication",
        ));
    }
    if disable_authentication && encryption.requires_token() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--disable-authentication requires --encryption none",
        ));
    }
    if (already_encrypted || receive_already_encrypted) && encryption != ZcTcpmuxEncryption::Aes256
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--already-encrypted requires --encryption aes-256",
        ));
    }
    if !disable_authentication && token.is_none() {
        token = Some(zc_tcpmux_generate_token()?);
    }
    let send_affinity = ZcTcpmuxAffinityConfig::from_cli(
        send_pin_cpus,
        send_cpu_list.as_deref(),
        "--send-cpu-list",
    )?;
    let receive_affinity = ZcTcpmuxAffinityConfig::from_cli(
        receive_pin_cpus,
        receive_cpu_list.as_deref(),
        "--receive-cpu-list",
    )?;

    if source.is_some() || sink.is_some() {
        let mode = mode.unwrap_or_else(|| "push".to_string());
        let host = positional.first().ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                "zcxfer with --source/--sink requires HOST",
            )
        })?;
        let source = source.unwrap_or_else(|| "zccat".to_string());
        let sink = sink.unwrap_or_else(|| "zcsink --consume count".to_string());
        println!(
            "zc-tcpmux-xfer-plan: mode={mode} host={host} lanes={lanes} base_port={base_port} \
             ssh_command={ssh_command:?} remote_path={remote_path:?} source={source:?} sink={sink:?}"
        );
        return Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "zc-tcpmux-xfer --source/--sink orchestration is planned but not implemented yet",
        ));
    }

    match (mode.as_deref(), positional.as_slice()) {
        (None, [remote]) => {
            let (host, remote_dest) = zc_tcpmux_endpoint(remote).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "single-argument zc-tcpmux-xfer requires HOST:DEST",
                )
            })?;
            let data_paths = zc_tcpmux_build_data_paths(
                host,
                data_host.as_deref(),
                data_hosts.as_deref(),
                local_data_address.as_deref(),
                local_data_addresses.as_deref(),
                &receive_listen_address,
                receive_listen_addresses.as_deref(),
                lanes,
            )?;
            zc_tcpmux_xfer_push(
                host,
                &data_paths,
                None,
                remote_dest,
                &ssh_command,
                &remote_path,
                receive_buffer_bytes,
                lanes,
                &receive_listen_port_range,
                token.as_deref(),
                disable_authentication,
                dry_run,
                encryption,
                already_encrypted,
                receive_already_encrypted,
                receive_assembly,
                &send_affinity,
                &receive_affinity,
            )
        }
        (Some("push"), [src, remote]) => {
            let (host, remote_dest) = zc_tcpmux_endpoint(remote).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "zc-tcpmux-xfer push requires DEST as HOST:PATH",
                )
            })?;
            let data_paths = zc_tcpmux_build_data_paths(
                host,
                data_host.as_deref(),
                data_hosts.as_deref(),
                local_data_address.as_deref(),
                local_data_addresses.as_deref(),
                &receive_listen_address,
                receive_listen_addresses.as_deref(),
                lanes,
            )?;
            zc_tcpmux_xfer_push(
                host,
                &data_paths,
                Some(src),
                remote_dest,
                &ssh_command,
                &remote_path,
                receive_buffer_bytes,
                lanes,
                &receive_listen_port_range,
                token.as_deref(),
                disable_authentication,
                dry_run,
                encryption,
                already_encrypted,
                receive_already_encrypted,
                receive_assembly,
                &send_affinity,
                &receive_affinity,
            )
        }
        (None, [src, remote]) if zc_tcpmux_endpoint(remote).is_some() => {
            let (host, remote_dest) = zc_tcpmux_endpoint(remote).expect("checked endpoint");
            let data_paths = zc_tcpmux_build_data_paths(
                host,
                data_host.as_deref(),
                data_hosts.as_deref(),
                local_data_address.as_deref(),
                local_data_addresses.as_deref(),
                &receive_listen_address,
                receive_listen_addresses.as_deref(),
                lanes,
            )?;
            zc_tcpmux_xfer_push(
                host,
                &data_paths,
                Some(src),
                remote_dest,
                &ssh_command,
                &remote_path,
                receive_buffer_bytes,
                lanes,
                &receive_listen_port_range,
                token.as_deref(),
                disable_authentication,
                dry_run,
                encryption,
                already_encrypted,
                receive_already_encrypted,
                receive_assembly,
                &send_affinity,
                &receive_affinity,
            )
        }
        (Some("pull"), [remote, dest]) => {
            let (host, remote_src) = zc_tcpmux_endpoint(remote).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "zc-tcpmux-xfer pull requires SRC as HOST:PATH",
                )
            })?;
            let _ = (host, remote_src, dest, dry_run);
            Err(io::Error::new(
                io::ErrorKind::Unsupported,
                "zc-tcpmux-xfer pull is not implemented yet",
            ))
        }
        (None, [remote, dest]) if zc_tcpmux_endpoint(remote).is_some() => {
            let (host, remote_src) = zc_tcpmux_endpoint(remote).expect("checked endpoint");
            let _ = (host, remote_src, dest, dry_run);
            Err(io::Error::new(
                io::ErrorKind::Unsupported,
                "zc-tcpmux-xfer pull is not implemented yet",
            ))
        }
        (Some("push"), [remote]) => {
            let (host, remote_dest) = zc_tcpmux_endpoint(remote).ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "zc-tcpmux-xfer push with stdin requires HOST:DEST",
                )
            })?;
            let data_paths = zc_tcpmux_build_data_paths(
                host,
                data_host.as_deref(),
                data_hosts.as_deref(),
                local_data_address.as_deref(),
                local_data_addresses.as_deref(),
                &receive_listen_address,
                receive_listen_addresses.as_deref(),
                lanes,
            )?;
            zc_tcpmux_xfer_push(
                host,
                &data_paths,
                None,
                remote_dest,
                &ssh_command,
                &remote_path,
                receive_buffer_bytes,
                lanes,
                &receive_listen_port_range,
                token.as_deref(),
                disable_authentication,
                dry_run,
                encryption,
                already_encrypted,
                receive_already_encrypted,
                receive_assembly,
                &send_affinity,
                &receive_affinity,
            )
        }
        (Some("pull"), _) => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zc-tcpmux-xfer pull requires HOST:SRC DEST",
        )),
        (Some(other), _) => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("unknown zc-tcpmux-xfer mode {other:?}; use push, pull, or help"),
        )),
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "usage: zc-tcpmux-xfer HOST:DEST | zc-tcpmux-xfer SRC HOST:DEST",
        )),
    }
}

fn zcgrep(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut pattern = None::<Vec<u8>>;
    let mut invert_match = false;
    let mut count_only = false;
    let mut primitive = ZcPrimitiveTopology::default();
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            _ if primitive.parse_common_flag(&mut args, &arg)? => {}
            "--pattern" => pattern = Some(next_flag_value(&mut args, "--pattern")?.into_bytes()),
            "--invert-match" => invert_match = true,
            "--count-only" => count_only = true,
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcgrep option {other:?}"),
                ));
            }
        }
    }
    primitive.activate_byte_compatible("zcgrep")?;
    let pattern = pattern.ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcgrep requires --pattern <bytes>",
        )
    })?;
    if pattern.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "zcgrep --pattern must not be empty",
        ));
    }

    let mut input = BufReader::new(io::stdin().lock());
    let mut output = BufWriter::new(io::stdout().lock());
    let mut line = Vec::new();
    let mut matches = 0usize;
    loop {
        line.clear();
        let n = input.read_until(b'\n', &mut line)?;
        if n == 0 {
            break;
        }
        let found = line.windows(pattern.len()).any(|window| window == pattern);
        if found ^ invert_match {
            matches += 1;
            if !count_only {
                output.write_all(&line)?;
            }
        }
    }
    if count_only {
        writeln!(output, "{matches}")?;
    }
    output.flush()
}

fn zcstat(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut pass_through = false;
    let mut buffer_bytes = 1024 * 1024usize;
    let mut primitive = ZcPrimitiveTopology::default();
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            _ if primitive.parse_common_flag(&mut args, &arg)? => {}
            "--pass-through" => pass_through = true,
            "--buffer-bytes" => {
                buffer_bytes = parse_size_arg(
                    &next_flag_value(&mut args, "--buffer-bytes")?,
                    "--buffer-bytes",
                )?
            }
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcstat option {other:?}"),
                ));
            }
        }
    }
    primitive.activate_byte_compatible("zcstat")?;
    let mut input = io::stdin().lock();
    let mut output = BufWriter::new(io::stdout().lock());
    let mut buf = vec![0u8; buffer_bytes.max(4096)];
    let mut total = 0usize;
    let mut chunks = 0usize;
    let started = Instant::now();
    loop {
        let n = input.read(&mut buf)?;
        if n == 0 {
            break;
        }
        total += n;
        chunks += 1;
        if pass_through {
            output.write_all(&buf[..n])?;
        }
    }
    if pass_through {
        output.flush()?;
    }
    let elapsed = started.elapsed();
    eprintln!(
        "zcstat-result: bytes={total} chunks={chunks} seconds={:.6} {}",
        elapsed.as_secs_f64(),
        primitive.log_fields()
    );
    print_tcp_bench_result("zcstat", total, elapsed);
    Ok(())
}

fn zcmeter(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut pass_through = true;
    let mut buffer_bytes = 1024 * 1024usize;
    let mut interval = Duration::from_secs(1);
    let mut label = "zcmeter".to_string();
    let mut primitive = ZcPrimitiveTopology::default();
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            _ if primitive.parse_common_flag(&mut args, &arg)? => {}
            "--pass-through" => pass_through = true,
            "--no-pass-through" | "--consume" => pass_through = false,
            "--buffer-bytes" | "--chunk-bytes" => {
                buffer_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--interval-ms" => {
                let ms = parse_u64_value(
                    &next_flag_value(&mut args, "--interval-ms")?,
                    "--interval-ms",
                )?;
                if ms == 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "--interval-ms must be greater than zero",
                    ));
                }
                interval = Duration::from_millis(ms);
            }
            "--label" => label = next_flag_value(&mut args, "--label")?,
            "help" | "--help" | "-h" => {
                println!(
                    "zcmeter - pass stdin to stdout while reporting byte rate to stderr\n\
                     \n\
                     zcmeter [--buffer-bytes BYTES] [--interval-ms MS] [--label NAME]\n\
                     zcmeter --no-pass-through"
                );
                return Ok(());
            }
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcmeter option {other:?}"),
                ));
            }
        }
    }
    primitive.activate_byte_compatible("zcmeter")?;

    let mut input = io::stdin().lock();
    let mut output = BufWriter::new(io::stdout().lock());
    let mut buf = vec![0u8; buffer_bytes.max(4096)];
    let started = Instant::now();
    let mut last_tick = started;
    let mut last_total = 0u64;
    let mut total = 0u64;
    let mut chunks = 0u64;

    loop {
        let n = input.read(&mut buf)?;
        if n == 0 {
            break;
        }
        if pass_through {
            output.write_all(&buf[..n])?;
        }
        total = total.checked_add(n as u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcmeter byte count overflow")
        })?;
        chunks = chunks.checked_add(1).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcmeter chunk count overflow")
        })?;

        let now = Instant::now();
        if now.duration_since(last_tick) >= interval {
            let elapsed = now.duration_since(last_tick).as_secs_f64();
            let interval_bytes = total.saturating_sub(last_total);
            let bytes_per_second = if elapsed > 0.0 {
                interval_bytes as f64 / elapsed
            } else {
                0.0
            };
            eprintln!(
                "{label}: received_bytes={total} interval_bytes={interval_bytes} bytes_per_second={bytes_per_second:.0} total_seconds={:.3}",
                now.duration_since(started).as_secs_f64()
            );
            last_tick = now;
            last_total = total;
        }
    }
    if pass_through {
        output.flush()?;
    }

    let finished = Instant::now();
    let total_seconds = finished.duration_since(started).as_secs_f64();
    let interval_seconds = finished.duration_since(last_tick).as_secs_f64();
    let interval_bytes = total.saturating_sub(last_total);
    let bytes_per_second = if interval_seconds > 0.0 {
        interval_bytes as f64 / interval_seconds
    } else {
        0.0
    };
    let average_bytes_per_second = if total_seconds > 0.0 {
        total as f64 / total_seconds
    } else {
        0.0
    };
    eprintln!(
        "{label}-final: received_bytes={total} interval_bytes={interval_bytes} bytes_per_second={bytes_per_second:.0} average_bytes_per_second={average_bytes_per_second:.0} chunks={chunks} total_seconds={total_seconds:.3} {}",
        primitive.log_fields()
    );
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ZcWritebenchMode {
    SameFile,
    Shards,
}

impl ZcWritebenchMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "same-file" | "same" | "pwrite" | "direct" => Ok(Self::SameFile),
            "shards" | "shard-files" | "per-lane" | "per-worker" => Ok(Self::Shards),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown zcwritebench mode {other:?}; use same-file or shards"),
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::SameFile => "same-file",
            Self::Shards => "shards",
        }
    }
}

fn zcwritebench_shard_path(base: &Path, worker: usize) -> PathBuf {
    PathBuf::from(format!("{}.lane{worker:04}", base.display()))
}

fn zcwritebench_worker(
    worker: usize,
    workers: usize,
    mode: ZcWritebenchMode,
    output: PathBuf,
    same_file: Option<Arc<fs::File>>,
    total_bytes: u64,
    chunk_bytes: usize,
    affinity: ZcTcpmuxAffinityConfig,
    start_barrier: Arc<Barrier>,
) -> io::Result<(u64, u64)> {
    let _affinity_result = affinity.pin_current_thread("zcwritebench", worker);
    let chunk_u64 = u64::try_from(chunk_bytes)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "chunk size exceeds u64"))?;
    let worker_u64 = u64::try_from(worker)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "worker exceeds u64 range"))?;
    let workers_u64 = u64::try_from(workers)
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "workers exceeds u64 range"))?;
    let stride = chunk_u64.checked_mul(workers_u64).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "zcwritebench stride overflow")
    })?;
    let mut logical_offset = chunk_u64.checked_mul(worker_u64).ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "zcwritebench offset overflow")
    })?;
    let mut local_offset = 0u64;
    let mut buf = vec![worker as u8; chunk_bytes.max(4096)];
    let shard_file = if mode == ZcWritebenchMode::Shards {
        let shard_path = zcwritebench_shard_path(&output, worker);
        let file = OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .read(true)
            .open(&shard_path)?;
        Some(file)
    } else {
        None
    };
    start_barrier.wait();

    let mut bytes = 0u64;
    let mut chunks = 0u64;
    while logical_offset < total_bytes {
        let len = total_bytes.saturating_sub(logical_offset).min(chunk_u64) as usize;
        if len < buf.len() {
            buf[len..].fill(0);
        }
        match mode {
            ZcWritebenchMode::SameFile => {
                let file = same_file.as_ref().ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "same-file mode missing file")
                })?;
                zc_write_all_at(file, &buf[..len], logical_offset)?;
            }
            ZcWritebenchMode::Shards => {
                let file = shard_file.as_ref().ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidInput, "shards mode missing file")
                })?;
                zc_write_all_at(file, &buf[..len], local_offset)?;
                local_offset = local_offset.checked_add(len as u64).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::InvalidData, "shard offset overflow")
                })?;
            }
        }
        bytes = bytes.checked_add(len as u64).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcwritebench byte count overflow",
            )
        })?;
        chunks = chunks.checked_add(1).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                "zcwritebench chunk count overflow",
            )
        })?;
        logical_offset = logical_offset.checked_add(stride).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcwritebench offset overflow")
        })?;
    }
    Ok((bytes, chunks))
}

fn zcwritebench(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut output = PathBuf::from("/dev/shm/zcwritebench.out");
    let mut mode = ZcWritebenchMode::SameFile;
    let mut workers = 64usize;
    let mut total_bytes = 20u64 * 1024 * 1024 * 1024;
    let mut chunk_bytes = 1024 * 1024usize;
    let mut pin_cpus = false;
    let mut cpu_list: Option<String> = None;
    let mut keep = false;
    let mut args = args.peekable();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--output" | "-o" => output = PathBuf::from(next_flag_value(&mut args, &arg)?),
            "--mode" => mode = ZcWritebenchMode::parse(&next_flag_value(&mut args, &arg)?)?,
            "--workers" | "--lanes" => {
                workers = parse_usize_value(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--total-bytes" | "--bytes" => {
                total_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)? as u64
            }
            "--chunk-bytes" | "--buffer-bytes" => {
                chunk_bytes = parse_size_arg(&next_flag_value(&mut args, &arg)?, &arg)?
            }
            "--pin-cpus" => pin_cpus = true,
            "--cpu-list" => cpu_list = Some(next_flag_value(&mut args, "--cpu-list")?),
            "--keep" => keep = true,
            "help" | "--help" | "-h" => {
                println!(
                    "zcwritebench - benchmark receive-side file materialization\n\
                     \n\
                     zcwritebench [--mode same-file|shards] [--output PATH]\n\
                     \t[--workers N] [--total-bytes BYTES] [--chunk-bytes BYTES]\n\
                     \t[--pin-cpus] [--cpu-list LIST] [--keep]\n\
                     \n\
                     same-file matches zc-tcpmux direct assembly: many workers pwrite\n\
                     disjoint chunks into one pre-sized output file. shards writes each\n\
                     worker's chunks into a separate file to expose single-inode limits."
                );
                return Ok(());
            }
            other => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown zcwritebench option {other:?}"),
                ));
            }
        }
    }
    if workers == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--workers must be greater than zero",
        ));
    }
    if chunk_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "--chunk-bytes must be greater than zero",
        ));
    }

    let affinity = ZcTcpmuxAffinityConfig::from_cli(pin_cpus, cpu_list.as_deref(), "--cpu-list")?;
    let same_file = if mode == ZcWritebenchMode::SameFile {
        let file = OpenOptions::new()
            .create(true)
            .truncate(true)
            .write(true)
            .read(true)
            .open(&output)?;
        file.set_len(total_bytes)?;
        Some(Arc::new(file))
    } else {
        for worker in 0..workers {
            let path = zcwritebench_shard_path(&output, worker);
            let _ = fs::remove_file(path);
        }
        None
    };

    let start_barrier = Arc::new(Barrier::new(workers + 1));
    let mut handles = Vec::with_capacity(workers);
    for worker in 0..workers {
        let output = output.clone();
        let same_file = same_file.clone();
        let affinity = affinity.clone();
        let start_barrier = start_barrier.clone();
        handles.push(thread::spawn(move || {
            zcwritebench_worker(
                worker,
                workers,
                mode,
                output,
                same_file,
                total_bytes,
                chunk_bytes,
                affinity,
                start_barrier,
            )
        }));
    }
    start_barrier.wait();
    let started = Instant::now();

    let mut bytes = 0u64;
    let mut chunks = 0u64;
    for (worker, handle) in handles.into_iter().enumerate() {
        let (worker_bytes, worker_chunks) = handle
            .join()
            .map_err(|_| io::Error::other(format!("zcwritebench worker {worker} panicked")))??;
        bytes = bytes.checked_add(worker_bytes).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcwritebench total overflow")
        })?;
        chunks = chunks.checked_add(worker_chunks).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "zcwritebench chunk overflow")
        })?;
    }
    let elapsed = started.elapsed();
    if bytes != total_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("zcwritebench wrote {bytes} bytes but expected {total_bytes}"),
        ));
    }
    if !keep {
        match mode {
            ZcWritebenchMode::SameFile => {
                let _ = fs::remove_file(&output);
            }
            ZcWritebenchMode::Shards => {
                for worker in 0..workers {
                    let _ = fs::remove_file(zcwritebench_shard_path(&output, worker));
                }
            }
        }
    }
    eprintln!(
        "zcwritebench-result: mode={} output={} workers={workers} bytes={bytes} chunks={chunks} chunk_bytes={chunk_bytes} keep={keep} affinity={} seconds={:.6}",
        mode.as_str(),
        output.display(),
        affinity.describe(),
        elapsed.as_secs_f64()
    );
    let print_bytes = usize::try_from(bytes).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            "zcwritebench byte count exceeds usize",
        )
    })?;
    print_tcp_bench_result("zcwritebench", print_bytes, elapsed);
    Ok(())
}

fn zcnc(args: impl Iterator<Item = String>) -> io::Result<()> {
    let mut args = args.peekable();
    let mode = args.next().unwrap_or_else(|| "probe".to_string());
    match mode.as_str() {
        "probe" => probe(),
        "listen" => {
            let mut bind = "0.0.0.0".to_string();
            let mut port = 8000u16;
            let mut connections = 1usize;
            let mut expected_bytes = 1024 * 1024 * 1024usize;
            let mut workers = 0usize;
            let mut recv_bytes = 1024 * 1024usize;
            let mut ring_entries = 4096u32;
            let mut recv = ZcRecvOptions {
                mode: ZcRecvMode::Auto,
                ifname: None,
                rxq: 0,
                rxq_count: None,
                must_zero_copy: false,
            };
            while let Some(arg) = args.next() {
                match arg.as_str() {
                    "--bind" => bind = next_flag_value(&mut args, "--bind")?,
                    "--port" => {
                        port = parse_u16_value(&next_flag_value(&mut args, "--port")?, "--port")?
                    }
                    "--connections" => {
                        connections = parse_usize_value(
                            &next_flag_value(&mut args, "--connections")?,
                            "--connections",
                        )?
                    }
                    "--expected-bytes" => {
                        expected_bytes = parse_size_arg(
                            &next_flag_value(&mut args, "--expected-bytes")?,
                            "--expected-bytes",
                        )?
                    }
                    "--workers" => {
                        workers = parse_usize_value(
                            &next_flag_value(&mut args, "--workers")?,
                            "--workers",
                        )?
                    }
                    "--recv-bytes" => {
                        recv_bytes = parse_size_arg(
                            &next_flag_value(&mut args, "--recv-bytes")?,
                            "--recv-bytes",
                        )?
                    }
                    "--ring-entries" => {
                        ring_entries = parse_u32_value(
                            &next_flag_value(&mut args, "--ring-entries")?,
                            "--ring-entries",
                        )?
                    }
                    "--recv-mode" => {
                        recv.mode = ZcRecvMode::parse(&next_flag_value(&mut args, "--recv-mode")?)?
                    }
                    "--ifname" => recv.ifname = Some(next_flag_value(&mut args, "--ifname")?),
                    "--rxq" => {
                        recv.rxq = parse_u32_value(&next_flag_value(&mut args, "--rxq")?, "--rxq")?
                    }
                    "--rxq-count" => {
                        recv.rxq_count = Some(parse_usize_value(
                            &next_flag_value(&mut args, "--rxq-count")?,
                            "--rxq-count",
                        )?)
                    }
                    "--must-zero-copy" => recv.must_zero_copy = true,
                    "--zero-copy-receive" | "--zero-copy" => {
                        let policy = ZcZeroCopyPolicy::parse(&next_flag_value(
                            &mut args,
                            "--zero-copy-receive",
                        )?)?;
                        policy.apply_to_recv(&mut recv);
                    }
                    other => {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            format!("unknown zcnc listen option {other:?}"),
                        ));
                    }
                }
            }
            tcp_bench_uring_mux_server_auto_zcrx(
                &bind,
                port,
                1,
                connections,
                expected_bytes,
                workers,
                recv_bytes,
                ring_entries,
                recv,
            )
        }
        "connect" => {
            let mut peer_addr = "127.0.0.1".to_string();
            let mut port = 8000u16;
            let mut connections = 1usize;
            let mut bytes_per_connection = 1024 * 1024 * 1024usize;
            let mut chunk_bytes = 1024 * 1024usize;
            let mut pipeline = 4usize;
            let mut workers = 0usize;
            let mut ring_entries = 4096u32;
            let mut send_mode = UringSendMode::SendZc;
            let mut zero_copy_policy = ZcZeroCopyPolicy::Auto;
            while let Some(arg) = args.next() {
                match arg.as_str() {
                    "--peer-addr" => peer_addr = next_flag_value(&mut args, "--peer-addr")?,
                    "--port" => {
                        port = parse_u16_value(&next_flag_value(&mut args, "--port")?, "--port")?
                    }
                    "--connections" => {
                        connections = parse_usize_value(
                            &next_flag_value(&mut args, "--connections")?,
                            "--connections",
                        )?
                    }
                    "--bytes-per-connection" => {
                        bytes_per_connection = parse_size_arg(
                            &next_flag_value(&mut args, "--bytes-per-connection")?,
                            "--bytes-per-connection",
                        )?
                    }
                    "--chunk-bytes" => {
                        chunk_bytes = parse_size_arg(
                            &next_flag_value(&mut args, "--chunk-bytes")?,
                            "--chunk-bytes",
                        )?
                    }
                    "--pipeline" => {
                        pipeline = parse_usize_value(
                            &next_flag_value(&mut args, "--pipeline")?,
                            "--pipeline",
                        )?
                    }
                    "--workers" => {
                        workers = parse_usize_value(
                            &next_flag_value(&mut args, "--workers")?,
                            "--workers",
                        )?
                    }
                    "--ring-entries" => {
                        ring_entries = parse_u32_value(
                            &next_flag_value(&mut args, "--ring-entries")?,
                            "--ring-entries",
                        )?
                    }
                    "--send-mode" => {
                        send_mode =
                            UringSendMode::parse(&next_flag_value(&mut args, "--send-mode")?)?;
                        zero_copy_policy = if send_mode.uses_zc() {
                            ZcZeroCopyPolicy::Required
                        } else {
                            ZcZeroCopyPolicy::Off
                        };
                    }
                    "--zero-copy-send" | "--zero-copy" => {
                        zero_copy_policy = ZcZeroCopyPolicy::parse(&next_flag_value(
                            &mut args,
                            "--zero-copy-send",
                        )?)?;
                        send_mode = zero_copy_policy.send_mode();
                    }
                    other => {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            format!("unknown zcnc connect option {other:?}"),
                        ));
                    }
                }
            }
            tcp_bench_uring_mux_send_with_policy(
                &peer_addr,
                port,
                1,
                connections,
                bytes_per_connection,
                chunk_bytes,
                pipeline,
                workers,
                ring_entries,
                send_mode,
                zero_copy_policy,
            )
        }
        other => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("unknown zcnc mode {other:?}; use probe, listen, or connect"),
        )),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ZcPlanMode {
    Stripe,
    Mirror,
    Raid10,
    Spill,
    Passthrough,
}

impl ZcPlanMode {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "stripe" | "raid0" => Ok(Self::Stripe),
            "mirror" | "raid1" => Ok(Self::Mirror),
            "raid10" | "raid-10" | "raid1+0" => Ok(Self::Raid10),
            "spill" | "tier-spill" => Ok(Self::Spill),
            "passthrough" | "pass" => Ok(Self::Passthrough),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "unknown plan mode {other:?}; use stripe, mirror, raid10, spill, or passthrough"
                ),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Stripe => "stripe",
            Self::Mirror => "mirror",
            Self::Raid10 => "raid10",
            Self::Spill => "spill",
            Self::Passthrough => "passthrough",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ZcPlanOperationMix {
    Read,
    Write,
    Mixed,
}

impl ZcPlanOperationMix {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "read" | "reads" => Ok(Self::Read),
            "write" | "writes" => Ok(Self::Write),
            "mixed" | "readwrite" | "read-write" | "rw" => Ok(Self::Mixed),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unknown operation mix {other:?}; use read, write, or mixed"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::Write => "write",
            Self::Mixed => "mixed",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ZcPlanObjective {
    LowLatency,
    MaxIops,
    MaxGbit,
    Balanced,
}

impl ZcPlanObjective {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "low-latency" | "latency" | "low_latency" => Ok(Self::LowLatency),
            "max-iops" | "iops" | "max_iops" => Ok(Self::MaxIops),
            "max-gbit" | "gbit" | "bandwidth" | "throughput" | "max_gbit" => Ok(Self::MaxGbit),
            "balanced" | "balance" => Ok(Self::Balanced),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "unknown objective {other:?}; use low-latency, max-iops, max-gbit, or balanced"
                ),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::LowLatency => "low-latency",
            Self::MaxIops => "max-iops",
            Self::MaxGbit => "max-gbit",
            Self::Balanced => "balanced",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ZcPlanTransport {
    TcpMux,
    LibfabricSockets,
    LibfabricTcp,
    LibfabricEfa,
    LibfabricEfaDirect,
    LibfabricVerbs,
    LibfabricShm,
}

impl ZcPlanTransport {
    fn parse(value: &str) -> io::Result<Self> {
        match value {
            "" | "tcp" | "tcp-mux" | "tcpmux" | "mux" => Ok(Self::TcpMux),
            "libfabric" | "ofi" | "libfabric-sockets" | "ofi-sockets" | "sockets" => {
                Ok(Self::LibfabricSockets)
            }
            "libfabric-tcp" | "ofi-tcp" => Ok(Self::LibfabricTcp),
            "libfabric-efa" | "ofi-efa" | "efa" => Ok(Self::LibfabricEfa),
            "libfabric-efa-direct" | "ofi-efa-direct" | "efa-direct" => {
                Ok(Self::LibfabricEfaDirect)
            }
            "libfabric-verbs" | "ofi-verbs" | "verbs" | "roce" | "rdma-roce" => {
                Ok(Self::LibfabricVerbs)
            }
            "libfabric-shm" | "ofi-shm" | "shm" => Ok(Self::LibfabricShm),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "unknown transport {other:?}; use tcp-mux, libfabric-sockets, \
                     libfabric-tcp, libfabric-efa, libfabric-efa-direct, \
                     libfabric-verbs, or libfabric-shm"
                ),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::TcpMux => "tcp-mux",
            Self::LibfabricSockets => "libfabric-sockets",
            Self::LibfabricTcp => "libfabric-tcp",
            Self::LibfabricEfa => "libfabric-efa",
            Self::LibfabricEfaDirect => "libfabric-efa-direct",
            Self::LibfabricVerbs => "libfabric-verbs",
            Self::LibfabricShm => "libfabric-shm",
        }
    }

    fn is_libfabric(self) -> bool {
        !matches!(self, Self::TcpMux)
    }

    fn provider(self) -> Option<&'static str> {
        match self {
            Self::TcpMux => None,
            Self::LibfabricSockets => Some("sockets"),
            Self::LibfabricTcp => Some("tcp"),
            Self::LibfabricEfa | Self::LibfabricEfaDirect => Some("efa"),
            Self::LibfabricVerbs => Some("verbs"),
            Self::LibfabricShm => Some("shm"),
        }
    }

    fn endpoint(self) -> &'static str {
        match self {
            Self::TcpMux => "stream",
            Self::LibfabricSockets
            | Self::LibfabricTcp
            | Self::LibfabricEfa
            | Self::LibfabricEfaDirect
            | Self::LibfabricVerbs
            | Self::LibfabricShm => "rdm",
        }
    }

    fn fi_endpoint(self) -> &'static str {
        match self.endpoint() {
            "rdm" => "FI_EP_RDM",
            "msg" => "FI_EP_MSG",
            "dgram" => "FI_EP_DGRAM",
            _ => "stream",
        }
    }

    fn lane_object(self) -> &'static str {
        match self {
            Self::TcpMux => "tcp_5tuple",
            Self::LibfabricSockets => "fi_endpoint_sockets",
            Self::LibfabricTcp => "fi_endpoint_tcp",
            Self::LibfabricEfa => "fi_endpoint_efa",
            Self::LibfabricEfaDirect => "fi_endpoint_efa_direct",
            Self::LibfabricVerbs => "fi_endpoint_verbs",
            Self::LibfabricShm => "fi_endpoint_shm",
        }
    }

    fn completion_model(self) -> &'static str {
        match self {
            Self::TcpMux => "io_uring_or_blocking_socket_completion",
            Self::LibfabricSockets | Self::LibfabricTcp => "ofi_cq_polled_by_lane_leader",
            Self::LibfabricEfa | Self::LibfabricEfaDirect => "efa_srd_cq_polled_by_lane_leader",
            Self::LibfabricVerbs => "verbs_cq_polled_by_lane_leader",
            Self::LibfabricShm => "ofi_shm_cq_polled_by_lane_leader",
        }
    }

    fn registered_memory_model(self) -> &'static str {
        match self {
            Self::TcpMux => "zcrx/send-zc-or-userspace-pool",
            Self::LibfabricSockets | Self::LibfabricTcp | Self::LibfabricShm => {
                "fi_mr_registered_pool_for_api_shape"
            }
            Self::LibfabricEfa | Self::LibfabricEfaDirect | Self::LibfabricVerbs => {
                "fi_mr_registered_hugetlb_or_pinned_pool"
            }
        }
    }

    fn fallback(self) -> &'static str {
        match self {
            Self::TcpMux => "none",
            Self::LibfabricSockets | Self::LibfabricTcp | Self::LibfabricShm => {
                "tcp-mux-for-non-ofi-peers"
            }
            Self::LibfabricEfa | Self::LibfabricEfaDirect | Self::LibfabricVerbs => {
                "tcp-mux-until-provider-smoke-and-route-checks-pass"
            }
        }
    }
}

